const QUESTION_BANK = [{"id": 1, "subject": "Anatomy", "difficulty": "Medium", "question": "Femur is the longest bone in the body. Its length is approximately what percentage of body height?", "options": [{"key": "A", "text": "15%"}, {"key": "B", "text": "20%"}, {"key": "C", "text": "27%"}, {"key": "D", "text": "35%"}], "correct": "C", "explanation": "Femur length ≈ 27% of total body height — useful in forensic estimation of stature."}, {"id": 2, "subject": "Anatomy", "difficulty": "Easy", "question": "The angle of inclination (neck-shaft angle) of femur in adults is:", "options": [{"key": "A", "text": "100–110°"}, {"key": "B", "text": "115–120°"}, {"key": "C", "text": "125–135°"}, {"key": "D", "text": "140–150°"}], "correct": "C", "explanation": "Normal neck-shaft angle = 125–135°. >135° = coxa valga; <125° = coxa vara."}, {"id": 3, "subject": "Anatomy", "difficulty": "Medium", "question": "Coxa vara is defined as neck-shaft angle:", "options": [{"key": "A", "text": "Greater than 135°"}, {"key": "B", "text": "Less than 120°"}, {"key": "C", "text": "Equal to 125°"}, {"key": "D", "text": "Greater than 150°"}], "correct": "B", "explanation": "Coxa vara = neck-shaft angle <120° (some say <125°); coxa valga = >135°."}, {"id": 4, "subject": "Anatomy", "difficulty": "Medium", "question": "The angle of anteversion of femoral neck in adults is:", "options": [{"key": "A", "text": "5–10°"}, {"key": "B", "text": "10–15°"}, {"key": "C", "text": "15–20°"}, {"key": "D", "text": "20–25°"}], "correct": "C", "explanation": "Normal femoral anteversion = 15–20° in adults; at birth ~40°, decreases with age."}, {"id": 5, "subject": "Anatomy", "difficulty": "Medium", "question": "Greater trochanter of femur lies at which vertebral level when standing?", "options": [{"key": "A", "text": "L3"}, {"key": "B", "text": "L4"}, {"key": "C", "text": "L5"}, {"key": "D", "text": "S1"}], "correct": "B", "explanation": "Greater trochanter is at the level of L4 vertebra — useful landmark in clinical practice."}, {"id": 6, "subject": "Anatomy", "difficulty": "Easy", "question": "Which structure is attached to the lesser trochanter of femur?", "options": [{"key": "A", "text": "Gluteus maximus"}, {"key": "B", "text": "Iliopsoas"}, {"key": "C", "text": "Piriformis"}, {"key": "D", "text": "Obturator internus"}], "correct": "B", "explanation": "Iliopsoas (iliacus + psoas major) inserts into the lesser trochanter of femur."}, {"id": 7, "subject": "Anatomy", "difficulty": "Medium", "question": "Gluteus maximus is inserted into which structure of femur?", "options": [{"key": "A", "text": "Greater trochanter"}, {"key": "B", "text": "Lesser trochanter"}, {"key": "C", "text": "Gluteal tuberosity and iliotibial tract"}, {"key": "D", "text": "Linea aspera"}], "correct": "C", "explanation": "Gluteus maximus inserts into gluteal tuberosity of femur and iliotibial tract (75% to IT band)."}, {"id": 8, "subject": "Anatomy", "difficulty": "Easy", "question": "Linea aspera is a feature found on which surface of femur?", "options": [{"key": "A", "text": "Anterior surface"}, {"key": "B", "text": "Medial surface"}, {"key": "C", "text": "Posterior surface"}, {"key": "D", "text": "Lateral surface"}], "correct": "C", "explanation": "Linea aspera is a prominent ridge on the posterior surface of femoral shaft."}, {"id": 9, "subject": "Anatomy", "difficulty": "Hard", "question": "The nutrient foramen of femur is directed towards:", "options": [{"key": "A", "text": "Knee (distally)"}, {"key": "B", "text": "Hip (proximally)"}, {"key": "C", "text": "Medially"}, {"key": "D", "text": "Laterally"}], "correct": "A", "explanation": "Nutrient foramen of femur directed distally (away from the growing end = knee)."}, {"id": 10, "subject": "Anatomy", "difficulty": "Medium", "question": "Adductor tubercle is located on which part of femur?", "options": [{"key": "A", "text": "Greater trochanter"}, {"key": "B", "text": "Medial condyle"}, {"key": "C", "text": "Lateral condyle"}, {"key": "D", "text": "Lesser trochanter"}], "correct": "B", "explanation": "Adductor tubercle is on the medial condyle — insertion of adductor magnus (hamstring part)."}, {"id": 11, "subject": "Anatomy", "difficulty": "Medium", "question": "Which structure separates the two condyles of femur anteriorly?", "options": [{"key": "A", "text": "Intercondylar fossa"}, {"key": "B", "text": "Patellar surface (trochlear groove)"}, {"key": "C", "text": "Popliteal surface"}, {"key": "D", "text": "Articular surface"}], "correct": "B", "explanation": "Patellar (trochlear) surface separates condyles anteriorly; intercondylar notch separates them posteriorly."}, {"id": 12, "subject": "Anatomy", "difficulty": "Hard", "question": "The quadriceps femoris muscle is attached to femur at:", "options": [{"key": "A", "text": "Linea aspera"}, {"key": "B", "text": "Intertrochanteric line (anterior)"}, {"key": "C", "text": "Both A and B"}, {"key": "D", "text": "Gluteal tuberosity"}], "correct": "B", "explanation": "Vastus intermedius arises from anterior/lateral femoral shaft; rectus femoris from AIIS — but common attachment = intertrochanteric line area."}, {"id": 13, "subject": "Anatomy", "difficulty": "Medium", "question": "In subcapital fracture of femur, blood supply most at risk is from:", "options": [{"key": "A", "text": "Obturator artery"}, {"key": "B", "text": "Medial circumflex femoral artery"}, {"key": "C", "text": "Lateral circumflex femoral artery"}, {"key": "D", "text": "First perforating artery"}], "correct": "B", "explanation": "Medial circumflex femoral artery (retinacular vessels) is the main supply to femoral head — at risk in neck fractures."}, {"id": 14, "subject": "Anatomy", "difficulty": "Medium", "question": "Intertrochanteric line is located on which surface of femur?", "options": [{"key": "A", "text": "Posterior"}, {"key": "B", "text": "Medial"}, {"key": "C", "text": "Anterior"}, {"key": "D", "text": "Lateral"}], "correct": "C", "explanation": "Intertrochanteric line is on the anterior surface; intertrochanteric crest is on the posterior surface."}, {"id": 15, "subject": "Anatomy", "difficulty": "Hard", "question": "Quadratus femoris is inserted into:", "options": [{"key": "A", "text": "Greater trochanter"}, {"key": "B", "text": "Intertrochanteric crest (quadrate tubercle)"}, {"key": "C", "text": "Lesser trochanter"}, {"key": "D", "text": "Linea aspera"}], "correct": "B", "explanation": "Quadratus femoris inserts into quadrate tubercle on intertrochanteric crest (posterior femur)."}, {"id": 16, "subject": "Anatomy", "difficulty": "Medium", "question": "Which bursae communicates with the knee joint cavity most commonly?", "options": [{"key": "A", "text": "Prepatellar bursa"}, {"key": "B", "text": "Suprapatellar bursa"}, {"key": "C", "text": "Infrapatellar bursa"}, {"key": "D", "text": "Pes anserinus bursa"}], "correct": "B", "explanation": "Suprapatellar bursa routinely communicates with knee joint cavity — part of synovial cavity."}, {"id": 17, "subject": "Anatomy", "difficulty": "Hard", "question": "Medial condyle of femur is larger than lateral condyle. Why?", "options": [{"key": "A", "text": "To compensate for the angle of neck"}, {"key": "B", "text": "To compensate for the valgus angle (Q-angle) of femur"}, {"key": "C", "text": "To support more body weight"}, {"key": "D", "text": "For knee flexion"}], "correct": "B", "explanation": "Medial condyle is longer to compensate for the femoral valgus — both condyles reach same horizontal level."}, {"id": 18, "subject": "Anatomy", "difficulty": "Hard", "question": "The popliteal surface of femur is formed between which structures?", "options": [{"key": "A", "text": "Two lips of linea aspera above, condyles below"}, {"key": "B", "text": "Medial and lateral supracondylar lines"}, {"key": "C", "text": "Condyles and popliteal fossa"}, {"key": "D", "text": "Linea aspera and condyles"}], "correct": "B", "explanation": "Popliteal surface = triangular area between medial & lateral supracondylar lines above condyles."}, {"id": 19, "subject": "Anatomy", "difficulty": "Medium", "question": "Piriformis is inserted into which part of femur?", "options": [{"key": "A", "text": "Lesser trochanter"}, {"key": "B", "text": "Intertrochanteric crest"}, {"key": "C", "text": "Greater trochanter (medial surface of upper border)"}, {"key": "D", "text": "Gluteal tuberosity"}], "correct": "C", "explanation": "Piriformis inserts into the medial surface of the upper border of greater trochanter."}, {"id": 20, "subject": "Anatomy", "difficulty": "Easy", "question": "Which type of bone is the femur?", "options": [{"key": "A", "text": "Short bone"}, {"key": "B", "text": "Flat bone"}, {"key": "C", "text": "Long bone"}, {"key": "D", "text": "Irregular bone"}], "correct": "C", "explanation": "Femur is a long bone — it has a diaphysis (shaft) and two epiphyses."}, {"id": 21, "subject": "Anatomy", "difficulty": "Hard", "question": "Distal femoral epiphysis appears at birth. Proximal femoral epiphysis (head) appears at:", "options": [{"key": "A", "text": "Birth"}, {"key": "B", "text": "6 months"}, {"key": "C", "text": "1 year"}, {"key": "D", "text": "3 years"}], "correct": "C", "explanation": "Distal femoral epiphysis = present at birth; Femoral head epiphysis appears at ~1 year of age."}, {"id": 22, "subject": "Anatomy", "difficulty": "Medium", "question": "Neck of femur fracture in elderly is most common at which type?", "options": [{"key": "A", "text": "Basal"}, {"key": "B", "text": "Transcervical"}, {"key": "C", "text": "Subcapital"}, {"key": "D", "text": "Pertrochanteric"}], "correct": "C", "explanation": "Subcapital fracture is most common neck of femur fracture in elderly — avascular necrosis risk highest."}, {"id": 23, "subject": "Anatomy", "difficulty": "Medium", "question": "Bryant's triangle is used to assess fractures/dislocation involving:", "options": [{"key": "A", "text": "Tibia"}, {"key": "B", "text": "Femoral neck"}, {"key": "C", "text": "Patella"}, {"key": "D", "text": "Ankle"}], "correct": "B", "explanation": "Bryant's triangle detects shortening of femoral neck — used in hip fractures and dislocations."}, {"id": 24, "subject": "Anatomy", "difficulty": "Easy", "question": "Which nerve is in close relation to the posterior aspect of hip joint, at risk in posterior dislocation?", "options": [{"key": "A", "text": "Femoral nerve"}, {"key": "B", "text": "Obturator nerve"}, {"key": "C", "text": "Sciatic nerve"}, {"key": "D", "text": "Lateral cutaneous nerve of thigh"}], "correct": "C", "explanation": "Sciatic nerve passes posterior to hip — at risk in posterior dislocation of hip."}, {"id": 25, "subject": "Anatomy", "difficulty": "Medium", "question": "The Q-angle (quadriceps angle) is formed between:", "options": [{"key": "A", "text": "Femur shaft and tibia"}, {"key": "B", "text": "Line from ASIS to patella and patella to tibial tuberosity"}, {"key": "C", "text": "Femoral neck and shaft"}, {"key": "D", "text": "IT band and patella"}], "correct": "B", "explanation": "Q-angle = angle between line ASIS→patella and patella→tibial tuberosity. Normal ♂ ~10–15°, ♀ ~15–20°."}, {"id": 26, "subject": "Anatomy", "difficulty": "Easy", "question": "Tibia is the weight-bearing bone of the leg. It transmits weight to the foot through:", "options": [{"key": "A", "text": "Fibula"}, {"key": "B", "text": "Talus via ankle mortise"}, {"key": "C", "text": "Calcaneus directly"}, {"key": "D", "text": "Navicular bone"}], "correct": "B", "explanation": "Tibia transmits body weight to the talus through the ankle (talocrural) joint."}, {"id": 27, "subject": "Anatomy", "difficulty": "Easy", "question": "The tibial tuberosity is the site of attachment of:", "options": [{"key": "A", "text": "Hamstrings"}, {"key": "B", "text": "Gastrocnemius"}, {"key": "C", "text": "Patellar tendon (ligamentum patellae)"}, {"key": "D", "text": "Sartorius"}], "correct": "C", "explanation": "Patellar tendon (ligamentum patellae) inserts into tibial tuberosity — Osgood-Schlatter disease affects this site."}, {"id": 28, "subject": "Anatomy", "difficulty": "Medium", "question": "Pes anserinus is the combined insertion of which three muscles on tibia?", "options": [{"key": "A", "text": "Rectus femoris, sartorius, gracilis"}, {"key": "B", "text": "Sartorius, gracilis, semitendinosus"}, {"key": "C", "text": "Sartorius, biceps femoris, gracilis"}, {"key": "D", "text": "Gracilis, semitendinosus, semimembranosus"}], "correct": "B", "explanation": "Pes anserinus (goose's foot) = Sartorius + Gracilis + Semitendinosus on medial tibia."}, {"id": 29, "subject": "Anatomy", "difficulty": "Medium", "question": "Intercondylar eminence of tibia lies between:", "options": [{"key": "A", "text": "Medial and lateral condyles posteriorly"}, {"key": "B", "text": "Medial and lateral tibial condyles (intercondylar area)"}, {"key": "C", "text": "Tibial tuberosity and shaft"}, {"key": "D", "text": "Tibial condyles and fibula head"}], "correct": "B", "explanation": "Intercondylar eminence (tibial spine) projects between medial and lateral articular facets of tibia."}, {"id": 30, "subject": "Anatomy", "difficulty": "Easy", "question": "Which ligament attaches to the anterior intercondylar area of tibia?", "options": [{"key": "A", "text": "Posterior cruciate ligament"}, {"key": "B", "text": "Anterior cruciate ligament"}, {"key": "C", "text": "Medial collateral ligament"}, {"key": "D", "text": "Lateral collateral ligament"}], "correct": "B", "explanation": "ACL attaches to anterior intercondylar area of tibia; PCL to posterior intercondylar area."}, {"id": 31, "subject": "Anatomy", "difficulty": "Medium", "question": "The soleal line is a feature on which surface of tibia?", "options": [{"key": "A", "text": "Anterior surface"}, {"key": "B", "text": "Medial surface"}, {"key": "C", "text": "Posterior surface"}, {"key": "D", "text": "Lateral surface"}], "correct": "C", "explanation": "Soleal line runs obliquely on the posterior surface of tibia — origin of soleus muscle."}, {"id": 32, "subject": "Anatomy", "difficulty": "Hard", "question": "The nutrient foramen of tibia is directed:", "options": [{"key": "A", "text": "Proximally (towards knee)"}, {"key": "B", "text": "Distally (towards ankle)"}, {"key": "C", "text": "Medially"}, {"key": "D", "text": "Laterally"}], "correct": "B", "explanation": "Nutrient foramen of tibia is directed distally — away from the growing end (upper end)."}, {"id": 33, "subject": "Anatomy", "difficulty": "Easy", "question": "Osgood-Schlatter disease is osteochondrosis of:", "options": [{"key": "A", "text": "Femoral head"}, {"key": "B", "text": "Tibial tuberosity"}, {"key": "C", "text": "Medial tibial condyle"}, {"key": "D", "text": "Navicular bone"}], "correct": "B", "explanation": "Osgood-Schlatter disease = traction apophysitis of tibial tuberosity in adolescents."}, {"id": 34, "subject": "Anatomy", "difficulty": "Easy", "question": "The medial malleolus is a part of:", "options": [{"key": "A", "text": "Fibula"}, {"key": "B", "text": "Tibia"}, {"key": "C", "text": "Talus"}, {"key": "D", "text": "Calcaneus"}], "correct": "B", "explanation": "Medial malleolus is the downward projection of the medial aspect of distal tibia."}, {"id": 35, "subject": "Anatomy", "difficulty": "Hard", "question": "Which structure is posterior to medial malleolus (from anterior to posterior order)?", "options": [{"key": "A", "text": "FHL, FDL, tibialis posterior"}, {"key": "B", "text": "Tibialis posterior, FDL, FHL"}, {"key": "C", "text": "FDL, tibialis posterior, FHL"}, {"key": "D", "text": "Tibialis anterior, EHL, EHB"}], "correct": "B", "explanation": "Tom, Dick And Very Nervous Harry: Tibialis posterior, FDL, posterior tibial Artery, Vein, Nerve, FHL."}, {"id": 36, "subject": "Anatomy", "difficulty": "Medium", "question": "Tibial plateau fracture most commonly involves which side?", "options": [{"key": "A", "text": "Medial plateau"}, {"key": "B", "text": "Lateral plateau"}, {"key": "C", "text": "Both equally"}, {"key": "D", "text": "Posterior plateau"}], "correct": "B", "explanation": "Lateral tibial plateau fracture is more common (Schatzker classification) due to valgus force in trauma."}, {"id": 37, "subject": "Anatomy", "difficulty": "Medium", "question": "The interosseous membrane between tibia and fibula is attached to which border of tibia?", "options": [{"key": "A", "text": "Medial border"}, {"key": "B", "text": "Posterior border"}, {"key": "C", "text": "Interosseous (lateral) border"}, {"key": "D", "text": "Anterior border"}], "correct": "C", "explanation": "Interosseous membrane attaches to the interosseous (lateral) border of tibia and medial border of fibula."}, {"id": 38, "subject": "Anatomy", "difficulty": "Hard", "question": "Which muscle arises from the lateral condyle of tibia?", "options": [{"key": "A", "text": "Popliteus"}, {"key": "B", "text": "Tibialis anterior"}, {"key": "C", "text": "Extensor digitorum longus"}, {"key": "D", "text": "Peroneus longus"}], "correct": "C", "explanation": "Extensor digitorum longus arises partly from lateral tibial condyle and interosseous membrane."}, {"id": 39, "subject": "Anatomy", "difficulty": "Medium", "question": "Popliteus muscle is attached to tibia at:", "options": [{"key": "A", "text": "Lateral condyle"}, {"key": "B", "text": "Medial condyle"}, {"key": "C", "text": "Posterior surface above soleal line"}, {"key": "D", "text": "Tibial tuberosity"}], "correct": "C", "explanation": "Popliteus inserts into triangular area on posterior tibia above soleal line."}, {"id": 40, "subject": "Anatomy", "difficulty": "Hard", "question": "The upper end of tibia ossifies:", "options": [{"key": "A", "text": "At birth only"}, {"key": "B", "text": "At 1 year"}, {"key": "C", "text": "At birth and joins shaft at 20 years"}, {"key": "D", "text": "At 3 years"}], "correct": "C", "explanation": "Upper tibial epiphysis present at birth; fuses with shaft around 20 years."}, {"id": 41, "subject": "Anatomy", "difficulty": "Medium", "question": "The tibial shaft is most narrow at:", "options": [{"key": "A", "text": "Upper third"}, {"key": "B", "text": "Junction of upper and middle third"}, {"key": "C", "text": "Junction of middle and lower third"}, {"key": "D", "text": "Lower third"}], "correct": "C", "explanation": "Tibia is narrowest at the junction of middle and lower third — most common site of stress fractures."}, {"id": 42, "subject": "Anatomy", "difficulty": "Easy", "question": "Shin bone refers to which surface of tibia?", "options": [{"key": "A", "text": "Posterior"}, {"key": "B", "text": "Lateral"}, {"key": "C", "text": "Anterior (subcutaneous)"}, {"key": "D", "text": "Medial"}], "correct": "C", "explanation": "Anterior surface/border of tibia is subcutaneous (shin) — no muscle covers it, prone to direct injury."}, {"id": 43, "subject": "Anatomy", "difficulty": "Medium", "question": "Semimembranosus inserts into which part of tibia?", "options": [{"key": "A", "text": "Tibial tuberosity"}, {"key": "B", "text": "Posterior aspect of medial tibial condyle"}, {"key": "C", "text": "Pes anserinus"}, {"key": "D", "text": "Gerdy's tubercle"}], "correct": "B", "explanation": "Semimembranosus inserts into the posterior aspect of medial tibial condyle."}, {"id": 44, "subject": "Anatomy", "difficulty": "Medium", "question": "Gerdy's tubercle on tibia is the insertion of:", "options": [{"key": "A", "text": "Patellar tendon"}, {"key": "B", "text": "Iliotibial band"}, {"key": "C", "text": "Biceps femoris"}, {"key": "D", "text": "Sartorius"}], "correct": "B", "explanation": "Iliotibial band inserts into Gerdy's tubercle on the anterolateral aspect of lateral tibial condyle."}, {"id": 45, "subject": "Anatomy", "difficulty": "Medium", "question": "In tibial shaft fracture, the compartment most commonly affected by compartment syndrome is:", "options": [{"key": "A", "text": "Posterior superficial"}, {"key": "B", "text": "Posterior deep"}, {"key": "C", "text": "Anterior"}, {"key": "D", "text": "Lateral"}], "correct": "C", "explanation": "Anterior compartment syndrome is most common after tibial fracture — tight fascial boundary."}, {"id": 46, "subject": "Anatomy", "difficulty": "Hard", "question": "The distal tibial growth plate (physis) fuses at approximately:", "options": [{"key": "A", "text": "12–14 years"}, {"key": "B", "text": "14–16 years"}, {"key": "C", "text": "16–18 years"}, {"key": "D", "text": "18–20 years"}], "correct": "C", "explanation": "Distal tibial physis fuses at ~16–18 years; proximal physis fuses later (~20 years)."}, {"id": 47, "subject": "Anatomy", "difficulty": "Hard", "question": "Tillaux fracture is a Salter-Harris type III fracture of which bone?", "options": [{"key": "A", "text": "Fibula"}, {"key": "B", "text": "Tibia (distal)"}, {"key": "C", "text": "Femur"}, {"key": "D", "text": "Calcaneus"}], "correct": "B", "explanation": "Tillaux fracture = Salter-Harris III of anterolateral distal tibia, seen in adolescents during physeal closure."}, {"id": 48, "subject": "Anatomy", "difficulty": "Easy", "question": "Which surface of tibia faces the fibula?", "options": [{"key": "A", "text": "Medial surface"}, {"key": "B", "text": "Posterior surface"}, {"key": "C", "text": "Lateral surface"}, {"key": "D", "text": "Anterior surface"}], "correct": "C", "explanation": "Lateral surface of tibia faces the fibula; interosseous membrane connects their interosseous borders."}, {"id": 49, "subject": "Anatomy", "difficulty": "Medium", "question": "The articular surface for fibula on tibia is located at:", "options": [{"key": "A", "text": "Lateral condyle only (proximal)"}, {"key": "B", "text": "Medial condyle"}, {"key": "C", "text": "Both proximal (lateral condyle) and distal fibular notch"}, {"key": "D", "text": "Intercondylar eminence"}], "correct": "C", "explanation": "Tibia articulates with fibula at superior tibiofibular joint (lateral condyle) and inferior (fibular notch)."}, {"id": 50, "subject": "Anatomy", "difficulty": "Hard", "question": "Dreaded black line in tibial stress fracture indicates:", "options": [{"key": "A", "text": "Healing fracture"}, {"key": "B", "text": "High-risk fracture of anterior tibial cortex"}, {"key": "C", "text": "Periosteal reaction"}, {"key": "D", "text": "Completed fracture"}], "correct": "B", "explanation": "Dreaded black line = transverse lucency on anterior tibial cortex — high nonunion risk, requires surgery."}, {"id": 51, "subject": "Anatomy", "difficulty": "Easy", "question": "Fibula is primarily a:", "options": [{"key": "A", "text": "Weight-bearing bone"}, {"key": "B", "text": "Non-weight-bearing bone providing muscle attachment and ankle stability"}, {"key": "C", "text": "Main bone of leg"}, {"key": "D", "text": "Sesamoid bone"}], "correct": "B", "explanation": "Fibula bears only ~6% of body weight; mainly provides muscle attachment and lateral ankle stability."}, {"id": 52, "subject": "Anatomy", "difficulty": "Easy", "question": "Head of fibula articulates with:", "options": [{"key": "A", "text": "Femoral condyle"}, {"key": "B", "text": "Lateral condyle of tibia"}, {"key": "C", "text": "Medial condyle of tibia"}, {"key": "D", "text": "Talus"}], "correct": "B", "explanation": "Fibular head articulates with the lateral condyle of tibia at the superior tibiofibular joint."}, {"id": 53, "subject": "Anatomy", "difficulty": "Medium", "question": "The lateral malleolus (fibula) extends how much lower than medial malleolus?", "options": [{"key": "A", "text": "Same level"}, {"key": "B", "text": "1 cm lower"}, {"key": "C", "text": "1–2 cm lower"}, {"key": "D", "text": "3 cm lower"}], "correct": "C", "explanation": "Lateral malleolus extends ~1–2 cm more distally than medial malleolus, preventing lateral talar shift."}, {"id": 54, "subject": "Anatomy", "difficulty": "Easy", "question": "Common peroneal nerve winds around which part of fibula?", "options": [{"key": "A", "text": "Head of fibula"}, {"key": "B", "text": "Neck of fibula"}, {"key": "C", "text": "Lateral surface of shaft"}, {"key": "D", "text": "Lateral malleolus"}], "correct": "B", "explanation": "Common peroneal nerve winds around the neck of fibula — vulnerable to injury here."}, {"id": 55, "subject": "Anatomy", "difficulty": "Easy", "question": "Fracture of neck of fibula most commonly injures which nerve?", "options": [{"key": "A", "text": "Tibial nerve"}, {"key": "B", "text": "Superficial peroneal nerve"}, {"key": "C", "text": "Common peroneal nerve"}, {"key": "D", "text": "Sural nerve"}], "correct": "C", "explanation": "CPN winds around fibular neck → foot drop on fracture at this level."}, {"id": 56, "subject": "Anatomy", "difficulty": "Hard", "question": "Fibula is used as a bone graft donor site most commonly for:", "options": [{"key": "A", "text": "Spinal fusion"}, {"key": "B", "text": "Mandible reconstruction"}, {"key": "C", "text": "Hip replacement"}, {"key": "D", "text": "Wrist fusion"}], "correct": "B", "explanation": "Free vascularized fibula graft is gold standard for mandibular reconstruction after oncologic resection."}, {"id": 57, "subject": "Anatomy", "difficulty": "Medium", "question": "The inferior tibiofibular joint is which type of joint?", "options": [{"key": "A", "text": "Synovial"}, {"key": "B", "text": "Fibrous (syndesmosis)"}, {"key": "C", "text": "Cartilaginous"}, {"key": "D", "text": "Gomphosis"}], "correct": "B", "explanation": "Inferior tibiofibular joint = fibrous syndesmosis — held by anterior & posterior tibiofibular ligaments."}, {"id": 58, "subject": "Anatomy", "difficulty": "Easy", "question": "Peroneus longus and brevis arise from the lateral surface of:", "options": [{"key": "A", "text": "Tibia"}, {"key": "B", "text": "Fibula"}, {"key": "C", "text": "Both tibia and fibula"}, {"key": "D", "text": "Calcaneus"}], "correct": "B", "explanation": "Peroneus (fibularis) longus and brevis arise from the lateral surface of the fibula."}, {"id": 59, "subject": "Anatomy", "difficulty": "Hard", "question": "Peroneus (fibularis) tertius arises from the:", "options": [{"key": "A", "text": "Lateral fibula (lower third)"}, {"key": "B", "text": "Medial fibula"}, {"key": "C", "text": "Tibia"}, {"key": "D", "text": "Anterior fibula (lower third)"}], "correct": "D", "explanation": "Peroneus tertius arises from the anterior surface of lower fibula — dorsiflexes and everts foot."}, {"id": 60, "subject": "Anatomy", "difficulty": "Medium", "question": "A Pott's fracture involves:", "options": [{"key": "A", "text": "Tibia only"}, {"key": "B", "text": "Fibula alone or with medial malleolus/deltoid ligament"}, {"key": "C", "text": "Talus"}, {"key": "D", "text": "Fifth metatarsal"}], "correct": "B", "explanation": "Pott's fracture = bimalleolar fracture (fibula + medial malleolus or deltoid tear) from eversion injury."}, {"id": 61, "subject": "Anatomy", "difficulty": "Hard", "question": "Maisonneuve fracture is a proximal fibular fracture associated with:", "options": [{"key": "A", "text": "Tibial shaft fracture"}, {"key": "B", "text": "Distal tibia fracture + syndesmotic disruption"}, {"key": "C", "text": "Talar fracture"}, {"key": "D", "text": "Calcaneal fracture"}], "correct": "B", "explanation": "Maisonneuve = proximal fibula fracture with disruption of syndesmosis and medial ankle structures."}, {"id": 62, "subject": "Anatomy", "difficulty": "Medium", "question": "Which muscle arises from the posterior surface of fibula?", "options": [{"key": "A", "text": "Tibialis anterior"}, {"key": "B", "text": "Peroneus longus"}, {"key": "C", "text": "Flexor hallucis longus"}, {"key": "D", "text": "Extensor hallucis longus"}], "correct": "C", "explanation": "FHL arises from posterior surface of fibula (lower 2/3) — important in hallux stabilisation."}, {"id": 63, "subject": "Anatomy", "difficulty": "Hard", "question": "Extensor hallucis longus arises from which surface of fibula?", "options": [{"key": "A", "text": "Lateral surface"}, {"key": "B", "text": "Medial (anterior interosseous) surface"}, {"key": "C", "text": "Posterior surface"}, {"key": "D", "text": "Medial surface"}], "correct": "B", "explanation": "EHL arises from the anterior (medial) surface of fibula and interosseous membrane."}, {"id": 64, "subject": "Anatomy", "difficulty": "Hard", "question": "The nutrient foramen of fibula is directed:", "options": [{"key": "A", "text": "Proximally"}, {"key": "B", "text": "Distally"}, {"key": "C", "text": "Medially"}, {"key": "D", "text": "Laterally"}], "correct": "B", "explanation": "Nutrient foramen of fibula faces distally — same direction as tibia (both away from growing proximal end)."}, {"id": 65, "subject": "Anatomy", "difficulty": "Medium", "question": "Anterior talofibular ligament (ATFL) is the most commonly injured ligament in ankle sprain. It attaches to:", "options": [{"key": "A", "text": "Medial malleolus and talus"}, {"key": "B", "text": "Lateral malleolus and talar neck"}, {"key": "C", "text": "Fibula and calcaneus"}, {"key": "D", "text": "Tibia and fibula"}], "correct": "B", "explanation": "ATFL runs from lateral malleolus to talar neck — ruptures in inversion sprain."}, {"id": 66, "subject": "Anatomy", "difficulty": "Easy", "question": "How many tarsal bones are present in the foot?", "options": [{"key": "A", "text": "5"}, {"key": "B", "text": "6"}, {"key": "C", "text": "7"}, {"key": "D", "text": "8"}], "correct": "C", "explanation": "7 tarsal bones: Calcaneus, Talus, Navicular, Cuboid, and 3 Cuneiforms (medial, intermediate, lateral)."}, {"id": 67, "subject": "Anatomy", "difficulty": "Easy", "question": "The largest tarsal bone is:", "options": [{"key": "A", "text": "Talus"}, {"key": "B", "text": "Navicular"}, {"key": "C", "text": "Calcaneus"}, {"key": "D", "text": "Cuboid"}], "correct": "C", "explanation": "Calcaneus is the largest tarsal bone — forms the heel and transmits body weight to the ground."}, {"id": 68, "subject": "Anatomy", "difficulty": "Hard", "question": "Talus is unique among tarsal bones because:", "options": [{"key": "A", "text": "It has no ligament attachments"}, {"key": "B", "text": "It has no muscle attachments"}, {"key": "C", "text": "It is sesamoid"}, {"key": "D", "text": "It is not weight-bearing"}], "correct": "B", "explanation": "Talus has NO muscular attachments — only ligaments and articular surfaces cover most of its surface."}, {"id": 69, "subject": "Anatomy", "difficulty": "Medium", "question": "The body of talus articulates with tibia above and fibula laterally. Which surface of talus articulates with calcaneus?", "options": [{"key": "A", "text": "Anterior surface"}, {"key": "B", "text": "Posterior surface"}, {"key": "C", "text": "Inferior surface (3 facets)"}, {"key": "D", "text": "Medial surface"}], "correct": "C", "explanation": "Inferior talus has 3 articular facets (anterior, middle, posterior) for subtalar joint with calcaneus."}, {"id": 70, "subject": "Anatomy", "difficulty": "Easy", "question": "Subtalar (talocalcaneal) joint is responsible for which movement?", "options": [{"key": "A", "text": "Dorsiflexion and plantarflexion"}, {"key": "B", "text": "Inversion and eversion of foot"}, {"key": "C", "text": "Toe flexion"}, {"key": "D", "text": "Knee flexion"}], "correct": "B", "explanation": "Subtalar joint produces inversion and eversion (pronation/supination) of the foot."}, {"id": 71, "subject": "Anatomy", "difficulty": "Easy", "question": "Calcaneus articulates with which bones?", "options": [{"key": "A", "text": "Talus and cuboid"}, {"key": "B", "text": "Talus only"}, {"key": "C", "text": "Navicular and talus"}, {"key": "D", "text": "Cuboid only"}], "correct": "A", "explanation": "Calcaneus articulates superiorly with talus (subtalar joint) and anteriorly with cuboid."}, {"id": 72, "subject": "Anatomy", "difficulty": "Easy", "question": "Calcaneal tuberosity (posterior) is the insertion of:", "options": [{"key": "A", "text": "Tibialis posterior"}, {"key": "B", "text": "Achilles tendon (tendo calcaneus)"}, {"key": "C", "text": "Peroneus longus"}, {"key": "D", "text": "Flexor hallucis longus"}], "correct": "B", "explanation": "Achilles tendon (gastrocnemius + soleus) inserts into the posterior calcaneal tuberosity."}, {"id": 73, "subject": "Anatomy", "difficulty": "Medium", "question": "Sustentaculum tali is a medial shelf of calcaneus that supports:", "options": [{"key": "A", "text": "Navicular"}, {"key": "B", "text": "Head of talus"}, {"key": "C", "text": "Cuboid"}, {"key": "D", "text": "Cuneiform"}], "correct": "B", "explanation": "Sustentaculum tali supports the head and neck of talus medially."}, {"id": 74, "subject": "Anatomy", "difficulty": "Hard", "question": "Which tendon passes in the groove beneath sustentaculum tali?", "options": [{"key": "A", "text": "Tibialis posterior"}, {"key": "B", "text": "Flexor digitorum longus"}, {"key": "C", "text": "Flexor hallucis longus"}, {"key": "D", "text": "Peroneus longus"}], "correct": "C", "explanation": "FHL runs in a groove under sustentaculum tali — hence sustentaculum tali is NOT avulsed in calcaneal fractures."}, {"id": 75, "subject": "Anatomy", "difficulty": "Medium", "question": "Bohler's angle (tuber-joint angle) is used to assess fractures of:", "options": [{"key": "A", "text": "Talus"}, {"key": "B", "text": "Navicular"}, {"key": "C", "text": "Calcaneus"}, {"key": "D", "text": "Fibula"}], "correct": "C", "explanation": "Bohler's angle (normal 20–40°) is reduced in calcaneal fractures — indicates depression."}, {"id": 76, "subject": "Anatomy", "difficulty": "Easy", "question": "Most common tarsal bone to fracture is:", "options": [{"key": "A", "text": "Talus"}, {"key": "B", "text": "Navicular"}, {"key": "C", "text": "Calcaneus"}, {"key": "D", "text": "Cuboid"}], "correct": "C", "explanation": "Calcaneus is the most commonly fractured tarsal bone — usually from axial loading (fall from height)."}, {"id": 77, "subject": "Anatomy", "difficulty": "Medium", "question": "Avascular necrosis is most common after fracture of which tarsal bone?", "options": [{"key": "A", "text": "Calcaneus"}, {"key": "B", "text": "Cuboid"}, {"key": "C", "text": "Navicular"}, {"key": "D", "text": "Talus"}], "correct": "D", "explanation": "Talus has precarious blood supply — AVN occurs in ~10–40% of talar neck fractures (Hawkins classification)."}, {"id": 78, "subject": "Anatomy", "difficulty": "Medium", "question": "Navicular bone is on the medial side of foot. It articulates with:", "options": [{"key": "A", "text": "Talus posteriorly, 3 cuneiforms anteriorly"}, {"key": "B", "text": "Calcaneus posteriorly, cuboid laterally"}, {"key": "C", "text": "Talus and cuboid"}, {"key": "D", "text": "Cuboid and 3 cuneiforms"}], "correct": "A", "explanation": "Navicular articulates with talus (posteriorly) and 3 cuneiforms (anteriorly), and sometimes cuboid."}, {"id": 79, "subject": "Anatomy", "difficulty": "Medium", "question": "Kohler's disease is osteochondrosis of:", "options": [{"key": "A", "text": "Calcaneus"}, {"key": "B", "text": "Talus"}, {"key": "C", "text": "Navicular"}, {"key": "D", "text": "Cuboid"}], "correct": "C", "explanation": "Kohler's disease = avascular necrosis of navicular bone in children aged 3–7 years."}, {"id": 80, "subject": "Anatomy", "difficulty": "Medium", "question": "Tibialis posterior inserts into which bone primarily?", "options": [{"key": "A", "text": "Calcaneus"}, {"key": "B", "text": "Cuboid"}, {"key": "C", "text": "Navicular tuberosity"}, {"key": "D", "text": "Medial cuneiform"}], "correct": "C", "explanation": "Tibialis posterior inserts primarily into navicular tuberosity + all tarsal bones except talus."}, {"id": 81, "subject": "Anatomy", "difficulty": "Hard", "question": "Peroneus longus tendon passes under the foot in a groove on:", "options": [{"key": "A", "text": "Navicular"}, {"key": "B", "text": "Medial cuneiform"}, {"key": "C", "text": "Cuboid"}, {"key": "D", "text": "Calcaneus"}], "correct": "C", "explanation": "Peroneus longus tendon turns under the foot in a groove on the cuboid — inserts into medial cuneiform + 1st MT base."}, {"id": 82, "subject": "Anatomy", "difficulty": "Medium", "question": "Lisfranc joint is the articulation between:", "options": [{"key": "A", "text": "Tibia and talus"}, {"key": "B", "text": "Talus and calcaneus"}, {"key": "C", "text": "Tarsals and metatarsals (tarsometatarsal joint)"}, {"key": "D", "text": "Metatarsals and phalanges"}], "correct": "C", "explanation": "Lisfranc joint = tarsometatarsal joint; Lisfranc ligament connects medial cuneiform to 2nd MT base."}, {"id": 83, "subject": "Anatomy", "difficulty": "Medium", "question": "Chopart's joint (midtarsal joint) is between:", "options": [{"key": "A", "text": "Talus + calcaneus / navicular + cuboid"}, {"key": "B", "text": "Tarsals and metatarsals"}, {"key": "C", "text": "Calcaneus and navicular"}, {"key": "D", "text": "Tibia and talus"}], "correct": "A", "explanation": "Chopart's joint = calcaneocuboid + talonavicular joints — transverse tarsal joint."}, {"id": 84, "subject": "Anatomy", "difficulty": "Hard", "question": "Cuboid bone articulates with all EXCEPT:", "options": [{"key": "A", "text": "Calcaneus"}, {"key": "B", "text": "4th and 5th metatarsals"}, {"key": "C", "text": "Navicular"}, {"key": "D", "text": "Lateral cuneiform"}], "correct": "C", "explanation": "Cuboid does NOT consistently articulate with navicular. It articulates with calcaneus, 4th/5th MT, and lateral cuneiform."}, {"id": 85, "subject": "Anatomy", "difficulty": "Medium", "question": "The medial longitudinal arch of foot passes through which bones?", "options": [{"key": "A", "text": "Calcaneus, cuboid, 4th/5th MT"}, {"key": "B", "text": "Calcaneus, talus, navicular, cuneiforms, 1st–3rd MT"}, {"key": "C", "text": "Calcaneus, talus, cuboid, MT"}, {"key": "D", "text": "Tibia, talus, navicular, MT"}], "correct": "B", "explanation": "Medial longitudinal arch: Calcaneus → Talus → Navicular → 3 Cuneiforms → 1st–3rd Metatarsals."}, {"id": 86, "subject": "Anatomy", "difficulty": "Medium", "question": "Lateral longitudinal arch of foot is formed by:", "options": [{"key": "A", "text": "Calcaneus, cuboid, 4th & 5th metatarsals"}, {"key": "B", "text": "Calcaneus, talus, navicular, 1st MT"}, {"key": "C", "text": "Calcaneus, cuneiforms, 1st–3rd MT"}, {"key": "D", "text": "Talus, cuboid, 5th MT"}], "correct": "A", "explanation": "Lateral longitudinal arch: Calcaneus → Cuboid → 4th & 5th metatarsals (lower, less mobile arch)."}, {"id": 87, "subject": "Anatomy", "difficulty": "Easy", "question": "Pes planus (flat foot) is loss of which arch?", "options": [{"key": "A", "text": "Transverse arch"}, {"key": "B", "text": "Lateral longitudinal arch"}, {"key": "C", "text": "Medial longitudinal arch"}, {"key": "D", "text": "All arches equally"}], "correct": "C", "explanation": "Pes planus = collapse of medial longitudinal arch — tibialis posterior insufficiency is common cause."}, {"id": 88, "subject": "Anatomy", "difficulty": "Medium", "question": "Pes cavus (high arch) is associated with which neurological condition?", "options": [{"key": "A", "text": "Cerebral palsy (diplegia)"}, {"key": "B", "text": "Charcot-Marie-Tooth disease"}, {"key": "C", "text": "Duchenne muscular dystrophy"}, {"key": "D", "text": "Polio"}], "correct": "B", "explanation": "Pes cavus = high arch; strongly associated with Charcot-Marie-Tooth (hereditary motor sensory neuropathy)."}, {"id": 89, "subject": "Anatomy", "difficulty": "Medium", "question": "In a 'March fracture' (stress fracture), which bone is most commonly involved?", "options": [{"key": "A", "text": "Tibia"}, {"key": "B", "text": "Fibula"}, {"key": "C", "text": "2nd metatarsal neck"}, {"key": "D", "text": "Calcaneus"}], "correct": "C", "explanation": "March fracture = stress fracture of 2nd (most common) or 3rd metatarsal neck from repetitive loading."}, {"id": 90, "subject": "Anatomy", "difficulty": "Medium", "question": "Sever's disease is apophysitis of:", "options": [{"key": "A", "text": "Tibial tuberosity"}, {"key": "B", "text": "Calcaneal apophysis"}, {"key": "C", "text": "Navicular"}, {"key": "D", "text": "Femoral head"}], "correct": "B", "explanation": "Sever's disease = calcaneal apophysitis in adolescents — traction by Achilles tendon on calcaneal growth plate."}, {"id": 91, "subject": "Anatomy", "difficulty": "Easy", "question": "Which bone gives attachment to the deltoid ligament?", "options": [{"key": "A", "text": "Lateral malleolus (fibula)"}, {"key": "B", "text": "Medial malleolus (tibia)"}, {"key": "C", "text": "Calcaneus"}, {"key": "D", "text": "Navicular"}], "correct": "B", "explanation": "Deltoid ligament (medial collateral) attaches to medial malleolus (tibia) — very strong, resists eversion."}, {"id": 92, "subject": "Anatomy", "difficulty": "Hard", "question": "The keystone of the medial longitudinal arch is:", "options": [{"key": "A", "text": "Navicular"}, {"key": "B", "text": "Talus"}, {"key": "C", "text": "Medial cuneiform"}, {"key": "D", "text": "Calcaneus"}], "correct": "B", "explanation": "Talus is the keystone of the medial longitudinal arch — it receives body weight and distributes it."}, {"id": 93, "subject": "Anatomy", "difficulty": "Medium", "question": "Thomas test assesses:", "options": [{"key": "A", "text": "Hip abduction contracture"}, {"key": "B", "text": "Hip flexion contracture (iliopsoas tightness)"}, {"key": "C", "text": "Knee extension lag"}, {"key": "D", "text": "Ankle dorsiflexion"}], "correct": "B", "explanation": "Thomas test detects fixed hip flexion deformity — normal hip extends to 0° when opposite hip fully flexed."}, {"id": 94, "subject": "Anatomy", "difficulty": "Hard", "question": "In calcaneal fracture from fall from height, which spinal level is also at risk?", "options": [{"key": "A", "text": "Cervical spine"}, {"key": "B", "text": "Thoracic spine"}, {"key": "C", "text": "Lumbar spine (L1)"}, {"key": "D", "text": "Sacrum"}], "correct": "C", "explanation": "Axial load fracture of calcaneus → 10% risk of L1 compression fracture (Don Juan fracture pattern)."}, {"id": 95, "subject": "Anatomy", "difficulty": "Medium", "question": "The talar neck fracture classification is known as:", "options": [{"key": "A", "text": "Garden classification"}, {"key": "B", "text": "Schatzker classification"}, {"key": "C", "text": "Hawkins classification"}, {"key": "D", "text": "Neer classification"}], "correct": "C", "explanation": "Hawkins classification (Type I–IV) describes talar neck fractures and risk of AVN."}, {"id": 96, "subject": "Anatomy", "difficulty": "Hard", "question": "Which fracture is described as 'lover's fracture' or 'Don Juan fracture'?", "options": [{"key": "A", "text": "Tibial plateau fracture"}, {"key": "B", "text": "Distal femur fracture"}, {"key": "C", "text": "Bilateral calcaneal fracture"}, {"key": "D", "text": "Talar fracture"}], "correct": "C", "explanation": "Bilateral calcaneal fractures from jumping/falling = lover's fracture or Don Juan fracture."}, {"id": 97, "subject": "Anatomy", "difficulty": "Hard", "question": "The normal tibiofibular angle (mechanical axis of lower limb) in adults is approximately:", "options": [{"key": "A", "text": "0° (straight)"}, {"key": "B", "text": "5–7° valgus"}, {"key": "C", "text": "10–15° valgus"}, {"key": "D", "text": "5° varus"}], "correct": "B", "explanation": "Normal mechanical axis of lower limb has ~5–7° valgus at knee — slight physiological valgus."}, {"id": 98, "subject": "Anatomy", "difficulty": "Hard", "question": "Which test assesses medial longitudinal arch clinically?", "options": [{"key": "A", "text": "Thomas test"}, {"key": "B", "text": "Trendelenburg test"}, {"key": "C", "text": "Jack's test (hallux dorsiflexion test)"}, {"key": "D", "text": "Lachman test"}], "correct": "C", "explanation": "Jack's test: passive dorsiflexion of hallux → plantar fascia tightens → MLA rises (windlass mechanism)."}, {"id": 99, "subject": "Anatomy", "difficulty": "Medium", "question": "Genu varum (bow legs) in adults is associated with which condition?", "options": [{"key": "A", "text": "Rickets in childhood / OA medial compartment"}, {"key": "B", "text": "Cerebral palsy"}, {"key": "C", "text": "Femoral neck fracture"}, {"key": "D", "text": "Tibial plateau fracture"}], "correct": "A", "explanation": "Genu varum = medial knee OA in adults or rickets in childhood — medial compartment overloaded."}, {"id": 100, "subject": "Anatomy", "difficulty": "Hard", "question": "The epiphysis of the distal femur is used in forensic medicine to estimate:", "options": [{"key": "A", "text": "Age at puberty"}, {"key": "B", "text": "Age at birth (present at birth → maturity)"}, {"key": "C", "text": "Sex of individual"}, {"key": "D", "text": "Height of individual"}], "correct": "B", "explanation": "Distal femoral epiphysis is present at birth and used as a sign of fetal maturity (≥36 weeks gestation)."}, {"id": 101, "subject": "Anatomy", "difficulty": "Easy", "question": "Hip joint is which type of synovial joint?", "options": [{"key": "A", "text": "Hinge joint"}, {"key": "B", "text": "Ball and socket joint"}, {"key": "C", "text": "Condyloid joint"}, {"key": "D", "text": "Pivot joint"}], "correct": "B", "explanation": "Hip joint = ball and socket (multiaxial) synovial joint — femoral head in acetabulum."}, {"id": 102, "subject": "Anatomy", "difficulty": "Easy", "question": "The acetabulum is formed by the fusion of which three bones?", "options": [{"key": "A", "text": "Ilium, ischium, pubis"}, {"key": "B", "text": "Ilium, sacrum, pubis"}, {"key": "C", "text": "Femur, ilium, ischium"}, {"key": "D", "text": "Ilium, ischium, coccyx"}], "correct": "A", "explanation": "Acetabulum formed by ilium (2/5), ischium (2/5), pubis (1/5) — fuse at triradiate cartilage."}, {"id": 103, "subject": "Anatomy", "difficulty": "Medium", "question": "The acetabular labrum is deficient inferiorly at:", "options": [{"key": "A", "text": "Acetabular notch"}, {"key": "B", "text": "Anterior rim"}, {"key": "C", "text": "Posterior rim"}, {"key": "D", "text": "Superior rim"}], "correct": "A", "explanation": "Acetabular labrum is C-shaped — deficient inferiorly at acetabular notch (bridged by transverse acetabular ligament)."}, {"id": 104, "subject": "Anatomy", "difficulty": "Hard", "question": "Transverse acetabular ligament converts the acetabular notch into a foramen through which passes:", "options": [{"key": "A", "text": "Obturator nerve"}, {"key": "B", "text": "Acetabular branch of obturator artery"}, {"key": "C", "text": "Femoral nerve"}, {"key": "D", "text": "Sciatic nerve"}], "correct": "B", "explanation": "Acetabular branch of obturator artery passes through acetabular notch to supply femoral head via ligamentum teres."}, {"id": 105, "subject": "Anatomy", "difficulty": "Easy", "question": "Ligamentum teres (round ligament of femur head) attaches to:", "options": [{"key": "A", "text": "Greater trochanter"}, {"key": "B", "text": "Lesser trochanter"}, {"key": "C", "text": "Fovea capitis of femoral head"}, {"key": "D", "text": "Femoral neck"}], "correct": "C", "explanation": "Ligamentum teres attaches to fovea capitis on femoral head and carries a small artery (in children)."}, {"id": 106, "subject": "Anatomy", "difficulty": "Easy", "question": "Which ligament is the strongest ligament of the hip joint?", "options": [{"key": "A", "text": "Pubofemoral ligament"}, {"key": "B", "text": "Ischiofemoral ligament"}, {"key": "C", "text": "Iliofemoral ligament (Y-ligament of Bigelow)"}, {"key": "D", "text": "Ligamentum teres"}], "correct": "C", "explanation": "Iliofemoral ligament (Y-ligament of Bigelow) is the strongest ligament in the body — prevents hyperextension."}, {"id": 107, "subject": "Anatomy", "difficulty": "Medium", "question": "The Y-ligament of Bigelow (iliofemoral ligament) is attached to which bony landmark?", "options": [{"key": "A", "text": "ASIS to intertrochanteric crest"}, {"key": "B", "text": "AIIS to intertrochanteric line"}, {"key": "C", "text": "ASIS to lesser trochanter"}, {"key": "D", "text": "Ischial spine to greater trochanter"}], "correct": "B", "explanation": "Iliofemoral ligament: AIIS (apex) → two bands to intertrochanteric line (Y-shape)."}, {"id": 108, "subject": "Anatomy", "difficulty": "Hard", "question": "Ischiofemoral ligament prevents which movement at hip?", "options": [{"key": "A", "text": "Flexion"}, {"key": "B", "text": "Extension"}, {"key": "C", "text": "Medial rotation and adduction (especially in extension)"}, {"key": "D", "text": "Abduction"}], "correct": "C", "explanation": "Ischiofemoral ligament (posterior capsule) prevents medial rotation and adduction — tightens in extension."}, {"id": 109, "subject": "Anatomy", "difficulty": "Medium", "question": "Hip joint capsule is attached anteriorly to:", "options": [{"key": "A", "text": "Intertrochanteric crest"}, {"key": "B", "text": "Intertrochanteric line"}, {"key": "C", "text": "Greater trochanter"}, {"key": "D", "text": "Lesser trochanter"}], "correct": "B", "explanation": "Anteriorly, capsule attaches to intertrochanteric line; posteriorly, ~1 cm above intertrochanteric crest."}, {"id": 110, "subject": "Anatomy", "difficulty": "Hard", "question": "Zona orbicularis of hip joint is:", "options": [{"key": "A", "text": "A band of synovium"}, {"key": "B", "text": "A circular band of capsular fibres around femoral neck"}, {"key": "C", "text": "A ligament"}, {"key": "D", "text": "Articular cartilage ring"}], "correct": "B", "explanation": "Zona orbicularis = circular fibres of capsule forming a collar around femoral neck."}, {"id": 111, "subject": "Anatomy", "difficulty": "Medium", "question": "The primary blood supply to femoral head in adults is via:", "options": [{"key": "A", "text": "Ligamentum teres artery"}, {"key": "B", "text": "Medial circumflex femoral artery (retinacular vessels)"}, {"key": "C", "text": "Lateral circumflex femoral artery"}, {"key": "D", "text": "Obturator artery"}], "correct": "B", "explanation": "Medial circumflex femoral artery → retinacular vessels supply most of femoral head in adults."}, {"id": 112, "subject": "Anatomy", "difficulty": "Medium", "question": "Trendelenburg sign is positive when:", "options": [{"key": "A", "text": "Affected leg cannot bear weight"}, {"key": "B", "text": "Pelvis drops on unsupported side (contralateral)"}, {"key": "C", "text": "Pelvis drops on the side of affected hip"}, {"key": "D", "text": "Both legs show limp"}], "correct": "B", "explanation": "Trendelenburg sign: weak abductors (affected side) → pelvis drops on opposite (unsupported) side."}, {"id": 113, "subject": "Anatomy", "difficulty": "Easy", "question": "Trendelenburg gait is caused by weakness of which muscle?", "options": [{"key": "A", "text": "Adductor magnus"}, {"key": "B", "text": "Gluteus maximus"}, {"key": "C", "text": "Gluteus medius and minimus"}, {"key": "D", "text": "Iliopsoas"}], "correct": "C", "explanation": "Gluteus medius & minimus are the hip abductors — weakness = Trendelenburg gait (waddling gait)."}, {"id": 114, "subject": "Anatomy", "difficulty": "Medium", "question": "Posterior dislocation of hip is more common than anterior. The classic posture is:", "options": [{"key": "A", "text": "Hip flexed, abducted, externally rotated"}, {"key": "B", "text": "Hip flexed, adducted, internally rotated"}, {"key": "C", "text": "Hip extended, abducted, externally rotated"}, {"key": "D", "text": "Hip extended, adducted, externally rotated"}], "correct": "B", "explanation": "Posterior dislocation: hip flexed, adducted, internally rotated — limb appears shortened."}, {"id": 115, "subject": "Anatomy", "difficulty": "Medium", "question": "In anterior dislocation of hip, the limb posture is:", "options": [{"key": "A", "text": "Flexed, adducted, internally rotated"}, {"key": "B", "text": "Extended, abducted, externally rotated"}, {"key": "C", "text": "Flexed, abducted, internally rotated"}, {"key": "D", "text": "Extended, adducted, internally rotated"}], "correct": "B", "explanation": "Anterior dislocation: hip extended, abducted, externally rotated — opposite of posterior."}, {"id": 116, "subject": "Anatomy", "difficulty": "Easy", "question": "Nerve most commonly injured in posterior hip dislocation:", "options": [{"key": "A", "text": "Femoral nerve"}, {"key": "B", "text": "Obturator nerve"}, {"key": "C", "text": "Sciatic nerve"}, {"key": "D", "text": "Superior gluteal nerve"}], "correct": "C", "explanation": "Sciatic nerve (especially peroneal division) is at risk in posterior hip dislocation."}, {"id": 117, "subject": "Anatomy", "difficulty": "Medium", "question": "Thomas test specifically detects:", "options": [{"key": "A", "text": "Hip abduction contracture"}, {"key": "B", "text": "Hip flexion deformity (fixed flexion deformity)"}, {"key": "C", "text": "Knee flexion contracture"}, {"key": "D", "text": "Trendelenburg weakness"}], "correct": "B", "explanation": "Thomas test: flex opposite hip fully → fixed flexion deformity of tested hip becomes apparent."}, {"id": 118, "subject": "Anatomy", "difficulty": "Medium", "question": "Ober's test assesses tightness of:", "options": [{"key": "A", "text": "Iliopsoas"}, {"key": "B", "text": "Piriformis"}, {"key": "C", "text": "Iliotibial band / tensor fasciae latae"}, {"key": "D", "text": "Adductors"}], "correct": "C", "explanation": "Ober's test detects IT band / TFL tightness — positive = hip remains abducted when lowered in sidelying."}, {"id": 119, "subject": "Anatomy", "difficulty": "Medium", "question": "FABER test (Patrick's test) is positive in:", "options": [{"key": "A", "text": "ACL tear"}, {"key": "B", "text": "Hip joint pathology or SI joint dysfunction"}, {"key": "C", "text": "Knee meniscus tear"}, {"key": "D", "text": "Tibial stress fracture"}], "correct": "B", "explanation": "FABER = Flexion ABduction External Rotation — stresses hip joint and SI joint."}, {"id": 120, "subject": "Anatomy", "difficulty": "Medium", "question": "FADIR test is used to detect:", "options": [{"key": "A", "text": "Hip labral tear or femoroacetabular impingement (FAI)"}, {"key": "B", "text": "Knee ligament laxity"}, {"key": "C", "text": "Ankle instability"}, {"key": "D", "text": "IT band syndrome"}], "correct": "A", "explanation": "FADIR = Flexion ADduction Internal Rotation — positive in FAI and labral tears."}, {"id": 121, "subject": "Anatomy", "difficulty": "Hard", "question": "In femoroacetabular impingement (FAI), CAM type involves:", "options": [{"key": "A", "text": "Acetabular over-coverage"}, {"key": "B", "text": "Aspherical femoral head-neck junction"}, {"key": "C", "text": "Acetabular retroversion"}, {"key": "D", "text": "Coxa vara"}], "correct": "B", "explanation": "CAM impingement = abnormal femoral head-neck junction (pistol grip deformity) — aspherical head."}, {"id": 122, "subject": "Anatomy", "difficulty": "Hard", "question": "PINCER type FAI is due to:", "options": [{"key": "A", "text": "Abnormal femoral head"}, {"key": "B", "text": "Acetabular over-coverage (coxa profunda/protrusio/retroversion)"}, {"key": "C", "text": "Coxa valga"}, {"key": "D", "text": "Ligamentum teres rupture"}], "correct": "B", "explanation": "PINCER FAI = acetabular over-coverage — linear contact between acetabular rim and femoral neck."}, {"id": 123, "subject": "Anatomy", "difficulty": "Medium", "question": "Normal range of hip flexion is:", "options": [{"key": "A", "text": "90°"}, {"key": "B", "text": "110–120°"}, {"key": "C", "text": "130–140°"}, {"key": "D", "text": "150°"}], "correct": "C", "explanation": "Hip flexion ROM = 0–120° (active), up to 135–140° passively with knee flexed."}, {"id": 124, "subject": "Anatomy", "difficulty": "Medium", "question": "Avascular necrosis of femoral head most commonly occurs after:", "options": [{"key": "A", "text": "Intertrochanteric fracture"}, {"key": "B", "text": "Subcapital fracture of femur neck"}, {"key": "C", "text": "Pelvic fracture"}, {"key": "D", "text": "Femoral shaft fracture"}], "correct": "B", "explanation": "Subcapital fracture disrupts retinacular vessels → AVN in 15–35% cases."}, {"id": 125, "subject": "Anatomy", "difficulty": "Medium", "question": "Garden classification is used for:", "options": [{"key": "A", "text": "Tibial plateau fractures"}, {"key": "B", "text": "Femoral neck fractures"}, {"key": "C", "text": "Talar fractures"}, {"key": "D", "text": "Acetabular fractures"}], "correct": "B", "explanation": "Garden classification (I–IV) grades femoral neck fractures by degree of displacement."}, {"id": 126, "subject": "Anatomy", "difficulty": "Hard", "question": "The obturator nerve (L2,L3,L4) supplies the hip joint and may refer pain to:", "options": [{"key": "A", "text": "Groin and medial thigh/knee"}, {"key": "B", "text": "Buttock and posterior thigh"}, {"key": "C", "text": "Lateral thigh"}, {"key": "D", "text": "Dorsum of foot"}], "correct": "A", "explanation": "Obturator nerve → pain referred to groin and medial knee (Hilton's law — same nerve supplies joint and skin)."}, {"id": 127, "subject": "Anatomy", "difficulty": "Hard", "question": "Snapping hip (coxa saltans) most commonly involves which structure snapping?", "options": [{"key": "A", "text": "Ligamentum teres over acetabular rim"}, {"key": "B", "text": "Iliotibial band over greater trochanter"}, {"key": "C", "text": "Psoas tendon over iliopectineal eminence"}, {"key": "D", "text": "Both B and C are common"}], "correct": "D", "explanation": "External type: IT band over greater trochanter; Internal type: iliopsoas tendon over iliopectineal eminence."}, {"id": 128, "subject": "Anatomy", "difficulty": "Medium", "question": "Shenton's line is disrupted in:", "options": [{"key": "A", "text": "Knee OA"}, {"key": "B", "text": "Hip dislocation or femoral neck fracture"}, {"key": "C", "text": "Ankle fracture"}, {"key": "D", "text": "Tibial plateau fracture"}], "correct": "B", "explanation": "Shenton's line = arc from medial femoral neck to superior obturator foramen — disrupted in hip pathology."}, {"id": 129, "subject": "Anatomy", "difficulty": "Medium", "question": "Legg-Calvé-Perthes disease is AVN of femoral head in children aged:", "options": [{"key": "A", "text": "0–2 years"}, {"key": "B", "text": "2–5 years"}, {"key": "C", "text": "4–8 years"}, {"key": "D", "text": "10–14 years"}], "correct": "C", "explanation": "Perthes disease affects children 4–8 years (peak), boys > girls, unilateral in 90%."}, {"id": 130, "subject": "Anatomy", "difficulty": "Medium", "question": "SUFE (Slipped Upper Femoral Epiphysis) most commonly occurs in:", "options": [{"key": "A", "text": "Toddlers"}, {"key": "B", "text": "School-age children 4–8 years"}, {"key": "C", "text": "Obese adolescents 10–16 years"}, {"key": "D", "text": "Adults"}], "correct": "C", "explanation": "SUFE occurs in obese adolescents during growth spurt — posterior and inferior slip of epiphysis."}, {"id": 131, "subject": "Anatomy", "difficulty": "Easy", "question": "The safe zone for intramuscular injection in gluteal region is:", "options": [{"key": "A", "text": "Upper outer quadrant"}, {"key": "B", "text": "Lower inner quadrant"}, {"key": "C", "text": "Lower outer quadrant"}, {"key": "D", "text": "Centre of buttock"}], "correct": "A", "explanation": "Upper outer quadrant of buttock — avoids sciatic nerve and superior gluteal vessels."}, {"id": 132, "subject": "Anatomy", "difficulty": "Medium", "question": "Piriformis syndrome causes compression of:", "options": [{"key": "A", "text": "Femoral nerve"}, {"key": "B", "text": "Obturator nerve"}, {"key": "C", "text": "Sciatic nerve"}, {"key": "D", "text": "Superior gluteal nerve"}], "correct": "C", "explanation": "Piriformis syndrome = sciatic nerve compressed by piriformis muscle in greater sciatic foramen."}, {"id": 133, "subject": "Anatomy", "difficulty": "Hard", "question": "Coxa profunda/protrusio acetabuli is characterised by:", "options": [{"key": "A", "text": "Shallow acetabulum"}, {"key": "B", "text": "Medial protrusion of femoral head into pelvis"}, {"key": "C", "text": "Coxa vara"}, {"key": "D", "text": "Lateral subluxation"}], "correct": "B", "explanation": "Protrusio acetabuli = medial wall of acetabulum pushed medially → femoral head protrudes into pelvis."}, {"id": 134, "subject": "Anatomy", "difficulty": "Medium", "question": "Which nerve is at risk in total hip replacement (posterior approach)?", "options": [{"key": "A", "text": "Femoral nerve"}, {"key": "B", "text": "Obturator nerve"}, {"key": "C", "text": "Sciatic nerve (peroneal division)"}, {"key": "D", "text": "Lateral femoral cutaneous nerve"}], "correct": "C", "explanation": "Sciatic nerve (especially common peroneal division) is at risk in posterior approach THR."}, {"id": 135, "subject": "Anatomy", "difficulty": "Easy", "question": "Hip joint is a multiaxial joint allowing movements in all EXCEPT:", "options": [{"key": "A", "text": "Flexion-extension"}, {"key": "B", "text": "Abduction-adduction"}, {"key": "C", "text": "Medial-lateral rotation"}, {"key": "D", "text": "Circumduction only in one plane"}], "correct": "D", "explanation": "Hip allows flexion, extension, abduction, adduction, medial/lateral rotation, and circumduction (multiaxial)."}, {"id": 136, "subject": "Anatomy", "difficulty": "Easy", "question": "Knee joint is which type of joint?", "options": [{"key": "A", "text": "Ball and socket"}, {"key": "B", "text": "Simple hinge"}, {"key": "C", "text": "Modified hinge (condylar) joint"}, {"key": "D", "text": "Pivot joint"}], "correct": "C", "explanation": "Knee = modified hinge (condylar) joint — primarily flexion/extension + slight rotation in flexion."}, {"id": 137, "subject": "Anatomy", "difficulty": "Medium", "question": "The knee joint is formed by how many articulations?", "options": [{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}, {"key": "D", "text": "4"}], "correct": "C", "explanation": "Knee = 3 articulations: medial tibiofemoral, lateral tibiofemoral, and patellofemoral joints."}, {"id": 138, "subject": "Anatomy", "difficulty": "Easy", "question": "Which structure deepens the articular surface of tibial condyles?", "options": [{"key": "A", "text": "Cruciate ligaments"}, {"key": "B", "text": "Collateral ligaments"}, {"key": "C", "text": "Medial and lateral menisci"}, {"key": "D", "text": "Patellar tendon"}], "correct": "C", "explanation": "Menisci deepen the tibial articular surface, distribute load, and improve stability."}, {"id": 139, "subject": "Anatomy", "difficulty": "Medium", "question": "Medial meniscus is more commonly injured than lateral meniscus because:", "options": [{"key": "A", "text": "It is larger"}, {"key": "B", "text": "It is firmly attached to medial collateral ligament and capsule (less mobile)"}, {"key": "C", "text": "It bears more weight"}, {"key": "D", "text": "It is thinner"}], "correct": "B", "explanation": "Medial meniscus is less mobile (attached to MCL + capsule) → more susceptible to injury in rotation."}, {"id": 140, "subject": "Anatomy", "difficulty": "Easy", "question": "Anterior cruciate ligament (ACL) prevents:", "options": [{"key": "A", "text": "Posterior translation of tibia on femur"}, {"key": "B", "text": "Anterior translation of tibia on femur + hyperextension"}, {"key": "C", "text": "Valgus stress"}, {"key": "D", "text": "Varus stress"}], "correct": "B", "explanation": "ACL prevents anterior tibial translation on femur and hyperextension."}, {"id": 141, "subject": "Anatomy", "difficulty": "Medium", "question": "ACL is attached on tibia at:", "options": [{"key": "A", "text": "Posterior intercondylar area"}, {"key": "B", "text": "Anterior intercondylar area"}, {"key": "C", "text": "Medial condyle"}, {"key": "D", "text": "Tibial tuberosity"}], "correct": "B", "explanation": "ACL: anterior intercondylar area of tibia → lateral femoral condyle (inner surface)."}, {"id": 142, "subject": "Anatomy", "difficulty": "Easy", "question": "Posterior cruciate ligament (PCL) prevents:", "options": [{"key": "A", "text": "Anterior translation of tibia"}, {"key": "B", "text": "Posterior translation of tibia on femur"}, {"key": "C", "text": "Valgus stress"}, {"key": "D", "text": "Knee hyperextension"}], "correct": "B", "explanation": "PCL is the primary restraint to posterior tibial translation — strongest ligament of knee."}, {"id": 143, "subject": "Anatomy", "difficulty": "Easy", "question": "Lachman test is the most sensitive test for:", "options": [{"key": "A", "text": "PCL tear"}, {"key": "B", "text": "ACL tear"}, {"key": "C", "text": "MCL tear"}, {"key": "D", "text": "Meniscus tear"}], "correct": "B", "explanation": "Lachman test (knee at 20–30° flexion) is the most sensitive test for ACL tear (~85% sensitivity)."}, {"id": 144, "subject": "Anatomy", "difficulty": "Medium", "question": "Anterior drawer test is performed at knee flexion of:", "options": [{"key": "A", "text": "0°"}, {"key": "B", "text": "20–30°"}, {"key": "C", "text": "90°"}, {"key": "D", "text": "Full flexion"}], "correct": "C", "explanation": "Anterior drawer test = knee at 90° flexion; Lachman = 20–30° flexion."}, {"id": 145, "subject": "Anatomy", "difficulty": "Easy", "question": "Posterior drawer test at 90° flexion is positive in:", "options": [{"key": "A", "text": "ACL tear"}, {"key": "B", "text": "MCL tear"}, {"key": "C", "text": "PCL tear"}, {"key": "D", "text": "Meniscus tear"}], "correct": "C", "explanation": "Posterior drawer test: tibia pushed posteriorly at 90° — positive if tibia drops back (PCL tear)."}, {"id": 146, "subject": "Anatomy", "difficulty": "Easy", "question": "McMurray's test is used to detect:", "options": [{"key": "A", "text": "ACL tear"}, {"key": "B", "text": "PCL tear"}, {"key": "C", "text": "Meniscus tear"}, {"key": "D", "text": "MCL tear"}], "correct": "C", "explanation": "McMurray's test: rotation + varus/valgus stress in flexion — click/pain = meniscus tear."}, {"id": 147, "subject": "Anatomy", "difficulty": "Medium", "question": "Apley's grind test differentiates meniscus injury from:", "options": [{"key": "A", "text": "ACL injury"}, {"key": "B", "text": "Ligament injury (distraction test)"}, {"key": "C", "text": "PCL injury"}, {"key": "D", "text": "Patellar injury"}], "correct": "B", "explanation": "Apley's test: compression (grind) → meniscus; distraction → ligament. Differentiates both."}, {"id": 148, "subject": "Anatomy", "difficulty": "Easy", "question": "Valgus stress test at 0° and 30° tests integrity of:", "options": [{"key": "A", "text": "ACL"}, {"key": "B", "text": "PCL"}, {"key": "C", "text": "MCL"}, {"key": "D", "text": "LCL"}], "correct": "C", "explanation": "Valgus stress test at 30° = MCL; at 0° (full extension) = MCL + posterior capsule."}, {"id": 149, "subject": "Anatomy", "difficulty": "Medium", "question": "Lateral collateral ligament (LCL) is attached to:", "options": [{"key": "A", "text": "Fibular head and lateral femoral condyle"}, {"key": "B", "text": "Fibular head and medial femoral condyle"}, {"key": "C", "text": "Tibia and femur"}, {"key": "D", "text": "Tibia and fibula"}], "correct": "A", "explanation": "LCL (fibular collateral ligament) = lateral femoral condyle → fibular head (cord-like, not attached to capsule)."}, {"id": 150, "subject": "Anatomy", "difficulty": "Medium", "question": "The unhappy triad (O'Donoghue's triad) of knee injuries consists of:", "options": [{"key": "A", "text": "ACL + PCL + medial meniscus"}, {"key": "B", "text": "ACL + MCL + medial meniscus"}, {"key": "C", "text": "ACL + LCL + lateral meniscus"}, {"key": "D", "text": "PCL + MCL + medial meniscus"}], "correct": "B", "explanation": "Unhappy triad = ACL + MCL + medial meniscus — from valgus + rotational force."}, {"id": 151, "subject": "Anatomy", "difficulty": "Easy", "question": "Patella is the largest sesamoid bone in the body. It is embedded in:", "options": [{"key": "A", "text": "ACL"}, {"key": "B", "text": "Quadriceps tendon / patellar tendon"}, {"key": "C", "text": "MCL"}, {"key": "D", "text": "IT band"}], "correct": "B", "explanation": "Patella is embedded in the quadriceps tendon (above) and continues as patellar tendon (below)."}, {"id": 152, "subject": "Anatomy", "difficulty": "Medium", "question": "The Q-angle is the angle between the quadriceps pull and patellar tendon. Increased Q-angle causes:", "options": [{"key": "A", "text": "Patellar medial subluxation"}, {"key": "B", "text": "Patellar lateral subluxation"}, {"key": "C", "text": "ACL tear"}, {"key": "D", "text": "PCL tear"}], "correct": "B", "explanation": "Increased Q-angle (>20° in females) increases lateral patellar subluxation risk."}, {"id": 153, "subject": "Anatomy", "difficulty": "Medium", "question": "Clarke's sign (patellar grind test) is positive in:", "options": [{"key": "A", "text": "ACL tear"}, {"key": "B", "text": "Chondromalacia patellae"}, {"key": "C", "text": "Meniscus tear"}, {"key": "D", "text": "LCL injury"}], "correct": "B", "explanation": "Clarke's sign: pressing patella distally and asking patient to contract quad — pain = chondromalacia."}, {"id": 154, "subject": "Anatomy", "difficulty": "Hard", "question": "The popliteus muscle 'unlocks' the knee by producing:", "options": [{"key": "A", "text": "Lateral rotation of tibia"}, {"key": "B", "text": "Medial rotation of tibia on femur (or lateral rotation of femur)"}, {"key": "C", "text": "Extension at terminal range"}, {"key": "D", "text": "Posterior translation of tibia"}], "correct": "B", "explanation": "Popliteus unlocks the fully extended (screwed-home) knee by medially rotating tibia (or laterally rotating femur)."}, {"id": 155, "subject": "Anatomy", "difficulty": "Hard", "question": "Screw-home mechanism of knee occurs during the last degrees of extension. It involves:", "options": [{"key": "A", "text": "Medial rotation of femur"}, {"key": "B", "text": "Lateral rotation of tibia on femur"}, {"key": "C", "text": "Flexion of knee"}, {"key": "D", "text": "Patellar tilt"}], "correct": "B", "explanation": "Screw-home: last 10–15° of knee extension → tibia laterally rotates → locks joint (close-packed)."}, {"id": 156, "subject": "Anatomy", "difficulty": "Hard", "question": "The suprapatellar bursa communicates with the knee joint at what age?", "options": [{"key": "A", "text": "Birth"}, {"key": "B", "text": "By age 3–6 months"}, {"key": "C", "text": "Adolescence"}, {"key": "D", "text": "It never communicates"}], "correct": "B", "explanation": "Suprapatellar bursa communicates with knee joint synovial cavity by ~6 months of age."}, {"id": 157, "subject": "Anatomy", "difficulty": "Hard", "question": "The oblique popliteal ligament is an expansion of which muscle?", "options": [{"key": "A", "text": "Biceps femoris"}, {"key": "B", "text": "Semimembranosus"}, {"key": "C", "text": "Popliteus"}, {"key": "D", "text": "Gastrocnemius"}], "correct": "B", "explanation": "Oblique popliteal ligament = expansion of semimembranosus tendon — reinforces posterior capsule."}, {"id": 158, "subject": "Anatomy", "difficulty": "Hard", "question": "Arcuate ligament of knee reinforces which aspect of the capsule?", "options": [{"key": "A", "text": "Anterior"}, {"key": "B", "text": "Medial"}, {"key": "C", "text": "Posterolateral"}, {"key": "D", "text": "Posteromedial"}], "correct": "C", "explanation": "Arcuate ligament = Y-shaped reinforcement of posterolateral capsule — part of posterolateral corner."}, {"id": 159, "subject": "Anatomy", "difficulty": "Medium", "question": "Pes anserinus bursitis causes pain at:", "options": [{"key": "A", "text": "Lateral knee"}, {"key": "B", "text": "Medial knee below joint line"}, {"key": "C", "text": "Posterior knee (popliteal fossa)"}, {"key": "D", "text": "Anterior knee"}], "correct": "B", "explanation": "Pes anserinus bursa is between the conjoined tendon (sartorius, gracilis, semitendinosus) and MCL — medial pain."}, {"id": 160, "subject": "Anatomy", "difficulty": "Medium", "question": "Baker's cyst (popliteal cyst) is a distension of which bursa?", "options": [{"key": "A", "text": "Prepatellar bursa"}, {"key": "B", "text": "Suprapatellar bursa"}, {"key": "C", "text": "Gastrocnemio-semimembranosus bursa"}, {"key": "D", "text": "Pes anserinus bursa"}], "correct": "C", "explanation": "Baker's cyst = gastrocnemio-semimembranosus bursa distension — communicates with knee in adults."}, {"id": 161, "subject": "Anatomy", "difficulty": "Hard", "question": "The lateral meniscus is more mobile than medial because:", "options": [{"key": "A", "text": "It is larger"}, {"key": "B", "text": "It has no attachment to LCL or popliteus"}, {"key": "C", "text": "It is attached to the capsule only anteriorly"}, {"key": "D", "text": "It is thicker"}], "correct": "B", "explanation": "Lateral meniscus is not attached to LCL (separated by popliteus tendon) → more mobile → less torn."}, {"id": 162, "subject": "Anatomy", "difficulty": "Easy", "question": "Osgood-Schlatter disease is caused by traction on patellar tendon at:", "options": [{"key": "A", "text": "Tibial tuberosity apophysis"}, {"key": "B", "text": "Patellar lower pole"}, {"key": "C", "text": "Tibial shaft"}, {"key": "D", "text": "Femoral condyle"}], "correct": "A", "explanation": "Osgood-Schlatter = repetitive traction apophysitis of tibial tuberosity — adolescents."}, {"id": 163, "subject": "Anatomy", "difficulty": "Hard", "question": "Which test is used to assess posterolateral corner (PLC) of knee?", "options": [{"key": "A", "text": "Lachman test"}, {"key": "B", "text": "Dial test (tibial external rotation at 30° and 90°)"}, {"key": "C", "text": "McMurray test"}, {"key": "D", "text": "Valgus stress test"}], "correct": "B", "explanation": "Dial test: ER of tibia at 30° = PLC injury; at both 30° and 90° = PLC + PCL injury."}, {"id": 164, "subject": "Anatomy", "difficulty": "Medium", "question": "The medial compartment of knee is most commonly affected in OA. Varus deformity develops because:", "options": [{"key": "A", "text": "Medial cartilage loss → varus"}, {"key": "B", "text": "Lateral cartilage loss → varus"}, {"key": "C", "text": "Ligament laxity only"}, {"key": "D", "text": "Muscular imbalance"}], "correct": "A", "explanation": "Medial compartment OA → medial cartilage loss → knee bows medially (genu varum)."}, {"id": 165, "subject": "Anatomy", "difficulty": "Hard", "question": "Pivot shift test (MacIntosh test) is specific for:", "options": [{"key": "A", "text": "PCL tear"}, {"key": "B", "text": "ACL tear with anterolateral instability"}, {"key": "C", "text": "MCL tear"}, {"key": "D", "text": "Meniscus bucket handle tear"}], "correct": "B", "explanation": "Pivot shift = subluxation-reduction of lateral tibial plateau — specific for ACL tear."}, {"id": 166, "subject": "Anatomy", "difficulty": "Medium", "question": "The knee joint is most stable in which position?", "options": [{"key": "A", "text": "90° flexion"}, {"key": "B", "text": "45° flexion"}, {"key": "C", "text": "Full extension (close-packed)"}, {"key": "D", "text": "20° flexion"}], "correct": "C", "explanation": "Close-packed position of knee = full extension (screw-home mechanism locks it)."}, {"id": 167, "subject": "Anatomy", "difficulty": "Easy", "question": "Prepatellar bursitis ('housemaid's knee') causes swelling:", "options": [{"key": "A", "text": "Behind the knee"}, {"key": "B", "text": "Above the patella"}, {"key": "C", "text": "Over the patella (superficial to it)"}, {"key": "D", "text": "Below tibial tuberosity"}], "correct": "C", "explanation": "Prepatellar bursa is anterior to patella — inflamed by prolonged kneeling."}, {"id": 168, "subject": "Anatomy", "difficulty": "Medium", "question": "Infrapatellar fat pad (Hoffa's fat pad) is located:", "options": [{"key": "A", "text": "Above patella"}, {"key": "B", "text": "Behind the patellar tendon between it and tibia"}, {"key": "C", "text": "Medial to patella"}, {"key": "D", "text": "In popliteal fossa"}], "correct": "B", "explanation": "Hoffa's fat pad is between the patellar tendon anteriorly and synovium posteriorly."}, {"id": 169, "subject": "Anatomy", "difficulty": "Hard", "question": "The nerve supply of knee joint is from all EXCEPT:", "options": [{"key": "A", "text": "Femoral nerve"}, {"key": "B", "text": "Obturator nerve"}, {"key": "C", "text": "Sciatic nerve"}, {"key": "D", "text": "Lateral femoral cutaneous nerve"}], "correct": "D", "explanation": "Knee joint supply: femoral, obturator, common peroneal, tibial (from sciatic). Lateral femoral cutaneous supplies skin, not joint."}, {"id": 170, "subject": "Anatomy", "difficulty": "Medium", "question": "Discoid meniscus is most common in which meniscus?", "options": [{"key": "A", "text": "Medial"}, {"key": "B", "text": "Lateral"}, {"key": "C", "text": "Both equally"}, {"key": "D", "text": "Posterior horn only"}], "correct": "B", "explanation": "Lateral discoid meniscus is more common — disc-shaped instead of C-shaped, causes snapping knee."}, {"id": 171, "subject": "Anatomy", "difficulty": "Easy", "question": "Ankle (talocrural) joint is which type of joint?", "options": [{"key": "A", "text": "Ball and socket"}, {"key": "B", "text": "Condyloid"}, {"key": "C", "text": "Hinge (ginglymus) joint"}, {"key": "D", "text": "Pivot"}], "correct": "C", "explanation": "Ankle = hinge (ginglymus) synovial joint — allows dorsiflexion and plantarflexion."}, {"id": 172, "subject": "Anatomy", "difficulty": "Easy", "question": "The ankle mortise is formed by:", "options": [{"key": "A", "text": "Tibia and talus"}, {"key": "B", "text": "Tibia, fibula (malleoli) and talus"}, {"key": "C", "text": "Tibia, fibula and calcaneus"}, {"key": "D", "text": "Fibula and calcaneus"}], "correct": "B", "explanation": "Ankle mortise = distal tibia (plafond) + medial malleolus + lateral malleolus gripping the talar dome."}, {"id": 173, "subject": "Anatomy", "difficulty": "Easy", "question": "Which surface of talus articulates in the ankle joint?", "options": [{"key": "A", "text": "Talar head"}, {"key": "B", "text": "Talar neck"}, {"key": "C", "text": "Talar dome (trochlea)"}, {"key": "D", "text": "Posterior process"}], "correct": "C", "explanation": "Talar dome (trochlea) articulates with tibial plafond above and malleoli on each side."}, {"id": 174, "subject": "Anatomy", "difficulty": "Medium", "question": "The talar dome is wider anteriorly. This makes ankle more stable in:", "options": [{"key": "A", "text": "Plantarflexion"}, {"key": "B", "text": "Dorsiflexion"}, {"key": "C", "text": "Inversion"}, {"key": "D", "text": "Eversion"}], "correct": "B", "explanation": "Wider anterior talus wedges into mortise during dorsiflexion → more stable. Plantarflexion is less stable."}, {"id": 175, "subject": "Anatomy", "difficulty": "Easy", "question": "Most ankle sprains are due to which mechanism?", "options": [{"key": "A", "text": "Eversion injury"}, {"key": "B", "text": "Inversion injury"}, {"key": "C", "text": "Dorsiflexion injury"}, {"key": "D", "text": "Plantarflexion injury"}], "correct": "B", "explanation": "85% ankle sprains = inversion (lateral ligament injuries — ATFL most commonly)."}, {"id": 176, "subject": "Anatomy", "difficulty": "Medium", "question": "The lateral ligament of ankle consists of three bands. Arrange from most to least commonly injured:", "options": [{"key": "A", "text": "ATFL > CFL > PTFL"}, {"key": "B", "text": "CFL > ATFL > PTFL"}, {"key": "C", "text": "PTFL > CFL > ATFL"}, {"key": "D", "text": "ATFL > PTFL > CFL"}], "correct": "A", "explanation": "ATFL (anterior talofibular) > CFL (calcaneofibular) > PTFL (posterior talofibular) — in order of injury frequency."}, {"id": 177, "subject": "Anatomy", "difficulty": "Medium", "question": "Deltoid ligament is the medial ligament of ankle. It is injured in:", "options": [{"key": "A", "text": "Inversion sprain"}, {"key": "B", "text": "Eversion injury / severe pronation trauma"}, {"key": "C", "text": "Plantarflexion"}, {"key": "D", "text": "Dorsiflexion only"}], "correct": "B", "explanation": "Deltoid (medial collateral) ligament is very strong — injured in eversion injuries or Pott's fractures."}, {"id": 178, "subject": "Anatomy", "difficulty": "Hard", "question": "The deltoid ligament has how many parts?", "options": [{"key": "A", "text": "2 (superficial and deep)"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}], "correct": "C", "explanation": "Deltoid ligament = 4 parts: tibionavicular, tibiocalcaneal, anterior tibiotalar, posterior tibiotalar."}, {"id": 179, "subject": "Anatomy", "difficulty": "Medium", "question": "Ottawa ankle rules indicate X-ray if there is:", "options": [{"key": "A", "text": "Any ankle pain"}, {"key": "B", "text": "Tenderness over lateral malleolus + inability to bear weight"}, {"key": "C", "text": "Swelling only"}, {"key": "D", "text": "Pain on dorsiflexion"}], "correct": "B", "explanation": "Ottawa rules: bony tenderness at posterior malleoli or base of 5th MT/navicular + inability to weight-bear → X-ray needed."}, {"id": 180, "subject": "Anatomy", "difficulty": "Easy", "question": "The subtalar (talocalcaneal) joint produces which movements?", "options": [{"key": "A", "text": "Dorsiflexion and plantarflexion"}, {"key": "B", "text": "Inversion and eversion of hindfoot"}, {"key": "C", "text": "Toe flexion and extension"}, {"key": "D", "text": "Rotation only"}], "correct": "B", "explanation": "Subtalar joint = triplanar motion producing inversion/eversion (supination/pronation) of hindfoot."}, {"id": 181, "subject": "Anatomy", "difficulty": "Easy", "question": "Simmond's (Thompson) test is positive when:", "options": [{"key": "A", "text": "Ankle doesn't plantarflex on calf squeeze"}, {"key": "B", "text": "Ankle is painful on dorsiflexion"}, {"key": "C", "text": "Ankle swells on compression"}, {"key": "D", "text": "Deltoid ligament is lax"}], "correct": "A", "explanation": "Simmonds/Thompson test: squeeze calf → no plantarflexion = Achilles tendon rupture."}, {"id": 182, "subject": "Anatomy", "difficulty": "Easy", "question": "Achilles tendon is the combined tendon of:", "options": [{"key": "A", "text": "Gastrocnemius only"}, {"key": "B", "text": "Soleus only"}, {"key": "C", "text": "Gastrocnemius + soleus (triceps surae)"}, {"key": "D", "text": "Gastrocnemius + plantaris"}], "correct": "C", "explanation": "Achilles tendon = gastrocnemius + soleus (triceps surae) → inserts into calcaneal tuberosity."}, {"id": 183, "subject": "Anatomy", "difficulty": "Medium", "question": "The watershed zone of Achilles tendon (most prone to rupture) is located:", "options": [{"key": "A", "text": "At calcaneal insertion"}, {"key": "B", "text": "2–6 cm proximal to calcaneal insertion"}, {"key": "C", "text": "At musculotendinous junction"}, {"key": "D", "text": "At myotendinous junction"}], "correct": "B", "explanation": "Achilles watershed zone (poorest blood supply) = 2–6 cm proximal to insertion → common rupture site."}, {"id": 184, "subject": "Anatomy", "difficulty": "Medium", "question": "Achilles tendon rupture is most commonly seen in:", "options": [{"key": "A", "text": "Young athletes"}, {"key": "B", "text": "Middle-aged recreational athletes (30–50 years)"}, {"key": "C", "text": "Elderly >70 years"}, {"key": "D", "text": "Children"}], "correct": "B", "explanation": "Achilles rupture most common in 'weekend warriors' — middle-aged recreational athletes."}, {"id": 185, "subject": "Anatomy", "difficulty": "Hard", "question": "Anterior talofibular ligament (ATFL) resists which movement?", "options": [{"key": "A", "text": "Eversion of ankle"}, {"key": "B", "text": "Anterior translation of talus and internal rotation in plantarflexion"}, {"key": "C", "text": "Dorsiflexion"}, {"key": "D", "text": "External rotation"}], "correct": "B", "explanation": "ATFL becomes the main stabilizer in plantarflexion — resists anterior talar translation + IR."}, {"id": 186, "subject": "Anatomy", "difficulty": "Medium", "question": "Anterior drawer test of ankle assesses integrity of:", "options": [{"key": "A", "text": "Deltoid ligament"}, {"key": "B", "text": "ATFL"}, {"key": "C", "text": "CFL"}, {"key": "D", "text": "PTFL"}], "correct": "B", "explanation": "Anterior drawer test: foot in 20° plantarflexion, stabilize tibia, push talus anteriorly — tests ATFL."}, {"id": 187, "subject": "Anatomy", "difficulty": "Medium", "question": "Talar tilt test assesses:", "options": [{"key": "A", "text": "ATFL"}, {"key": "B", "text": "CFL (and ATFL if severe)"}, {"key": "C", "text": "Deltoid ligament"}, {"key": "D", "text": "Syndesmosis"}], "correct": "B", "explanation": "Talar tilt test: inversion stress — primarily tests CFL (calcaneofibular ligament)."}, {"id": 188, "subject": "Anatomy", "difficulty": "Medium", "question": "High ankle sprain (syndesmotic sprain) injury involves:", "options": [{"key": "A", "text": "ATFL and CFL"}, {"key": "B", "text": "Anterior tibiofibular ligament and interosseous membrane"}, {"key": "C", "text": "Deltoid ligament"}, {"key": "D", "text": "Subtalar joint"}], "correct": "B", "explanation": "High ankle sprain = syndesmotic injury (anterior tibiofibular ligament + interosseous membrane) from ER force."}, {"id": 189, "subject": "Anatomy", "difficulty": "Medium", "question": "Squeeze test for ankle syndesmosis: squeeze fibula to tibia at mid-calf causes:", "options": [{"key": "A", "text": "Pain at subtalar joint"}, {"key": "B", "text": "Pain at ankle (syndesmosis) = positive"}, {"key": "C", "text": "Fibular fracture"}, {"key": "D", "text": "Negative always"}], "correct": "B", "explanation": "Squeeze test: compression at mid-fibula-tibia → pain at distal syndesmosis = syndesmotic sprain."}, {"id": 190, "subject": "Anatomy", "difficulty": "Medium", "question": "The tarsal tunnel syndrome is compression of which nerve?", "options": [{"key": "A", "text": "Common peroneal nerve"}, {"key": "B", "text": "Superficial peroneal nerve"}, {"key": "C", "text": "Posterior tibial nerve"}, {"key": "D", "text": "Sural nerve"}], "correct": "C", "explanation": "Tarsal tunnel syndrome = posterior tibial nerve compressed under flexor retinaculum behind medial malleolus."}, {"id": 191, "subject": "Anatomy", "difficulty": "Medium", "question": "Peroneal tendons pass posterior to which structure at ankle?", "options": [{"key": "A", "text": "Medial malleolus"}, {"key": "B", "text": "Lateral malleolus"}, {"key": "C", "text": "Calcaneus"}, {"key": "D", "text": "Navicular"}], "correct": "B", "explanation": "Peroneus longus and brevis pass posterior to lateral malleolus in a groove, held by superior peroneal retinaculum."}, {"id": 192, "subject": "Anatomy", "difficulty": "Hard", "question": "Peroneal tendon subluxation occurs due to rupture of:", "options": [{"key": "A", "text": "Inferior peroneal retinaculum"}, {"key": "B", "text": "Superior peroneal retinaculum"}, {"key": "C", "text": "Calcaneofibular ligament"}, {"key": "D", "text": "ATFL"}], "correct": "B", "explanation": "Superior peroneal retinaculum rupture → peroneal tendon subluxation/dislocation anteriorly."}, {"id": 193, "subject": "Anatomy", "difficulty": "Easy", "question": "Plantar fasciitis causes heel pain most severe:", "options": [{"key": "A", "text": "After rest, first steps in morning"}, {"key": "B", "text": "During running only"}, {"key": "C", "text": "At night"}, {"key": "D", "text": "On dorsiflexion of toes"}], "correct": "A", "explanation": "Plantar fasciitis pain is worst with first steps in morning (after rest) — fascia tightens overnight."}, {"id": 194, "subject": "Anatomy", "difficulty": "Easy", "question": "The plantar fascia (plantar aponeurosis) originates from:", "options": [{"key": "A", "text": "Navicular tuberosity"}, {"key": "B", "text": "Medial calcaneal tuberosity"}, {"key": "C", "text": "Cuboid"}, {"key": "D", "text": "Talus"}], "correct": "B", "explanation": "Plantar fascia arises from medial calcaneal tuberosity and inserts into bases of proximal phalanges."}, {"id": 195, "subject": "Anatomy", "difficulty": "Medium", "question": "Windlass mechanism refers to:", "options": [{"key": "A", "text": "Subtalar joint locking"}, {"key": "B", "text": "Tightening of plantar fascia on toe dorsiflexion → raises medial arch"}, {"key": "C", "text": "Achilles tendon elastic recoil"}, {"key": "D", "text": "Peroneal tendon stabilisation"}], "correct": "B", "explanation": "Windlass mechanism: hallux dorsiflexion tightens plantar fascia → raises medial longitudinal arch."}, {"id": 196, "subject": "Anatomy", "difficulty": "Hard", "question": "Haglund's deformity is a bony prominence at:", "options": [{"key": "A", "text": "Base of 5th metatarsal"}, {"key": "B", "text": "Posterior-superior calcaneus (pump bump)"}, {"key": "C", "text": "Navicular tuberosity"}, {"key": "D", "text": "Medial malleolus"}], "correct": "B", "explanation": "Haglund's deformity = posterosuperior calcaneal prominence → retrocalcaneal bursitis + Achilles impingement."}, {"id": 197, "subject": "Anatomy", "difficulty": "Medium", "question": "The close-packed position of ankle joint is:", "options": [{"key": "A", "text": "Plantarflexion"}, {"key": "B", "text": "Neutral"}, {"key": "C", "text": "Maximum dorsiflexion"}, {"key": "D", "text": "Inversion"}], "correct": "C", "explanation": "Close-packed (most stable) position of ankle = maximum dorsiflexion — wider talus locked in mortise."}, {"id": 198, "subject": "Anatomy", "difficulty": "Hard", "question": "Lateral process of talus fracture is called:", "options": [{"key": "A", "text": "Aviator's astragalus"}, {"key": "B", "text": "Snowboarder's fracture"}, {"key": "C", "text": "Jones fracture"}, {"key": "D", "text": "Lisfranc fracture"}], "correct": "B", "explanation": "Snowboarder's fracture = lateral talar process fracture — from dorsiflexion + inversion in snowboarding."}, {"id": 199, "subject": "Anatomy", "difficulty": "Medium", "question": "Jones fracture is a fracture at the base of:", "options": [{"key": "A", "text": "1st metatarsal"}, {"key": "B", "text": "2nd metatarsal"}, {"key": "C", "text": "4th metatarsal"}, {"key": "D", "text": "5th metatarsal (junction of proximal metaphysis and diaphysis)"}], "correct": "D", "explanation": "Jones fracture = 5th MT at meta-diaphyseal junction (~1.5 cm distal to styloid) — poor healing, high nonunion."}, {"id": 200, "subject": "Anatomy", "difficulty": "Medium", "question": "Which ankle ligament injury accompanies a Pott's fracture (bimalleolar injury)?", "options": [{"key": "A", "text": "ATFL"}, {"key": "B", "text": "CFL"}, {"key": "C", "text": "Deltoid ligament (medial)"}, {"key": "D", "text": "PTFL"}], "correct": "C", "explanation": "Pott's fracture = fibula fracture + either medial malleolus fracture or deltoid ligament tear."}, {"id": 201, "subject": "Anatomy", "difficulty": "Easy", "question": "Which part of humerus articulates with glenoid cavity?", "options": [{"key": "A", "text": "Capitulum"}, {"key": "B", "text": "Trochlea"}, {"key": "C", "text": "Head"}, {"key": "D", "text": "Greater tubercle"}], "correct": "C", "explanation": "Head of humerus is the rounded part that fits into glenoid cavity of scapula forming glenohumeral joint."}, {"id": 202, "subject": "Anatomy", "difficulty": "Easy", "question": "Greater tubercle of humerus gives attachment to which muscle?", "options": [{"key": "A", "text": "Subscapularis"}, {"key": "B", "text": "Supraspinatus"}, {"key": "C", "text": "Coracobrachialis"}, {"key": "D", "text": "Biceps brachii"}], "correct": "B", "explanation": "Supraspinatus inserts on the highest facet of greater tubercle; infraspinatus and teres minor on middle and lower facets."}, {"id": 203, "subject": "Anatomy", "difficulty": "Medium", "question": "Lesser tubercle of humerus is the insertion for which muscle?", "options": [{"key": "A", "text": "Supraspinatus"}, {"key": "B", "text": "Infraspinatus"}, {"key": "C", "text": "Subscapularis"}, {"key": "D", "text": "Teres minor"}], "correct": "C", "explanation": "Subscapularis inserts on lesser tubercle; it is the only rotator cuff muscle inserting on lesser tubercle."}, {"id": 204, "subject": "Anatomy", "difficulty": "Easy", "question": "Surgical neck of humerus is vulnerable to injury involving which nerve?", "options": [{"key": "A", "text": "Radial nerve"}, {"key": "B", "text": "Axillary nerve"}, {"key": "C", "text": "Musculocutaneous nerve"}, {"key": "D", "text": "Median nerve"}], "correct": "B", "explanation": "Axillary nerve winds around surgical neck of humerus; fracture here commonly damages this nerve."}, {"id": 205, "subject": "Anatomy", "difficulty": "Easy", "question": "Radial groove (spiral groove) of humerus transmits which structure?", "options": [{"key": "A", "text": "Median nerve and brachial artery"}, {"key": "B", "text": "Ulnar nerve"}, {"key": "C", "text": "Radial nerve and profunda brachii artery"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "C", "explanation": "Radial nerve and profunda brachii artery lie in the radial groove on the posterior shaft of humerus."}, {"id": 206, "subject": "Anatomy", "difficulty": "Easy", "question": "Which epicondyle of humerus gives origin to common flexor tendons?", "options": [{"key": "A", "text": "Lateral epicondyle"}, {"key": "B", "text": "Medial epicondyle"}, {"key": "C", "text": "Capitulum"}, {"key": "D", "text": "Trochlea"}], "correct": "B", "explanation": "Medial epicondyle is the common origin of wrist and finger flexors (tennis elbow medial type)."}, {"id": 207, "subject": "Anatomy", "difficulty": "Easy", "question": "Lateral epicondyle of humerus gives origin to which muscles?", "options": [{"key": "A", "text": "Wrist flexors"}, {"key": "B", "text": "Common extensor muscles"}, {"key": "C", "text": "Pronator teres"}, {"key": "D", "text": "Flexor carpi ulnaris"}], "correct": "B", "explanation": "Common extensor origin: extensor carpi radialis brevis, extensor digitorum, extensor digiti minimi, extensor carpi ulnaris."}, {"id": 208, "subject": "Anatomy", "difficulty": "Easy", "question": "Trochlea of humerus articulates with which bone?", "options": [{"key": "A", "text": "Head of radius"}, {"key": "B", "text": "Olecranon of ulna"}, {"key": "C", "text": "Trochlear notch of ulna"}, {"key": "D", "text": "Coronoid process of ulna"}], "correct": "C", "explanation": "Trochlea articulates with the trochlear notch (semilunar notch) of ulna at the elbow joint."}, {"id": 209, "subject": "Anatomy", "difficulty": "Easy", "question": "Capitulum of humerus articulates with which structure?", "options": [{"key": "A", "text": "Olecranon"}, {"key": "B", "text": "Head of radius"}, {"key": "C", "text": "Coronoid process"}, {"key": "D", "text": "Radial notch of ulna"}], "correct": "B", "explanation": "Capitulum is the rounded lateral part of the distal humerus that articulates with the head of radius."}, {"id": 210, "subject": "Anatomy", "difficulty": "Easy", "question": "Deltoid tuberosity is located on which part of humerus?", "options": [{"key": "A", "text": "Upper third"}, {"key": "B", "text": "Middle third"}, {"key": "C", "text": "Lower third"}, {"key": "D", "text": "Near surgical neck"}], "correct": "B", "explanation": "Deltoid tuberosity is a roughened area on the lateral aspect of the middle third of the humeral shaft."}, {"id": 211, "subject": "Anatomy", "difficulty": "Easy", "question": "Which fossa of humerus accommodates the olecranon in full extension?", "options": [{"key": "A", "text": "Coronoid fossa"}, {"key": "B", "text": "Radial fossa"}, {"key": "C", "text": "Olecranon fossa"}, {"key": "D", "text": "Cubital fossa"}], "correct": "C", "explanation": "Olecranon fossa is a posterior depression that receives the olecranon process during elbow extension."}, {"id": 212, "subject": "Anatomy", "difficulty": "Medium", "question": "Coronoid fossa of humerus is on which surface?", "options": [{"key": "A", "text": "Posterior"}, {"key": "B", "text": "Lateral"}, {"key": "C", "text": "Anterior"}, {"key": "D", "text": "Medial"}], "correct": "C", "explanation": "Coronoid fossa is on the anterior surface of distal humerus; it receives the coronoid process in full flexion."}, {"id": 213, "subject": "Anatomy", "difficulty": "Easy", "question": "Ulnar nerve passes behind which structure at the elbow?", "options": [{"key": "A", "text": "Lateral epicondyle"}, {"key": "B", "text": "Medial epicondyle"}, {"key": "C", "text": "Olecranon"}, {"key": "D", "text": "Head of radius"}], "correct": "B", "explanation": "Ulnar nerve passes through the cubital tunnel behind the medial epicondyle, vulnerable to 'funny bone' injury."}, {"id": 214, "subject": "Anatomy", "difficulty": "Hard", "question": "Fracture of anatomical neck of humerus affects which structure primarily?", "options": [{"key": "A", "text": "Axillary nerve"}, {"key": "B", "text": "Blood supply to head"}, {"key": "C", "text": "Radial nerve"}, {"key": "D", "text": "Brachial plexus"}], "correct": "B", "explanation": "Anatomical neck fracture disrupts blood supply to humeral head causing avascular necrosis risk."}, {"id": 215, "subject": "Anatomy", "difficulty": "Easy", "question": "Intertubercular (bicipital) groove lies between which structures?", "options": [{"key": "A", "text": "Head and greater tubercle"}, {"key": "B", "text": "Greater and lesser tubercles"}, {"key": "C", "text": "Capitulum and trochlea"}, {"key": "D", "text": "Medial and lateral epicondyles"}], "correct": "B", "explanation": "The bicipital groove between greater and lesser tubercles transmits the long head of biceps tendon."}, {"id": 216, "subject": "Anatomy", "difficulty": "Easy", "question": "Which tendon runs in the intertubercular groove of humerus?", "options": [{"key": "A", "text": "Short head of biceps"}, {"key": "B", "text": "Long head of biceps"}, {"key": "C", "text": "Coracobrachialis"}, {"key": "D", "text": "Subscapularis"}], "correct": "B", "explanation": "Long head of biceps tendon runs in the intertubercular groove held by transverse humeral ligament."}, {"id": 217, "subject": "Anatomy", "difficulty": "Hard", "question": "Teres major inserts on which part of humerus?", "options": [{"key": "A", "text": "Lesser tubercle"}, {"key": "B", "text": "Greater tubercle"}, {"key": "C", "text": "Medial lip of bicipital groove"}, {"key": "D", "text": "Lateral lip of bicipital groove"}], "correct": "C", "explanation": "Teres major inserts on the medial lip of intertubercular groove; latissimus dorsi on the floor."}, {"id": 218, "subject": "Anatomy", "difficulty": "Medium", "question": "Pectoralis major inserts on which part of humerus?", "options": [{"key": "A", "text": "Greater tubercle"}, {"key": "B", "text": "Lesser tubercle"}, {"key": "C", "text": "Lateral lip of intertubercular groove"}, {"key": "D", "text": "Medial lip of intertubercular groove"}], "correct": "C", "explanation": "Pectoralis major inserts on the lateral lip of bicipital groove (intertubercular groove)."}, {"id": 219, "subject": "Anatomy", "difficulty": "Hard", "question": "Carrying angle at elbow is due to which feature of humerus?", "options": [{"key": "A", "text": "Oblique trochlea"}, {"key": "B", "text": "Medial epicondyle projection"}, {"key": "C", "text": "Capitulum prominence"}, {"key": "D", "text": "Lateral condyle tilt"}], "correct": "A", "explanation": "The oblique orientation of trochlea causes the carrying angle (physiological valgus) of the elbow."}, {"id": 220, "subject": "Anatomy", "difficulty": "Medium", "question": "Normal carrying angle in males is approximately:", "options": [{"key": "A", "text": "5-10 degrees"}, {"key": "B", "text": "10-15 degrees"}, {"key": "C", "text": "15-20 degrees"}, {"key": "D", "text": "20-25 degrees"}], "correct": "A", "explanation": "Carrying angle is 5-10° in males and 10-15° in females; greater angles indicate cubitus valgus."}, {"id": 221, "subject": "Anatomy", "difficulty": "Easy", "question": "Head of radius is located at which end?", "options": [{"key": "A", "text": "Distal"}, {"key": "B", "text": "Middle"}, {"key": "C", "text": "Proximal"}, {"key": "D", "text": "Medial"}], "correct": "C", "explanation": "Head of radius is at the proximal end; it articulates with capitulum of humerus and radial notch of ulna."}, {"id": 222, "subject": "Anatomy", "difficulty": "Easy", "question": "Radial tuberosity is the insertion for which muscle?", "options": [{"key": "A", "text": "Brachioradialis"}, {"key": "B", "text": "Biceps brachii"}, {"key": "C", "text": "Supinator"}, {"key": "D", "text": "Pronator teres"}], "correct": "B", "explanation": "Biceps brachii inserts on radial tuberosity; this is also called bicipital tuberosity."}, {"id": 223, "subject": "Anatomy", "difficulty": "Medium", "question": "Pronator teres inserts on which part of radius?", "options": [{"key": "A", "text": "Radial tuberosity"}, {"key": "B", "text": "Middle of lateral surface"}, {"key": "C", "text": "Distal end"}, {"key": "D", "text": "Styloid process"}], "correct": "B", "explanation": "Pronator teres inserts on the middle of the lateral convex surface (pronator tuberosity) of radius."}, {"id": 224, "subject": "Anatomy", "difficulty": "Easy", "question": "Styloid process of radius is on which side?", "options": [{"key": "A", "text": "Medial"}, {"key": "B", "text": "Posterior"}, {"key": "C", "text": "Lateral"}, {"key": "D", "text": "Anterior"}], "correct": "C", "explanation": "Radial styloid process is on the lateral side and extends further distally than ulnar styloid process."}, {"id": 225, "subject": "Anatomy", "difficulty": "Medium", "question": "Which carpal bone articulates with the distal end of radius?", "options": [{"key": "A", "text": "Triquetrum"}, {"key": "B", "text": "Lunate and scaphoid"}, {"key": "C", "text": "Capitate"}, {"key": "D", "text": "Hamate"}], "correct": "B", "explanation": "Distal radius articulates with scaphoid (lateral) and lunate (medial) in the radiocarpal joint."}, {"id": 226, "subject": "Anatomy", "difficulty": "Easy", "question": "Colles' fracture involves which structure?", "options": [{"key": "A", "text": "Proximal radius"}, {"key": "B", "text": "Distal radius with dorsal displacement"}, {"key": "C", "text": "Head of radius"}, {"key": "D", "text": "Radial neck"}], "correct": "B", "explanation": "Colles' fracture is a distal radius fracture with dorsal (posterior) displacement giving 'dinner fork' deformity."}, {"id": 227, "subject": "Anatomy", "difficulty": "Medium", "question": "Smith's fracture is reverse Colles' — what is the displacement?", "options": [{"key": "A", "text": "Dorsal"}, {"key": "B", "text": "Lateral"}, {"key": "C", "text": "Volar (anterior)"}, {"key": "D", "text": "Medial"}], "correct": "C", "explanation": "Smith's fracture has volar/anterior displacement of distal fragment, opposite to Colles' fracture."}, {"id": 228, "subject": "Anatomy", "difficulty": "Medium", "question": "Supinator muscle wraps around which part of radius?", "options": [{"key": "A", "text": "Head"}, {"key": "B", "text": "Neck"}, {"key": "C", "text": "Upper third of shaft"}, {"key": "D", "text": "Middle third"}], "correct": "C", "explanation": "Supinator wraps around the upper third of radius, rotating it to produce supination."}, {"id": 229, "subject": "Anatomy", "difficulty": "Hard", "question": "Interosseous membrane connects radius to ulna. Its fibers run in which direction?", "options": [{"key": "A", "text": "Horizontal"}, {"key": "B", "text": "Downward-medially from radius to ulna"}, {"key": "C", "text": "Upward-medially"}, {"key": "D", "text": "Vertically"}], "correct": "B", "explanation": "Interosseous membrane fibers run downward and medially from radius to ulna, transmitting force proximally."}, {"id": 230, "subject": "Anatomy", "difficulty": "Medium", "question": "Which nerve is at risk in radial neck fracture?", "options": [{"key": "A", "text": "Median nerve"}, {"key": "B", "text": "Ulnar nerve"}, {"key": "C", "text": "Posterior interosseous nerve"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "C", "explanation": "Posterior interosseous nerve (deep branch of radial nerve) winds around radial neck and is at risk."}, {"id": 231, "subject": "Anatomy", "difficulty": "Easy", "question": "Olecranon process of ulna is the insertion for which muscle?", "options": [{"key": "A", "text": "Biceps brachii"}, {"key": "B", "text": "Brachialis"}, {"key": "C", "text": "Triceps brachii"}, {"key": "D", "text": "Anconeus"}], "correct": "C", "explanation": "Triceps brachii inserts on the posterior surface of olecranon process of ulna."}, {"id": 232, "subject": "Anatomy", "difficulty": "Easy", "question": "Coronoid process of ulna gives insertion to which muscle?", "options": [{"key": "A", "text": "Triceps"}, {"key": "B", "text": "Brachialis"}, {"key": "C", "text": "Biceps"}, {"key": "D", "text": "Supinator"}], "correct": "B", "explanation": "Brachialis inserts on coronoid process and anterior surface of ulna (tuberosity of ulna)."}, {"id": 233, "subject": "Anatomy", "difficulty": "Easy", "question": "Trochlear notch (semilunar notch) of ulna articulates with which structure?", "options": [{"key": "A", "text": "Capitulum"}, {"key": "B", "text": "Head of radius"}, {"key": "C", "text": "Trochlea of humerus"}, {"key": "D", "text": "Lateral epicondyle"}], "correct": "C", "explanation": "Trochlear notch is the large concavity on the anterior ulna that articulates with trochlea of humerus."}, {"id": 234, "subject": "Anatomy", "difficulty": "Medium", "question": "Radial notch of ulna articulates with which structure?", "options": [{"key": "A", "text": "Capitulum"}, {"key": "B", "text": "Head of radius"}, {"key": "C", "text": "Radial tuberosity"}, {"key": "D", "text": "Distal radius"}], "correct": "B", "explanation": "Radial notch is a small articular depression on the lateral aspect of coronoid process for head of radius."}, {"id": 235, "subject": "Anatomy", "difficulty": "Easy", "question": "Styloid process of ulna is on which aspect?", "options": [{"key": "A", "text": "Lateral distal end"}, {"key": "B", "text": "Medial distal end"}, {"key": "C", "text": "Posterior proximal"}, {"key": "D", "text": "Anterior distal"}], "correct": "B", "explanation": "Ulnar styloid process projects from the posteromedial aspect of the distal ulna."}, {"id": 236, "subject": "Anatomy", "difficulty": "Medium", "question": "Flexor digitorum profundus originates from which bone primarily?", "options": [{"key": "A", "text": "Radius"}, {"key": "B", "text": "Ulna"}, {"key": "C", "text": "Humerus"}, {"key": "D", "text": "Carpals"}], "correct": "B", "explanation": "Flexor digitorum profundus originates from the anterior and medial surfaces of the upper 3/4 of ulna."}, {"id": 237, "subject": "Anatomy", "difficulty": "Hard", "question": "Extensor carpi ulnaris originates from which structure?", "options": [{"key": "A", "text": "Medial epicondyle only"}, {"key": "B", "text": "Lateral epicondyle and posterior ulna"}, {"key": "C", "text": "Olecranon only"}, {"key": "D", "text": "Styloid process"}], "correct": "B", "explanation": "Extensor carpi ulnaris has a dual origin: lateral epicondyle (common extensor) and posterior border of ulna."}, {"id": 238, "subject": "Anatomy", "difficulty": "Medium", "question": "The proximal radioulnar joint involves which surface of ulna?", "options": [{"key": "A", "text": "Trochlear notch"}, {"key": "B", "text": "Radial notch"}, {"key": "C", "text": "Coronoid fossa"}, {"key": "D", "text": "Olecranon fossa"}], "correct": "B", "explanation": "Radial notch of ulna forms the proximal radioulnar joint with the circumference of radial head."}, {"id": 239, "subject": "Anatomy", "difficulty": "Hard", "question": "Ulna is the main stabilizer of elbow joint. Which process provides this stability?", "options": [{"key": "A", "text": "Styloid process"}, {"key": "B", "text": "Coronoid process and olecranon together"}, {"key": "C", "text": "Radial notch"}, {"key": "D", "text": "Interosseous border"}], "correct": "B", "explanation": "Coronoid process prevents posterior dislocation and olecranon prevents hyperextension — together they stabilize."}, {"id": 240, "subject": "Anatomy", "difficulty": "Hard", "question": "Anconeus muscle inserts on which part of ulna?", "options": [{"key": "A", "text": "Olecranon lateral surface"}, {"key": "B", "text": "Coronoid process"}, {"key": "C", "text": "Posterior shaft"}, {"key": "D", "text": "Styloid process"}], "correct": "A", "explanation": "Anconeus inserts on the lateral surface of olecranon and upper posterior ulna; assists in elbow extension."}, {"id": 241, "subject": "Anatomy", "difficulty": "Easy", "question": "How many carpal bones are there?", "options": [{"key": "A", "text": "6"}, {"key": "B", "text": "7"}, {"key": "C", "text": "8"}, {"key": "D", "text": "10"}], "correct": "C", "explanation": "There are 8 carpal bones arranged in 2 rows of 4: proximal (STLP) and distal (TCHT) row."}, {"id": 242, "subject": "Anatomy", "difficulty": "Easy", "question": "Which carpal bone is most commonly fractured?", "options": [{"key": "A", "text": "Lunate"}, {"key": "B", "text": "Triquetrum"}, {"key": "C", "text": "Scaphoid"}, {"key": "D", "text": "Capitate"}], "correct": "C", "explanation": "Scaphoid is the most commonly fractured carpal bone, often from fall on outstretched hand (FOOSH)."}, {"id": 243, "subject": "Anatomy", "difficulty": "Medium", "question": "Scaphoid fracture at waist risks avascular necrosis due to:", "options": [{"key": "A", "text": "Distal blood supply"}, {"key": "B", "text": "Proximal blood supply entering distally"}, {"key": "C", "text": "No blood supply"}, {"key": "D", "text": "Periosteal stripping"}], "correct": "B", "explanation": "Blood enters scaphoid distally; waist fracture cuts off supply to proximal pole causing AVN."}, {"id": 244, "subject": "Anatomy", "difficulty": "Medium", "question": "Which carpal bone can dislocate anteriorly causing median nerve compression?", "options": [{"key": "A", "text": "Scaphoid"}, {"key": "B", "text": "Triquetrum"}, {"key": "C", "text": "Lunate"}, {"key": "D", "text": "Capitate"}], "correct": "C", "explanation": "Lunate dislocation is the most common carpal dislocation and compresses median nerve in carpal tunnel."}, {"id": 245, "subject": "Anatomy", "difficulty": "Medium", "question": "Carpal tunnel contains all of the following EXCEPT:", "options": [{"key": "A", "text": "Flexor digitorum superficialis tendons"}, {"key": "B", "text": "Flexor pollicis longus"}, {"key": "C", "text": "Ulnar nerve"}, {"key": "D", "text": "Median nerve"}], "correct": "C", "explanation": "Ulnar nerve passes through Guyon's canal (ulnar canal), NOT the carpal tunnel."}, {"id": 246, "subject": "Anatomy", "difficulty": "Easy", "question": "Which carpal bone articulates with the thumb metacarpal at a saddle joint?", "options": [{"key": "A", "text": "Scaphoid"}, {"key": "B", "text": "Trapezoid"}, {"key": "C", "text": "Trapezium"}, {"key": "D", "text": "Capitate"}], "correct": "C", "explanation": "Trapezium articulates with the first metacarpal at the carpometacarpal joint — a saddle (sellar) joint."}, {"id": 247, "subject": "Anatomy", "difficulty": "Easy", "question": "Pisiform bone is a sesamoid bone in the tendon of which muscle?", "options": [{"key": "A", "text": "Flexor carpi radialis"}, {"key": "B", "text": "Flexor carpi ulnaris"}, {"key": "C", "text": "Extensor carpi ulnaris"}, {"key": "D", "text": "Palmaris longus"}], "correct": "B", "explanation": "Pisiform is a sesamoid bone within the flexor carpi ulnaris tendon and sits on the anterior triquetrum."}, {"id": 248, "subject": "Anatomy", "difficulty": "Medium", "question": "Anatomical snuffbox is bounded by tendons of which muscles?", "options": [{"key": "A", "text": "EPL and FPL"}, {"key": "B", "text": "APL, EPB (radially), EPL (ulnarly)"}, {"key": "C", "text": "FCR and FCU"}, {"key": "D", "text": "EDC and EIP"}], "correct": "B", "explanation": "Anatomical snuffbox: radial boundary — APL and EPB; ulnar boundary — EPL. Floor is scaphoid."}, {"id": 249, "subject": "Anatomy", "difficulty": "Easy", "question": "Tenderness in anatomical snuffbox after wrist injury suggests fracture of:", "options": [{"key": "A", "text": "Trapezium"}, {"key": "B", "text": "Lunate"}, {"key": "C", "text": "Scaphoid"}, {"key": "D", "text": "Capitate"}], "correct": "C", "explanation": "Scaphoid forms the floor of anatomical snuffbox; snuffbox tenderness is classical for scaphoid fracture."}, {"id": 250, "subject": "Anatomy", "difficulty": "Hard", "question": "Hamate bone has a hook (hamulus) that forms the:", "options": [{"key": "A", "text": "Radial border of carpal tunnel"}, {"key": "B", "text": "Ulnar border of carpal tunnel"}, {"key": "C", "text": "Roof of carpal tunnel"}, {"key": "D", "text": "Floor of Guyon's canal"}], "correct": "B", "explanation": "Hook of hamate forms the ulnar border of carpal tunnel and the radial wall of Guyon's canal."}, {"id": 251, "subject": "Anatomy", "difficulty": "Medium", "question": "Which muscle originates from the supraglenoid tubercle of scapula and runs in the bicipital groove?", "options": [{"key": "A", "text": "Short head of biceps"}, {"key": "B", "text": "Long head of biceps"}, {"key": "C", "text": "Coracobrachialis"}, {"key": "D", "text": "Deltoid"}], "correct": "B", "explanation": "Long head of biceps originates from supraglenoid tubercle and travels through the bicipital groove of humerus."}, {"id": 252, "subject": "Anatomy", "difficulty": "Easy", "question": "Deltoid muscle inserts on which surface of humerus?", "options": [{"key": "A", "text": "Medial surface"}, {"key": "B", "text": "Posterior surface"}, {"key": "C", "text": "Deltoid tuberosity on lateral surface"}, {"key": "D", "text": "Anterior surface"}], "correct": "C", "explanation": "Deltoid inserts on the deltoid tuberosity, a roughened V-shaped area on the lateral mid-shaft of humerus."}, {"id": 253, "subject": "Anatomy", "difficulty": "Hard", "question": "In a Holstein-Lewis fracture, which nerve is injured?", "options": [{"key": "A", "text": "Axillary nerve"}, {"key": "B", "text": "Radial nerve"}, {"key": "C", "text": "Ulnar nerve"}, {"key": "D", "text": "Median nerve"}], "correct": "B", "explanation": "Holstein-Lewis fracture is a distal third humeral shaft fracture that traps the radial nerve."}, {"id": 254, "subject": "Anatomy", "difficulty": "Medium", "question": "Supracondylar fracture of humerus in children commonly injures which artery?", "options": [{"key": "A", "text": "Radial artery"}, {"key": "B", "text": "Brachial artery"}, {"key": "C", "text": "Ulnar artery"}, {"key": "D", "text": "Anterior interosseous artery"}], "correct": "B", "explanation": "Brachial artery can be kinked/torn in supracondylar fractures causing Volkmann's ischemic contracture."}, {"id": 255, "subject": "Anatomy", "difficulty": "Hard", "question": "Medial nerve injury in supracondylar fracture produces which deformity?", "options": [{"key": "A", "text": "Claw hand"}, {"key": "B", "text": "Wrist drop"}, {"key": "C", "text": "Ape hand"}, {"key": "D", "text": "Benediction hand"}], "correct": "C", "explanation": "Median nerve injury causes 'ape hand' — loss of thenar eminence and inability to oppose thumb."}, {"id": 256, "subject": "Anatomy", "difficulty": "Easy", "question": "Which bursa lies between the olecranon and skin?", "options": [{"key": "A", "text": "Subacromial bursa"}, {"key": "B", "text": "Olecranon bursa"}, {"key": "C", "text": "Radial bursa"}, {"key": "D", "text": "Cubital bursa"}], "correct": "B", "explanation": "Olecranon bursa is a superficial bursa overlying the olecranon; inflamed in 'student's elbow'."}, {"id": 257, "subject": "Anatomy", "difficulty": "Medium", "question": "Coracobrachialis muscle inserts on which part of humerus?", "options": [{"key": "A", "text": "Lesser tubercle"}, {"key": "B", "text": "Greater tubercle"}, {"key": "C", "text": "Medial surface of mid-shaft"}, {"key": "D", "text": "Deltoid tuberosity"}], "correct": "C", "explanation": "Coracobrachialis inserts on the medial surface of humerus at the mid-shaft level."}, {"id": 258, "subject": "Anatomy", "difficulty": "Easy", "question": "Which muscle is NOT a rotator cuff muscle?", "options": [{"key": "A", "text": "Supraspinatus"}, {"key": "B", "text": "Infraspinatus"}, {"key": "C", "text": "Teres major"}, {"key": "D", "text": "Teres minor"}], "correct": "C", "explanation": "Rotator cuff = SITS: Supraspinatus, Infraspinatus, Teres minor, Subscapularis. Teres major is NOT part of it."}, {"id": 259, "subject": "Anatomy", "difficulty": "Hard", "question": "The medial wall of intertubercular groove is formed by:", "options": [{"key": "A", "text": "Greater tubercle"}, {"key": "B", "text": "Lesser tubercle"}, {"key": "C", "text": "Deltoid tuberosity"}, {"key": "D", "text": "Surgical neck"}], "correct": "B", "explanation": "Lesser tubercle forms the medial wall of the bicipital (intertubercular) groove."}, {"id": 260, "subject": "Anatomy", "difficulty": "Medium", "question": "Radial fossa of humerus receives which structure during elbow flexion?", "options": [{"key": "A", "text": "Olecranon"}, {"key": "B", "text": "Radial head"}, {"key": "C", "text": "Coronoid process"}, {"key": "D", "text": "Capitulum"}], "correct": "B", "explanation": "Radial fossa is a shallow anterior depression above capitulum that accommodates radial head during flexion."}, {"id": 261, "subject": "Anatomy", "difficulty": "Medium", "question": "Which muscle originates from the anterior surface of radius and inserts on distal phalanx of thumb?", "options": [{"key": "A", "text": "Flexor pollicis brevis"}, {"key": "B", "text": "Flexor pollicis longus"}, {"key": "C", "text": "Abductor pollicis longus"}, {"key": "D", "text": "Opponens pollicis"}], "correct": "B", "explanation": "Flexor pollicis longus originates from anterior radius and interosseous membrane; flexes IP joint of thumb."}, {"id": 262, "subject": "Anatomy", "difficulty": "Hard", "question": "Lister's tubercle is present on which bone?", "options": [{"key": "A", "text": "Ulna"}, {"key": "B", "text": "Radius"}, {"key": "C", "text": "Scaphoid"}, {"key": "D", "text": "Lunate"}], "correct": "B", "explanation": "Lister's tubercle (dorsal radial tubercle) is on the dorsal distal radius; EPL tendon wraps around it."}, {"id": 263, "subject": "Anatomy", "difficulty": "Medium", "question": "Abductor pollicis longus inserts on which structure?", "options": [{"key": "A", "text": "Proximal phalanx of thumb"}, {"key": "B", "text": "Base of first metacarpal"}, {"key": "C", "text": "Trapezium"}, {"key": "D", "text": "Distal phalanx of thumb"}], "correct": "B", "explanation": "APL inserts on the base of first metacarpal (radial side) and contributes to anatomical snuffbox boundary."}, {"id": 264, "subject": "Anatomy", "difficulty": "Easy", "question": "Distal radioulnar joint allows which movement?", "options": [{"key": "A", "text": "Flexion-extension"}, {"key": "B", "text": "Pronation-supination"}, {"key": "C", "text": "Radial-ulnar deviation"}, {"key": "D", "text": "Circumduction"}], "correct": "B", "explanation": "Distal radioulnar joint (DRUJ) along with proximal RUJ allows forearm pronation and supination."}, {"id": 265, "subject": "Anatomy", "difficulty": "Hard", "question": "Galeazzi fracture is:", "options": [{"key": "A", "text": "Radial head fracture with ulnar dislocation"}, {"key": "B", "text": "Radius shaft fracture with DRUJ dislocation"}, {"key": "C", "text": "Both bones forearm fracture"}, {"key": "D", "text": "Distal radius with ulnar styloid fracture"}], "correct": "B", "explanation": "Galeazzi = fracture of radius shaft + dislocation of distal radioulnar joint. 'Radius friend, ulna end'."}, {"id": 266, "subject": "Anatomy", "difficulty": "Hard", "question": "Monteggia fracture involves:", "options": [{"key": "A", "text": "Distal radius fracture"}, {"key": "B", "text": "Ulna shaft fracture with radial head dislocation"}, {"key": "C", "text": "Both bone forearm fracture"}, {"key": "D", "text": "Scaphoid fracture"}], "correct": "B", "explanation": "Monteggia = fracture of proximal ulna + dislocation of radial head. 'Ulna friend, radius head end'."}, {"id": 267, "subject": "Anatomy", "difficulty": "Medium", "question": "Brachioradialis muscle inserts on which part of radius?", "options": [{"key": "A", "text": "Radial tuberosity"}, {"key": "B", "text": "Styloid process"}, {"key": "C", "text": "Middle of shaft"}, {"key": "D", "text": "Dorsal surface"}], "correct": "B", "explanation": "Brachioradialis inserts on the lateral surface of distal radius above the styloid process."}, {"id": 268, "subject": "Anatomy", "difficulty": "Hard", "question": "Which muscle is attached to the oblique line of radius?", "options": [{"key": "A", "text": "Flexor digitorum superficialis"}, {"key": "B", "text": "Pronator teres"}, {"key": "C", "text": "Supinator"}, {"key": "D", "text": "Flexor pollicis longus"}], "correct": "A", "explanation": "Flexor digitorum superficialis has an oblique line origin on the anterior radius between radial tuberosity and pronator insertion."}, {"id": 269, "subject": "Anatomy", "difficulty": "Medium", "question": "The annular ligament stabilizes which joint?", "options": [{"key": "A", "text": "Elbow joint"}, {"key": "B", "text": "Proximal radioulnar joint"}, {"key": "C", "text": "Distal radioulnar joint"}, {"key": "D", "text": "Wrist joint"}], "correct": "B", "explanation": "Annular ligament wraps around the head of radius, holding it against the radial notch of ulna."}, {"id": 270, "subject": "Anatomy", "difficulty": "Medium", "question": "Pulled elbow (nursemaid's elbow) is due to slipping of radial head through which structure?", "options": [{"key": "A", "text": "Interosseous membrane"}, {"key": "B", "text": "Annular ligament"}, {"key": "C", "text": "Quadrate ligament"}, {"key": "D", "text": "Lateral collateral ligament"}], "correct": "B", "explanation": "Annular ligament slips over the radial head in young children causing subluxation (pulled elbow)."}, {"id": 271, "subject": "Anatomy", "difficulty": "Hard", "question": "Supinator originates from which part of ulna?", "options": [{"key": "A", "text": "Olecranon"}, {"key": "B", "text": "Coronoid process and supinator crest"}, {"key": "C", "text": "Posterior shaft"}, {"key": "D", "text": "Radial notch"}], "correct": "B", "explanation": "Supinator originates from lateral epicondyle of humerus, radial collateral ligament, and supinator crest of ulna."}, {"id": 272, "subject": "Anatomy", "difficulty": "Medium", "question": "Flexor carpi ulnaris has two heads — which structure passes between them?", "options": [{"key": "A", "text": "Radial artery"}, {"key": "B", "text": "Median nerve"}, {"key": "C", "text": "Ulnar nerve"}, {"key": "D", "text": "Anterior interosseous nerve"}], "correct": "C", "explanation": "Ulnar nerve passes between the humeral and ulnar heads of flexor carpi ulnaris — compression here causes cubital tunnel syndrome."}, {"id": 273, "subject": "Anatomy", "difficulty": "Hard", "question": "Extensor pollicis longus wraps around which bony landmark?", "options": [{"key": "A", "text": "Radial styloid"}, {"key": "B", "text": "Lister's tubercle on radius"}, {"key": "C", "text": "Ulnar styloid"}, {"key": "D", "text": "Olecranon"}], "correct": "B", "explanation": "EPL tendon changes direction around Lister's tubercle (dorsal tubercle of radius) before reaching thumb."}, {"id": 274, "subject": "Anatomy", "difficulty": "Hard", "question": "The triangular fibrocartilage complex (TFCC) attaches to the base of:", "options": [{"key": "A", "text": "Radial styloid"}, {"key": "B", "text": "Ulnar styloid"}, {"key": "C", "text": "Triquetrum"}, {"key": "D", "text": "Pisiform"}], "correct": "B", "explanation": "TFCC attaches to the base of ulnar styloid process and is the primary stabilizer of DRUJ."}, {"id": 275, "subject": "Anatomy", "difficulty": "Easy", "question": "In cubital tunnel syndrome, which nerve is compressed?", "options": [{"key": "A", "text": "Median nerve"}, {"key": "B", "text": "Radial nerve"}, {"key": "C", "text": "Ulnar nerve"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "C", "explanation": "Ulnar nerve is compressed in cubital tunnel (behind medial epicondyle); causes ring and little finger numbness."}, {"id": 276, "subject": "Anatomy", "difficulty": "Medium", "question": "Which surface of ulna is subcutaneous throughout its length?", "options": [{"key": "A", "text": "Anterior surface"}, {"key": "B", "text": "Posterior surface"}, {"key": "C", "text": "Medial surface"}, {"key": "D", "text": "Lateral surface"}], "correct": "C", "explanation": "The posterior/medial border of ulna is subcutaneous throughout; palpable along entire length."}, {"id": 277, "subject": "Anatomy", "difficulty": "Easy", "question": "Pronator quadratus muscle is located:", "options": [{"key": "A", "text": "In the arm"}, {"key": "B", "text": "In the forearm anteriorly near wrist"}, {"key": "C", "text": "In the hand"}, {"key": "D", "text": "In the forearm posteriorly"}], "correct": "B", "explanation": "Pronator quadratus is a flat quadrilateral muscle on the anterior distal forearm connecting radius and ulna."}, {"id": 278, "subject": "Anatomy", "difficulty": "Medium", "question": "Which is the primary pronator of the forearm?", "options": [{"key": "A", "text": "Pronator quadratus"}, {"key": "B", "text": "Pronator teres"}, {"key": "C", "text": "Brachioradialis"}, {"key": "D", "text": "Flexor carpi radialis"}], "correct": "B", "explanation": "Pronator teres is the primary pronator; pronator quadratus assists and acts alone in slow pronation."}, {"id": 279, "subject": "Anatomy", "difficulty": "Easy", "question": "Olecranon bursitis is clinically called:", "options": [{"key": "A", "text": "Tennis elbow"}, {"key": "B", "text": "Golfer's elbow"}, {"key": "C", "text": "Student's elbow"}, {"key": "D", "text": "Miner's elbow"}], "correct": "C", "explanation": "Olecranon bursitis due to pressure from leaning on elbows while studying is called student's elbow."}, {"id": 280, "subject": "Anatomy", "difficulty": "Medium", "question": "The interosseous border of ulna gives attachment to:", "options": [{"key": "A", "text": "Flexor carpi ulnaris"}, {"key": "B", "text": "Interosseous membrane"}, {"key": "C", "text": "Extensor carpi ulnaris"}, {"key": "D", "text": "Pronator quadratus"}], "correct": "B", "explanation": "The sharp interosseous border of ulna gives attachment to the interosseous membrane connecting radius-ulna."}, {"id": 281, "subject": "Anatomy", "difficulty": "Easy", "question": "Proximal row of carpals from radial to ulnar side:", "options": [{"key": "A", "text": "Scaphoid, Lunate, Triquetrum, Pisiform"}, {"key": "B", "text": "Trapezium, Trapezoid, Capitate, Hamate"}, {"key": "C", "text": "Lunate, Scaphoid, Pisiform, Triquetrum"}, {"key": "D", "text": "Capitate, Hamate, Trapezium, Trapezoid"}], "correct": "A", "explanation": "Proximal row: Scaphoid, Lunate, Triquetrum, Pisiform (mnemonic: She Looks Too Pretty)."}, {"id": 282, "subject": "Anatomy", "difficulty": "Easy", "question": "Distal row of carpals from radial to ulnar side:", "options": [{"key": "A", "text": "Scaphoid, Lunate, Triquetrum, Pisiform"}, {"key": "B", "text": "Trapezium, Trapezoid, Capitate, Hamate"}, {"key": "C", "text": "Capitate, Hamate, Trapezium, Trapezoid"}, {"key": "D", "text": "Lunate, Capitate, Trapezoid, Hamate"}], "correct": "B", "explanation": "Distal row: Trapezium, Trapezoid, Capitate, Hamate (mnemonic: Try To Catch Her)."}, {"id": 283, "subject": "Anatomy", "difficulty": "Hard", "question": "Which carpal bone has no muscular attachment?", "options": [{"key": "A", "text": "Capitate"}, {"key": "B", "text": "Lunate"}, {"key": "C", "text": "Scaphoid"}, {"key": "D", "text": "Trapezoid"}], "correct": "B", "explanation": "Lunate has no muscle attachments; it is held by ligaments only, making it prone to dislocation."}, {"id": 284, "subject": "Anatomy", "difficulty": "Easy", "question": "Carpal tunnel syndrome most commonly compresses which nerve?", "options": [{"key": "A", "text": "Ulnar nerve"}, {"key": "B", "text": "Radial nerve"}, {"key": "C", "text": "Median nerve"}, {"key": "D", "text": "Anterior interosseous nerve"}], "correct": "C", "explanation": "Carpal tunnel syndrome involves compression of median nerve under flexor retinaculum causing thenar wasting."}, {"id": 285, "subject": "Anatomy", "difficulty": "Hard", "question": "Flexor retinaculum (transverse carpal ligament) is attached to which four bones?", "options": [{"key": "A", "text": "Scaphoid, Lunate, Capitate, Hamate"}, {"key": "B", "text": "Scaphoid, Trapezium, Hamate, Pisiform"}, {"key": "C", "text": "Radius, Ulna, Capitate, Hamate"}, {"key": "D", "text": "Trapezium, Trapezoid, Capitate, Pisiform"}], "correct": "B", "explanation": "Flexor retinaculum attaches to scaphoid tubercle, trapezium ridge (radially) and hamate hook, pisiform (ulnarly)."}, {"id": 286, "subject": "Anatomy", "difficulty": "Medium", "question": "Kienbock's disease is avascular necrosis of which carpal bone?", "options": [{"key": "A", "text": "Scaphoid"}, {"key": "B", "text": "Capitate"}, {"key": "C", "text": "Lunate"}, {"key": "D", "text": "Triquetrum"}], "correct": "C", "explanation": "Kienbock's disease = AVN of lunate, often associated with negative ulnar variance."}, {"id": 287, "subject": "Anatomy", "difficulty": "Medium", "question": "Guyon's canal (ulnar tunnel) transmits:", "options": [{"key": "A", "text": "Median nerve and radial artery"}, {"key": "B", "text": "Ulnar nerve and ulnar artery"}, {"key": "C", "text": "Anterior interosseous nerve"}, {"key": "D", "text": "Superficial radial nerve"}], "correct": "B", "explanation": "Guyon's canal transmits ulnar nerve and ulnar artery; bounded by pisiform, hamate, and palmar carpal ligament."}, {"id": 288, "subject": "Anatomy", "difficulty": "Medium", "question": "Which carpal bone is at the apex of the carpal arch (keystone)?", "options": [{"key": "A", "text": "Capitate"}, {"key": "B", "text": "Lunate"}, {"key": "C", "text": "Scaphoid"}, {"key": "D", "text": "Hamate"}], "correct": "A", "explanation": "Capitate is the largest carpal bone and acts as the keystone of the carpal arch."}, {"id": 289, "subject": "Anatomy", "difficulty": "Hard", "question": "Watson's test (scaphoid shift test) is used to diagnose:", "options": [{"key": "A", "text": "Lunate dislocation"}, {"key": "B", "text": "Scapholunate instability"}, {"key": "C", "text": "TFCC tear"}, {"key": "D", "text": "Hook of hamate fracture"}], "correct": "B", "explanation": "Watson's test detects scapholunate dissociation by applying pressure on scaphoid tubercle during ulnar-to-radial deviation."}, {"id": 290, "subject": "Anatomy", "difficulty": "Hard", "question": "Perilunate dislocation — which bone dislocates?", "options": [{"key": "A", "text": "Lunate anteriorly"}, {"key": "B", "text": "All carpals except lunate"}, {"key": "C", "text": "Scaphoid posteriorly"}, {"key": "D", "text": "Triquetrum medially"}], "correct": "B", "explanation": "In perilunate dislocation, the lunate stays in place while all other carpals dislocate posteriorly."}, {"id": 291, "subject": "Anatomy", "difficulty": "Medium", "question": "Which ossification centre appears first in the elbow?", "options": [{"key": "A", "text": "Radial head"}, {"key": "B", "text": "Medial epicondyle"}, {"key": "C", "text": "Capitulum"}, {"key": "D", "text": "Lateral epicondyle"}], "correct": "C", "explanation": "Capitulum appears first at 1-2 years. Mnemonic for order: CRITOE (C-R-I-T-O-E)."}, {"id": 292, "subject": "Anatomy", "difficulty": "Hard", "question": "CRITOE mnemonic for elbow ossification — what does 'T' stand for?", "options": [{"key": "A", "text": "Trochlea"}, {"key": "B", "text": "Tubercle"}, {"key": "C", "text": "Triquetrum"}, {"key": "D", "text": "Teres"}], "correct": "A", "explanation": "CRITOE: Capitulum, Radial head, Internal (medial) epicondyle, Trochlea, Olecranon, External (lateral) epicondyle."}, {"id": 293, "subject": "Anatomy", "difficulty": "Medium", "question": "Lateral epicondylitis (Tennis elbow) involves which tendon primarily?", "options": [{"key": "A", "text": "Extensor carpi ulnaris"}, {"key": "B", "text": "Extensor carpi radialis brevis"}, {"key": "C", "text": "Extensor digitorum"}, {"key": "D", "text": "Extensor carpi radialis longus"}], "correct": "B", "explanation": "Extensor carpi radialis brevis (ECRB) tendon is most commonly involved in lateral epicondylitis."}, {"id": 294, "subject": "Anatomy", "difficulty": "Medium", "question": "Medial epicondylitis (Golfer's elbow) involves which muscles?", "options": [{"key": "A", "text": "Common extensor origin"}, {"key": "B", "text": "Common flexor-pronator origin"}, {"key": "C", "text": "Triceps"}, {"key": "D", "text": "Brachioradialis"}], "correct": "B", "explanation": "Golfer's elbow affects the common flexor-pronator origin at the medial epicondyle, especially FCR and pronator teres."}, {"id": 295, "subject": "Anatomy", "difficulty": "Easy", "question": "Posterior interosseous nerve is a branch of which nerve?", "options": [{"key": "A", "text": "Median nerve"}, {"key": "B", "text": "Ulnar nerve"}, {"key": "C", "text": "Radial nerve"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "C", "explanation": "Posterior interosseous nerve is the deep branch of radial nerve; it supplies extensor muscles of forearm."}, {"id": 296, "subject": "Anatomy", "difficulty": "Medium", "question": "Anterior interosseous nerve is a branch of which nerve?", "options": [{"key": "A", "text": "Ulnar nerve"}, {"key": "B", "text": "Radial nerve"}, {"key": "C", "text": "Median nerve"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "C", "explanation": "Anterior interosseous nerve (AIN) is a branch of median nerve supplying FPL, lateral FDP, and pronator quadratus."}, {"id": 297, "subject": "Anatomy", "difficulty": "Easy", "question": "In 'Saturday night palsy' which nerve is injured?", "options": [{"key": "A", "text": "Ulnar nerve"}, {"key": "B", "text": "Median nerve"}, {"key": "C", "text": "Radial nerve"}, {"key": "D", "text": "Axillary nerve"}], "correct": "C", "explanation": "Radial nerve is compressed in the spiral groove (e.g., sleeping with arm over chair) causing wrist drop."}, {"id": 298, "subject": "Anatomy", "difficulty": "Medium", "question": "Froment's sign is positive in injury to which nerve?", "options": [{"key": "A", "text": "Median nerve"}, {"key": "B", "text": "Ulnar nerve"}, {"key": "C", "text": "Radial nerve"}, {"key": "D", "text": "Axillary nerve"}], "correct": "B", "explanation": "Froment's sign: thumb IP flexion during key pinch due to adductor pollicis weakness — ulnar nerve palsy."}, {"id": 299, "subject": "Anatomy", "difficulty": "Easy", "question": "'Dinner fork' deformity is seen in which fracture?", "options": [{"key": "A", "text": "Colles' fracture"}, {"key": "B", "text": "Smith's fracture"}, {"key": "C", "text": "Monteggia fracture"}, {"key": "D", "text": "Galeazzi fracture"}], "correct": "A", "explanation": "Colles' fracture produces 'dinner fork' deformity due to dorsal displacement and tilt of distal radius fragment."}, {"id": 300, "subject": "Anatomy", "difficulty": "Hard", "question": "Wartenberg's sign is associated with palsy of which nerve?", "options": [{"key": "A", "text": "Median nerve"}, {"key": "B", "text": "Radial nerve"}, {"key": "C", "text": "Ulnar nerve"}, {"key": "D", "text": "Anterior interosseous nerve"}], "correct": "C", "explanation": "Wartenberg's sign = persistent abduction of little finger due to weakness of palmar interossei in ulnar nerve palsy."}, {"id": 301, "subject": "Anatomy", "difficulty": "Easy", "question": "Shoulder (glenohumeral) joint is classified as which type of synovial joint?", "options": [{"key": "A", "text": "Hinge joint"}, {"key": "B", "text": "Condyloid joint"}, {"key": "C", "text": "Ball and socket joint"}, {"key": "D", "text": "Saddle joint"}], "correct": "C", "explanation": "Glenohumeral joint is a multiaxial ball and socket synovial joint allowing greatest ROM of any joint in body."}, {"id": 302, "subject": "Anatomy", "difficulty": "Easy", "question": "Glenoid cavity is deepened by which fibrocartilaginous structure?", "options": [{"key": "A", "text": "Glenohumeral ligament"}, {"key": "B", "text": "Glenoid labrum"}, {"key": "C", "text": "Coracoacromial ligament"}, {"key": "D", "text": "Transverse humeral ligament"}], "correct": "B", "explanation": "Glenoid labrum is a fibrocartilaginous rim that deepens the glenoid by approximately 50%, improving stability."}, {"id": 303, "subject": "Anatomy", "difficulty": "Medium", "question": "The shoulder joint capsule is attached proximally to the rim of:", "options": [{"key": "A", "text": "Humeral head"}, {"key": "B", "text": "Glenoid labrum and glenoid margin"}, {"key": "C", "text": "Coracoid process"}, {"key": "D", "text": "Acromion"}], "correct": "B", "explanation": "The capsule is attached proximally to the glenoid labrum and margin of glenoid cavity."}, {"id": 304, "subject": "Anatomy", "difficulty": "Medium", "question": "Which is the weakest part of the shoulder joint capsule?", "options": [{"key": "A", "text": "Superior"}, {"key": "B", "text": "Anterior"}, {"key": "C", "text": "Posterior"}, {"key": "D", "text": "Inferior (axillary pouch)"}], "correct": "D", "explanation": "Inferior capsule (axillary pouch) is the weakest — most shoulder dislocations are inferior initially then anterior."}, {"id": 305, "subject": "Anatomy", "difficulty": "Medium", "question": "Coracohumeral ligament strengthens which part of the shoulder capsule?", "options": [{"key": "A", "text": "Inferior"}, {"key": "B", "text": "Posterior"}, {"key": "C", "text": "Superior"}, {"key": "D", "text": "Anterior"}], "correct": "C", "explanation": "Coracohumeral ligament blends with the superior capsule and reinforces it; also limits external rotation."}, {"id": 306, "subject": "Anatomy", "difficulty": "Medium", "question": "Which three glenohumeral ligaments reinforce the anterior capsule?", "options": [{"key": "A", "text": "Superior, Middle, Inferior GHL"}, {"key": "B", "text": "Coracohumeral, Coracoacromial, Coracoclavicular"}, {"key": "C", "text": "Transverse, Oblique, Vertical"}, {"key": "D", "text": "Acromioclavicular, Sternoclavicular, Coracoclavicular"}], "correct": "A", "explanation": "Superior, Middle and Inferior glenohumeral ligaments (SGHL, MGHL, IGHL) reinforce the anterior joint capsule."}, {"id": 307, "subject": "Anatomy", "difficulty": "Hard", "question": "Inferior glenohumeral ligament (IGHL) is the primary stabilizer against:", "options": [{"key": "A", "text": "Superior translation"}, {"key": "B", "text": "Anterior-inferior dislocation"}, {"key": "C", "text": "Posterior dislocation"}, {"key": "D", "text": "Superior dislocation"}], "correct": "B", "explanation": "IGHL complex is the primary static stabilizer against anterior-inferior translation and dislocation."}, {"id": 308, "subject": "Anatomy", "difficulty": "Easy", "question": "Which muscle is the primary dynamic stabilizer of the shoulder joint?", "options": [{"key": "A", "text": "Deltoid"}, {"key": "B", "text": "Rotator cuff muscles"}, {"key": "C", "text": "Biceps brachii"}, {"key": "D", "text": "Pectoralis major"}], "correct": "B", "explanation": "Rotator cuff (SITS) provides dynamic stability by compressing humeral head into glenoid during movements."}, {"id": 309, "subject": "Anatomy", "difficulty": "Hard", "question": "Rotator cuff interval is a gap between which two tendons?", "options": [{"key": "A", "text": "Supraspinatus and infraspinatus"}, {"key": "B", "text": "Subscapularis and supraspinatus"}, {"key": "C", "text": "Infraspinatus and teres minor"}, {"key": "D", "text": "Supraspinatus and deltoid"}], "correct": "B", "explanation": "Rotator cuff interval is between subscapularis and supraspinatus tendons; contains SGHL and CHL."}, {"id": 310, "subject": "Anatomy", "difficulty": "Medium", "question": "Which muscle prevents superior migration of humeral head during deltoid contraction?", "options": [{"key": "A", "text": "Subscapularis"}, {"key": "B", "text": "Teres minor"}, {"key": "C", "text": "Supraspinatus"}, {"key": "D", "text": "Infraspinatus"}], "correct": "C", "explanation": "Supraspinatus acts as a humeral head depressor/stabilizer preventing superior migration during shoulder abduction."}, {"id": 311, "subject": "Anatomy", "difficulty": "Easy", "question": "Subacromial bursa lies between which structures?", "options": [{"key": "A", "text": "Deltoid and supraspinatus tendon/greater tubercle"}, {"key": "B", "text": "Acromion and clavicle"}, {"key": "C", "text": "Glenoid and humeral head"}, {"key": "D", "text": "Coracoid and subscapularis"}], "correct": "A", "explanation": "Subacromial (subdeltoid) bursa lies between deltoid muscle and supraspinatus tendon/greater tubercle."}, {"id": 312, "subject": "Anatomy", "difficulty": "Medium", "question": "Neer's impingement sign tests which tendon primarily?", "options": [{"key": "A", "text": "Subscapularis"}, {"key": "B", "text": "Infraspinatus"}, {"key": "C", "text": "Supraspinatus"}, {"key": "D", "text": "Biceps long head"}], "correct": "C", "explanation": "Neer's sign: pain on passive forward flexion — tests supraspinatus (and long head biceps) impingement under acromion."}, {"id": 313, "subject": "Anatomy", "difficulty": "Medium", "question": "Hawkins-Kennedy test is positive in impingement of:", "options": [{"key": "A", "text": "Subscapularis"}, {"key": "B", "text": "Supraspinatus under coracoacromial arch"}, {"key": "C", "text": "Infraspinatus"}, {"key": "D", "text": "Teres minor"}], "correct": "B", "explanation": "Hawkins-Kennedy: internal rotation in 90° flexion — impinges supraspinatus against coracoacromial ligament."}, {"id": 314, "subject": "Anatomy", "difficulty": "Easy", "question": "Painful arc syndrome occurs during shoulder abduction between:", "options": [{"key": "A", "text": "0-30°"}, {"key": "B", "text": "30-60°"}, {"key": "C", "text": "60-120°"}, {"key": "D", "text": "120-180°"}], "correct": "C", "explanation": "Painful arc is between 60-120° of abduction due to supraspinatus tendon impingement under acromion."}, {"id": 315, "subject": "Anatomy", "difficulty": "Easy", "question": "Anterior shoulder dislocation — humeral head lies:", "options": [{"key": "A", "text": "Below acromion"}, {"key": "B", "text": "Anterior to glenoid, under coracoid process"}, {"key": "C", "text": "Posterior to glenoid"}, {"key": "D", "text": "Superior to glenoid"}], "correct": "B", "explanation": "In anterior dislocation (most common — 95%), humeral head lies anteriorly under coracoid process."}, {"id": 316, "subject": "Anatomy", "difficulty": "Medium", "question": "Bankart lesion in recurrent shoulder dislocation involves:", "options": [{"key": "A", "text": "Hill-Sachs lesion on humerus"}, {"key": "B", "text": "Rotator cuff tear"}, {"key": "C", "text": "Anterior-inferior labrum detachment"}, {"key": "D", "text": "Acromion fracture"}], "correct": "C", "explanation": "Bankart lesion = detachment of anterior-inferior glenoid labrum and capsule from glenoid rim."}, {"id": 317, "subject": "Anatomy", "difficulty": "Medium", "question": "Hill-Sachs lesion in anterior shoulder dislocation is:", "options": [{"key": "A", "text": "Compression fracture of anterior glenoid"}, {"key": "B", "text": "Compression fracture of posterior humeral head"}, {"key": "C", "text": "Labrum tear"}, {"key": "D", "text": "SLAP lesion"}], "correct": "B", "explanation": "Hill-Sachs lesion = compression fracture/defect of posterolateral humeral head from impaction on glenoid rim."}, {"id": 318, "subject": "Anatomy", "difficulty": "Hard", "question": "Posterior dislocation of shoulder is associated with which injury mechanism?", "options": [{"key": "A", "text": "Fall on outstretched hand"}, {"key": "B", "text": "Epileptic seizure or electric shock"}, {"key": "C", "text": "Overhead throwing"}, {"key": "D", "text": "Collision sports"}], "correct": "B", "explanation": "Posterior dislocation is classically associated with epileptic seizures and electrocution (strong internal rotation)."}, {"id": 319, "subject": "Anatomy", "difficulty": "Easy", "question": "Axillary nerve injury in shoulder dislocation causes loss of sensation over:", "options": [{"key": "A", "text": "Medial arm"}, {"key": "B", "text": "Lateral shoulder (regimental badge area)"}, {"key": "C", "text": "Medial forearm"}, {"key": "D", "text": "Thumb and index finger"}], "correct": "B", "explanation": "Axillary nerve supplies sensation to regimental badge area (upper lateral arm) via superior lateral cutaneous nerve."}, {"id": 320, "subject": "Anatomy", "difficulty": "Medium", "question": "Empty can test (Jobe's test) specifically tests integrity of:", "options": [{"key": "A", "text": "Infraspinatus"}, {"key": "B", "text": "Subscapularis"}, {"key": "C", "text": "Supraspinatus"}, {"key": "D", "text": "Teres minor"}], "correct": "C", "explanation": "Empty can test: arm in 90° abduction, 30° horizontal flexion (scapular plane), internal rotation — tests supraspinatus."}, {"id": 321, "subject": "Anatomy", "difficulty": "Medium", "question": "SLAP lesion stands for:", "options": [{"key": "A", "text": "Superior Labrum Anterior-Posterior tear"}, {"key": "B", "text": "Supraspinatus Labrum Anterior-Posterior"}, {"key": "C", "text": "Superior Ligament Avulsion Posterior"}, {"key": "D", "text": "Subluxation Labrum Anterior Posterior"}], "correct": "A", "explanation": "SLAP lesion = Superior Labrum Anterior to Posterior tear — involves long head of biceps anchor at glenoid."}, {"id": 322, "subject": "Anatomy", "difficulty": "Hard", "question": "O'Brien's active compression test is used to diagnose:", "options": [{"key": "A", "text": "Rotator cuff tear"}, {"key": "B", "text": "SLAP lesion and AC joint pathology"}, {"key": "C", "text": "Frozen shoulder"}, {"key": "D", "text": "Shoulder instability"}], "correct": "B", "explanation": "O'Brien's test: 90° flexion, 10° adduction, internal rotation — positive for SLAP lesion or AC joint pathology."}, {"id": 323, "subject": "Anatomy", "difficulty": "Medium", "question": "Lift-off test (Gerber's test) assesses integrity of:", "options": [{"key": "A", "text": "Supraspinatus"}, {"key": "B", "text": "Infraspinatus"}, {"key": "C", "text": "Subscapularis"}, {"key": "D", "text": "Teres minor"}], "correct": "C", "explanation": "Lift-off test: hand behind back, patient lifts away — tests subscapularis muscle and tendon integrity."}, {"id": 324, "subject": "Anatomy", "difficulty": "Hard", "question": "External rotation lag sign tests which muscle?", "options": [{"key": "A", "text": "Subscapularis"}, {"key": "B", "text": "Supraspinatus"}, {"key": "C", "text": "Infraspinatus and teres minor"}, {"key": "D", "text": "Deltoid"}], "correct": "C", "explanation": "External rotation lag sign: inability to maintain external rotation in 90° abduction — tests infraspinatus/teres minor."}, {"id": 325, "subject": "Anatomy", "difficulty": "Medium", "question": "Frozen shoulder (adhesive capsulitis) affects which motion first and most?", "options": [{"key": "A", "text": "Flexion"}, {"key": "B", "text": "Abduction"}, {"key": "C", "text": "External rotation"}, {"key": "D", "text": "Internal rotation"}], "correct": "C", "explanation": "External rotation is lost first and most in frozen shoulder due to contracture of coracohumeral ligament."}, {"id": 326, "subject": "Anatomy", "difficulty": "Medium", "question": "Acromioclavicular (AC) joint type is:", "options": [{"key": "A", "text": "Ball and socket"}, {"key": "B", "text": "Plane (gliding) synovial joint"}, {"key": "C", "text": "Hinge joint"}, {"key": "D", "text": "Saddle joint"}], "correct": "B", "explanation": "AC joint is a plane synovial joint with a fibrocartilaginous disc between the acromial and clavicular articular surfaces."}, {"id": 327, "subject": "Anatomy", "difficulty": "Medium", "question": "Coracoclavicular ligament has two components — which are they?", "options": [{"key": "A", "text": "Anterior and posterior"}, {"key": "B", "text": "Medial and lateral"}, {"key": "C", "text": "Conoid and trapezoid"}, {"key": "D", "text": "Superior and inferior"}], "correct": "C", "explanation": "Coracoclavicular ligament = conoid (posteromedial) + trapezoid (anterolateral); suspends scapula from clavicle."}, {"id": 328, "subject": "Anatomy", "difficulty": "Hard", "question": "In Grade III AC joint dislocation, which ligament is torn?", "options": [{"key": "A", "text": "Coracoclavicular ligament only"}, {"key": "B", "text": "AC ligament only"}, {"key": "C", "text": "Both AC and coracoclavicular ligaments"}, {"key": "D", "text": "Coracoacromial ligament"}], "correct": "C", "explanation": "Grade III: complete tear of both AC and coracoclavicular ligaments causing complete dislocation."}, {"id": 329, "subject": "Anatomy", "difficulty": "Medium", "question": "Piano key sign is seen in:", "options": [{"key": "A", "text": "AC joint dislocation"}, {"key": "B", "text": "Sternoclavicular dislocation"}, {"key": "C", "text": "Shoulder impingement"}, {"key": "D", "text": "Frozen shoulder"}], "correct": "A", "explanation": "Piano key sign: distal clavicle springs up when pressed down — positive in complete AC joint dislocation."}, {"id": 330, "subject": "Anatomy", "difficulty": "Easy", "question": "Sternoclavicular (SC) joint is the only articulation between:", "options": [{"key": "A", "text": "Scapula and thorax"}, {"key": "B", "text": "Upper limb and axial skeleton"}, {"key": "C", "text": "Clavicle and first rib"}, {"key": "D", "text": "Manubrium and coracoid"}], "correct": "B", "explanation": "SC joint is the only synovial joint connecting the upper limb to the axial skeleton."}, {"id": 331, "subject": "Anatomy", "difficulty": "Easy", "question": "Elbow joint is a compound joint consisting of how many articulations?", "options": [{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}], "correct": "B", "explanation": "Elbow has 3 articulations: humeroulnar, humeroradial, and proximal radioulnar — all within one capsule."}, {"id": 332, "subject": "Anatomy", "difficulty": "Easy", "question": "Humeroulnar joint is classified as:", "options": [{"key": "A", "text": "Ball and socket"}, {"key": "B", "text": "Condyloid"}, {"key": "C", "text": "Hinge (ginglymoid)"}, {"key": "D", "text": "Pivot"}], "correct": "C", "explanation": "Humeroulnar joint is a hinge joint allowing flexion and extension only."}, {"id": 333, "subject": "Anatomy", "difficulty": "Easy", "question": "Proximal radioulnar joint is classified as:", "options": [{"key": "A", "text": "Hinge"}, {"key": "B", "text": "Pivot (trochoid)"}, {"key": "C", "text": "Saddle"}, {"key": "D", "text": "Condyloid"}], "correct": "B", "explanation": "Proximal RUJ is a pivot joint — radial head rotates within the annular ligament."}, {"id": 334, "subject": "Anatomy", "difficulty": "Easy", "question": "Normal elbow extension is limited by which structure impacting olecranon fossa?", "options": [{"key": "A", "text": "Coronoid process"}, {"key": "B", "text": "Radial head"}, {"key": "C", "text": "Olecranon"}, {"key": "D", "text": "Medial epicondyle"}], "correct": "C", "explanation": "Olecranon impacting the olecranon fossa is the bony block to elbow extension (0°)."}, {"id": 335, "subject": "Anatomy", "difficulty": "Easy", "question": "Normal range of elbow flexion is approximately:", "options": [{"key": "A", "text": "90°"}, {"key": "B", "text": "120°"}, {"key": "C", "text": "140-150°"}, {"key": "D", "text": "160°"}], "correct": "C", "explanation": "Normal elbow flexion is 140-150°; functional range for daily activities is 30-130°."}, {"id": 336, "subject": "Anatomy", "difficulty": "Medium", "question": "Medial collateral ligament (UCL) of elbow has which most important component?", "options": [{"key": "A", "text": "Posterior band"}, {"key": "B", "text": "Transverse band"}, {"key": "C", "text": "Anterior band"}, {"key": "D", "text": "Oblique band"}], "correct": "C", "explanation": "Anterior band of UCL (from medial epicondyle to coronoid process) is the primary stabilizer against valgus stress."}, {"id": 337, "subject": "Anatomy", "difficulty": "Medium", "question": "Tommy John surgery involves reconstruction of which structure?", "options": [{"key": "A", "text": "Lateral collateral ligament"}, {"key": "B", "text": "Ulnar collateral ligament (medial)"}, {"key": "C", "text": "Annular ligament"}, {"key": "D", "text": "Interosseous membrane"}], "correct": "B", "explanation": "Tommy John surgery = UCL (medial collateral ligament) reconstruction using palmaris longus or gracilis graft."}, {"id": 338, "subject": "Anatomy", "difficulty": "Hard", "question": "Lateral collateral ligament complex of elbow includes:", "options": [{"key": "A", "text": "UCL and annular ligament"}, {"key": "B", "text": "LUCL, RCL, annular and accessory lateral ligaments"}, {"key": "C", "text": "Only radial collateral ligament"}, {"key": "D", "text": "Coracoclavicular and coracoacromial"}], "correct": "B", "explanation": "Lateral complex: Lateral UCL (LUCL), radial collateral ligament (RCL), annular ligament, accessory lateral ligament."}, {"id": 339, "subject": "Anatomy", "difficulty": "Hard", "question": "Posterolateral rotatory instability (PLRI) of elbow is due to injury of:", "options": [{"key": "A", "text": "Medial UCL"}, {"key": "B", "text": "Lateral UCL (LUCL)"}, {"key": "C", "text": "Annular ligament"}, {"key": "D", "text": "Interosseous membrane"}], "correct": "B", "explanation": "LUCL injury causes PLRI — most common pattern of elbow instability after dislocation."}, {"id": 340, "subject": "Anatomy", "difficulty": "Medium", "question": "Cubital fossa is bounded medially by which muscle?", "options": [{"key": "A", "text": "Brachioradialis"}, {"key": "B", "text": "Pronator teres"}, {"key": "C", "text": "Brachialis"}, {"key": "D", "text": "Biceps brachii"}], "correct": "B", "explanation": "Cubital fossa: medial border — pronator teres; lateral border — brachioradialis; roof — bicipital aponeurosis."}, {"id": 341, "subject": "Anatomy", "difficulty": "Medium", "question": "Contents of cubital fossa from medial to lateral (TAN):", "options": [{"key": "A", "text": "Tendon of biceps, Brachial artery, Median nerve"}, {"key": "B", "text": "Median nerve, Brachial artery, Tendon of biceps"}, {"key": "C", "text": "Radial nerve, Brachial artery, Biceps tendon"}, {"key": "D", "text": "Ulnar nerve, Radial artery, Biceps tendon"}], "correct": "B", "explanation": "Cubital fossa contents medial to lateral: Median nerve, brachial Artery, biceps teNdon (MAN/TAN)."}, {"id": 342, "subject": "Anatomy", "difficulty": "Easy", "question": "Carrying angle of elbow is measured between:", "options": [{"key": "A", "text": "Humerus and radius"}, {"key": "B", "text": "Humerus and ulna"}, {"key": "C", "text": "Radius and ulna"}, {"key": "D", "text": "Forearm and hand"}], "correct": "B", "explanation": "Carrying angle is the angle between long axis of humerus and ulna with elbow in full extension and supination."}, {"id": 343, "subject": "Anatomy", "difficulty": "Medium", "question": "Cubitus valgus (increased carrying angle >15°) can stretch which nerve?", "options": [{"key": "A", "text": "Radial nerve"}, {"key": "B", "text": "Median nerve"}, {"key": "C", "text": "Ulnar nerve"}, {"key": "D", "text": "Axillary nerve"}], "correct": "C", "explanation": "Increased carrying angle (cubitus valgus) stretches ulnar nerve causing tardy ulnar nerve palsy."}, {"id": 344, "subject": "Anatomy", "difficulty": "Easy", "question": "In posterior elbow dislocation, the olecranon displaces:", "options": [{"key": "A", "text": "Anteriorly"}, {"key": "B", "text": "Medially"}, {"key": "C", "text": "Posteriorly"}, {"key": "D", "text": "Laterally"}], "correct": "C", "explanation": "In posterior dislocation (most common elbow dislocation), both radius and ulna displace posteriorly."}, {"id": 345, "subject": "Anatomy", "difficulty": "Easy", "question": "Valgus stress test of elbow tests integrity of:", "options": [{"key": "A", "text": "Lateral collateral ligament"}, {"key": "B", "text": "Medial collateral ligament (UCL)"}, {"key": "C", "text": "Annular ligament"}, {"key": "D", "text": "Interosseous membrane"}], "correct": "B", "explanation": "Valgus stress test (milking maneuver) stresses the medial UCL; pain/laxity indicates UCL injury."}, {"id": 346, "subject": "Anatomy", "difficulty": "Medium", "question": "Cozen's test is used to diagnose:", "options": [{"key": "A", "text": "Medial epicondylitis"}, {"key": "B", "text": "Lateral epicondylitis"}, {"key": "C", "text": "Biceps tendon rupture"}, {"key": "D", "text": "Posterior interosseous nerve entrapment"}], "correct": "B", "explanation": "Cozen's test: resisted wrist extension with elbow extended — pain at lateral epicondyle indicates tennis elbow."}, {"id": 347, "subject": "Anatomy", "difficulty": "Medium", "question": "Mill's test for lateral epicondylitis involves:", "options": [{"key": "A", "text": "Resisted wrist flexion"}, {"key": "B", "text": "Passive wrist flexion with elbow extended and forearm pronated"}, {"key": "C", "text": "Resisted supination"}, {"key": "D", "text": "Resisted pronation"}], "correct": "B", "explanation": "Mill's test: passive wrist/finger flexion with elbow extended — stretches ECRB causing lateral epicondyle pain."}, {"id": 348, "subject": "Anatomy", "difficulty": "Easy", "question": "Normal pronation range of the forearm is approximately:", "options": [{"key": "A", "text": "45°"}, {"key": "B", "text": "60-80°"}, {"key": "C", "text": "90°"}, {"key": "D", "text": "100°"}], "correct": "C", "explanation": "Normal pronation is approximately 80-90°; supination is also 80-90° (some sources 80°)."}, {"id": 349, "subject": "Anatomy", "difficulty": "Easy", "question": "Biceps brachii is the most powerful:", "options": [{"key": "A", "text": "Elbow flexor and pronator"}, {"key": "B", "text": "Elbow flexor and supinator"}, {"key": "C", "text": "Shoulder abductor and flexor"}, {"key": "D", "text": "Wrist flexor"}], "correct": "B", "explanation": "Biceps brachii is a powerful elbow flexor (in supination) and the most powerful supinator of the forearm."}, {"id": 350, "subject": "Anatomy", "difficulty": "Medium", "question": "Popeye sign (distal biceps rupture) causes the muscle belly to:", "options": [{"key": "A", "text": "Disappear"}, {"key": "B", "text": "Migrate distally"}, {"key": "C", "text": "Migrate proximally (bunch up)"}, {"key": "D", "text": "Become elongated"}], "correct": "C", "explanation": "Distal biceps tendon rupture causes the muscle belly to retract/bunch up proximally — Popeye deformity."}, {"id": 351, "subject": "Anatomy", "difficulty": "Easy", "question": "Wrist (radiocarpal) joint is classified as:", "options": [{"key": "A", "text": "Hinge joint"}, {"key": "B", "text": "Ellipsoid (condyloid) joint"}, {"key": "C", "text": "Saddle joint"}, {"key": "D", "text": "Ball and socket"}], "correct": "B", "explanation": "Wrist joint is an ellipsoid (condyloid) synovial joint allowing flexion, extension, and radial/ulnar deviation."}, {"id": 352, "subject": "Anatomy", "difficulty": "Hard", "question": "Distal articular surface of radius is inclined in which direction?", "options": [{"key": "A", "text": "Dorsally and radially"}, {"key": "B", "text": "Volarly and ulnarly"}, {"key": "C", "text": "Horizontally"}, {"key": "D", "text": "Ulnarly only"}], "correct": "B", "explanation": "Normal distal radius has 11-12° of volar tilt and 22-23° of ulnar inclination."}, {"id": 353, "subject": "Anatomy", "difficulty": "Medium", "question": "Ulna does NOT directly articulate with the carpals — which structure separates them?", "options": [{"key": "A", "text": "Palmar carpal ligament"}, {"key": "B", "text": "Triangular fibrocartilage (TFCC)"}, {"key": "C", "text": "Ulnar collateral ligament"}, {"key": "D", "text": "Flexor retinaculum"}], "correct": "B", "explanation": "TFCC (triangular fibrocartilage complex) separates the distal ulna from the carpals at the wrist."}, {"id": 354, "subject": "Anatomy", "difficulty": "Hard", "question": "Radial deviation at the wrist is limited by:", "options": [{"key": "A", "text": "Scaphoid-trapezium contact"}, {"key": "B", "text": "Radial styloid impacting scaphoid"}, {"key": "C", "text": "Ulnar styloid"}, {"key": "D", "text": "TFCC"}], "correct": "B", "explanation": "Radial deviation (~15-20°) is limited when scaphoid impinges against the radial styloid process."}, {"id": 355, "subject": "Anatomy", "difficulty": "Medium", "question": "Ulnar deviation at the wrist has greater range than radial deviation — approximately:", "options": [{"key": "A", "text": "10° vs 30°"}, {"key": "B", "text": "30° vs 15°"}, {"key": "C", "text": "45° vs 30°"}, {"key": "D", "text": "20° vs 20°"}], "correct": "B", "explanation": "Ulnar deviation is ~30-40° while radial deviation is ~15-20°; ulnar deviation allows greater excursion."}, {"id": 356, "subject": "Anatomy", "difficulty": "Medium", "question": "Flexor carpi radialis inserts on base of which metacarpal?", "options": [{"key": "A", "text": "First"}, {"key": "B", "text": "Second and third"}, {"key": "C", "text": "Fourth"}, {"key": "D", "text": "Fifth"}], "correct": "B", "explanation": "FCR inserts primarily on base of 2nd metacarpal with a slip to 3rd metacarpal."}, {"id": 357, "subject": "Anatomy", "difficulty": "Hard", "question": "Flexor carpi ulnaris inserts on which bone primarily?", "options": [{"key": "A", "text": "Pisiform (and via ligaments to hamate and 5th metacarpal)"}, {"key": "B", "text": "Triquetrum"}, {"key": "C", "text": "Hamate directly"}, {"key": "D", "text": "Ulnar styloid"}], "correct": "A", "explanation": "FCU inserts on pisiform, and via pisohamate and pisometacarpal ligaments extends to hamate and 5th metacarpal."}, {"id": 358, "subject": "Anatomy", "difficulty": "Medium", "question": "De Quervain's tenosynovitis affects tendons in which extensor compartment?", "options": [{"key": "A", "text": "First dorsal compartment (APL and EPB)"}, {"key": "B", "text": "Second dorsal compartment"}, {"key": "C", "text": "Third dorsal compartment"}, {"key": "D", "text": "Sixth dorsal compartment"}], "correct": "A", "explanation": "De Quervain's = stenosing tenosynovitis of 1st dorsal compartment containing APL and EPB tendons."}, {"id": 359, "subject": "Anatomy", "difficulty": "Easy", "question": "Finkelstein's test is used to diagnose:", "options": [{"key": "A", "text": "Carpal tunnel syndrome"}, {"key": "B", "text": "De Quervain's tenosynovitis"}, {"key": "C", "text": "TFCC tear"}, {"key": "D", "text": "Scapholunate instability"}], "correct": "B", "explanation": "Finkelstein's: thumb in palm, ulnar deviation of wrist — pain over radial styloid = De Quervain's positive."}, {"id": 360, "subject": "Anatomy", "difficulty": "Easy", "question": "Phalen's test for carpal tunnel syndrome involves:", "options": [{"key": "A", "text": "Wrist extension for 60 seconds"}, {"key": "B", "text": "Wrist flexion for 60 seconds causing median nerve symptoms"}, {"key": "C", "text": "Tapping over carpal tunnel"}, {"key": "D", "text": "Resisted finger flexion"}], "correct": "B", "explanation": "Phalen's test: sustained wrist flexion (60 sec) compresses median nerve, reproducing CTS symptoms."}, {"id": 361, "subject": "Anatomy", "difficulty": "Easy", "question": "Tinel's sign at the wrist indicates:", "options": [{"key": "A", "text": "Ulnar nerve injury"}, {"key": "B", "text": "Radial nerve injury"}, {"key": "C", "text": "Median nerve regeneration or compression"}, {"key": "D", "text": "TFCC tear"}], "correct": "C", "explanation": "Tinel's sign: tapping over carpal tunnel produces tingling in median nerve distribution — indicates CTS."}, {"id": 362, "subject": "Anatomy", "difficulty": "Medium", "question": "TFCC tear causes pain specifically with:", "options": [{"key": "A", "text": "Wrist flexion"}, {"key": "B", "text": "Radial deviation"}, {"key": "C", "text": "Ulnar-sided wrist pain, worse with forearm rotation"}, {"key": "D", "text": "Wrist extension only"}], "correct": "C", "explanation": "TFCC tears cause ulnar-sided wrist pain exacerbated by gripping, forearm rotation and ulnar deviation."}, {"id": 363, "subject": "Anatomy", "difficulty": "Hard", "question": "The piano key sign at the wrist (DRUJ) indicates:", "options": [{"key": "A", "text": "TFCC tear"}, {"key": "B", "text": "Scapholunate instability"}, {"key": "C", "text": "Distal ulna dorsal instability"}, {"key": "D", "text": "De Quervain's"}], "correct": "C", "explanation": "Piano key sign at DRUJ: dorsal prominence of distal ulna that springs back on pressure — DRUJ instability."}, {"id": 364, "subject": "Anatomy", "difficulty": "Easy", "question": "Midcarpal joint is between:", "options": [{"key": "A", "text": "Radius and proximal carpals"}, {"key": "B", "text": "Proximal and distal carpal rows"}, {"key": "C", "text": "Distal carpals and metacarpals"}, {"key": "D", "text": "DRUJ and radiocarpal joint"}], "correct": "B", "explanation": "Midcarpal joint lies between the proximal and distal rows of carpal bones."}, {"id": 365, "subject": "Anatomy", "difficulty": "Easy", "question": "Carpometacarpal (CMC) joint of thumb is a saddle joint allowing:", "options": [{"key": "A", "text": "Flexion-extension only"}, {"key": "B", "text": "Flexion, extension, abduction, adduction, and opposition"}, {"key": "C", "text": "Rotation only"}, {"key": "D", "text": "Hinge movements only"}], "correct": "B", "explanation": "Thumb CMC joint (trapezio-metacarpal) is a saddle joint allowing multi-directional movement including opposition."}, {"id": 366, "subject": "Anatomy", "difficulty": "Hard", "question": "Scapholunate dissociation shows which finding on X-ray?", "options": [{"key": "A", "text": "Terry Thomas sign (gap > 3mm between scaphoid and lunate)"}, {"key": "B", "text": "Traction spur on lunate"}, {"key": "C", "text": "Distal radius tilt"}, {"key": "D", "text": "Pisiform fracture"}], "correct": "A", "explanation": "Scapholunate dissociation = >3mm gap between scaphoid and lunate on PA X-ray (Terry Thomas/David Letterman sign)."}, {"id": 367, "subject": "Anatomy", "difficulty": "Medium", "question": "Normal wrist flexion-extension total arc is approximately:", "options": [{"key": "A", "text": "100°"}, {"key": "B", "text": "130°"}, {"key": "C", "text": "160-170°"}, {"key": "D", "text": "90°"}], "correct": "C", "explanation": "Normal wrist: flexion ~80-85° + extension ~70-80° = total arc ~160-170°. Functional arc: 40° flex to 40° ext."}, {"id": 368, "subject": "Anatomy", "difficulty": "Medium", "question": "Extensor retinaculum at the wrist has how many compartments?", "options": [{"key": "A", "text": "4"}, {"key": "B", "text": "5"}, {"key": "C", "text": "6"}, {"key": "D", "text": "8"}], "correct": "C", "explanation": "Extensor retinaculum divides into 6 compartments for the extensor tendons of the wrist and hand."}, {"id": 369, "subject": "Anatomy", "difficulty": "Hard", "question": "EPL tendon runs in which dorsal compartment of the wrist?", "options": [{"key": "A", "text": "First"}, {"key": "B", "text": "Second"}, {"key": "C", "text": "Third"}, {"key": "D", "text": "Fourth"}], "correct": "C", "explanation": "EPL runs in the 3rd dorsal compartment (with Lister's tubercle as a pulley) before reaching thumb."}, {"id": 370, "subject": "Anatomy", "difficulty": "Easy", "question": "Wrist drop is due to injury of which nerve?", "options": [{"key": "A", "text": "Ulnar nerve"}, {"key": "B", "text": "Median nerve"}, {"key": "C", "text": "Radial nerve"}, {"key": "D", "text": "Anterior interosseous nerve"}], "correct": "C", "explanation": "Radial nerve injury causes wrist drop — loss of wrist and finger extension due to extensor muscle paralysis."}, {"id": 371, "subject": "Anatomy", "difficulty": "Easy", "question": "Guyon's canal syndrome causes sensory loss in:", "options": [{"key": "A", "text": "Thumb, index and middle finger"}, {"key": "B", "text": "Ring and little finger"}, {"key": "C", "text": "All fingers"}, {"key": "D", "text": "Dorsum of hand"}], "correct": "B", "explanation": "Guyon's canal syndrome (ulnar nerve compression) causes numbness in ring and little fingers."}, {"id": 372, "subject": "Anatomy", "difficulty": "Hard", "question": "The 'dangerous arc' of shoulder abduction where most rotator cuff tears occur is at:", "options": [{"key": "A", "text": "0-30°"}, {"key": "B", "text": "30-60°"}, {"key": "C", "text": "60-90°"}, {"key": "D", "text": "Above 90°"}], "correct": "C", "explanation": "Supraspinatus tension is greatest between 60-90° of abduction — the zone of maximal impingement risk."}, {"id": 373, "subject": "Anatomy", "difficulty": "Medium", "question": "Scapulohumeral rhythm ratio during arm elevation is:", "options": [{"key": "A", "text": "1:1"}, {"key": "B", "text": "2:1 (glenohumeral:scapulothoracic)"}, {"key": "C", "text": "1:2"}, {"key": "D", "text": "3:1"}], "correct": "B", "explanation": "Normal scapulohumeral rhythm: 2° glenohumeral movement for every 1° scapulothoracic movement (2:1 ratio)."}, {"id": 374, "subject": "Anatomy", "difficulty": "Medium", "question": "Winging of scapula is caused by paralysis of which muscle?", "options": [{"key": "A", "text": "Trapezius"}, {"key": "B", "text": "Serratus anterior"}, {"key": "C", "text": "Rhomboids"}, {"key": "D", "text": "Both A and B"}], "correct": "D", "explanation": "Medial (vertebral border) winging — serratus anterior palsy; lateral winging — trapezius palsy."}, {"id": 375, "subject": "Anatomy", "difficulty": "Medium", "question": "Long thoracic nerve injury causes winging of scapula by paralyzing:", "options": [{"key": "A", "text": "Trapezius"}, {"key": "B", "text": "Serratus anterior"}, {"key": "C", "text": "Rhomboids"}, {"key": "D", "text": "Levator scapulae"}], "correct": "B", "explanation": "Long thoracic nerve (C5,6,7) supplies serratus anterior; its injury causes classic medial border winging."}, {"id": 376, "subject": "Anatomy", "difficulty": "Hard", "question": "Suprascapular nerve entrapment at the spinoglenoid notch causes weakness of:", "options": [{"key": "A", "text": "Supraspinatus only"}, {"key": "B", "text": "Infraspinatus only"}, {"key": "C", "text": "Both supraspinatus and infraspinatus"}, {"key": "D", "text": "Subscapularis"}], "correct": "B", "explanation": "Entrapment at spinoglenoid notch affects only infraspinatus (supraspinatus branch already given off at suprascapular notch)."}, {"id": 377, "subject": "Anatomy", "difficulty": "Medium", "question": "Speed's test is positive in pathology of:", "options": [{"key": "A", "text": "Supraspinatus"}, {"key": "B", "text": "Long head of biceps tendon"}, {"key": "C", "text": "Subscapularis"}, {"key": "D", "text": "SLAP lesion"}], "correct": "B", "explanation": "Speed's test: resisted shoulder flexion with elbow extended and forearm supinated — positive for bicipital tendinitis."}, {"id": 378, "subject": "Anatomy", "difficulty": "Medium", "question": "Yergason's test assesses:", "options": [{"key": "A", "text": "Rotator cuff integrity"}, {"key": "B", "text": "Long head of biceps stability in bicipital groove"}, {"key": "C", "text": "AC joint pathology"}, {"key": "D", "text": "Shoulder instability"}], "correct": "B", "explanation": "Yergason's test: resisted supination with elbow at 90° — pain in bicipital groove indicates biceps tendinitis/instability."}, {"id": 379, "subject": "Anatomy", "difficulty": "Easy", "question": "Apprehension test for shoulder tests for:", "options": [{"key": "A", "text": "Rotator cuff tear"}, {"key": "B", "text": "AC joint instability"}, {"key": "C", "text": "Anterior glenohumeral instability"}, {"key": "D", "text": "SLAP lesion"}], "correct": "C", "explanation": "Apprehension test: arm in 90° abduction and external rotation — patient feels apprehension of dislocation."}, {"id": 380, "subject": "Anatomy", "difficulty": "Medium", "question": "Relocation test (Jobe's relocation test) is a follow-up to which test?", "options": [{"key": "A", "text": "Empty can test"}, {"key": "B", "text": "Apprehension test"}, {"key": "C", "text": "Speed's test"}, {"key": "D", "text": "Neer's test"}], "correct": "B", "explanation": "Relocation test: posterior pressure on proximal humerus during apprehension test — relief confirms anterior instability."}, {"id": 381, "subject": "Anatomy", "difficulty": "Easy", "question": "The most common direction of recurrent shoulder instability is:", "options": [{"key": "A", "text": "Posterior"}, {"key": "B", "text": "Inferior"}, {"key": "C", "text": "Anterior-inferior"}, {"key": "D", "text": "Superior"}], "correct": "C", "explanation": "Anterior-inferior instability is most common (>95%) — associated with Bankart and Hill-Sachs lesions."}, {"id": 382, "subject": "Anatomy", "difficulty": "Hard", "question": "Type II SLAP lesion (most common) involves:", "options": [{"key": "A", "text": "Fraying of superior labrum only"}, {"key": "B", "text": "Detachment of biceps anchor and superior labrum"}, {"key": "C", "text": "Posterior labrum only"}, {"key": "D", "text": "Bucket handle tear of labrum"}], "correct": "B", "explanation": "Type II SLAP = detachment of biceps-labral complex from superior glenoid — most clinically significant type."}, {"id": 383, "subject": "Anatomy", "difficulty": "Medium", "question": "Sulcus sign indicates:", "options": [{"key": "A", "text": "AC joint instability"}, {"key": "B", "text": "Inferior glenohumeral instability"}, {"key": "C", "text": "Posterior instability"}, {"key": "D", "text": "Rotator cuff tear"}], "correct": "B", "explanation": "Sulcus sign: downward traction on arm creates a dimple below acromion — indicates inferior shoulder laxity/MDI."}, {"id": 384, "subject": "Anatomy", "difficulty": "Easy", "question": "Multidirectional instability (MDI) of shoulder is best treated initially with:", "options": [{"key": "A", "text": "Surgery"}, {"key": "B", "text": "Immobilization"}, {"key": "C", "text": "Physiotherapy and muscle strengthening"}, {"key": "D", "text": "Steroid injection"}], "correct": "C", "explanation": "MDI is primarily treated conservatively with rotator cuff and periscapular strengthening for 6 months."}, {"id": 385, "subject": "Anatomy", "difficulty": "Medium", "question": "Calcific tendinitis of the shoulder most commonly affects which tendon?", "options": [{"key": "A", "text": "Subscapularis"}, {"key": "B", "text": "Infraspinatus"}, {"key": "C", "text": "Supraspinatus (critical zone)"}, {"key": "D", "text": "Teres minor"}], "correct": "C", "explanation": "Calcific tendinitis most commonly occurs in the critical zone of supraspinatus — 1 cm from its insertion."}, {"id": 386, "subject": "Anatomy", "difficulty": "Hard", "question": "The 'critical zone' of supraspinatus tendon is an area of:", "options": [{"key": "A", "text": "Maximum tension"}, {"key": "B", "text": "Relative avascularity"}, {"key": "C", "text": "Maximum thickness"}, {"key": "D", "text": "Nerve supply"}], "correct": "B", "explanation": "Critical zone is ~1 cm from supraspinatus insertion — relatively avascular, predisposing to tears and calcification."}, {"id": 387, "subject": "Anatomy", "difficulty": "Easy", "question": "Varus stress test of elbow tests which ligament?", "options": [{"key": "A", "text": "Medial UCL"}, {"key": "B", "text": "Lateral collateral ligament complex"}, {"key": "C", "text": "Annular ligament"}, {"key": "D", "text": "Interosseous membrane"}], "correct": "B", "explanation": "Varus stress test stresses the lateral collateral ligament complex of the elbow."}, {"id": 388, "subject": "Anatomy", "difficulty": "Hard", "question": "Moving valgus stress test is the most sensitive test for:", "options": [{"key": "A", "text": "Lateral epicondylitis"}, {"key": "B", "text": "UCL injury in throwing athletes"}, {"key": "C", "text": "Posterior impingement"}, {"key": "D", "text": "Radial head fracture"}], "correct": "B", "explanation": "Moving valgus stress test: valgus stress while moving elbow 30-120° — pain at 70-120° (shear zone) = UCL tear."}, {"id": 389, "subject": "Anatomy", "difficulty": "Easy", "question": "Radial head fracture most commonly results from:", "options": [{"key": "A", "text": "Direct blow"}, {"key": "B", "text": "Fall on outstretched hand (FOOSH)"}, {"key": "C", "text": "Throwing"}, {"key": "D", "text": "Hyperextension only"}], "correct": "B", "explanation": "Radial head fracture commonly results from FOOSH — axial load transmitted through radius to radial head."}, {"id": 390, "subject": "Anatomy", "difficulty": "Medium", "question": "Mason classification is used for:", "options": [{"key": "A", "text": "Elbow dislocation"}, {"key": "B", "text": "Radial head fractures"}, {"key": "C", "text": "Lateral epicondylitis grades"}, {"key": "D", "text": "Coronoid fractures"}], "correct": "B", "explanation": "Mason classification (Types I-IV) grades radial head fractures by displacement and comminution."}, {"id": 391, "subject": "Anatomy", "difficulty": "Hard", "question": "Posterior interosseous nerve (PIN) entrapment occurs at:", "options": [{"key": "A", "text": "Cubital tunnel"}, {"key": "B", "text": "Radial tunnel (Arcade of Frohse)"}, {"key": "C", "text": "Carpal tunnel"}, {"key": "D", "text": "Guyon's canal"}], "correct": "B", "explanation": "PIN is entrapped at the arcade of Frohse (fibrous arch at supinator muscle) — causes radial tunnel syndrome."}, {"id": 392, "subject": "Anatomy", "difficulty": "Hard", "question": "Radial tunnel syndrome pain is located:", "options": [{"key": "A", "text": "Directly over lateral epicondyle"}, {"key": "B", "text": "4-5 cm distal to lateral epicondyle over radial tunnel"}, {"key": "C", "text": "Medial elbow"}, {"key": "D", "text": "Posterior elbow"}], "correct": "B", "explanation": "Radial tunnel syndrome pain is 4-5 cm distal to lateral epicondyle — distinct from epicondylitis location."}, {"id": 393, "subject": "Anatomy", "difficulty": "Medium", "question": "Distal biceps tendon rupture best position for repair is:", "options": [{"key": "A", "text": "Immediate repair within 2 weeks"}, {"key": "B", "text": "Delayed repair at 6 weeks"}, {"key": "C", "text": "Conservative management only"}, {"key": "D", "text": "Never surgical"}], "correct": "A", "explanation": "Distal biceps rupture: surgical repair within 2 weeks gives best outcomes; delay causes retraction and scarring."}, {"id": 394, "subject": "Anatomy", "difficulty": "Hard", "question": "Triceps tendon rupture is the LEAST common tendon rupture in the body. Mechanism is:", "options": [{"key": "A", "text": "Fall on outstretched hand"}, {"key": "B", "text": "Forceful flexion against resisting extension"}, {"key": "C", "text": "Direct blow only"}, {"key": "D", "text": "Overuse"}], "correct": "B", "explanation": "Triceps rupture: forceful elbow flexion against an actively contracting triceps (eccentric failure)."}, {"id": 395, "subject": "Anatomy", "difficulty": "Hard", "question": "Lateral pivot shift test of elbow tests for:", "options": [{"key": "A", "text": "UCL integrity"}, {"key": "B", "text": "Posterolateral rotatory instability (PLRI)"}, {"key": "C", "text": "Radial head dislocation"}, {"key": "D", "text": "Annular ligament injury"}], "correct": "B", "explanation": "Lateral pivot shift test: supination + valgus + axial load in flexion — positive for PLRI (LUCL injury)."}, {"id": 396, "subject": "Anatomy", "difficulty": "Medium", "question": "Cubital tunnel syndrome is the second most common peripheral nerve compression after:", "options": [{"key": "A", "text": "Radial tunnel syndrome"}, {"key": "B", "text": "Carpal tunnel syndrome"}, {"key": "C", "text": "Thoracic outlet syndrome"}, {"key": "D", "text": "Guyon's canal syndrome"}], "correct": "B", "explanation": "Cubital tunnel syndrome (ulnar nerve at elbow) is second most common after CTS (median nerve at wrist)."}, {"id": 397, "subject": "Anatomy", "difficulty": "Hard", "question": "Scapholunate angle on lateral wrist X-ray is normally:", "options": [{"key": "A", "text": "10-20°"}, {"key": "B", "text": "30-60°"}, {"key": "C", "text": "70-90°"}, {"key": "D", "text": "100-120°"}], "correct": "B", "explanation": "Normal scapholunate angle is 30-60° (average 47°); >70° suggests scapholunate dissociation."}, {"id": 398, "subject": "Anatomy", "difficulty": "Hard", "question": "DISI (Dorsal Intercalated Segment Instability) shows:", "options": [{"key": "A", "text": "Lunate tilts volar, scaphoid tilts dorsal"}, {"key": "B", "text": "Lunate tilts dorsal, scaphoid flexes"}, {"key": "C", "text": "Both bones rotate equally"}, {"key": "D", "text": "Capitate dislocates"}], "correct": "B", "explanation": "DISI: lunate tilts dorsally (extended) due to scapholunate ligament rupture — SL angle >70°."}, {"id": 399, "subject": "Anatomy", "difficulty": "Hard", "question": "VISI (Volar Intercalated Segment Instability) is associated with:", "options": [{"key": "A", "text": "Scapholunate ligament tear"}, {"key": "B", "text": "Lunotriquetral ligament tear"}, {"key": "C", "text": "TFCC tear only"}, {"key": "D", "text": "Distal radius fracture"}], "correct": "B", "explanation": "VISI: lunate tilts volarly due to lunotriquetral ligament injury — SL angle < 30°."}, {"id": 400, "subject": "Anatomy", "difficulty": "Medium", "question": "Ulnar variance refers to:", "options": [{"key": "A", "text": "Ulnar deviation angle"}, {"key": "B", "text": "Relative length difference between distal radius and ulna"}, {"key": "C", "text": "Ulnar styloid length"}, {"key": "D", "text": "DRUJ gap"}], "correct": "B", "explanation": "Ulnar variance = relative length of distal ulnar articular surface vs distal radius (positive, negative or neutral)."}, {"id": 401, "subject": "Anatomy", "difficulty": "Hard", "question": "Positive ulnar variance is associated with:", "options": [{"key": "A", "text": "Kienbock's disease"}, {"key": "B", "text": "TFCC tears and ulnocarpal impaction"}, {"key": "C", "text": "Scapholunate dissociation"}, {"key": "D", "text": "Galeazzi fracture only"}], "correct": "B", "explanation": "Positive ulnar variance (ulna longer than radius) causes ulnocarpal impaction and increased TFCC stress."}, {"id": 402, "subject": "Anatomy", "difficulty": "Medium", "question": "Grind test (compression rotation test) of thumb CMC joint diagnoses:", "options": [{"key": "A", "text": "Scaphoid fracture"}, {"key": "B", "text": "De Quervain's tenosynovitis"}, {"key": "C", "text": "Basal thumb arthritis (CMC OA)"}, {"key": "D", "text": "Trigger thumb"}], "correct": "C", "explanation": "Grind test: axial compression + rotation of thumb CMC joint — pain/crepitus = CMC osteoarthritis."}, {"id": 403, "subject": "Anatomy", "difficulty": "Hard", "question": "Intersection syndrome is inflammation of which tendons crossing?", "options": [{"key": "A", "text": "1st and 2nd dorsal compartment tendons"}, {"key": "B", "text": "2nd and 3rd dorsal compartment tendons"}, {"key": "C", "text": "3rd and 4th dorsal compartment tendons"}, {"key": "D", "text": "FCR and FCU"}], "correct": "A", "explanation": "Intersection syndrome: 1st compartment (APL, EPB) crossing 2nd compartment (ECRL, ECRB) ~4 cm proximal to wrist."}, {"id": 404, "subject": "Anatomy", "difficulty": "Medium", "question": "Trigger finger is due to stenosis of:", "options": [{"key": "A", "text": "Carpal tunnel"}, {"key": "B", "text": "A1 pulley of the finger flexor tendon sheath"}, {"key": "C", "text": "Extensor retinaculum"}, {"key": "D", "text": "Lumbrical canal"}], "correct": "B", "explanation": "Trigger finger = stenosing tenosynovitis at A1 pulley causing catching/locking of the flexor tendon."}, {"id": 405, "subject": "Anatomy", "difficulty": "Hard", "question": "Linburg-Comstock syndrome is anomalous connection between tendons of:", "options": [{"key": "A", "text": "FDS and FDP"}, {"key": "B", "text": "FPL and FDP of index finger"}, {"key": "C", "text": "EPL and EIP"}, {"key": "D", "text": "APL and EPB"}], "correct": "B", "explanation": "Linburg-Comstock: anomalous tendinous slip between FPL and FDP of index finger causing linked movement."}, {"id": 406, "subject": "Anatomy", "difficulty": "Hard", "question": "Codman's paradox refers to:", "options": [{"key": "A", "text": "Painful arc phenomenon"}, {"key": "B", "text": "Rotation produced by circumduction without active rotation"}, {"key": "C", "text": "Shoulder instability pattern"}, {"key": "D", "text": "Scapular rhythm reversal"}], "correct": "B", "explanation": "Codman's paradox: after circumduction the arm ends in opposite rotation to start — demonstrates coupled motions."}, {"id": 407, "subject": "Anatomy", "difficulty": "Hard", "question": "Zero position of shoulder (Saha's zero position) is at:", "options": [{"key": "A", "text": "0° — arm at side"}, {"key": "B", "text": "90° abduction in scapular plane with full external rotation"}, {"key": "C", "text": "Full elevation"}, {"key": "D", "text": "90° forward flexion"}], "correct": "B", "explanation": "Zero position: arm in scapular plane at ~155° elevation — glenohumeral and scapular axes aligned; most stable."}, {"id": 408, "subject": "Anatomy", "difficulty": "Medium", "question": "GIRD (Glenohumeral Internal Rotation Deficit) is common in:", "options": [{"key": "A", "text": "Swimmers"}, {"key": "B", "text": "Overhead throwing athletes"}, {"key": "C", "text": "Weight lifters"}, {"key": "D", "text": "Gymnasts"}], "correct": "B", "explanation": "GIRD is common in throwers (baseball pitchers) — posterior capsule tightness restricts internal rotation."}, {"id": 409, "subject": "Anatomy", "difficulty": "Hard", "question": "Thrower's shoulder 'dead arm' syndrome is caused by:", "options": [{"key": "A", "text": "Rotator cuff tear"}, {"key": "B", "text": "Transient anterior subluxation causing neurovascular symptoms"}, {"key": "C", "text": "AC joint injury"}, {"key": "D", "text": "Biceps rupture"}], "correct": "B", "explanation": "Dead arm = transient neurological symptoms from anterior subluxation during late cocking phase of throwing."}, {"id": 410, "subject": "Anatomy", "difficulty": "Medium", "question": "Lateral epicondylitis is due to degeneration of which tendon and at what location?", "options": [{"key": "A", "text": "ECRL at origin"}, {"key": "B", "text": "ECRB at its origin on lateral epicondyle"}, {"key": "C", "text": "EDC at musculotendinous junction"}, {"key": "D", "text": "ECU at lateral epicondyle"}], "correct": "B", "explanation": "Tennis elbow = angiofibroblastic tendinosis of ECRB at its origin on lateral epicondyle."}, {"id": 411, "subject": "Anatomy", "difficulty": "Medium", "question": "Normal elbow carrying angle in females is:", "options": [{"key": "A", "text": "5-10°"}, {"key": "B", "text": "10-15°"}, {"key": "C", "text": "15-20°"}, {"key": "D", "text": "20-25°"}], "correct": "C", "explanation": "Carrying angle in females is approximately 13-15° (some references up to 15-20°) — greater than males."}, {"id": 412, "subject": "Anatomy", "difficulty": "Easy", "question": "Nursemaid's elbow (pulled elbow) most commonly occurs in children aged:", "options": [{"key": "A", "text": "Below 1 year"}, {"key": "B", "text": "1-4 years"}, {"key": "C", "text": "5-10 years"}, {"key": "D", "text": "Above 10 years"}], "correct": "B", "explanation": "Pulled elbow most common in 1-4 year olds — annular ligament is lax and radial head is smaller."}, {"id": 413, "subject": "Anatomy", "difficulty": "Medium", "question": "After elbow dislocation reduction, which movement is tested first?", "options": [{"key": "A", "text": "Supination-pronation"}, {"key": "B", "text": "Flexion-extension arc and valgus-varus stability"}, {"key": "C", "text": "Wrist extension"}, {"key": "D", "text": "Shoulder rotation"}], "correct": "B", "explanation": "After reduction, elbow is tested through flexion-extension arc and stressed for medial/lateral stability."}, {"id": 414, "subject": "Anatomy", "difficulty": "Hard", "question": "Wartenberg's syndrome is entrapment of:", "options": [{"key": "A", "text": "Posterior interosseous nerve"}, {"key": "B", "text": "Anterior interosseous nerve"}, {"key": "C", "text": "Superficial branch of radial nerve"}, {"key": "D", "text": "Ulnar nerve at wrist"}], "correct": "C", "explanation": "Wartenberg's syndrome: entrapment of superficial radial nerve causing dorsoradial forearm/hand sensory symptoms."}, {"id": 415, "subject": "Anatomy", "difficulty": "Hard", "question": "Normal grip strength loss expected after wrist fusion (arthrodesis) is:", "options": [{"key": "A", "text": "No loss"}, {"key": "B", "text": "~10-15% loss"}, {"key": "C", "text": "~50% loss"}, {"key": "D", "text": "~80% loss"}], "correct": "B", "explanation": "Wrist fusion sacrifices all wrist motion but grip strength is generally well preserved (~10-15% reduction)."}, {"id": 416, "subject": "Anatomy", "difficulty": "Medium", "question": "Scapular plane (scaption) is approximately how many degrees anterior to the coronal plane?", "options": [{"key": "A", "text": "15°"}, {"key": "B", "text": "30-45°"}, {"key": "C", "text": "60°"}, {"key": "D", "text": "90°"}], "correct": "B", "explanation": "Scapular plane (scaption) is 30-45° anterior to the coronal plane — optimal position for shoulder function."}, {"id": 417, "subject": "Anatomy", "difficulty": "Hard", "question": "In FOOSH injury, which combination represents 'terrible triad' of the elbow?", "options": [{"key": "A", "text": "Radial head fracture + UCL tear + elbow dislocation"}, {"key": "B", "text": "Elbow dislocation + radial head fracture + coronoid fracture"}, {"key": "C", "text": "Olecranon fracture + UCL + lateral ligament tear"}, {"key": "D", "text": "Coronoid + olecranon + MCL tear"}], "correct": "B", "explanation": "Terrible triad of elbow = elbow dislocation + radial head fracture + coronoid process fracture."}, {"id": 418, "subject": "Anatomy", "difficulty": "Easy", "question": "SITS mnemonic for rotator cuff muscles stands for:", "options": [{"key": "A", "text": "Subscapularis, Infraspinatus, Teres major, Supraspinatus"}, {"key": "B", "text": "Supraspinatus, Infraspinatus, Teres minor, Subscapularis"}, {"key": "C", "text": "Supraspinatus, Infraspinatus, Teres major, Serratus"}, {"key": "D", "text": "Subscapularis, Infraspinatus, Trapezius, Supraspinatus"}], "correct": "B", "explanation": "SITS = Supraspinatus, Infraspinatus, Teres minor, Subscapularis — all 4 rotator cuff muscles."}, {"id": 419, "subject": "Anatomy", "difficulty": "Easy", "question": "Supraspinatus originates from which fossa of scapula?", "options": [{"key": "A", "text": "Infraspinous fossa"}, {"key": "B", "text": "Subscapular fossa"}, {"key": "C", "text": "Supraspinous fossa"}, {"key": "D", "text": "Glenoid fossa"}], "correct": "C", "explanation": "Supraspinatus originates from the supraspinous fossa of scapula above the spine of scapula."}, {"id": 420, "subject": "Anatomy", "difficulty": "Easy", "question": "Supraspinatus inserts on which facet of greater tubercle?", "options": [{"key": "A", "text": "Middle facet"}, {"key": "B", "text": "Lower facet"}, {"key": "C", "text": "Upper (highest) facet"}, {"key": "D", "text": "Lesser tubercle"}], "correct": "C", "explanation": "Supraspinatus inserts on the uppermost (highest) facet of the greater tubercle of humerus."}, {"id": 421, "subject": "Anatomy", "difficulty": "Easy", "question": "Primary action of supraspinatus is:", "options": [{"key": "A", "text": "Internal rotation"}, {"key": "B", "text": "External rotation"}, {"key": "C", "text": "Initiation of abduction (0-15°)"}, {"key": "D", "text": "Adduction"}], "correct": "C", "explanation": "Supraspinatus initiates abduction and compresses humeral head into glenoid; acts throughout entire abduction arc."}, {"id": 422, "subject": "Anatomy", "difficulty": "Easy", "question": "Nerve supply of supraspinatus is:", "options": [{"key": "A", "text": "Axillary nerve"}, {"key": "B", "text": "Thoracodorsal nerve"}, {"key": "C", "text": "Suprascapular nerve (C5,C6)"}, {"key": "D", "text": "Upper subscapular nerve"}], "correct": "C", "explanation": "Supraspinatus is supplied by the suprascapular nerve (C5, C6) which passes through the suprascapular notch."}, {"id": 423, "subject": "Anatomy", "difficulty": "Easy", "question": "Infraspinatus originates from which fossa?", "options": [{"key": "A", "text": "Supraspinous fossa"}, {"key": "B", "text": "Subscapular fossa"}, {"key": "C", "text": "Infraspinous fossa"}, {"key": "D", "text": "Teres fossa"}], "correct": "C", "explanation": "Infraspinatus originates from the infraspinous fossa of scapula, below the spine of scapula."}, {"id": 424, "subject": "Anatomy", "difficulty": "Easy", "question": "Infraspinatus inserts on which facet of greater tubercle?", "options": [{"key": "A", "text": "Highest facet"}, {"key": "B", "text": "Middle facet"}, {"key": "C", "text": "Lowest facet"}, {"key": "D", "text": "Lesser tubercle"}], "correct": "B", "explanation": "Infraspinatus inserts on the middle facet of the greater tubercle of humerus."}, {"id": 425, "subject": "Anatomy", "difficulty": "Easy", "question": "Primary action of infraspinatus is:", "options": [{"key": "A", "text": "Internal rotation of shoulder"}, {"key": "B", "text": "External rotation of shoulder"}, {"key": "C", "text": "Abduction of shoulder"}, {"key": "D", "text": "Adduction of shoulder"}], "correct": "B", "explanation": "Infraspinatus is the primary external rotator of the shoulder along with teres minor."}, {"id": 426, "subject": "Anatomy", "difficulty": "Easy", "question": "Teres minor inserts on which facet of greater tubercle?", "options": [{"key": "A", "text": "Highest facet"}, {"key": "B", "text": "Middle facet"}, {"key": "C", "text": "Lowest (inferior) facet"}, {"key": "D", "text": "Lesser tubercle"}], "correct": "C", "explanation": "Teres minor inserts on the lowest (inferior) facet of the greater tubercle of humerus."}, {"id": 427, "subject": "Anatomy", "difficulty": "Medium", "question": "Teres minor is supplied by which nerve?", "options": [{"key": "A", "text": "Suprascapular nerve"}, {"key": "B", "text": "Upper subscapular nerve"}, {"key": "C", "text": "Posterior branch of axillary nerve"}, {"key": "D", "text": "Lower subscapular nerve"}], "correct": "C", "explanation": "Teres minor is supplied by the posterior branch of the axillary nerve (C5, C6)."}, {"id": 428, "subject": "Anatomy", "difficulty": "Easy", "question": "Subscapularis originates from:", "options": [{"key": "A", "text": "Supraspinous fossa"}, {"key": "B", "text": "Infraspinous fossa"}, {"key": "C", "text": "Subscapular fossa (costal surface of scapula)"}, {"key": "D", "text": "Spine of scapula"}], "correct": "C", "explanation": "Subscapularis originates from the subscapular fossa on the costal (anterior) surface of the scapula."}, {"id": 429, "subject": "Anatomy", "difficulty": "Easy", "question": "Subscapularis inserts on:", "options": [{"key": "A", "text": "Greater tubercle — highest facet"}, {"key": "B", "text": "Greater tubercle — middle facet"}, {"key": "C", "text": "Lesser tubercle of humerus"}, {"key": "D", "text": "Intertubercular groove floor"}], "correct": "C", "explanation": "Subscapularis inserts on the lesser tubercle of humerus — the only rotator cuff muscle to do so."}, {"id": 430, "subject": "Anatomy", "difficulty": "Easy", "question": "Primary action of subscapularis is:", "options": [{"key": "A", "text": "External rotation and abduction"}, {"key": "B", "text": "Internal rotation and adduction of shoulder"}, {"key": "C", "text": "Flexion of shoulder"}, {"key": "D", "text": "Extension of shoulder"}], "correct": "B", "explanation": "Subscapularis is the primary internal rotator of the shoulder and also assists in adduction."}, {"id": 431, "subject": "Anatomy", "difficulty": "Medium", "question": "Subscapularis is supplied by which nerves?", "options": [{"key": "A", "text": "Suprascapular nerve"}, {"key": "B", "text": "Axillary nerve"}, {"key": "C", "text": "Upper and lower subscapular nerves (C5,C6)"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "C", "explanation": "Subscapularis is supplied by upper subscapular nerve (C5,6) and lower subscapular nerve (C5,6)."}, {"id": 432, "subject": "Anatomy", "difficulty": "Easy", "question": "Lift-off test specifically tests which rotator cuff muscle?", "options": [{"key": "A", "text": "Supraspinatus"}, {"key": "B", "text": "Infraspinatus"}, {"key": "C", "text": "Teres minor"}, {"key": "D", "text": "Subscapularis"}], "correct": "D", "explanation": "Lift-off test (Gerber): hand behind back, lift away from lumbar spine — tests subscapularis integrity."}, {"id": 433, "subject": "Anatomy", "difficulty": "Medium", "question": "Bear hug test is another clinical test for:", "options": [{"key": "A", "text": "Supraspinatus tear"}, {"key": "B", "text": "Subscapularis tear"}, {"key": "C", "text": "Infraspinatus tear"}, {"key": "D", "text": "Teres minor tear"}], "correct": "B", "explanation": "Bear hug test: patient places hand on opposite shoulder, examiner tries to pull it away — tests subscapularis."}, {"id": 434, "subject": "Anatomy", "difficulty": "Easy", "question": "Most commonly torn rotator cuff tendon is:", "options": [{"key": "A", "text": "Subscapularis"}, {"key": "B", "text": "Infraspinatus"}, {"key": "C", "text": "Supraspinatus"}, {"key": "D", "text": "Teres minor"}], "correct": "C", "explanation": "Supraspinatus is the most commonly torn rotator cuff tendon, especially at the critical zone (1 cm from insertion)."}, {"id": 435, "subject": "Anatomy", "difficulty": "Medium", "question": "Full-thickness supraspinatus tear on MRI shows which sign?", "options": [{"key": "A", "text": "Dark signal in tendon"}, {"key": "B", "text": "Fluid signal (bright on T2) through full thickness of tendon"}, {"key": "C", "text": "Thickened tendon"}, {"key": "D", "text": "Calcification only"}], "correct": "B", "explanation": "Full-thickness tear shows bright T2 fluid signal extending through entire thickness of supraspinatus tendon."}, {"id": 436, "subject": "Anatomy", "difficulty": "Medium", "question": "Rotator cuff muscles collectively perform which key biomechanical function?", "options": [{"key": "A", "text": "Abduction only"}, {"key": "B", "text": "Force couple with deltoid for abduction"}, {"key": "C", "text": "Compression of humeral head into glenoid (concavity compression)"}, {"key": "D", "text": "Elevation of scapula"}], "correct": "C", "explanation": "Rotator cuff muscles compress the humeral head into the glenoid (concavity compression), providing dynamic stability."}, {"id": 437, "subject": "Anatomy", "difficulty": "Medium", "question": "External rotation lag sign indicates tear of:", "options": [{"key": "A", "text": "Supraspinatus"}, {"key": "B", "text": "Subscapularis"}, {"key": "C", "text": "Infraspinatus and/or teres minor"}, {"key": "D", "text": "Long head of biceps"}], "correct": "C", "explanation": "ER lag sign: patient cannot maintain full external rotation — indicates infraspinatus (± teres minor) tear."}, {"id": 438, "subject": "Anatomy", "difficulty": "Easy", "question": "Biceps brachii has two heads — where does the long head originate?", "options": [{"key": "A", "text": "Coracoid process"}, {"key": "B", "text": "Supraglenoid tubercle of scapula"}, {"key": "C", "text": "Glenoid labrum only"}, {"key": "D", "text": "Acromion"}], "correct": "B", "explanation": "Long head of biceps originates from the supraglenoid tubercle of scapula and passes through the bicipital groove."}, {"id": 439, "subject": "Anatomy", "difficulty": "Easy", "question": "Short head of biceps originates from:", "options": [{"key": "A", "text": "Supraglenoid tubercle"}, {"key": "B", "text": "Coracoid process of scapula"}, {"key": "C", "text": "Clavicle"}, {"key": "D", "text": "Acromion"}], "correct": "B", "explanation": "Short head of biceps originates from the tip of the coracoid process along with coracobrachialis."}, {"id": 440, "subject": "Anatomy", "difficulty": "Easy", "question": "Biceps brachii inserts on:", "options": [{"key": "A", "text": "Coronoid process of ulna"}, {"key": "B", "text": "Radial tuberosity and bicipital aponeurosis"}, {"key": "C", "text": "Olecranon of ulna"}, {"key": "D", "text": "Styloid process of radius"}], "correct": "B", "explanation": "Biceps inserts on the radial tuberosity (main insertion) and the bicipital aponeurosis (lacertus fibrosus)."}, {"id": 441, "subject": "Anatomy", "difficulty": "Easy", "question": "Biceps brachii is supplied by which nerve?", "options": [{"key": "A", "text": "Radial nerve"}, {"key": "B", "text": "Median nerve"}, {"key": "C", "text": "Musculocutaneous nerve (C5, C6)"}, {"key": "D", "text": "Axillary nerve"}], "correct": "C", "explanation": "Biceps brachii is supplied by the musculocutaneous nerve (C5, C6) — a branch of lateral cord of brachial plexus."}, {"id": 442, "subject": "Anatomy", "difficulty": "Medium", "question": "Biceps brachii is most powerful as a supinator when the elbow is at:", "options": [{"key": "A", "text": "Full extension"}, {"key": "B", "text": "90° flexion"}, {"key": "C", "text": "Full flexion"}, {"key": "D", "text": "45° flexion"}], "correct": "B", "explanation": "Biceps is most efficient supinator when elbow is at 90° flexion — the tendon angle of pull is optimal."}, {"id": 443, "subject": "Anatomy", "difficulty": "Medium", "question": "Bicipital aponeurosis (lacertus fibrosus) protects which structure beneath it?", "options": [{"key": "A", "text": "Radial artery"}, {"key": "B", "text": "Brachial artery and median nerve"}, {"key": "C", "text": "Ulnar nerve"}, {"key": "D", "text": "Radial nerve"}], "correct": "B", "explanation": "Bicipital aponeurosis fans medially over the cubital fossa, protecting the brachial artery and median nerve."}, {"id": 444, "subject": "Anatomy", "difficulty": "Easy", "question": "Speed's test is positive for pathology of:", "options": [{"key": "A", "text": "Short head of biceps"}, {"key": "B", "text": "Long head of biceps tendon"}, {"key": "C", "text": "Subscapularis"}, {"key": "D", "text": "Coracobrachialis"}], "correct": "B", "explanation": "Speed's test: resisted forward flexion with elbow extended and forearm supinated — tests long head of biceps."}, {"id": 445, "subject": "Anatomy", "difficulty": "Easy", "question": "Yergason's test involves:", "options": [{"key": "A", "text": "Resisted abduction"}, {"key": "B", "text": "Resisted supination with elbow at 90° — pain in bicipital groove"}, {"key": "C", "text": "Passive internal rotation"}, {"key": "D", "text": "Resisted elbow flexion"}], "correct": "B", "explanation": "Yergason's test: resisted supination at 90° elbow flexion — pain in bicipital groove = biceps tendinitis/instability."}, {"id": 446, "subject": "Anatomy", "difficulty": "Medium", "question": "Proximal biceps tendon rupture causes which deformity?", "options": [{"key": "A", "text": "Popeye deformity proximally"}, {"key": "B", "text": "Popeye deformity distally"}, {"key": "C", "text": "Wrist drop"}, {"key": "D", "text": "Claw hand"}], "correct": "A", "explanation": "Proximal (long head) biceps rupture: muscle belly falls distally creating a bulge in distal arm (Popeye sign)."}, {"id": 447, "subject": "Anatomy", "difficulty": "Hard", "question": "Distal biceps tendon rupture — which action is most affected?", "options": [{"key": "A", "text": "Elbow flexion strength"}, {"key": "B", "text": "Supination strength (50-60% loss)"}, {"key": "C", "text": "Shoulder abduction"}, {"key": "D", "text": "Wrist flexion"}], "correct": "B", "explanation": "Distal biceps rupture causes ~50% loss of supination strength and ~30% loss of flexion strength."}, {"id": 448, "subject": "Anatomy", "difficulty": "Medium", "question": "Hook test is used to diagnose:", "options": [{"key": "A", "text": "Proximal biceps rupture"}, {"key": "B", "text": "Distal biceps tendon rupture"}, {"key": "C", "text": "Coracobrachialis tear"}, {"key": "D", "text": "Brachialis tear"}], "correct": "B", "explanation": "Hook test: examiner hooks finger under biceps tendon from lateral side at elbow — absence of cord = distal rupture."}, {"id": 449, "subject": "Anatomy", "difficulty": "Easy", "question": "Biceps brachii reflex tests which nerve root level?", "options": [{"key": "A", "text": "C4"}, {"key": "B", "text": "C5–C6"}, {"key": "C", "text": "C7"}, {"key": "D", "text": "C8"}], "correct": "B", "explanation": "Biceps reflex (C5–C6) tests musculocutaneous nerve; diminished in C5/C6 radiculopathy."}, {"id": 450, "subject": "Anatomy", "difficulty": "Hard", "question": "Long head of biceps tendon is an intra-articular but extra-synovial structure. It lies:", "options": [{"key": "A", "text": "Inside the glenohumeral joint capsule, covered by synovium"}, {"key": "B", "text": "Outside the capsule only"}, {"key": "C", "text": "Inside the subacromial bursa"}, {"key": "D", "text": "Below the coracoacromial arch only"}], "correct": "A", "explanation": "Long head biceps is intra-articular (within capsule) but covered by synovial sheath — makes it extra-synovial."}, {"id": 451, "subject": "Anatomy", "difficulty": "Hard", "question": "Biceps is a weak flexor in which forearm position?", "options": [{"key": "A", "text": "Supination"}, {"key": "B", "text": "Pronation"}, {"key": "C", "text": "Neutral"}, {"key": "D", "text": "Semi-supination"}], "correct": "B", "explanation": "In pronation, biceps tendon is wound around radial tuberosity, reducing its mechanical advantage for flexion."}, {"id": 452, "subject": "Anatomy", "difficulty": "Easy", "question": "Coracobrachialis muscle shares origin with biceps short head at:", "options": [{"key": "A", "text": "Acromion"}, {"key": "B", "text": "Glenoid rim"}, {"key": "C", "text": "Coracoid process"}, {"key": "D", "text": "Supraglenoid tubercle"}], "correct": "C", "explanation": "Coracobrachialis and short head of biceps both originate from the tip of the coracoid process."}, {"id": 453, "subject": "Anatomy", "difficulty": "Easy", "question": "Triceps brachii has how many heads?", "options": [{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "1"}], "correct": "B", "explanation": "Triceps brachii has three heads: long, medial, and lateral — the only extensor of the elbow."}, {"id": 454, "subject": "Anatomy", "difficulty": "Easy", "question": "Long head of triceps originates from:", "options": [{"key": "A", "text": "Posterior humerus"}, {"key": "B", "text": "Infraglenoid tubercle of scapula"}, {"key": "C", "text": "Posterior ulna"}, {"key": "D", "text": "Lateral epicondyle"}], "correct": "B", "explanation": "Long head of triceps originates from the infraglenoid tubercle of scapula — only head with scapular origin."}, {"id": 455, "subject": "Anatomy", "difficulty": "Medium", "question": "Lateral head of triceps originates from:", "options": [{"key": "A", "text": "Posterior shaft above the radial groove"}, {"key": "B", "text": "Posterior shaft below the radial groove"}, {"key": "C", "text": "Infraglenoid tubercle"}, {"key": "D", "text": "Lateral epicondyle"}], "correct": "A", "explanation": "Lateral head originates from the posterior humeral shaft proximal and lateral to the radial (spiral) groove."}, {"id": 456, "subject": "Anatomy", "difficulty": "Medium", "question": "Medial head of triceps is also called the 'deep head'. It originates from:", "options": [{"key": "A", "text": "Posterior humerus above radial groove"}, {"key": "B", "text": "Posterior humerus below the radial groove (entire posterior shaft)"}, {"key": "C", "text": "Infraglenoid tubercle"}, {"key": "D", "text": "Olecranon"}], "correct": "B", "explanation": "Medial (deep) head originates from the posterior humeral shaft distal and medial to the radial groove."}, {"id": 457, "subject": "Anatomy", "difficulty": "Easy", "question": "Triceps brachii inserts on:", "options": [{"key": "A", "text": "Coronoid process"}, {"key": "B", "text": "Radial tuberosity"}, {"key": "C", "text": "Posterior surface of olecranon"}, {"key": "D", "text": "Styloid process of ulna"}], "correct": "C", "explanation": "All three heads of triceps converge and insert on the posterior surface (upper part) of the olecranon process."}, {"id": 458, "subject": "Anatomy", "difficulty": "Easy", "question": "Triceps brachii is supplied by which nerve?", "options": [{"key": "A", "text": "Musculocutaneous nerve"}, {"key": "B", "text": "Axillary nerve"}, {"key": "C", "text": "Radial nerve (C6,C7,C8)"}, {"key": "D", "text": "Median nerve"}], "correct": "C", "explanation": "Triceps is supplied by the radial nerve (C6, C7, C8) — branches arise in the axilla and spiral groove."}, {"id": 459, "subject": "Anatomy", "difficulty": "Hard", "question": "Which head of triceps is not affected in radial nerve injury at the spiral groove?", "options": [{"key": "A", "text": "Lateral head"}, {"key": "B", "text": "Long head"}, {"key": "C", "text": "Medial head (deep head)"}, {"key": "D", "text": "All are equally affected"}], "correct": "C", "explanation": "Medial head's nerve branch arises proximal to spiral groove — it is often spared in Saturday night palsy."}, {"id": 460, "subject": "Anatomy", "difficulty": "Easy", "question": "Triceps reflex tests which nerve root?", "options": [{"key": "A", "text": "C5–C6"}, {"key": "B", "text": "C6–C7"}, {"key": "C", "text": "C7–C8"}, {"key": "D", "text": "C8–T1"}], "correct": "C", "explanation": "Triceps reflex (C7–C8) tests the radial nerve; diminished in C7 radiculopathy."}, {"id": 461, "subject": "Anatomy", "difficulty": "Hard", "question": "Long head of triceps passes between which two muscles?", "options": [{"key": "A", "text": "Teres major and minor"}, {"key": "B", "text": "Teres minor above and teres major below"}, {"key": "C", "text": "Deltoid and teres minor"}, {"key": "D", "text": "Infraspinatus and teres major"}], "correct": "B", "explanation": "Long head of triceps passes between teres minor (above) and teres major (below), creating quadrangular and triangular spaces."}, {"id": 462, "subject": "Anatomy", "difficulty": "Medium", "question": "Quadrangular space transmits which structures?", "options": [{"key": "A", "text": "Radial nerve and profunda brachii"}, {"key": "B", "text": "Axillary nerve and posterior circumflex humeral artery"}, {"key": "C", "text": "Ulnar nerve and ulnar artery"}, {"key": "D", "text": "Long thoracic nerve"}], "correct": "B", "explanation": "Quadrangular space: bounded by teres minor, teres major, long head triceps, and humerus — transmits axillary nerve and PCHA."}, {"id": 463, "subject": "Anatomy", "difficulty": "Hard", "question": "Triangular space (medial triangular space) transmits:", "options": [{"key": "A", "text": "Axillary nerve"}, {"key": "B", "text": "Circumflex scapular artery"}, {"key": "C", "text": "Profunda brachii artery"}, {"key": "D", "text": "Radial nerve"}], "correct": "B", "explanation": "Medial triangular space (between teres minor, teres major, long head triceps) transmits the circumflex scapular artery."}, {"id": 464, "subject": "Anatomy", "difficulty": "Hard", "question": "Triangular interval (lower triangular space) transmits:", "options": [{"key": "A", "text": "Axillary nerve and PCHA"}, {"key": "B", "text": "Circumflex scapular artery"}, {"key": "C", "text": "Radial nerve and profunda brachii artery"}, {"key": "D", "text": "Ulnar nerve"}], "correct": "C", "explanation": "Triangular interval (between teres major, lateral head triceps, humerus shaft) transmits radial nerve and profunda brachii."}, {"id": 465, "subject": "Anatomy", "difficulty": "Medium", "question": "Anconeus muscle assists triceps in elbow extension. Its nerve supply is:", "options": [{"key": "A", "text": "Ulnar nerve"}, {"key": "B", "text": "Median nerve"}, {"key": "C", "text": "Radial nerve"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "C", "explanation": "Anconeus is supplied by the radial nerve (C7, C8); it assists extension and abducts ulna in pronation."}, {"id": 466, "subject": "Anatomy", "difficulty": "Medium", "question": "Primary action of long head of triceps (in addition to elbow extension) is:", "options": [{"key": "A", "text": "Shoulder flexion"}, {"key": "B", "text": "Shoulder extension and adduction"}, {"key": "C", "text": "Shoulder abduction"}, {"key": "D", "text": "Elbow flexion"}], "correct": "B", "explanation": "Long head crosses the shoulder joint — it assists in shoulder extension and adduction."}, {"id": 467, "subject": "Anatomy", "difficulty": "Easy", "question": "Triceps tendon rupture is avulsed from which structure?", "options": [{"key": "A", "text": "Lateral epicondyle"}, {"key": "B", "text": "Posterior olecranon"}, {"key": "C", "text": "Medial epicondyle"}, {"key": "D", "text": "Posterior ulnar shaft"}], "correct": "B", "explanation": "Triceps tendon avulses from the posterior olecranon — tested by resisted elbow extension."}, {"id": 468, "subject": "Anatomy", "difficulty": "Easy", "question": "Anterior compartment of forearm is divided into how many layers?", "options": [{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}], "correct": "B", "explanation": "Anterior forearm has 3 layers: superficial (5 muscles), intermediate (FDS), and deep (FDP, FPL, PQ)."}, {"id": 469, "subject": "Anatomy", "difficulty": "Medium", "question": "Which muscles form the superficial layer of anterior forearm?", "options": [{"key": "A", "text": "FCR, FCU, PL, PT, FDS"}, {"key": "B", "text": "PT, FCR, PL, FCU, BR"}, {"key": "C", "text": "FDS, FDP, FPL, PQ, PT"}, {"key": "D", "text": "FCR, FCU, FDP, PL, PT"}], "correct": "B", "explanation": "Superficial layer (5 muscles): Pronator teres, FCR, Palmaris longus, FCU, and Brachioradialis (BR)."}, {"id": 470, "subject": "Anatomy", "difficulty": "Easy", "question": "Flexor digitorum superficialis (FDS) inserts on:", "options": [{"key": "A", "text": "Distal phalanges of fingers 2-5"}, {"key": "B", "text": "Middle phalanges of fingers 2-5"}, {"key": "C", "text": "Proximal phalanges of fingers 2-5"}, {"key": "D", "text": "Base of first metacarpal"}], "correct": "B", "explanation": "FDS splits and inserts on the sides of the middle phalanges of the medial four fingers."}, {"id": 471, "subject": "Anatomy", "difficulty": "Easy", "question": "Flexor digitorum profundus (FDP) inserts on:", "options": [{"key": "A", "text": "Middle phalanges"}, {"key": "B", "text": "Proximal phalanges"}, {"key": "C", "text": "Distal phalanges of fingers 2-5"}, {"key": "D", "text": "Metacarpals"}], "correct": "C", "explanation": "FDP inserts on the anterior surface of the base of distal phalanges of fingers 2-5."}, {"id": 472, "subject": "Anatomy", "difficulty": "Medium", "question": "FDP to index and middle fingers is supplied by:", "options": [{"key": "A", "text": "Ulnar nerve"}, {"key": "B", "text": "Anterior interosseous nerve (branch of median)"}, {"key": "C", "text": "Median nerve proper"}, {"key": "D", "text": "Radial nerve"}], "correct": "B", "explanation": "Lateral part of FDP (index and middle fingers) is supplied by the anterior interosseous nerve (AIN), branch of median nerve."}, {"id": 473, "subject": "Anatomy", "difficulty": "Medium", "question": "FDP to ring and little fingers is supplied by:", "options": [{"key": "A", "text": "Median nerve"}, {"key": "B", "text": "Radial nerve"}, {"key": "C", "text": "Ulnar nerve"}, {"key": "D", "text": "Anterior interosseous nerve"}], "correct": "C", "explanation": "Medial part of FDP (ring and little fingers) is supplied by the ulnar nerve (C8, T1)."}, {"id": 474, "subject": "Anatomy", "difficulty": "Easy", "question": "Flexor pollicis longus originates from:", "options": [{"key": "A", "text": "Anterior surface of ulna"}, {"key": "B", "text": "Anterior surface of radius and adjacent interosseous membrane"}, {"key": "C", "text": "Medial epicondyle"}, {"key": "D", "text": "Coracoid process"}], "correct": "B", "explanation": "FPL originates from the anterior surface of the radius and adjacent interosseous membrane."}, {"id": 475, "subject": "Anatomy", "difficulty": "Medium", "question": "FPL is supplied by which nerve?", "options": [{"key": "A", "text": "Ulnar nerve"}, {"key": "B", "text": "Median nerve proper"}, {"key": "C", "text": "Anterior interosseous nerve (AIN)"}, {"key": "D", "text": "Radial nerve"}], "correct": "C", "explanation": "FPL is supplied by the anterior interosseous nerve (AIN) — a branch of the median nerve."}, {"id": 476, "subject": "Anatomy", "difficulty": "Medium", "question": "Pronator quadratus (PQ) is the primary muscle for:", "options": [{"key": "A", "text": "Slow pronation and maintains DRUJ stability"}, {"key": "B", "text": "Rapid pronation only"}, {"key": "C", "text": "Supination of forearm"}, {"key": "D", "text": "Wrist flexion"}], "correct": "A", "explanation": "PQ is the primary pronator for all forearm pronation and stabilizes DRUJ; pronator teres assists."}, {"id": 477, "subject": "Anatomy", "difficulty": "Medium", "question": "Palmaris longus is absent in approximately what percentage of population?", "options": [{"key": "A", "text": "5%"}, {"key": "B", "text": "14%"}, {"key": "C", "text": "30%"}, {"key": "D", "text": "50%"}], "correct": "B", "explanation": "Palmaris longus is absent in about 14% of individuals (varies by population); used as graft donor tendon."}, {"id": 478, "subject": "Anatomy", "difficulty": "Medium", "question": "Palmaris longus is used clinically as a graft for:", "options": [{"key": "A", "text": "Knee ACL reconstruction"}, {"key": "B", "text": "Tendon graft for UCL reconstruction (Tommy John)"}, {"key": "C", "text": "Nerve graft"}, {"key": "D", "text": "Skin graft"}], "correct": "B", "explanation": "Palmaris longus tendon is commonly harvested for UCL reconstruction (Tommy John surgery) at the elbow."}, {"id": 479, "subject": "Anatomy", "difficulty": "Hard", "question": "Anterior interosseous nerve (AIN) syndrome causes inability to:", "options": [{"key": "A", "text": "Flex fingers 4 and 5"}, {"key": "B", "text": "Flex distal phalanx of index finger and thumb (pinch sign)"}, {"key": "C", "text": "Extend wrist"}, {"key": "D", "text": "Abduct thumb"}], "correct": "B", "explanation": "AIN syndrome: loss of FPL and lateral FDP (index) — patient cannot make 'OK sign'; pinch becomes tip-to-tip."}, {"id": 480, "subject": "Anatomy", "difficulty": "Hard", "question": "'OK sign' (tip-to-tip pinch) failure suggests injury to:", "options": [{"key": "A", "text": "Ulnar nerve"}, {"key": "B", "text": "Anterior interosseous nerve"}, {"key": "C", "text": "Posterior interosseous nerve"}, {"key": "D", "text": "Median nerve at wrist"}], "correct": "B", "explanation": "AIN palsy: FPL and lateral FDP paralysis — patient makes pulp-to-pulp instead of tip-to-tip pinch."}, {"id": 481, "subject": "Anatomy", "difficulty": "Medium", "question": "Flexor carpi radialis (FCR) inserts on:", "options": [{"key": "A", "text": "Pisiform bone"}, {"key": "B", "text": "Bases of 2nd and 3rd metacarpals"}, {"key": "C", "text": "Base of 5th metacarpal"}, {"key": "D", "text": "Trapezium"}], "correct": "B", "explanation": "FCR inserts on the base of the 2nd metacarpal (primarily) and a slip to 3rd metacarpal."}, {"id": 482, "subject": "Anatomy", "difficulty": "Medium", "question": "Flexor carpi ulnaris (FCU) is the only flexor muscle supplied entirely by the ulnar nerve. It inserts on:", "options": [{"key": "A", "text": "Triquetrum"}, {"key": "B", "text": "Hamate only"}, {"key": "C", "text": "Pisiform (and via ligaments to hamate and 5th metacarpal)"}, {"key": "D", "text": "Lunate"}], "correct": "C", "explanation": "FCU inserts on pisiform, and its pull is transmitted via pisohamate and pisometacarpal ligaments."}, {"id": 483, "subject": "Anatomy", "difficulty": "Easy", "question": "Which forearm muscle is the primary wrist flexor tested in isolation?", "options": [{"key": "A", "text": "FDS"}, {"key": "B", "text": "FCR"}, {"key": "C", "text": "FDP"}, {"key": "D", "text": "PQ"}], "correct": "B", "explanation": "FCR and FCU are the primary wrist flexors; FCR tested by resisted wrist flexion with radial deviation."}, {"id": 484, "subject": "Anatomy", "difficulty": "Hard", "question": "Volkmann's ischemic contracture follows compartment syndrome of forearm. Which muscles are primarily affected?", "options": [{"key": "A", "text": "Extensor muscles"}, {"key": "B", "text": "Flexor muscles (FDP and FPL most severely)"}, {"key": "C", "text": "Brachioradialis"}, {"key": "D", "text": "Intrinsic hand muscles"}], "correct": "B", "explanation": "Volkmann's: deep flexors (FDP and FPL) are most affected as they are furthest from collateral circulation."}, {"id": 485, "subject": "Anatomy", "difficulty": "Medium", "question": "Pronator syndrome is entrapment of median nerve between two heads of:", "options": [{"key": "A", "text": "FDS"}, {"key": "B", "text": "FCU"}, {"key": "C", "text": "Pronator teres"}, {"key": "D", "text": "PQ"}], "correct": "C", "explanation": "Pronator syndrome: median nerve compressed between humeral and ulnar heads of pronator teres."}, {"id": 486, "subject": "Anatomy", "difficulty": "Medium", "question": "FDS is tested in isolation by:", "options": [{"key": "A", "text": "Flexing all fingers simultaneously"}, {"key": "B", "text": "Holding other fingers in extension, then flexing the tested finger at PIP joint"}, {"key": "C", "text": "Flexing DIP joint against resistance"}, {"key": "D", "text": "Resisted wrist flexion"}], "correct": "B", "explanation": "FDS test: hold other fingers extended (eliminating FDP), then flex the tested finger at PIP — tests FDS only."}, {"id": 487, "subject": "Anatomy", "difficulty": "Easy", "question": "Intermediate layer of anterior forearm consists of:", "options": [{"key": "A", "text": "Pronator teres only"}, {"key": "B", "text": "Flexor digitorum superficialis only"}, {"key": "C", "text": "FDP and FPL"}, {"key": "D", "text": "PQ only"}], "correct": "B", "explanation": "FDS forms the entire intermediate layer; it is the largest muscle in the anterior forearm."}, {"id": 488, "subject": "Anatomy", "difficulty": "Medium", "question": "Posterior compartment of forearm has how many muscles?", "options": [{"key": "A", "text": "7"}, {"key": "B", "text": "9"}, {"key": "C", "text": "12"}, {"key": "D", "text": "6"}], "correct": "C", "explanation": "Posterior forearm has 12 muscles: 7 superficial (including BR, ECRL, ECRB, ED, EDM, ECU, Anconeus) and 5 deep."}, {"id": 489, "subject": "Anatomy", "difficulty": "Easy", "question": "Brachioradialis muscle, though in posterior compartment, is a:", "options": [{"key": "A", "text": "Wrist extensor"}, {"key": "B", "text": "Elbow flexor"}, {"key": "C", "text": "Forearm supinator"}, {"key": "D", "text": "Wrist flexor"}], "correct": "B", "explanation": "Brachioradialis (supplied by radial nerve) is primarily an elbow flexor — most effective when forearm is in neutral."}, {"id": 490, "subject": "Anatomy", "difficulty": "Medium", "question": "ECRL and ECRB insert on which metacarpal bases?", "options": [{"key": "A", "text": "1st and 2nd"}, {"key": "B", "text": "2nd and 3rd"}, {"key": "C", "text": "3rd and 4th"}, {"key": "D", "text": "4th and 5th"}], "correct": "B", "explanation": "ECRL inserts on base of 2nd metacarpal; ECRB on base of 3rd metacarpal — both extend and radially deviate wrist."}, {"id": 491, "subject": "Anatomy", "difficulty": "Easy", "question": "Extensor carpi ulnaris (ECU) inserts on:", "options": [{"key": "A", "text": "Base of 4th metacarpal"}, {"key": "B", "text": "Base of 5th metacarpal"}, {"key": "C", "text": "Hamate"}, {"key": "D", "text": "Triquetrum"}], "correct": "B", "explanation": "ECU inserts on the base of the 5th metacarpal — it extends and ulnarly deviates the wrist."}, {"id": 492, "subject": "Anatomy", "difficulty": "Medium", "question": "Supinator muscle originates from:", "options": [{"key": "A", "text": "Medial epicondyle only"}, {"key": "B", "text": "Lateral epicondyle, radial collateral ligament, and supinator crest of ulna"}, {"key": "C", "text": "Radial head only"}, {"key": "D", "text": "Annular ligament only"}], "correct": "B", "explanation": "Supinator has a broad origin: lateral epicondyle, radial collateral ligament, annular ligament, and supinator crest of ulna."}, {"id": 493, "subject": "Anatomy", "difficulty": "Medium", "question": "Posterior interosseous nerve (PIN) passes between the two heads of:", "options": [{"key": "A", "text": "Pronator teres"}, {"key": "B", "text": "Supinator"}, {"key": "C", "text": "Brachioradialis"}, {"key": "D", "text": "FCU"}], "correct": "B", "explanation": "PIN (deep branch of radial nerve) passes between the superficial and deep heads of supinator at the arcade of Frohse."}, {"id": 494, "subject": "Anatomy", "difficulty": "Medium", "question": "Arcade of Frohse is the fibrous arch at the proximal edge of:", "options": [{"key": "A", "text": "Pronator teres"}, {"key": "B", "text": "Supinator"}, {"key": "C", "text": "ECU"}, {"key": "D", "text": "Brachioradialis"}], "correct": "B", "explanation": "Arcade of Frohse is the fibrous proximal arch of the superficial head of supinator — most common site of PIN entrapment."}, {"id": 495, "subject": "Anatomy", "difficulty": "Medium", "question": "Abductor pollicis longus (APL) inserts on:", "options": [{"key": "A", "text": "Proximal phalanx of thumb"}, {"key": "B", "text": "Base of first metacarpal"}, {"key": "C", "text": "Trapezium"}, {"key": "D", "text": "Distal phalanx of thumb"}], "correct": "B", "explanation": "APL inserts on the base of the first metacarpal (radial side) — forms the radial border of anatomical snuffbox."}, {"id": 496, "subject": "Anatomy", "difficulty": "Medium", "question": "Extensor pollicis brevis (EPB) inserts on:", "options": [{"key": "A", "text": "Base of proximal phalanx of thumb"}, {"key": "B", "text": "Base of distal phalanx of thumb"}, {"key": "C", "text": "First metacarpal base"}, {"key": "D", "text": "Trapezium"}], "correct": "A", "explanation": "EPB inserts on the base of the proximal phalanx of the thumb — it extends the MCP joint of thumb."}, {"id": 497, "subject": "Anatomy", "difficulty": "Easy", "question": "Extensor pollicis longus (EPL) inserts on:", "options": [{"key": "A", "text": "Base of proximal phalanx"}, {"key": "B", "text": "Base of distal phalanx of thumb"}, {"key": "C", "text": "First metacarpal"}, {"key": "D", "text": "Trapezoid bone"}], "correct": "B", "explanation": "EPL inserts on the base of the distal phalanx of thumb — it extends the IP joint of thumb."}, {"id": 498, "subject": "Anatomy", "difficulty": "Medium", "question": "Extensor indicis proprius (EIP) allows:", "options": [{"key": "A", "text": "Index finger extension only"}, {"key": "B", "text": "Independent extension of index finger with other fingers flexed"}, {"key": "C", "text": "Abduction of index finger"}, {"key": "D", "text": "Wrist extension"}], "correct": "B", "explanation": "EIP allows independent extension of index finger; clinically tested by asking patient to point while fist is made."}, {"id": 499, "subject": "Anatomy", "difficulty": "Easy", "question": "De Quervain's tenosynovitis involves tendons in which extensor compartment?", "options": [{"key": "A", "text": "2nd"}, {"key": "B", "text": "3rd"}, {"key": "C", "text": "1st (APL and EPB)"}, {"key": "D", "text": "4th"}], "correct": "C", "explanation": "De Quervain's = stenosing tenosynovitis of 1st dorsal compartment containing APL and EPB."}, {"id": 500, "subject": "Anatomy", "difficulty": "Easy", "question": "All muscles of posterior forearm are supplied by:", "options": [{"key": "A", "text": "Median nerve"}, {"key": "B", "text": "Ulnar nerve"}, {"key": "C", "text": "Radial nerve and its branches"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "C", "explanation": "All posterior forearm muscles are supplied by the radial nerve — either directly or via its PIN branch."}, {"id": 501, "subject": "Anatomy", "difficulty": "Medium", "question": "Mallet finger is due to rupture/avulsion of:", "options": [{"key": "A", "text": "FDS tendon"}, {"key": "B", "text": "FDP tendon at middle phalanx"}, {"key": "C", "text": "Extensor tendon at DIP joint (terminal tendon)"}, {"key": "D", "text": "Intrinsic muscles"}], "correct": "C", "explanation": "Mallet finger: forced flexion of extended DIP joint ruptures the terminal extensor tendon, causing droop."}, {"id": 502, "subject": "Anatomy", "difficulty": "Hard", "question": "Boutonniere deformity results from rupture of:", "options": [{"key": "A", "text": "Terminal extensor tendon"}, {"key": "B", "text": "FDS tendon"}, {"key": "C", "text": "Central slip of extensor tendon at PIP joint"}, {"key": "D", "text": "Lateral bands"}], "correct": "C", "explanation": "Boutonniere: central slip rupture allows PIP to flex through the rent; lateral bands slide volarly causing DIP hyperextension."}, {"id": 503, "subject": "Anatomy", "difficulty": "Easy", "question": "Wrist drop is due to which nerve injury?", "options": [{"key": "A", "text": "Ulnar nerve"}, {"key": "B", "text": "Median nerve"}, {"key": "C", "text": "Radial nerve"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "C", "explanation": "Radial nerve injury causes wrist drop — loss of wrist and finger extensors (posterior compartment paralysis)."}, {"id": 504, "subject": "Anatomy", "difficulty": "Medium", "question": "In radial nerve palsy, which wrist movement is preserved?", "options": [{"key": "A", "text": "Wrist extension"}, {"key": "B", "text": "Finger extension"}, {"key": "C", "text": "Wrist flexion (FCR and FCU intact via median and ulnar nerves)"}, {"key": "D", "text": "Thumb extension"}], "correct": "C", "explanation": "In radial nerve palsy, wrist flexion is preserved because FCR (median) and FCU (ulnar) are intact."}, {"id": 505, "subject": "Anatomy", "difficulty": "Easy", "question": "Claw hand deformity is due to injury of:", "options": [{"key": "A", "text": "Median nerve only"}, {"key": "B", "text": "Ulnar nerve — ring and little finger clawing"}, {"key": "C", "text": "Radial nerve"}, {"key": "D", "text": "All three nerves"}], "correct": "B", "explanation": "Ulnar nerve palsy causes intrinsic muscle paralysis of ring and little fingers — MCP hyperextension + IP flexion (claw)."}, {"id": 506, "subject": "Anatomy", "difficulty": "Hard", "question": "'Pointing index' (Benediction hand) posture occurs in high median nerve injury because:", "options": [{"key": "A", "text": "FDS is weak"}, {"key": "B", "text": "FDP and FPL for index and middle are paralyzed"}, {"key": "C", "text": "Interossei are paralyzed"}, {"key": "D", "text": "Thenar muscles are weak"}], "correct": "B", "explanation": "High median nerve injury paralyzes lateral FDP and FPL — patient cannot flex index and middle fingers fully."}, {"id": 507, "subject": "Anatomy", "difficulty": "Easy", "question": "Ape hand deformity (thenar wasting) is due to:", "options": [{"key": "A", "text": "Ulnar nerve palsy"}, {"key": "B", "text": "Radial nerve palsy"}, {"key": "C", "text": "Median nerve palsy"}, {"key": "D", "text": "Axillary nerve palsy"}], "correct": "C", "explanation": "Median nerve palsy causes thenar wasting and loss of thumb opposition — classic ape hand appearance."}, {"id": 508, "subject": "Anatomy", "difficulty": "Medium", "question": "Intrinsic plus position of hand (lumbrical position) is:", "options": [{"key": "A", "text": "MCP hyperextension + IP flexion"}, {"key": "B", "text": "MCP flexion + IP extension"}, {"key": "C", "text": "All joints in flexion"}, {"key": "D", "text": "All joints in extension"}], "correct": "B", "explanation": "Intrinsic plus (lumbrical) position: MCP flexion with IP extension — opposite to claw hand deformity."}, {"id": 509, "subject": "Anatomy", "difficulty": "Medium", "question": "Froment's sign tests which muscle?", "options": [{"key": "A", "text": "Opponens pollicis (median)"}, {"key": "B", "text": "Adductor pollicis (ulnar nerve)"}, {"key": "C", "text": "APL (radial nerve)"}, {"key": "D", "text": "FPL (AIN)"}], "correct": "B", "explanation": "Froment's sign: patient flexes thumb IP (using FPL) during key pinch — indicates adductor pollicis weakness (ulnar nerve)."}, {"id": 510, "subject": "Anatomy", "difficulty": "Medium", "question": "Intrinsic muscles of the hand are supplied by:", "options": [{"key": "A", "text": "Median nerve only"}, {"key": "B", "text": "Ulnar nerve only"}, {"key": "C", "text": "Median (LOAF) and ulnar nerves"}, {"key": "D", "text": "Radial nerve"}], "correct": "C", "explanation": "LOAF muscles by median nerve; remaining intrinsics (interossei, medial 2 lumbricals, hypothenar) by ulnar nerve."}, {"id": 511, "subject": "Anatomy", "difficulty": "Medium", "question": "LOAF muscles (median nerve in hand) are:", "options": [{"key": "A", "text": "Lumbricals 1&2, Opponens pollicis, Abductor pollicis brevis, Flexor pollicis brevis"}, {"key": "B", "text": "Lumbricals 3&4, Opponens, APL, FPB"}, {"key": "C", "text": "All lumbricals and thenar"}, {"key": "D", "text": "Interossei and lumbricals"}], "correct": "A", "explanation": "LOAF: Lateral 2 Lumbricals, Opponens pollicis, Abductor pollicis brevis, Flexor pollicis brevis (superficial head)."}, {"id": 512, "subject": "Anatomy", "difficulty": "Hard", "question": "Wartenberg's sign (persistent little finger abduction) is due to paralysis of:", "options": [{"key": "A", "text": "Abductor digiti minimi"}, {"key": "B", "text": "Palmar interosseous muscle of little finger"}, {"key": "C", "text": "FDS to little finger"}, {"key": "D", "text": "Extensor digiti minimi"}], "correct": "B", "explanation": "Wartenberg's sign: ulnar nerve palsy paralyzes the palmar interosseous — no active adduction of little finger."}, {"id": 513, "subject": "Anatomy", "difficulty": "Medium", "question": "Compartment syndrome of forearm — which test is most sensitive?", "options": [{"key": "A", "text": "Passive stretch pain"}, {"key": "B", "text": "Paresthesia"}, {"key": "C", "text": "Paralysis"}, {"key": "D", "text": "Pallor"}], "correct": "A", "explanation": "Passive stretch pain is the earliest and most sensitive sign of forearm compartment syndrome."}, {"id": 514, "subject": "Anatomy", "difficulty": "Hard", "question": "After radial nerve repair at the spiral groove, which muscle recovers last?", "options": [{"key": "A", "text": "Brachioradialis"}, {"key": "B", "text": "ECRL"}, {"key": "C", "text": "Extensor indicis proprius (EIP)"}, {"key": "D", "text": "Supinator"}], "correct": "C", "explanation": "EIP is most distal — nerve regenerates at ~1 mm/day, so distal muscles recover last after proximal injury."}, {"id": 515, "subject": "Anatomy", "difficulty": "Hard", "question": "Z-plasty lengthening of Achilles tendon is a technique borrowed for forearm flexor contracture release in Volkmann's. The original Volkmann's procedure involves:", "options": [{"key": "A", "text": "Muscle slide operation"}, {"key": "B", "text": "Tendon transfer"}, {"key": "C", "text": "Fasciotomy only"}, {"key": "D", "text": "Nerve decompression"}], "correct": "A", "explanation": "Muscle slide (modified Scaglietti) procedure releases flexor pronator origin to correct Volkmann's contracture."}, {"id": 516, "subject": "Anatomy", "difficulty": "Hard", "question": "Which test differentiates between extrinsic and intrinsic tightness of hand?", "options": [{"key": "A", "text": "Bunnel-Littler test"}, {"key": "B", "text": "Froment's sign"}, {"key": "C", "text": "Finkelstein's test"}, {"key": "D", "text": "Watson's test"}], "correct": "A", "explanation": "Bunnel-Littler test: PIP flexion tested with MCP extended vs flexed — differentiates intrinsic from capsular tightness."}, {"id": 517, "subject": "Anatomy", "difficulty": "Medium", "question": "Stenosing tenosynovitis (trigger finger) most commonly affects which finger?", "options": [{"key": "A", "text": "Index finger"}, {"key": "B", "text": "Ring finger"}, {"key": "C", "text": "Little finger"}, {"key": "D", "text": "Middle finger"}], "correct": "B", "explanation": "Trigger finger most commonly affects the ring finger, followed by the thumb (trigger thumb)."}, {"id": 518, "subject": "Anatomy", "difficulty": "Easy", "question": "Brachial plexus is formed by the ventral rami of which spinal segments?", "options": [{"key": "A", "text": "C4-C8"}, {"key": "B", "text": "C5-T1"}, {"key": "C", "text": "C4-T1"}, {"key": "D", "text": "C5-T2"}], "correct": "B", "explanation": "Brachial plexus = C5, C6, C7, C8, T1 ventral rami."}, {"id": 519, "subject": "Anatomy", "difficulty": "Easy", "question": "Which part of brachial plexus lies in the posterior triangle of neck?", "options": [{"key": "A", "text": "Cords"}, {"key": "B", "text": "Divisions"}, {"key": "C", "text": "Trunks"}, {"key": "D", "text": "Branches"}], "correct": "C", "explanation": "3 trunks (upper, middle, lower) lie in posterior triangle of neck."}, {"id": 520, "subject": "Anatomy", "difficulty": "Easy", "question": "Upper trunk of brachial plexus is formed by:", "options": [{"key": "A", "text": "C5 only"}, {"key": "B", "text": "C5 & C6"}, {"key": "C", "text": "C6 & C7"}, {"key": "D", "text": "C5, C6 & C7"}], "correct": "B", "explanation": "Upper trunk = C5 + C6; Middle trunk = C7; Lower trunk = C8 + T1."}, {"id": 521, "subject": "Anatomy", "difficulty": "Medium", "question": "Erb's point is located at:", "options": [{"key": "A", "text": "C4-C5 junction"}, {"key": "B", "text": "C5-C6 junction"}, {"key": "C", "text": "C6-C7 junction"}, {"key": "D", "text": "C7-T1 junction"}], "correct": "B", "explanation": "Erb's point = junction of C5 & C6 roots; site of upper trunk of brachial plexus."}, {"id": 522, "subject": "Anatomy", "difficulty": "Easy", "question": "Erb's palsy results from injury to which roots of brachial plexus?", "options": [{"key": "A", "text": "C8, T1"}, {"key": "B", "text": "C5, C6"}, {"key": "C", "text": "C6, C7"}, {"key": "D", "text": "C7, C8"}], "correct": "B", "explanation": "C5-C6 injury = Erb's palsy (waiter's tip position) — shoulder adducted, elbow extended."}, {"id": 523, "subject": "Anatomy", "difficulty": "Easy", "question": "Klumpke's palsy results from injury to:", "options": [{"key": "A", "text": "C5, C6"}, {"key": "B", "text": "C6, C7"}, {"key": "C", "text": "C7, C8"}, {"key": "D", "text": "C8, T1"}], "correct": "D", "explanation": "C8-T1 injury = Klumpke's palsy — intrinsic hand muscle weakness, claw hand."}, {"id": 524, "subject": "Anatomy", "difficulty": "Medium", "question": "Which cord of brachial plexus lies medial to axillary artery?", "options": [{"key": "A", "text": "Lateral cord"}, {"key": "B", "text": "Posterior cord"}, {"key": "C", "text": "Medial cord"}, {"key": "D", "text": "All cords"}], "correct": "C", "explanation": "Medial cord is medial, lateral cord is lateral, posterior cord is posterior to axillary artery."}, {"id": 525, "subject": "Anatomy", "difficulty": "Medium", "question": "Posterior cord of brachial plexus is formed by:", "options": [{"key": "A", "text": "Anterior divisions of all 3 trunks"}, {"key": "B", "text": "Posterior divisions of all 3 trunks"}, {"key": "C", "text": "C5, C6, C7 posterior divisions"}, {"key": "D", "text": "C7, C8, T1 posterior divisions"}], "correct": "B", "explanation": "Posterior cord = posterior divisions of all 3 trunks (C5–T1)."}, {"id": 526, "subject": "Anatomy", "difficulty": "Medium", "question": "Which nerve arises directly from the roots of brachial plexus?", "options": [{"key": "A", "text": "Musculocutaneous nerve"}, {"key": "B", "text": "Long thoracic nerve"}, {"key": "C", "text": "Radial nerve"}, {"key": "D", "text": "Ulnar nerve"}], "correct": "B", "explanation": "Long thoracic nerve (C5,C6,C7) arises directly from the roots, not cords."}, {"id": 527, "subject": "Anatomy", "difficulty": "Medium", "question": "Lateral cord of brachial plexus gives rise to all EXCEPT:", "options": [{"key": "A", "text": "Lateral pectoral nerve"}, {"key": "B", "text": "Musculocutaneous nerve"}, {"key": "C", "text": "Medial root of median nerve"}, {"key": "D", "text": "Ulnar nerve"}], "correct": "D", "explanation": "Ulnar nerve arises from medial cord, not lateral cord."}, {"id": 528, "subject": "Anatomy", "difficulty": "Easy", "question": "Median nerve is formed by the union of:", "options": [{"key": "A", "text": "Lateral and posterior cords"}, {"key": "B", "text": "Medial cord only"}, {"key": "C", "text": "Lateral and medial cords"}, {"key": "D", "text": "Posterior cord only"}], "correct": "C", "explanation": "Median nerve = lateral root (lateral cord C6,C7) + medial root (medial cord C8,T1)."}, {"id": 529, "subject": "Anatomy", "difficulty": "Medium", "question": "Median nerve enters forearm between which two heads of pronator teres?", "options": [{"key": "A", "text": "Radial and ulnar heads"}, {"key": "B", "text": "Humeral and ulnar heads"}, {"key": "C", "text": "Radial and humeral heads"}, {"key": "D", "text": "Superficial and deep heads"}], "correct": "B", "explanation": "Median nerve passes between humeral and ulnar heads of pronator teres."}, {"id": 530, "subject": "Anatomy", "difficulty": "Easy", "question": "The Ape thumb deformity is associated with which nerve injury?", "options": [{"key": "A", "text": "Ulnar nerve"}, {"key": "B", "text": "Radial nerve"}, {"key": "C", "text": "Median nerve"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "C", "explanation": "Median nerve injury → loss of thenar muscles → ape thumb (thumb lies in plane of palm)."}, {"id": 531, "subject": "Anatomy", "difficulty": "Easy", "question": "Carpal tunnel syndrome is due to compression of which nerve?", "options": [{"key": "A", "text": "Ulnar nerve"}, {"key": "B", "text": "Radial nerve"}, {"key": "C", "text": "Median nerve"}, {"key": "D", "text": "Anterior interosseous nerve"}], "correct": "C", "explanation": "Median nerve is compressed under flexor retinaculum at carpal tunnel."}, {"id": 532, "subject": "Anatomy", "difficulty": "Hard", "question": "Palmar cutaneous branch of median nerve arises:", "options": [{"key": "A", "text": "Inside carpal tunnel"}, {"key": "B", "text": "Proximal to carpal tunnel"}, {"key": "C", "text": "Distal to carpal tunnel"}, {"key": "D", "text": "From ulnar nerve"}], "correct": "B", "explanation": "Palmar cutaneous branch arises proximal to flexor retinaculum, so spared in carpal tunnel syndrome."}, {"id": 533, "subject": "Anatomy", "difficulty": "Medium", "question": "Anterior interosseous nerve (AIN) is a branch of:", "options": [{"key": "A", "text": "Ulnar nerve"}, {"key": "B", "text": "Median nerve"}, {"key": "C", "text": "Radial nerve"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "B", "explanation": "AIN is a pure motor branch of median nerve in the forearm."}, {"id": 534, "subject": "Anatomy", "difficulty": "Hard", "question": "AIN syndrome causes weakness of all EXCEPT:", "options": [{"key": "A", "text": "Flexor pollicis longus"}, {"key": "B", "text": "Pronator quadratus"}, {"key": "C", "text": "Flexor digitorum profundus (index)"}, {"key": "D", "text": "Opponens pollicis"}], "correct": "D", "explanation": "Opponens pollicis is supplied by recurrent branch of median nerve, not AIN."}, {"id": 535, "subject": "Anatomy", "difficulty": "Medium", "question": "LOAF muscles are supplied by median nerve. What does 'L' stand for?", "options": [{"key": "A", "text": "Lumbrical 1 & 2"}, {"key": "B", "text": "Lumbrical 3 & 4"}, {"key": "C", "text": "Lumbrical 1 only"}, {"key": "D", "text": "Lumbrical 2 only"}], "correct": "A", "explanation": "LOAF = Lumbricals (1&2), Opponens pollicis, Abductor pollicis brevis, Flexor pollicis brevis."}, {"id": 536, "subject": "Anatomy", "difficulty": "Medium", "question": "Which test is used to test the integrity of median nerve at wrist?", "options": [{"key": "A", "text": "Froment's sign"}, {"key": "B", "text": "Phalen's test"}, {"key": "C", "text": "Allen's test"}, {"key": "D", "text": "Finkelstein's test"}], "correct": "B", "explanation": "Phalen's test (wrist flexion for 60 sec) reproduces symptoms of carpal tunnel syndrome."}, {"id": 537, "subject": "Anatomy", "difficulty": "Hard", "question": "Benediction sign is seen in injury to which nerve?", "options": [{"key": "A", "text": "Ulnar nerve at wrist"}, {"key": "B", "text": "Median nerve at elbow"}, {"key": "C", "text": "Radial nerve"}, {"key": "D", "text": "Median nerve at wrist"}], "correct": "B", "explanation": "High median nerve injury → benediction hand (index & middle fingers extended while ring & little flex)."}, {"id": 538, "subject": "Anatomy", "difficulty": "Easy", "question": "Ulnar nerve arises from which cord of brachial plexus?", "options": [{"key": "A", "text": "Lateral cord"}, {"key": "B", "text": "Posterior cord"}, {"key": "C", "text": "Medial cord"}, {"key": "D", "text": "Both lateral and medial cords"}], "correct": "C", "explanation": "Ulnar nerve (C8, T1) arises from medial cord of brachial plexus."}, {"id": 539, "subject": "Anatomy", "difficulty": "Easy", "question": "Ulnar nerve passes through which groove at the elbow?", "options": [{"key": "A", "text": "Bicipital groove"}, {"key": "B", "text": "Radial groove"}, {"key": "C", "text": "Cubital tunnel (medial epicondyle groove)"}, {"key": "D", "text": "Olecranon fossa"}], "correct": "C", "explanation": "Ulnar nerve passes posterior to medial epicondyle in cubital tunnel."}, {"id": 540, "subject": "Anatomy", "difficulty": "Medium", "question": "Ulnar nerve enters palm through:", "options": [{"key": "A", "text": "Carpal tunnel"}, {"key": "B", "text": "Guyon's canal"}, {"key": "C", "text": "Cubital tunnel"}, {"key": "D", "text": "Spiral groove"}], "correct": "B", "explanation": "Ulnar nerve passes through Guyon's canal (ulnar canal) at wrist."}, {"id": 541, "subject": "Anatomy", "difficulty": "Hard", "question": "Claw hand deformity is most pronounced in:", "options": [{"key": "A", "text": "High ulnar nerve lesion"}, {"key": "B", "text": "Low ulnar nerve lesion"}, {"key": "C", "text": "High median nerve lesion"}, {"key": "D", "text": "Radial nerve lesion"}], "correct": "B", "explanation": "Low ulnar nerve lesion → more pronounced claw (ring & little fingers) due to intact FDP."}, {"id": 542, "subject": "Anatomy", "difficulty": "Medium", "question": "Froment's sign tests the function of:", "options": [{"key": "A", "text": "Flexor pollicis longus"}, {"key": "B", "text": "Adductor pollicis"}, {"key": "C", "text": "Opponens pollicis"}, {"key": "D", "text": "Abductor pollicis brevis"}], "correct": "B", "explanation": "Froment's sign tests adductor pollicis (ulnar nerve); positive = thumb IP flexion during paper grip."}, {"id": 543, "subject": "Anatomy", "difficulty": "Easy", "question": "Hypothenar muscles are supplied by:", "options": [{"key": "A", "text": "Median nerve"}, {"key": "B", "text": "Radial nerve"}, {"key": "C", "text": "Ulnar nerve"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "C", "explanation": "Hypothenar muscles (abductor, flexor, opponens digiti minimi) all supplied by ulnar nerve."}, {"id": 544, "subject": "Anatomy", "difficulty": "Medium", "question": "Which muscle is NOT supplied by ulnar nerve?", "options": [{"key": "A", "text": "Flexor carpi ulnaris"}, {"key": "B", "text": "Flexor digitorum profundus (ring & little)"}, {"key": "C", "text": "Palmaris longus"}, {"key": "D", "text": "Adductor pollicis"}], "correct": "C", "explanation": "Palmaris longus is supplied by median nerve, not ulnar nerve."}, {"id": 545, "subject": "Anatomy", "difficulty": "Hard", "question": "Ulnar paradox refers to:", "options": [{"key": "A", "text": "More claw in high lesion"}, {"key": "B", "text": "Less claw in high lesion"}, {"key": "C", "text": "More claw in radial lesion"}, {"key": "D", "text": "Froment's sign reversal"}], "correct": "B", "explanation": "In high ulnar lesion, FDP also paralysed → less claw deformity (ulnar paradox)."}, {"id": 546, "subject": "Anatomy", "difficulty": "Hard", "question": "Dorsal cutaneous branch of ulnar nerve arises:", "options": [{"key": "A", "text": "In palm"}, {"key": "B", "text": "Inside Guyon's canal"}, {"key": "C", "text": "5 cm proximal to wrist"}, {"key": "D", "text": "At medial epicondyle"}], "correct": "C", "explanation": "Dorsal cutaneous branch arises ~5 cm proximal to wrist, so spared in Guyon's canal compression."}, {"id": 547, "subject": "Anatomy", "difficulty": "Hard", "question": "Wartenberg's sign is a feature of:", "options": [{"key": "A", "text": "Median nerve injury"}, {"key": "B", "text": "Radial nerve injury"}, {"key": "C", "text": "Ulnar nerve injury"}, {"key": "D", "text": "Musculocutaneous injury"}], "correct": "C", "explanation": "Wartenberg's sign = abducted little finger due to unopposed extensor digiti minimi in ulnar palsy."}, {"id": 548, "subject": "Anatomy", "difficulty": "Easy", "question": "Radial nerve arises from which cord of brachial plexus?", "options": [{"key": "A", "text": "Lateral cord"}, {"key": "B", "text": "Medial cord"}, {"key": "C", "text": "Posterior cord"}, {"key": "D", "text": "Both lateral and medial"}], "correct": "C", "explanation": "Radial nerve (C5-T1) is the largest branch of posterior cord."}, {"id": 549, "subject": "Anatomy", "difficulty": "Easy", "question": "Radial nerve winds around the humerus in which groove?", "options": [{"key": "A", "text": "Bicipital groove"}, {"key": "B", "text": "Cubital groove"}, {"key": "C", "text": "Spiral (radial) groove"}, {"key": "D", "text": "Olecranon groove"}], "correct": "C", "explanation": "Radial nerve lies in the spiral groove (radial groove) of humerus — site of injury in midshaft humeral fractures."}, {"id": 550, "subject": "Anatomy", "difficulty": "Easy", "question": "Wrist drop is a feature of injury to:", "options": [{"key": "A", "text": "Median nerve"}, {"key": "B", "text": "Ulnar nerve"}, {"key": "C", "text": "Radial nerve"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "C", "explanation": "Radial nerve injury → paralysis of wrist extensors → wrist drop."}, {"id": 551, "subject": "Anatomy", "difficulty": "Medium", "question": "Deep branch of radial nerve is also known as:", "options": [{"key": "A", "text": "Anterior interosseous nerve"}, {"key": "B", "text": "Posterior interosseous nerve"}, {"key": "C", "text": "Lateral cutaneous nerve"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "B", "explanation": "Deep branch of radial nerve = Posterior Interosseous Nerve (PIN) — purely motor."}, {"id": 552, "subject": "Anatomy", "difficulty": "Medium", "question": "Superficial branch of radial nerve is:", "options": [{"key": "A", "text": "Purely motor"}, {"key": "B", "text": "Purely sensory"}, {"key": "C", "text": "Mixed"}, {"key": "D", "text": "Autonomic"}], "correct": "B", "explanation": "Superficial radial nerve is purely sensory — supplies dorsum of hand (lateral 3½ digits)."}, {"id": 553, "subject": "Anatomy", "difficulty": "Medium", "question": "Saturday night palsy involves which nerve and level?", "options": [{"key": "A", "text": "Ulnar nerve at wrist"}, {"key": "B", "text": "Radial nerve in axilla"}, {"key": "C", "text": "Radial nerve in spiral groove"}, {"key": "D", "text": "Median nerve at elbow"}], "correct": "C", "explanation": "Saturday night palsy = radial nerve compressed in spiral groove (arm draped over chair)."}, {"id": 554, "subject": "Anatomy", "difficulty": "Medium", "question": "In crutch palsy, radial nerve is damaged at:", "options": [{"key": "A", "text": "Spiral groove"}, {"key": "B", "text": "Axilla"}, {"key": "C", "text": "Lateral epicondyle"}, {"key": "D", "text": "Posterior cord"}], "correct": "B", "explanation": "Crutch palsy → radial nerve compressed at axilla by crutch top."}, {"id": 555, "subject": "Anatomy", "difficulty": "Hard", "question": "Posterior interosseous nerve (PIN) syndrome spares which muscle?", "options": [{"key": "A", "text": "Extensor digitorum"}, {"key": "B", "text": "Extensor carpi radialis longus (ECRL)"}, {"key": "C", "text": "Extensor carpi ulnaris"}, {"key": "D", "text": "Extensor pollicis longus"}], "correct": "B", "explanation": "ECRL is supplied by radial nerve before it bifurcates, so spared in PIN syndrome."}, {"id": 556, "subject": "Anatomy", "difficulty": "Hard", "question": "Triceps is spared in which radial nerve injury?", "options": [{"key": "A", "text": "Axillary injury"}, {"key": "B", "text": "Spiral groove injury"}, {"key": "C", "text": "Lateral epicondyle injury"}, {"key": "D", "text": "Posterior cord injury"}], "correct": "B", "explanation": "Triceps branch arises proximal to spiral groove; mid-humeral fracture spares triceps."}, {"id": 557, "subject": "Anatomy", "difficulty": "Medium", "question": "Radial nerve supplies the skin of dorsum of hand over how many digits?", "options": [{"key": "A", "text": "2½ digits"}, {"key": "B", "text": "3½ digits"}, {"key": "C", "text": "4 digits"}, {"key": "D", "text": "All 5 digits"}], "correct": "B", "explanation": "Radial nerve (superficial branch) supplies dorsum of lateral 3½ digits (thumb, index, middle, half ring)."}, {"id": 558, "subject": "Anatomy", "difficulty": "Easy", "question": "Musculocutaneous nerve is a branch of which cord?", "options": [{"key": "A", "text": "Medial cord"}, {"key": "B", "text": "Posterior cord"}, {"key": "C", "text": "Lateral cord"}, {"key": "D", "text": "All cords"}], "correct": "C", "explanation": "Musculocutaneous nerve (C5,C6,C7) is a branch of the lateral cord."}, {"id": 559, "subject": "Anatomy", "difficulty": "Medium", "question": "Which nerve is most commonly injured in anterior dislocation of shoulder?", "options": [{"key": "A", "text": "Radial nerve"}, {"key": "B", "text": "Median nerve"}, {"key": "C", "text": "Ulnar nerve"}, {"key": "D", "text": "Axillary nerve"}], "correct": "D", "explanation": "Axillary nerve winds around surgical neck of humerus — injured in shoulder dislocation/surgical neck fracture."}, {"id": 560, "subject": "Anatomy", "difficulty": "Hard", "question": "'Pen test' or 'OK sign' tests integrity of:", "options": [{"key": "A", "text": "Ulnar nerve"}, {"key": "B", "text": "Median nerve — AIN"}, {"key": "C", "text": "Radial nerve"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "B", "explanation": "AIN (branch of median nerve) is tested by making OK sign — FPL and FDP index finger."}, {"id": 561, "subject": "Anatomy", "difficulty": "Medium", "question": "In high radial nerve palsy, which movement is preserved?", "options": [{"key": "A", "text": "Wrist extension"}, {"key": "B", "text": "Finger extension"}, {"key": "C", "text": "Elbow flexion"}, {"key": "D", "text": "Elbow extension"}], "correct": "C", "explanation": "Elbow flexion is by musculocutaneous nerve (biceps/brachialis), unaffected in radial nerve injury."}, {"id": 562, "subject": "Anatomy", "difficulty": "Medium", "question": "Which nerve injury causes loss of sensation over the anatomical snuffbox?", "options": [{"key": "A", "text": "Ulnar nerve"}, {"key": "B", "text": "Median nerve"}, {"key": "C", "text": "Superficial radial nerve"}, {"key": "D", "text": "Anterior interosseous nerve"}], "correct": "C", "explanation": "Anatomical snuffbox sensory supply = superficial branch of radial nerve."}, {"id": 563, "subject": "Anatomy", "difficulty": "Easy", "question": "Sensory loss on medial 1½ fingers (palmar) indicates injury to:", "options": [{"key": "A", "text": "Radial nerve"}, {"key": "B", "text": "Median nerve"}, {"key": "C", "text": "Ulnar nerve"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "C", "explanation": "Ulnar nerve supplies palmar aspect of medial 1½ fingers (little + medial ring)."}, {"id": 564, "subject": "Anatomy", "difficulty": "Easy", "question": "Which nerve injury results in loss of elbow flexion?", "options": [{"key": "A", "text": "Radial nerve"}, {"key": "B", "text": "Median nerve"}, {"key": "C", "text": "Ulnar nerve"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "D", "explanation": "Musculocutaneous nerve supplies biceps brachii and brachialis — main elbow flexors."}, {"id": 565, "subject": "Anatomy", "difficulty": "Medium", "question": "Lateral cutaneous nerve of forearm is the cutaneous continuation of:", "options": [{"key": "A", "text": "Radial nerve"}, {"key": "B", "text": "Ulnar nerve"}, {"key": "C", "text": "Musculocutaneous nerve"}, {"key": "D", "text": "Median nerve"}], "correct": "C", "explanation": "Musculocutaneous nerve pierces deep fascia and continues as lateral cutaneous nerve of forearm."}, {"id": 566, "subject": "Anatomy", "difficulty": "Medium", "question": "In lower trunk (C8,T1) injury, which feature is SEEN?", "options": [{"key": "A", "text": "Loss of shoulder abduction"}, {"key": "B", "text": "Wrist drop"}, {"key": "C", "text": "Claw hand with intrinsic weakness"}, {"key": "D", "text": "Loss of elbow flexion"}], "correct": "C", "explanation": "Lower trunk = Klumpke's palsy — intrinsic hand muscle weakness, claw hand, Horner's syndrome."}, {"id": 567, "subject": "Anatomy", "difficulty": "Hard", "question": "The 'gun stock deformity' (cubitus varus) most likely injures which nerve?", "options": [{"key": "A", "text": "Ulnar nerve"}, {"key": "B", "text": "Median nerve"}, {"key": "C", "text": "Radial nerve"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "A", "explanation": "Cubitus varus (malunited supracondylar fracture) causes delayed ulnar nerve palsy due to stretching."}, {"id": 568, "subject": "Anatomy", "difficulty": "Hard", "question": "Which of the following muscles is supplied by BOTH median and ulnar nerves?", "options": [{"key": "A", "text": "Flexor digitorum superficialis"}, {"key": "B", "text": "Flexor digitorum profundus"}, {"key": "C", "text": "Opponens pollicis"}, {"key": "D", "text": "Flexor carpi ulnaris"}], "correct": "B", "explanation": "FDP medial half (ring & little) = ulnar nerve; FDP lateral half (index & middle) = median nerve."}, {"id": 569, "subject": "Anatomy", "difficulty": "Medium", "question": "Which nerve arises from the upper trunk of brachial plexus?", "options": [{"key": "A", "text": "Nerve to subclavius"}, {"key": "B", "text": "Suprascapular nerve"}, {"key": "C", "text": "Both A and B"}, {"key": "D", "text": "Long thoracic nerve"}], "correct": "C", "explanation": "Upper trunk gives: suprascapular nerve + nerve to subclavius."}, {"id": 570, "subject": "Anatomy", "difficulty": "Medium", "question": "Thoracodorsal nerve supplies which muscle?", "options": [{"key": "A", "text": "Serratus anterior"}, {"key": "B", "text": "Pectoralis major"}, {"key": "C", "text": "Latissimus dorsi"}, {"key": "D", "text": "Teres minor"}], "correct": "C", "explanation": "Thoracodorsal nerve (C6,C7,C8) from posterior cord supplies latissimus dorsi."}, {"id": 571, "subject": "Anatomy", "difficulty": "Easy", "question": "Injury to long thoracic nerve causes:", "options": [{"key": "A", "text": "Winging of scapula"}, {"key": "B", "text": "Wrist drop"}, {"key": "C", "text": "Claw hand"}, {"key": "D", "text": "Shoulder dislocation"}], "correct": "A", "explanation": "Long thoracic nerve → serratus anterior → paralysis causes medial winging of scapula."}, {"id": 572, "subject": "Anatomy", "difficulty": "Medium", "question": "Which nerve supplies teres minor?", "options": [{"key": "A", "text": "Axillary nerve"}, {"key": "B", "text": "Radial nerve"}, {"key": "C", "text": "Suprascapular nerve"}, {"key": "D", "text": "Lower subscapular nerve"}], "correct": "A", "explanation": "Axillary nerve (C5,C6) supplies teres minor and deltoid."}, {"id": 573, "subject": "Anatomy", "difficulty": "Medium", "question": "Medial pectoral nerve arises from:", "options": [{"key": "A", "text": "Lateral cord"}, {"key": "B", "text": "Medial cord"}, {"key": "C", "text": "Posterior cord"}, {"key": "D", "text": "Upper trunk"}], "correct": "B", "explanation": "Medial pectoral nerve (C8,T1) arises from medial cord; lateral pectoral from lateral cord."}, {"id": 574, "subject": "Anatomy", "difficulty": "Medium", "question": "Which cord gives rise to both ulnar nerve and medial cutaneous nerves of arm and forearm?", "options": [{"key": "A", "text": "Lateral cord"}, {"key": "B", "text": "Posterior cord"}, {"key": "C", "text": "Medial cord"}, {"key": "D", "text": "Upper trunk"}], "correct": "C", "explanation": "Medial cord → ulnar nerve, medial cutaneous nerve of arm, medial cutaneous nerve of forearm."}, {"id": 575, "subject": "Anatomy", "difficulty": "Hard", "question": "Horner's syndrome in brachial plexus injury indicates involvement of:", "options": [{"key": "A", "text": "Upper trunk (C5,C6)"}, {"key": "B", "text": "Middle trunk (C7)"}, {"key": "C", "text": "Lower trunk (C8,T1)"}, {"key": "D", "text": "Posterior cord"}], "correct": "C", "explanation": "T1 root carries sympathetic fibres; lower trunk injury can cause Horner's syndrome."}, {"id": 576, "subject": "Anatomy", "difficulty": "Easy", "question": "'Policeman's tip' posture is seen in:", "options": [{"key": "A", "text": "Klumpke's palsy"}, {"key": "B", "text": "Erb's palsy"}, {"key": "C", "text": "PIN syndrome"}, {"key": "D", "text": "Carpal tunnel syndrome"}], "correct": "B", "explanation": "Erb's palsy → shoulder adducted & internally rotated, elbow extended, forearm pronated = waiter's/policeman's tip."}, {"id": 577, "subject": "Anatomy", "difficulty": "Medium", "question": "Which muscle is supplied by dorsal scapular nerve?", "options": [{"key": "A", "text": "Serratus anterior"}, {"key": "B", "text": "Rhomboids"}, {"key": "C", "text": "Supraspinatus"}, {"key": "D", "text": "Infraspinatus"}], "correct": "B", "explanation": "Dorsal scapular nerve (C5) supplies rhomboids major, minor and levator scapulae."}, {"id": 578, "subject": "Anatomy", "difficulty": "Hard", "question": "The medial root of median nerve carries fibres from:", "options": [{"key": "A", "text": "C5, C6"}, {"key": "B", "text": "C6, C7"}, {"key": "C", "text": "C7, C8"}, {"key": "D", "text": "C8, T1"}], "correct": "D", "explanation": "Medial root of median nerve = C8,T1 from medial cord; lateral root = C6,C7 from lateral cord."}, {"id": 579, "subject": "Anatomy", "difficulty": "Medium", "question": "Flexor digitorum superficialis is supplied by which nerve?", "options": [{"key": "A", "text": "Ulnar nerve"}, {"key": "B", "text": "Radial nerve"}, {"key": "C", "text": "Median nerve"}, {"key": "D", "text": "Anterior interosseous nerve"}], "correct": "C", "explanation": "FDS is supplied by median nerve in the forearm (not AIN)."}, {"id": 580, "subject": "Anatomy", "difficulty": "Hard", "question": "In carpal tunnel syndrome, which test has highest sensitivity?", "options": [{"key": "A", "text": "Tinel's sign"}, {"key": "B", "text": "Phalen's test"}, {"key": "C", "text": "Durkan's compression test"}, {"key": "D", "text": "Reverse Phalen's test"}], "correct": "C", "explanation": "Durkan's carpal compression test has highest sensitivity (~87%) for CTS."}, {"id": 581, "subject": "Anatomy", "difficulty": "Medium", "question": "Median nerve innervates all of the following in the hand EXCEPT:", "options": [{"key": "A", "text": "Abductor pollicis brevis"}, {"key": "B", "text": "Opponens pollicis"}, {"key": "C", "text": "Adductor pollicis"}, {"key": "D", "text": "Flexor pollicis brevis (superficial head)"}], "correct": "C", "explanation": "Adductor pollicis is supplied by deep branch of ulnar nerve, not median nerve."}, {"id": 582, "subject": "Anatomy", "difficulty": "Medium", "question": "Pronator syndrome is compression of median nerve between heads of:", "options": [{"key": "A", "text": "Supinator"}, {"key": "B", "text": "Pronator teres"}, {"key": "C", "text": "Flexor carpi radialis"}, {"key": "D", "text": "Flexor digitorum superficialis"}], "correct": "B", "explanation": "Pronator syndrome = median nerve compressed between humeral and ulnar heads of pronator teres."}, {"id": 583, "subject": "Anatomy", "difficulty": "Easy", "question": "Which finger is NOT affected in median nerve sensory loss at wrist?", "options": [{"key": "A", "text": "Thumb"}, {"key": "B", "text": "Index finger"}, {"key": "C", "text": "Middle finger"}, {"key": "D", "text": "Little finger"}], "correct": "D", "explanation": "Median nerve supplies palmar aspect of lateral 3½ digits; little finger (medial 1½) = ulnar nerve."}, {"id": 584, "subject": "Anatomy", "difficulty": "Hard", "question": "Recurrent (thenar) branch of median nerve arises:", "options": [{"key": "A", "text": "Inside carpal tunnel"}, {"key": "B", "text": "Distal to flexor retinaculum"}, {"key": "C", "text": "Proximal to carpal tunnel"}, {"key": "D", "text": "From AIN"}], "correct": "B", "explanation": "Recurrent branch arises just distal to flexor retinaculum and hooks back to supply thenar muscles."}, {"id": 585, "subject": "Anatomy", "difficulty": "Medium", "question": "The functional loss most disabling in median nerve injury at wrist is:", "options": [{"key": "A", "text": "Loss of wrist flexion"}, {"key": "B", "text": "Loss of thumb opposition"}, {"key": "C", "text": "Loss of elbow flexion"}, {"key": "D", "text": "Loss of finger extension"}], "correct": "B", "explanation": "Thumb opposition (opponens pollicis) is the most functionally important movement lost in median nerve injury."}, {"id": 586, "subject": "Anatomy", "difficulty": "Medium", "question": "Flexor pollicis longus is supplied by:", "options": [{"key": "A", "text": "Median nerve (main trunk)"}, {"key": "B", "text": "Anterior interosseous nerve"}, {"key": "C", "text": "Recurrent branch of median nerve"}, {"key": "D", "text": "Ulnar nerve"}], "correct": "B", "explanation": "FPL is exclusively supplied by AIN (branch of median nerve) in the forearm."}, {"id": 587, "subject": "Anatomy", "difficulty": "Medium", "question": "Lumbrical muscles 3 and 4 are supplied by:", "options": [{"key": "A", "text": "Median nerve"}, {"key": "B", "text": "Ulnar nerve"}, {"key": "C", "text": "Radial nerve"}, {"key": "D", "text": "Both median and ulnar"}], "correct": "B", "explanation": "Lumbricals 1&2 = median nerve; Lumbricals 3&4 = deep branch of ulnar nerve."}, {"id": 588, "subject": "Anatomy", "difficulty": "Hard", "question": "In high median nerve lesion at elbow, which movement is PRESERVED?", "options": [{"key": "A", "text": "Thumb flexion (FPL)"}, {"key": "B", "text": "Index finger flexion (FDP)"}, {"key": "C", "text": "Ring finger flexion (FDP)"}, {"key": "D", "text": "Wrist flexion by FCR"}], "correct": "C", "explanation": "Ring & little FDP = ulnar nerve; so ring finger flexion preserved in median nerve lesion."}, {"id": 589, "subject": "Anatomy", "difficulty": "Medium", "question": "Flexor carpi ulnaris is tested by:", "options": [{"key": "A", "text": "Wrist extension against resistance"}, {"key": "B", "text": "Wrist flexion with ulnar deviation"}, {"key": "C", "text": "Finger abduction"}, {"key": "D", "text": "Thumb opposition"}], "correct": "B", "explanation": "FCU (ulnar nerve) causes wrist flexion with ulnar deviation."}, {"id": 590, "subject": "Anatomy", "difficulty": "Medium", "question": "Which intrinsic hand muscles are supplied by ulnar nerve? (Select best answer)", "options": [{"key": "A", "text": "All interossei + medial 2 lumbricals + hypothenar"}, {"key": "B", "text": "All interossei only"}, {"key": "C", "text": "Thenar + hypothenar"}, {"key": "D", "text": "All lumbricals + thenar"}], "correct": "A", "explanation": "Ulnar nerve supplies: all 7 interossei, lumbricals 3&4, all hypothenar muscles, adductor pollicis, deep head FPB."}, {"id": 591, "subject": "Anatomy", "difficulty": "Medium", "question": "In Guyon's canal, the ulnar nerve divides into:", "options": [{"key": "A", "text": "Dorsal and palmar branches"}, {"key": "B", "text": "Superficial and deep branches"}, {"key": "C", "text": "Motor and sensory branches"}, {"key": "D", "text": "Medial and lateral branches"}], "correct": "B", "explanation": "In Guyon's canal, ulnar nerve divides into superficial (sensory) and deep (motor) branches."}, {"id": 592, "subject": "Anatomy", "difficulty": "Hard", "question": "Card test (Egawa's test) assesses function of:", "options": [{"key": "A", "text": "Adductor pollicis"}, {"key": "B", "text": "Dorsal interossei"}, {"key": "C", "text": "Opponens digiti minimi"}, {"key": "D", "text": "Lumbrical 3 & 4"}], "correct": "B", "explanation": "Card test (holding card between fingers) tests dorsal interossei — finger abduction — ulnar nerve."}, {"id": 593, "subject": "Anatomy", "difficulty": "Medium", "question": "In ulnar nerve injury, the interossei are paralyzed causing loss of:", "options": [{"key": "A", "text": "Finger abduction and adduction (DAB, PAD)"}, {"key": "B", "text": "Finger flexion"}, {"key": "C", "text": "Wrist extension"}, {"key": "D", "text": "Thumb flexion"}], "correct": "A", "explanation": "Dorsal interossei = ABduct (DAB); Palmar interossei = ADduct (PAD) — both paralyzed in ulnar nerve injury."}, {"id": 594, "subject": "Anatomy", "difficulty": "Easy", "question": "Cubital tunnel syndrome is compression of ulnar nerve at:", "options": [{"key": "A", "text": "Wrist (Guyon's canal)"}, {"key": "B", "text": "Elbow (medial epicondyle)"}, {"key": "C", "text": "Axilla"}, {"key": "D", "text": "Spiral groove"}], "correct": "B", "explanation": "Cubital tunnel syndrome = ulnar nerve compressed at elbow, most common site of ulnar nerve entrapment."}, {"id": 595, "subject": "Anatomy", "difficulty": "Hard", "question": "In ulnar nerve lesion, sensory loss on dorsum of hand means lesion is:", "options": [{"key": "A", "text": "At wrist (Guyon's canal)"}, {"key": "B", "text": "Distal to dorsal cutaneous branch"}, {"key": "C", "text": "At or proximal to mid-forearm"}, {"key": "D", "text": "Inside carpal tunnel"}], "correct": "C", "explanation": "Dorsal cutaneous branch arises 5 cm proximal to wrist; its involvement indicates lesion at/above mid-forearm."}, {"id": 596, "subject": "Anatomy", "difficulty": "Hard", "question": "Which deformity is MORE pronounced in LOW ulnar nerve lesion?", "options": [{"key": "A", "text": "Wrist drop"}, {"key": "B", "text": "Claw hand"}, {"key": "C", "text": "Ape thumb"}, {"key": "D", "text": "Winging of scapula"}], "correct": "B", "explanation": "Low lesion → FDP intact → stronger pull on ring & little fingers → more pronounced claw (ulnar paradox)."}, {"id": 597, "subject": "Anatomy", "difficulty": "Medium", "question": "Adductor pollicis is tested clinically by:", "options": [{"key": "A", "text": "Pinch grip strength"}, {"key": "B", "text": "Froment's sign"}, {"key": "C", "text": "Pen test"}, {"key": "D", "text": "Phalen's test"}], "correct": "B", "explanation": "Froment's sign tests adductor pollicis — patient uses FPL (median) to compensate when holding paper."}, {"id": 598, "subject": "Anatomy", "difficulty": "Hard", "question": "Rider's palsy / handlebar neuropathy is compression of:", "options": [{"key": "A", "text": "Radial nerve at spiral groove"}, {"key": "B", "text": "Median nerve at wrist"}, {"key": "C", "text": "Ulnar nerve at Guyon's canal"}, {"key": "D", "text": "PIN at arcade of Frohse"}], "correct": "C", "explanation": "Cyclist's palsy / handlebar palsy = ulnar nerve compression at Guyon's canal due to prolonged cycling."}, {"id": 599, "subject": "Anatomy", "difficulty": "Medium", "question": "Arcade of Frohse is the site of compression of:", "options": [{"key": "A", "text": "Anterior interosseous nerve"}, {"key": "B", "text": "Posterior interosseous nerve"}, {"key": "C", "text": "Superficial radial nerve"}, {"key": "D", "text": "Ulnar nerve"}], "correct": "B", "explanation": "Arcade of Frohse = fibrous arch of supinator — compresses PIN (deep branch of radial nerve)."}, {"id": 600, "subject": "Anatomy", "difficulty": "Hard", "question": "In radial nerve injury at spiral groove, which movement is SPARED?", "options": [{"key": "A", "text": "Wrist extension"}, {"key": "B", "text": "Finger extension"}, {"key": "C", "text": "Thumb extension"}, {"key": "D", "text": "Elbow extension (triceps)"}], "correct": "D", "explanation": "Triceps branch arises proximal to spiral groove → elbow extension preserved in midshaft humeral fracture."}, {"id": 601, "subject": "Anatomy", "difficulty": "Easy", "question": "The radial nerve is most commonly injured in fracture of:", "options": [{"key": "A", "text": "Surgical neck of humerus"}, {"key": "B", "text": "Midshaft of humerus"}, {"key": "C", "text": "Lateral epicondyle"}, {"key": "D", "text": "Radial head"}], "correct": "B", "explanation": "Radial nerve lies in spiral groove at midshaft humerus — most common site of injury."}, {"id": 602, "subject": "Anatomy", "difficulty": "Hard", "question": "Cheiralgia paresthetica is compression of which nerve?", "options": [{"key": "A", "text": "Median nerve"}, {"key": "B", "text": "Ulnar nerve"}, {"key": "C", "text": "Superficial radial nerve"}, {"key": "D", "text": "Lateral cutaneous nerve of forearm"}], "correct": "C", "explanation": "Cheiralgia paresthetica (Wartenberg's syndrome) = compression of superficial radial nerve at wrist."}, {"id": 603, "subject": "Anatomy", "difficulty": "Medium", "question": "Brachioradialis is supplied by radial nerve. It acts as:", "options": [{"key": "A", "text": "Weak elbow flexor in mid-prone position"}, {"key": "B", "text": "Elbow extensor"}, {"key": "C", "text": "Wrist extensor"}, {"key": "D", "text": "Forearm supinator"}], "correct": "A", "explanation": "Brachioradialis flexes the elbow, especially in mid-prone position (between full pronation and supination)."}, {"id": 604, "subject": "Anatomy", "difficulty": "Hard", "question": "In PIN (posterior interosseous nerve) palsy, wrist extension is:", "options": [{"key": "A", "text": "Completely lost"}, {"key": "B", "text": "Partially preserved (radial deviation)"}, {"key": "C", "text": "Normal"}, {"key": "D", "text": "Replaced by ulnar deviation"}], "correct": "B", "explanation": "ECRL (radial nerve, proximal to PIN) preserved → wrist extends with radial deviation; ECU (PIN) paralyzed."}, {"id": 605, "subject": "Anatomy", "difficulty": "Medium", "question": "Radial nerve at axilla injury additionally loses which function compared to spiral groove injury?", "options": [{"key": "A", "text": "Wrist extension"}, {"key": "B", "text": "Triceps function"}, {"key": "C", "text": "Finger extension"}, {"key": "D", "text": "Brachioradialis"}], "correct": "B", "explanation": "Triceps branch arises above spiral groove; axillary injury additionally paralyzes triceps."}, {"id": 606, "subject": "Anatomy", "difficulty": "Hard", "question": "Tennis elbow (lateral epicondylitis) must be differentiated from:", "options": [{"key": "A", "text": "Cubital tunnel syndrome"}, {"key": "B", "text": "PIN entrapment at radial tunnel"}, {"key": "C", "text": "Guyon's canal syndrome"}, {"key": "D", "text": "CTS"}], "correct": "B", "explanation": "Radial tunnel syndrome (PIN entrapment) mimics tennis elbow — point tenderness 4 cm distal to lateral epicondyle."}, {"id": 607, "subject": "Anatomy", "difficulty": "Medium", "question": "Extensor pollicis longus is supplied by:", "options": [{"key": "A", "text": "Superficial radial nerve"}, {"key": "B", "text": "Posterior interosseous nerve (PIN)"}, {"key": "C", "text": "Anterior interosseous nerve"}, {"key": "D", "text": "Ulnar nerve"}], "correct": "B", "explanation": "EPL, EPB, APL, EIP, EDC, ECU — all supplied by PIN (deep branch of radial nerve)."}, {"id": 608, "subject": "Anatomy", "difficulty": "Medium", "question": "Sensory supply of the first web space on dorsum of hand is by:", "options": [{"key": "A", "text": "Median nerve"}, {"key": "B", "text": "Ulnar nerve"}, {"key": "C", "text": "Superficial radial nerve"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "C", "explanation": "First web space (dorsal) = superficial branch of radial nerve — useful to test in radial nerve lesions."}, {"id": 609, "subject": "Anatomy", "difficulty": "Hard", "question": "Intrinsic plus deformity refers to:", "options": [{"key": "A", "text": "MCP extension + IP flexion"}, {"key": "B", "text": "MCP flexion + IP extension"}, {"key": "C", "text": "MCP flexion + IP flexion"}, {"key": "D", "text": "MCP extension + IP extension"}], "correct": "B", "explanation": "Intrinsic plus = lumbricals/interossei overactive → MCP flexion + IP extension (opposite of claw)."}, {"id": 610, "subject": "Anatomy", "difficulty": "Medium", "question": "Which nerve is tested by resisted forearm supination with elbow at 90°?", "options": [{"key": "A", "text": "Ulnar nerve"}, {"key": "B", "text": "Median nerve"}, {"key": "C", "text": "Musculocutaneous nerve"}, {"key": "D", "text": "Radial nerve"}], "correct": "C", "explanation": "Biceps brachii (musculocutaneous nerve) is the primary supinator with elbow at 90°."}, {"id": 611, "subject": "Anatomy", "difficulty": "Hard", "question": "Boutonniére deformity involves which structures primarily?", "options": [{"key": "A", "text": "FDS + FDP"}, {"key": "B", "text": "Central slip of extensor tendon + volar plate"}, {"key": "C", "text": "Lateral bands + collateral ligaments"}, {"key": "D", "text": "Interossei + lumbricals"}], "correct": "B", "explanation": "Boutonnière = rupture of central slip → PIP flexion + DIP hyperextension."}, {"id": 612, "subject": "Anatomy", "difficulty": "Hard", "question": "Injury to medial cord of brachial plexus causes loss of BOTH:", "options": [{"key": "A", "text": "Median and radial nerve functions"}, {"key": "B", "text": "Ulnar and radial nerve functions"}, {"key": "C", "text": "Median (partial) and ulnar nerve functions"}, {"key": "D", "text": "Musculocutaneous and radial functions"}], "correct": "C", "explanation": "Medial cord gives ulnar nerve + medial root of median nerve (C8,T1) — both affected in medial cord injury."}, {"id": 613, "subject": "Anatomy", "difficulty": "Hard", "question": "Posterior cord injury causes loss of all EXCEPT:", "options": [{"key": "A", "text": "Shoulder abduction (deltoid)"}, {"key": "B", "text": "Elbow extension (triceps)"}, {"key": "C", "text": "Elbow flexion"}, {"key": "D", "text": "Wrist and finger extension"}], "correct": "C", "explanation": "Elbow flexion (biceps/brachialis) = musculocutaneous nerve (lateral cord) — not affected in posterior cord lesion."}, {"id": 614, "subject": "Anatomy", "difficulty": "Medium", "question": "Which nerve supplies the first dorsal interosseous muscle?", "options": [{"key": "A", "text": "Median nerve"}, {"key": "B", "text": "Superficial ulnar nerve"}, {"key": "C", "text": "Deep branch of ulnar nerve"}, {"key": "D", "text": "Radial nerve"}], "correct": "C", "explanation": "All interossei (including 1st dorsal interosseous) are supplied by deep branch of ulnar nerve."}, {"id": 615, "subject": "Anatomy", "difficulty": "Hard", "question": "Pinch grip is mainly tested for:", "options": [{"key": "A", "text": "Ulnar nerve — adductor pollicis"}, {"key": "B", "text": "Median nerve — opponens pollicis"}, {"key": "C", "text": "Radial nerve — EPL"}, {"key": "D", "text": "Both median and ulnar"}], "correct": "D", "explanation": "Normal pinch requires median nerve (APB, opponens) + ulnar nerve (adductor pollicis) working together."}, {"id": 616, "subject": "Anatomy", "difficulty": "Easy", "question": "The most common site of ulnar nerve entrapment is:", "options": [{"key": "A", "text": "Wrist (Guyon's canal)"}, {"key": "B", "text": "Elbow (cubital tunnel)"}, {"key": "C", "text": "Axilla"}, {"key": "D", "text": "Thoracic outlet"}], "correct": "B", "explanation": "Cubital tunnel (elbow) is the most common site of ulnar nerve entrapment."}, {"id": 617, "subject": "Anatomy", "difficulty": "Hard", "question": "Which nerve injury produces a 'pointing index finger' on making a fist?", "options": [{"key": "A", "text": "Ulnar nerve at wrist"}, {"key": "B", "text": "Median nerve at elbow"}, {"key": "C", "text": "Radial nerve"}, {"key": "D", "text": "AIN injury"}], "correct": "D", "explanation": "AIN injury → FPL + FDP index paralysis → patient cannot flex index DIP or thumb IP when making fist."}, {"id": 618, "subject": "Anatomy", "difficulty": "Medium", "question": "In thoracic outlet syndrome, which trunk is most commonly compressed?", "options": [{"key": "A", "text": "Upper trunk (C5,C6)"}, {"key": "B", "text": "Middle trunk (C7)"}, {"key": "C", "text": "Lower trunk (C8,T1)"}, {"key": "D", "text": "All trunks equally"}], "correct": "C", "explanation": "Lower trunk (C8,T1) is most vulnerable in thoracic outlet syndrome — causes hand intrinsic weakness."}, {"id": 619, "subject": "Anatomy", "difficulty": "Hard", "question": "The nerve to subclavius is clinically important because it may provide accessory supply to:", "options": [{"key": "A", "text": "Deltoid"}, {"key": "B", "text": "Phrenic nerve (C5 anastomosis)"}, {"key": "C", "text": "Serratus anterior"}, {"key": "D", "text": "Biceps brachii"}], "correct": "B", "explanation": "Nerve to subclavius may anastomose with phrenic nerve — important in cervical root avulsion surgeries."}, {"id": 620, "subject": "Anatomy", "difficulty": "Easy", "question": "Which muscle is the primary knee extensor?", "options": [{"key": "A", "text": "Biceps femoris"}, {"key": "B", "text": "Rectus femoris"}, {"key": "C", "text": "Sartorius"}, {"key": "D", "text": "Gracilis"}], "correct": "B", "explanation": "Rectus femoris is the only quadriceps muscle that crosses both hip and knee joints, making it primary knee extensor."}, {"id": 621, "subject": "Anatomy", "difficulty": "Easy", "question": "How many heads does the quadriceps femoris have?", "options": [{"key": "A", "text": "Two"}, {"key": "B", "text": "Three"}, {"key": "C", "text": "Four"}, {"key": "D", "text": "Five"}], "correct": "C", "explanation": "Quadriceps femoris has four heads: rectus femoris, vastus lateralis, vastus medialis, and vastus intermedius."}, {"id": 622, "subject": "Anatomy", "difficulty": "Easy", "question": "The quadriceps muscle inserts into which structure?", "options": [{"key": "A", "text": "Fibular head"}, {"key": "B", "text": "Tibial tuberosity via patellar tendon"}, {"key": "C", "text": "Medial condyle of tibia"}, {"key": "D", "text": "Lateral condyle of femur"}], "correct": "B", "explanation": "All four quadriceps heads converge into the quadriceps tendon, which continues as the patellar tendon inserting into tibial tuberosity."}, {"id": 623, "subject": "Anatomy", "difficulty": "Medium", "question": "Vastus medialis oblique (VMO) is primarily responsible for:", "options": [{"key": "A", "text": "Full knee extension"}, {"key": "B", "text": "Last 15-20 degrees of knee extension"}, {"key": "C", "text": "Knee flexion"}, {"key": "D", "text": "Hip flexion"}], "correct": "B", "explanation": "VMO is critical for the final 15-20 degrees of knee extension and patellar stabilization."}, {"id": 624, "subject": "Anatomy", "difficulty": "Easy", "question": "Which nerve innervates the quadriceps femoris?", "options": [{"key": "A", "text": "Obturator nerve"}, {"key": "B", "text": "Sciatic nerve"}, {"key": "C", "text": "Femoral nerve"}, {"key": "D", "text": "Common peroneal nerve"}], "correct": "C", "explanation": "Femoral nerve (L2, L3, L4) innervates all four heads of quadriceps femoris."}, {"id": 625, "subject": "Anatomy", "difficulty": "Medium", "question": "Rectus femoris originates from:", "options": [{"key": "A", "text": "Greater trochanter"}, {"key": "B", "text": "Anterior inferior iliac spine (AIIS)"}, {"key": "C", "text": "Ischial tuberosity"}, {"key": "D", "text": "Lesser trochanter"}], "correct": "B", "explanation": "Rectus femoris has two heads: straight head from AIIS and reflected head from acetabular ridge."}, {"id": 626, "subject": "Anatomy", "difficulty": "Easy", "question": "Which quadriceps muscle does NOT cross the hip joint?", "options": [{"key": "A", "text": "Rectus femoris"}, {"key": "B", "text": "Vastus lateralis"}, {"key": "C", "text": "Both B and C"}, {"key": "D", "text": "None of these"}], "correct": "C", "explanation": "Vastus lateralis, vastus medialis, and vastus intermedius originate from the femur and only cross the knee joint."}, {"id": 627, "subject": "Anatomy", "difficulty": "Medium", "question": "The Q-angle is measured between:", "options": [{"key": "A", "text": "Quadriceps line and patellar tendon"}, {"key": "B", "text": "ASIS to patella center and patella center to tibial tuberosity"}, {"key": "C", "text": "Femur and tibia"}, {"key": "D", "text": "Hip and knee axis"}], "correct": "B", "explanation": "Q-angle is the angle formed by a line from ASIS to patella center and patella center to tibial tuberosity; normal is 10-15 degrees."}, {"id": 628, "subject": "Anatomy", "difficulty": "Hard", "question": "Vastus intermedius originates from:", "options": [{"key": "A", "text": "Medial femoral surface"}, {"key": "B", "text": "Lateral femoral surface"}, {"key": "C", "text": "Anterior and lateral femoral surface"}, {"key": "D", "text": "Posterior femoral surface"}], "correct": "C", "explanation": "Vastus intermedius originates from the anterior and lateral surfaces of the femoral shaft."}, {"id": 629, "subject": "Anatomy", "difficulty": "Hard", "question": "In knee extension, the screw-home mechanism involves:", "options": [{"key": "A", "text": "Medial rotation of tibia"}, {"key": "B", "text": "Lateral rotation of tibia"}, {"key": "C", "text": "Medial rotation of femur on fixed tibia"}, {"key": "D", "text": "Lateral rotation of femur"}], "correct": "B", "explanation": "During terminal knee extension (open kinetic chain), tibia laterally rotates to lock the knee - called screw-home mechanism."}, {"id": 630, "subject": "Anatomy", "difficulty": "Medium", "question": "Which quadriceps muscle has oblique fiber orientation most important for patellar tracking?", "options": [{"key": "A", "text": "Vastus lateralis"}, {"key": "B", "text": "Vastus medialis oblique"}, {"key": "C", "text": "Rectus femoris"}, {"key": "D", "text": "Vastus intermedius"}], "correct": "B", "explanation": "VMO's oblique fibers (50-55 degrees) pull patella medially, counteracting lateral pull of vastus lateralis."}, {"id": 631, "subject": "Anatomy", "difficulty": "Hard", "question": "Peak torque of quadriceps is produced at approximately:", "options": [{"key": "A", "text": "Full extension (0 degrees)"}, {"key": "B", "text": "30-60 degrees of knee flexion"}, {"key": "C", "text": "90 degrees of knee flexion"}, {"key": "D", "text": "120 degrees of knee flexion"}], "correct": "B", "explanation": "Quadriceps produce maximum torque between 30-60 degrees of knee flexion due to optimal length-tension relationship."}, {"id": 632, "subject": "Anatomy", "difficulty": "Medium", "question": "The blood supply to quadriceps is primarily from:", "options": [{"key": "A", "text": "Popliteal artery"}, {"key": "B", "text": "Femoral artery and its branches"}, {"key": "C", "text": "Obturator artery"}, {"key": "D", "text": "Lateral circumflex femoral artery"}], "correct": "B", "explanation": "Quadriceps is primarily supplied by the femoral artery and its muscular branches, including lateral circumflex femoral artery."}, {"id": 633, "subject": "Anatomy", "difficulty": "Easy", "question": "Rectus femoris acts as a hip flexor due to its origin at:", "options": [{"key": "A", "text": "ASIS"}, {"key": "B", "text": "AIIS"}, {"key": "C", "text": "Pubic symphysis"}, {"key": "D", "text": "Iliac crest"}], "correct": "B", "explanation": "Rectus femoris originates at AIIS, anterior to the hip joint axis, allowing it to flex the hip."}, {"id": 634, "subject": "Anatomy", "difficulty": "Medium", "question": "In open kinetic chain, quadriceps contraction produces:", "options": [{"key": "A", "text": "Knee flexion"}, {"key": "B", "text": "Knee extension with tibial movement"}, {"key": "C", "text": "Hip extension"}, {"key": "D", "text": "Tibial internal rotation"}], "correct": "B", "explanation": "In open kinetic chain, distal segment (tibia) moves; quadriceps contraction extends the knee by moving tibia forward."}, {"id": 635, "subject": "Anatomy", "difficulty": "Hard", "question": "The quadriceps-to-hamstring strength ratio (Q:H ratio) normal value is approximately:", "options": [{"key": "A", "text": "1:1"}, {"key": "B", "text": "2:1"}, {"key": "C", "text": "3:1"}, {"key": "D", "text": "1:2"}], "correct": "B", "explanation": "Normal Q:H ratio is approximately 2:1 (60:30 Nm), though values between 1.5:1 to 2.5:1 are considered acceptable."}, {"id": 636, "subject": "Anatomy", "difficulty": "Medium", "question": "Vastus lateralis originates from:", "options": [{"key": "A", "text": "Intertrochanteric line and lateral lip of linea aspera"}, {"key": "B", "text": "Medial lip of linea aspera"}, {"key": "C", "text": "Greater trochanter only"}, {"key": "D", "text": "Femoral neck"}], "correct": "A", "explanation": "Vastus lateralis originates from the intertrochanteric line, greater trochanter, and lateral lip of linea aspera."}, {"id": 637, "subject": "Anatomy", "difficulty": "Medium", "question": "Which condition is associated with VMO weakness and patellar maltracking?", "options": [{"key": "A", "text": "Patellofemoral pain syndrome"}, {"key": "B", "text": "Hamstring strain"}, {"key": "C", "text": "Iliotibial band syndrome"}, {"key": "D", "text": "Meniscal tear"}], "correct": "A", "explanation": "Weak VMO causes lateral patellar tracking, leading to patellofemoral pain syndrome due to increased lateral compression."}, {"id": 638, "subject": "Anatomy", "difficulty": "Easy", "question": "The patellar reflex tests which spinal cord level?", "options": [{"key": "A", "text": "L1-L2"}, {"key": "B", "text": "L2-L3"}, {"key": "C", "text": "L3-L4"}, {"key": "D", "text": "L4-L5"}], "correct": "C", "explanation": "The patellar (knee jerk) reflex tests the L3-L4 spinal cord levels via the femoral nerve."}, {"id": 639, "subject": "Anatomy", "difficulty": "Hard", "question": "During closed kinetic chain squat, quadriceps work is greatest at:", "options": [{"key": "A", "text": "Full extension"}, {"key": "B", "text": "0-30 degrees flexion"}, {"key": "C", "text": "60-90 degrees flexion"}, {"key": "D", "text": "Beyond 90 degrees"}], "correct": "C", "explanation": "Quadriceps work is greatest at 60-90 degrees during squat as the moment arm and compressive forces are highest."}, {"id": 640, "subject": "Anatomy", "difficulty": "Medium", "question": "Eccentric quadriceps contraction is used in treatment of:", "options": [{"key": "A", "text": "Patellar tendinopathy"}, {"key": "B", "text": "Hip bursitis"}, {"key": "C", "text": "Achilles tendinopathy"}, {"key": "D", "text": "Plantar fasciitis"}], "correct": "A", "explanation": "Eccentric quadriceps loading (e.g., decline squat) is the gold standard for patellar tendinopathy rehabilitation."}, {"id": 641, "subject": "Anatomy", "difficulty": "Medium", "question": "The femoral triangle contains the femoral nerve, artery, and vein in which order (lateral to medial)?", "options": [{"key": "A", "text": "Vein, artery, nerve"}, {"key": "B", "text": "Artery, vein, nerve"}, {"key": "C", "text": "Nerve, artery, vein"}, {"key": "D", "text": "Nerve, vein, artery"}], "correct": "C", "explanation": "From lateral to medial: Nerve, Artery, Vein - remembered by acronym NAVY (Nerve, Artery, Vein)."}, {"id": 642, "subject": "Anatomy", "difficulty": "Medium", "question": "Rectus femoris tightness test is performed by:", "options": [{"key": "A", "text": "Thomas test"}, {"key": "B", "text": "Ely's test"}, {"key": "C", "text": "Ober's test"}, {"key": "D", "text": "FABER test"}], "correct": "B", "explanation": "Ely's test (prone knee flexion test) assesses rectus femoris tightness; positive if hip rises from table."}, {"id": 643, "subject": "Anatomy", "difficulty": "Hard", "question": "Which quadriceps exercise provides maximum VMO activation with minimal patellofemoral stress?", "options": [{"key": "A", "text": "Full arc extension"}, {"key": "B", "text": "Terminal knee extension"}, {"key": "C", "text": "Deep squat"}, {"key": "D", "text": "Leg press at 90 degrees"}], "correct": "B", "explanation": "Terminal knee extension (0-30 degrees) maximally activates VMO with least patellofemoral joint compression."}, {"id": 644, "subject": "Anatomy", "difficulty": "Hard", "question": "Quadriceps cross-sectional area is largest in which muscle?", "options": [{"key": "A", "text": "Rectus femoris"}, {"key": "B", "text": "Vastus medialis"}, {"key": "C", "text": "Vastus lateralis"}, {"key": "D", "text": "Vastus intermedius"}], "correct": "C", "explanation": "Vastus lateralis has the largest cross-sectional area among quadriceps muscles and contributes most to total quadriceps force."}, {"id": 645, "subject": "Anatomy", "difficulty": "Easy", "question": "Which muscles form the hamstring group?", "options": [{"key": "A", "text": "Rectus femoris, biceps femoris, semimembranosus"}, {"key": "B", "text": "Biceps femoris, semitendinosus, semimembranosus"}, {"key": "C", "text": "Adductor magnus, biceps femoris, gracilis"}, {"key": "D", "text": "Biceps femoris, semitendinosus, popliteus"}], "correct": "B", "explanation": "Hamstrings consist of biceps femoris (long and short head), semitendinosus, and semimembranosus."}, {"id": 646, "subject": "Anatomy", "difficulty": "Medium", "question": "Most hamstring injuries occur at:", "options": [{"key": "A", "text": "Proximal musculotendinous junction"}, {"key": "B", "text": "Mid-belly"}, {"key": "C", "text": "Distal insertion"}, {"key": "D", "text": "Ischial tuberosity"}], "correct": "A", "explanation": "Approximately 70% of hamstring strains occur at the proximal myotendinous junction, especially in biceps femoris long head."}, {"id": 647, "subject": "Anatomy", "difficulty": "Easy", "question": "The common origin of hamstrings is:", "options": [{"key": "A", "text": "Femoral shaft"}, {"key": "B", "text": "Ischial tuberosity"}, {"key": "C", "text": "Greater trochanter"}, {"key": "D", "text": "AIIS"}], "correct": "B", "explanation": "All three hamstring muscles (except biceps short head) originate from the ischial tuberosity."}, {"id": 648, "subject": "Anatomy", "difficulty": "Hard", "question": "Biceps femoris short head is innervated by:", "options": [{"key": "A", "text": "Tibial nerve"}, {"key": "B", "text": "Common peroneal nerve"}, {"key": "C", "text": "Femoral nerve"}, {"key": "D", "text": "Obturator nerve"}], "correct": "B", "explanation": "Biceps femoris short head is uniquely innervated by common peroneal nerve (L5, S1, S2), unlike other hamstrings."}, {"id": 649, "subject": "Anatomy", "difficulty": "Medium", "question": "Semimembranosus inserts into:", "options": [{"key": "A", "text": "Head of fibula"}, {"key": "B", "text": "Medial condyle of tibia"}, {"key": "C", "text": "Lateral condyle of tibia"}, {"key": "D", "text": "Tibial tuberosity"}], "correct": "B", "explanation": "Semimembranosus inserts primarily into the medial condyle of tibia via its direct arm."}, {"id": 650, "subject": "Anatomy", "difficulty": "Medium", "question": "The 'pes anserinus' is formed by:", "options": [{"key": "A", "text": "Sartorius, gracilis, semitendinosus"}, {"key": "B", "text": "Sartorius, semimembranosus, biceps femoris"}, {"key": "C", "text": "Gracilis, biceps femoris, semitendinosus"}, {"key": "D", "text": "Rectus femoris, sartorius, gracilis"}], "correct": "A", "explanation": "Pes anserinus ('goose foot') is the conjoined insertion of sartorius, gracilis, and semitendinosus on the medial tibia."}, {"id": 651, "subject": "Anatomy", "difficulty": "Hard", "question": "During running, hamstrings are most active in:", "options": [{"key": "A", "text": "Swing phase deceleration and early stance"}, {"key": "B", "text": "Mid-swing only"}, {"key": "C", "text": "Push-off phase"}, {"key": "D", "text": "Loading response"}], "correct": "A", "explanation": "Hamstrings decelerate the swinging leg (eccentric) and then produce hip extension force in early stance."}, {"id": 652, "subject": "Anatomy", "difficulty": "Medium", "question": "The Nordic hamstring curl primarily trains:", "options": [{"key": "A", "text": "Concentric hamstring contraction"}, {"key": "B", "text": "Eccentric hamstring contraction"}, {"key": "C", "text": "Isometric hamstring contraction"}, {"key": "D", "text": "Hip extensor strength"}], "correct": "B", "explanation": "Nordic hamstring curl is an eccentric exercise where hamstrings control knee extension under load, preventing injury."}, {"id": 653, "subject": "Anatomy", "difficulty": "Easy", "question": "Semitendinosus tendon is commonly harvested for:", "options": [{"key": "A", "text": "ACL reconstruction"}, {"key": "B", "text": "PCL reconstruction"}, {"key": "C", "text": "Patellar tendon repair"}, {"key": "D", "text": "Meniscal repair"}], "correct": "A", "explanation": "Semitendinosus (and gracilis) tendons are commonly used as autograft for ACL reconstruction."}, {"id": 654, "subject": "Anatomy", "difficulty": "Easy", "question": "Which test assesses hamstring flexibility?", "options": [{"key": "A", "text": "Thomas test"}, {"key": "B", "text": "Straight leg raise test"}, {"key": "C", "text": "Trendelenburg test"}, {"key": "D", "text": "Ober's test"}], "correct": "B", "explanation": "Straight leg raise (SLR) with passive hip flexion (knee extended) assesses hamstring flexibility; normal >80 degrees."}, {"id": 655, "subject": "Anatomy", "difficulty": "Easy", "question": "Hamstrings function as knee flexors and:", "options": [{"key": "A", "text": "Hip flexors"}, {"key": "B", "text": "Hip extensors"}, {"key": "C", "text": "Hip abductors"}, {"key": "D", "text": "Hip adductors"}], "correct": "B", "explanation": "Hamstrings (except biceps short head) cross both joints, acting as knee flexors and hip extensors."}, {"id": 656, "subject": "Anatomy", "difficulty": "Medium", "question": "Proximal hamstring tendinopathy pain is aggravated by:", "options": [{"key": "A", "text": "Standing"}, {"key": "B", "text": "Walking flat"}, {"key": "C", "text": "Sitting on hard surfaces and hill running"}, {"key": "D", "text": "Lying down"}], "correct": "C", "explanation": "Proximal hamstring tendinopathy causes pain with sitting (compressive load) and uphill running (high stretch loads)."}, {"id": 657, "subject": "Anatomy", "difficulty": "Hard", "question": "The 'H' ratio (hamstring:quadriceps) for injury prevention should be:", "options": [{"key": "A", "text": "Less than 0.5"}, {"key": "B", "text": "0.6-0.8"}, {"key": "C", "text": "Greater than 1.0"}, {"key": "D", "text": "Exactly 1.0"}], "correct": "B", "explanation": "Hamstring:Quadriceps ratio of 0.6-0.8 is considered safe; ratio below 0.6 increases hamstring injury risk."}, {"id": 658, "subject": "Anatomy", "difficulty": "Medium", "question": "Biceps femoris long head is innervated by:", "options": [{"key": "A", "text": "Common peroneal nerve"}, {"key": "B", "text": "Tibial nerve"}, {"key": "C", "text": "Femoral nerve"}, {"key": "D", "text": "Saphenous nerve"}], "correct": "B", "explanation": "Biceps femoris long head is innervated by the tibial division of sciatic nerve (L5, S1, S2)."}, {"id": 659, "subject": "Anatomy", "difficulty": "Hard", "question": "Semimembranosus has how many insertional arms?", "options": [{"key": "A", "text": "One"}, {"key": "B", "text": "Two"}, {"key": "C", "text": "Three"}, {"key": "D", "text": "Five"}], "correct": "D", "explanation": "Semimembranosus has five insertional arms: direct, anterior, oblique popliteal ligament, popliteal fascia, and medial meniscus."}, {"id": 660, "subject": "Anatomy", "difficulty": "Medium", "question": "Which hamstring is most commonly injured in sprinting?", "options": [{"key": "A", "text": "Semitendinosus"}, {"key": "B", "text": "Semimembranosus"}, {"key": "C", "text": "Biceps femoris long head"}, {"key": "D", "text": "Biceps femoris short head"}], "correct": "C", "explanation": "Biceps femoris long head is the most commonly injured hamstring in sprinting due to its biarticular nature."}, {"id": 661, "subject": "Anatomy", "difficulty": "Hard", "question": "During seated knee flexion, which hamstrings are at mechanical advantage?", "options": [{"key": "A", "text": "Biceps femoris"}, {"key": "B", "text": "Semitendinosus"}, {"key": "C", "text": "Semimembranosus"}, {"key": "D", "text": "All equally"}], "correct": "A", "explanation": "Biceps femoris has a greater moment arm for knee flexion when hip is flexed (seated position)."}, {"id": 662, "subject": "Anatomy", "difficulty": "Easy", "question": "Grade II hamstring strain involves:", "options": [{"key": "A", "text": "Less than 5% fiber tear"}, {"key": "B", "text": "Partial muscle tear (5-90% fibers)"}, {"key": "C", "text": "Complete muscle rupture"}, {"key": "D", "text": "Bone avulsion"}], "correct": "B", "explanation": "Grade II strain involves partial tear (5-90% of fibers), causing significant pain and functional limitation."}, {"id": 663, "subject": "Anatomy", "difficulty": "Medium", "question": "Return to sport after hamstring grade II strain typically takes:", "options": [{"key": "A", "text": "3-5 days"}, {"key": "B", "text": "1-2 weeks"}, {"key": "C", "text": "3-6 weeks"}, {"key": "D", "text": "3-6 months"}], "correct": "C", "explanation": "Grade II hamstring strain typically requires 3-6 weeks for rehabilitation before safe return to sport."}, {"id": 664, "subject": "Anatomy", "difficulty": "Medium", "question": "The posterior thigh cutaneous nerve provides sensation to:", "options": [{"key": "A", "text": "Anterior thigh"}, {"key": "B", "text": "Posterior thigh and upper leg"}, {"key": "C", "text": "Medial knee"}, {"key": "D", "text": "Lateral leg"}], "correct": "B", "explanation": "Posterior femoral cutaneous nerve (S1-S3) provides sensory innervation to posterior thigh and proximal leg."}, {"id": 665, "subject": "Anatomy", "difficulty": "Medium", "question": "Hamstring tightness affects lumbar spine by:", "options": [{"key": "A", "text": "Increasing lumbar lordosis"}, {"key": "B", "text": "Flattening lumbar lordosis in standing"}, {"key": "C", "text": "No effect on lumbar spine"}, {"key": "D", "text": "Increasing thoracic kyphosis"}], "correct": "B", "explanation": "Tight hamstrings posteriorly tilt the pelvis, which flattens the lumbar lordosis in standing posture."}, {"id": 666, "subject": "Anatomy", "difficulty": "Hard", "question": "The optimal length for hamstring strengthening on isokinetic machine is:", "options": [{"key": "A", "text": "At shortened position"}, {"key": "B", "text": "At lengthened position"}, {"key": "C", "text": "At neutral position"}, {"key": "D", "text": "Position doesn't matter"}], "correct": "B", "explanation": "Hamstrings are stronger eccentrically and training at longer muscle lengths improves eccentric capacity and reduces injury risk."}, {"id": 667, "subject": "Anatomy", "difficulty": "Medium", "question": "Avulsion fracture of ischial tuberosity is common in:", "options": [{"key": "A", "text": "Elderly patients"}, {"key": "B", "text": "Young athletes during sudden sprinting"}, {"key": "C", "text": "Osteoporotic women"}, {"key": "D", "text": "Distance runners"}], "correct": "B", "explanation": "Ischial tuberosity avulsion occurs in young athletes (open physis) during sudden hamstring contraction in sprinting."}, {"id": 668, "subject": "Anatomy", "difficulty": "Hard", "question": "Sciatic nerve relationship to hamstrings:", "options": [{"key": "A", "text": "Lies anterior to hamstrings"}, {"key": "B", "text": "Lies between hamstrings"}, {"key": "C", "text": "Lies posterior to hamstrings"}, {"key": "D", "text": "Not related to hamstrings"}], "correct": "B", "explanation": "Sciatic nerve courses between the long and short heads of biceps femoris in the posterior thigh."}, {"id": 669, "subject": "Anatomy", "difficulty": "Hard", "question": "In ACL deficient knee, hamstrings compensate by:", "options": [{"key": "A", "text": "Reducing their activity"}, {"key": "B", "text": "Increasing their co-contraction to provide dynamic stability"}, {"key": "C", "text": "Relaxing during loading"}, {"key": "D", "text": "Shifting to concentric work only"}], "correct": "B", "explanation": "In ACL deficiency, hamstrings increase their co-contraction to provide dynamic posterior tibial restraint and joint stability."}, {"id": 670, "subject": "Anatomy", "difficulty": "Easy", "question": "The gluteus maximus is the primary:", "options": [{"key": "A", "text": "Hip abductor"}, {"key": "B", "text": "Hip extensor"}, {"key": "C", "text": "Hip internal rotator"}, {"key": "D", "text": "Hip flexor"}], "correct": "B", "explanation": "Gluteus maximus is the largest and most powerful hip extensor, also performing external rotation."}, {"id": 671, "subject": "Anatomy", "difficulty": "Easy", "question": "Gluteus maximus innervation is from:", "options": [{"key": "A", "text": "Superior gluteal nerve"}, {"key": "B", "text": "Inferior gluteal nerve"}, {"key": "C", "text": "Sciatic nerve"}, {"key": "D", "text": "Pudendal nerve"}], "correct": "B", "explanation": "Gluteus maximus is innervated by the inferior gluteal nerve (L5, S1, S2)."}, {"id": 672, "subject": "Anatomy", "difficulty": "Easy", "question": "Trendelenburg sign indicates weakness of:", "options": [{"key": "A", "text": "Gluteus maximus"}, {"key": "B", "text": "Gluteus medius and minimus"}, {"key": "C", "text": "Piriformis"}, {"key": "D", "text": "Obturator internus"}], "correct": "B", "explanation": "Positive Trendelenburg sign indicates weakness of gluteus medius/minimus on the weight-bearing side, causing pelvic drop."}, {"id": 673, "subject": "Anatomy", "difficulty": "Easy", "question": "Gluteus medius is primarily a:", "options": [{"key": "A", "text": "Hip extensor"}, {"key": "B", "text": "Hip abductor and internal rotator"}, {"key": "C", "text": "Hip flexor"}, {"key": "D", "text": "Hip adductor"}], "correct": "B", "explanation": "Gluteus medius is the primary hip abductor; its anterior fibers also internally rotate the hip."}, {"id": 674, "subject": "Anatomy", "difficulty": "Medium", "question": "The IT band (iliotibial band) is the distal extension of:", "options": [{"key": "A", "text": "Gluteus maximus only"}, {"key": "B", "text": "Tensor fasciae latae and gluteus maximus"}, {"key": "C", "text": "Gluteus medius"}, {"key": "D", "text": "Rectus femoris"}], "correct": "B", "explanation": "The IT band receives contributions from both TFL and gluteus maximus as it courses down the lateral thigh."}, {"id": 675, "subject": "Anatomy", "difficulty": "Medium", "question": "Piriformis syndrome mimics:", "options": [{"key": "A", "text": "Femoral nerve compression"}, {"key": "B", "text": "Sciatic nerve compression (sciatica)"}, {"key": "C", "text": "Obturator nerve compression"}, {"key": "D", "text": "Lateral cutaneous nerve compression"}], "correct": "B", "explanation": "Piriformis muscle can compress the sciatic nerve (which passes through or beneath it), mimicking true sciatica."}, {"id": 676, "subject": "Anatomy", "difficulty": "Medium", "question": "The superior gluteal nerve innervates:", "options": [{"key": "A", "text": "Gluteus maximus"}, {"key": "B", "text": "Gluteus medius, minimus, and TFL"}, {"key": "C", "text": "Piriformis"}, {"key": "D", "text": "Obturator internus"}], "correct": "B", "explanation": "Superior gluteal nerve (L4, L5, S1) innervates gluteus medius, gluteus minimus, and tensor fasciae latae."}, {"id": 677, "subject": "Anatomy", "difficulty": "Medium", "question": "Gluteus maximus inserts primarily into:", "options": [{"key": "A", "text": "Greater trochanter"}, {"key": "B", "text": "Iliotibial band and gluteal tuberosity of femur"}, {"key": "C", "text": "Lesser trochanter"}, {"key": "D", "text": "Femoral neck"}], "correct": "B", "explanation": "Approximately 75% of gluteus maximus inserts into the IT band and 25% into the gluteal tuberosity of the femur."}, {"id": 678, "subject": "Anatomy", "difficulty": "Hard", "question": "The 'deep six' external rotators of the hip include all EXCEPT:", "options": [{"key": "A", "text": "Piriformis"}, {"key": "B", "text": "Gluteus medius"}, {"key": "C", "text": "Obturator internus"}, {"key": "D", "text": "Quadratus femoris"}], "correct": "B", "explanation": "The six deep external rotators are: piriformis, obturator internus/externus, superior/inferior gemellus, and quadratus femoris."}, {"id": 679, "subject": "Anatomy", "difficulty": "Easy", "question": "Gluteus minimus primary function:", "options": [{"key": "A", "text": "Hip extension"}, {"key": "B", "text": "Hip abduction and internal rotation"}, {"key": "C", "text": "Hip external rotation"}, {"key": "D", "text": "Knee flexion"}], "correct": "B", "explanation": "Gluteus minimus assists gluteus medius in hip abduction; its anterior fibers also medially rotate the hip."}, {"id": 680, "subject": "Anatomy", "difficulty": "Medium", "question": "During single-leg stance, gluteus medius must produce torque to prevent:", "options": [{"key": "A", "text": "Hip extension"}, {"key": "B", "text": "Pelvic drop on the contralateral side"}, {"key": "C", "text": "Knee extension"}, {"key": "D", "text": "Ankle pronation"}], "correct": "B", "explanation": "Gluteus medius contracts isometrically/eccentrically to prevent contralateral pelvic drop during single-leg stance."}, {"id": 681, "subject": "Anatomy", "difficulty": "Medium", "question": "Greater trochanteric pain syndrome (bursitis) is associated with:", "options": [{"key": "A", "text": "Gluteus medius/minimus tendinopathy"}, {"key": "B", "text": "Hamstring tendinopathy"}, {"key": "C", "text": "Hip flexor tendinopathy"}, {"key": "D", "text": "Piriformis syndrome"}], "correct": "A", "explanation": "Greater trochanteric pain is now understood to primarily involve gluteus medius/minimus tendinopathy rather than pure bursitis."}, {"id": 682, "subject": "Anatomy", "difficulty": "Easy", "question": "Clam shell exercise primarily strengthens:", "options": [{"key": "A", "text": "Gluteus maximus"}, {"key": "B", "text": "Gluteus medius in external rotation"}, {"key": "C", "text": "Hip flexors"}, {"key": "D", "text": "Adductors"}], "correct": "B", "explanation": "Clamshell exercise targets gluteus medius in external rotation while maintaining hip and knee flexion position."}, {"id": 683, "subject": "Anatomy", "difficulty": "Medium", "question": "The sciatic nerve exits the pelvis through:", "options": [{"key": "A", "text": "Greater sciatic foramen below piriformis"}, {"key": "B", "text": "Lesser sciatic foramen"}, {"key": "C", "text": "Obturator foramen"}, {"key": "D", "text": "Ischial spine"}], "correct": "A", "explanation": "Sciatic nerve typically exits below piriformis through the greater sciatic foramen (infrapiriform portion)."}, {"id": 684, "subject": "Anatomy", "difficulty": "Hard", "question": "Weak gluteus maximus affects gait by producing:", "options": [{"key": "A", "text": "Trendelenburg gait"}, {"key": "B", "text": "Gluteus maximus lurch (backward trunk lean)"}, {"key": "C", "text": "Steppage gait"}, {"key": "D", "text": "Antalgic gait"}], "correct": "B", "explanation": "Weak gluteus maximus causes the patient to lean backward over the stance leg to reduce hip extension demand."}, {"id": 685, "subject": "Anatomy", "difficulty": "Easy", "question": "The FABER test (Patrick's test) assesses:", "options": [{"key": "A", "text": "Hamstring tightness"}, {"key": "B", "text": "Hip joint pathology and SI joint"}, {"key": "C", "text": "Quadriceps tightness"}, {"key": "D", "text": "IT band tightness"}], "correct": "B", "explanation": "FABER (Flexion, ABduction, External Rotation) tests hip joint integrity and sacroiliac joint dysfunction."}, {"id": 686, "subject": "Anatomy", "difficulty": "Medium", "question": "Gluteus medius weakness leads to which lower extremity alignment problem?", "options": [{"key": "A", "text": "Genu varum"}, {"key": "B", "text": "Increased hip adduction and knee valgus (dynamic)"}, {"key": "C", "text": "Genu recurvatum"}, {"key": "D", "text": "Ankle pronation alone"}], "correct": "B", "explanation": "Weak gluteus medius allows hip adduction and internal rotation, creating dynamic knee valgus (medial knee collapse)."}, {"id": 687, "subject": "Anatomy", "difficulty": "Hard", "question": "The piriformis muscle originates from:", "options": [{"key": "A", "text": "Posterior ilium"}, {"key": "B", "text": "Anterior sacrum"}, {"key": "C", "text": "Ischial tuberosity"}, {"key": "D", "text": "Pubic bone"}], "correct": "B", "explanation": "Piriformis originates from the anterior surface of sacrum (S2-S4) and inserts into greater trochanter."}, {"id": 688, "subject": "Anatomy", "difficulty": "Easy", "question": "Hip abduction strength testing MMT grade 3 means:", "options": [{"key": "A", "text": "Full ROM against gravity with maximum resistance"}, {"key": "B", "text": "Full ROM against gravity with no resistance"}, {"key": "C", "text": "Full ROM only with gravity eliminated"}, {"key": "D", "text": "Partial ROM against gravity"}], "correct": "B", "explanation": "MMT Grade 3 = full ROM against gravity with no additional resistance applied."}, {"id": 689, "subject": "Anatomy", "difficulty": "Medium", "question": "The tensor fasciae latae (TFL) is a:", "options": [{"key": "A", "text": "Pure hip abductor"}, {"key": "B", "text": "Hip flexor, internal rotator, and abductor"}, {"key": "C", "text": "Hip extensor"}, {"key": "D", "text": "Knee extensor"}], "correct": "B", "explanation": "TFL performs hip flexion, abduction, and internal rotation; it also provides IT band tension for knee stabilization."}, {"id": 690, "subject": "Anatomy", "difficulty": "Medium", "question": "Iliotibial band syndrome (ITBS) is caused by:", "options": [{"key": "A", "text": "IT band friction over lateral femoral epicondyle"}, {"key": "B", "text": "Medial knee ligament injury"}, {"key": "C", "text": "Patellar maltracking"}, {"key": "D", "text": "Hamstring tightness"}], "correct": "A", "explanation": "ITBS results from repetitive friction of the tight IT band over the lateral femoral epicondyle during knee flexion-extension."}, {"id": 691, "subject": "Anatomy", "difficulty": "Medium", "question": "Gluteal amnesia refers to:", "options": [{"key": "A", "text": "Memory loss due to gluteal injury"}, {"key": "B", "text": "Inhibition of gluteal muscles due to prolonged sitting"}, {"key": "C", "text": "Gluteal muscle atrophy from nerve damage"}, {"key": "D", "text": "Hip pain affecting memory"}], "correct": "B", "explanation": "Prolonged sitting causes reciprocal inhibition of gluteal muscles by hip flexors, leading to reduced gluteal activation."}, {"id": 692, "subject": "Anatomy", "difficulty": "Hard", "question": "The obturator externus inserts into:", "options": [{"key": "A", "text": "Greater trochanter"}, {"key": "B", "text": "Trochanteric fossa"}, {"key": "C", "text": "Lesser trochanter"}, {"key": "D", "text": "Iliotibial band"}], "correct": "B", "explanation": "Obturator externus inserts into the trochanteric fossa on the medial surface of the greater trochanter."}, {"id": 693, "subject": "Anatomy", "difficulty": "Hard", "question": "Which deep gluteal muscle passes through the lesser sciatic foramen?", "options": [{"key": "A", "text": "Piriformis"}, {"key": "B", "text": "Obturator internus"}, {"key": "C", "text": "Gemellus superior"}, {"key": "D", "text": "Quadratus femoris"}], "correct": "B", "explanation": "Obturator internus leaves the pelvis through the lesser sciatic foramen, hooking around the ischium."}, {"id": 694, "subject": "Anatomy", "difficulty": "Medium", "question": "For runners with gluteal weakness, which exercise best activates gluteus medius?", "options": [{"key": "A", "text": "Prone hip extension"}, {"key": "B", "text": "Side-lying hip abduction"}, {"key": "C", "text": "Hip thrust"}, {"key": "D", "text": "Deadlift"}], "correct": "B", "explanation": "Side-lying hip abduction isolates gluteus medius effectively; single-leg bridges and step-ups also provide high activation."}, {"id": 695, "subject": "Anatomy", "difficulty": "Easy", "question": "The gastrocnemius has how many heads?", "options": [{"key": "A", "text": "One"}, {"key": "B", "text": "Two"}, {"key": "C", "text": "Three"}, {"key": "D", "text": "Four"}], "correct": "B", "explanation": "Gastrocnemius has two heads: medial and lateral, originating from respective femoral condyles."}, {"id": 696, "subject": "Anatomy", "difficulty": "Easy", "question": "The Achilles tendon is the common tendon of:", "options": [{"key": "A", "text": "Gastrocnemius only"}, {"key": "B", "text": "Soleus only"}, {"key": "C", "text": "Gastrocnemius and soleus"}, {"key": "D", "text": "Gastrocnemius, soleus, and plantaris"}], "correct": "C", "explanation": "Achilles tendon is formed by the combined tendons of gastrocnemius and soleus (triceps surae)."}, {"id": 697, "subject": "Anatomy", "difficulty": "Easy", "question": "Gastrocnemius is innervated by:", "options": [{"key": "A", "text": "Common peroneal nerve"}, {"key": "B", "text": "Tibial nerve"}, {"key": "C", "text": "Superficial peroneal nerve"}, {"key": "D", "text": "Sural nerve"}], "correct": "B", "explanation": "Gastrocnemius is innervated by the tibial nerve (S1, S2)."}, {"id": 698, "subject": "Anatomy", "difficulty": "Medium", "question": "Which calf muscle is more important for walking at slow speeds?", "options": [{"key": "A", "text": "Gastrocnemius"}, {"key": "B", "text": "Soleus"}, {"key": "C", "text": "Plantaris"}, {"key": "D", "text": "Popliteus"}], "correct": "B", "explanation": "Soleus is more active during slow walking; gastrocnemius is more active during faster walking and running."}, {"id": 699, "subject": "Anatomy", "difficulty": "Medium", "question": "Soleus originates from:", "options": [{"key": "A", "text": "Posterior femoral condyles"}, {"key": "B", "text": "Posterior fibular head and soleal line of tibia"}, {"key": "C", "text": "Calcaneus"}, {"key": "D", "text": "Posterior tibia only"}], "correct": "B", "explanation": "Soleus originates from the posterior fibular head/neck, soleal line and medial border of tibia."}, {"id": 700, "subject": "Anatomy", "difficulty": "Easy", "question": "Thompson's test assesses integrity of:", "options": [{"key": "A", "text": "Tibialis anterior"}, {"key": "B", "text": "Achilles tendon"}, {"key": "C", "text": "Peroneal tendons"}, {"key": "D", "text": "Plantar fascia"}], "correct": "B", "explanation": "Thompson test (calf squeeze test) diagnoses Achilles tendon rupture; absence of plantar flexion = positive."}, {"id": 701, "subject": "Anatomy", "difficulty": "Medium", "question": "The soleus is primarily composed of:", "options": [{"key": "A", "text": "Type I (slow-twitch) fibers"}, {"key": "B", "text": "Type II (fast-twitch) fibers"}, {"key": "C", "text": "Equal mix"}, {"key": "D", "text": "Type IIx fibers predominantly"}], "correct": "A", "explanation": "Soleus contains approximately 70-80% Type I slow-twitch fibers, making it ideal for sustained anti-gravity function."}, {"id": 702, "subject": "Anatomy", "difficulty": "Easy", "question": "Gastrocnemius acts on which joints?", "options": [{"key": "A", "text": "Ankle only"}, {"key": "B", "text": "Knee and ankle"}, {"key": "C", "text": "Hip and ankle"}, {"key": "D", "text": "Hip, knee, and ankle"}], "correct": "B", "explanation": "Gastrocnemius crosses both knee and ankle joints, acting as knee flexor and ankle plantarflexor."}, {"id": 703, "subject": "Anatomy", "difficulty": "Medium", "question": "The triceps surae group includes:", "options": [{"key": "A", "text": "Gastrocnemius and soleus"}, {"key": "B", "text": "Gastrocnemius, soleus, and plantaris"}, {"key": "C", "text": "All posterior compartment muscles"}, {"key": "D", "text": "Gastrocnemius and popliteus"}], "correct": "B", "explanation": "Triceps surae consists of gastrocnemius (2 heads) and soleus, sometimes including plantaris as a fourth head."}, {"id": 704, "subject": "Anatomy", "difficulty": "Medium", "question": "Eccentric calf training (heel drop exercise) on a step is used for:", "options": [{"key": "A", "text": "Plantar fasciitis"}, {"key": "B", "text": "Achilles tendinopathy"}, {"key": "C", "text": "Posterior tibialis tendinopathy"}, {"key": "D", "text": "Peroneal tendinopathy"}], "correct": "B", "explanation": "Alfredson protocol of eccentric heel drops (straight and bent knee) is first-line treatment for Achilles tendinopathy."}, {"id": 705, "subject": "Anatomy", "difficulty": "Medium", "question": "The sural nerve provides sensation to:", "options": [{"key": "A", "text": "Dorsum of foot"}, {"key": "B", "text": "Lateral foot and little toe"}, {"key": "C", "text": "Medial sole of foot"}, {"key": "D", "text": "Plantar surface"}], "correct": "B", "explanation": "Sural nerve is a sensory nerve providing sensation to the lateral foot and fifth toe."}, {"id": 706, "subject": "Anatomy", "difficulty": "Easy", "question": "Calf raises with straight knee primarily targets:", "options": [{"key": "A", "text": "Soleus"}, {"key": "B", "text": "Gastrocnemius"}, {"key": "C", "text": "Tibialis posterior"}, {"key": "D", "text": "Flexor digitorum longus"}], "correct": "B", "explanation": "Straight knee calf raises (plantarflexion with extended knee) primarily target gastrocnemius as it crosses the knee."}, {"id": 707, "subject": "Anatomy", "difficulty": "Easy", "question": "Calf raises with bent knee (90 degrees) primarily targets:", "options": [{"key": "A", "text": "Gastrocnemius"}, {"key": "B", "text": "Soleus"}, {"key": "C", "text": "Both equally"}, {"key": "D", "text": "Plantaris"}], "correct": "B", "explanation": "Bent-knee calf raises reduce gastrocnemius contribution (it's slackened), isolating soleus."}, {"id": 708, "subject": "Anatomy", "difficulty": "Easy", "question": "The Achilles tendon insertion is on:", "options": [{"key": "A", "text": "Navicular bone"}, {"key": "B", "text": "Calcaneal tuberosity (posterior surface)"}, {"key": "C", "text": "Cuboid"}, {"key": "D", "text": "Base of fifth metatarsal"}], "correct": "B", "explanation": "Achilles tendon inserts into the posterior surface of the calcaneus (calcaneal tuberosity)."}, {"id": 709, "subject": "Anatomy", "difficulty": "Easy", "question": "Which condition presents with medial heel pain worse in the morning?", "options": [{"key": "A", "text": "Achilles tendinopathy"}, {"key": "B", "text": "Plantar fasciitis"}, {"key": "C", "text": "Tarsal tunnel syndrome"}, {"key": "D", "text": "Posterior tibialis tendinopathy"}], "correct": "B", "explanation": "Plantar fasciitis classically presents with medial heel pain that is worst with first steps in the morning."}, {"id": 710, "subject": "Anatomy", "difficulty": "Medium", "question": "Ankle plantarflexion range of motion is normally:", "options": [{"key": "A", "text": "0-30 degrees"}, {"key": "B", "text": "0-50 degrees"}, {"key": "C", "text": "0-20 degrees"}, {"key": "D", "text": "0-70 degrees"}], "correct": "B", "explanation": "Normal ankle plantarflexion is 0-50 degrees (average 45 degrees) measured from neutral position."}, {"id": 711, "subject": "Anatomy", "difficulty": "Hard", "question": "The zone of poor vascularity in Achilles tendon is located:", "options": [{"key": "A", "text": "At the calcaneal insertion"}, {"key": "B", "text": "2-6 cm proximal to insertion"}, {"key": "C", "text": "At the musculotendinous junction"}, {"key": "D", "text": "Throughout the tendon"}], "correct": "B", "explanation": "The critical zone of relative avascularity (watershed zone) is 2-6 cm proximal to the Achilles insertion, where most ruptures occur."}, {"id": 712, "subject": "Anatomy", "difficulty": "Hard", "question": "Calf muscle pump failure leads to:", "options": [{"key": "A", "text": "Arterial insufficiency"}, {"key": "B", "text": "Venous insufficiency and DVT risk"}, {"key": "C", "text": "Lymphedema only"}, {"key": "D", "text": "Nerve compression"}], "correct": "B", "explanation": "The calf muscle pump (soleus venous sinuses) propels blood upward; pump failure leads to venous stasis, edema, and DVT risk."}, {"id": 713, "subject": "Anatomy", "difficulty": "Easy", "question": "Which spinal level is tested by Achilles tendon reflex?", "options": [{"key": "A", "text": "L3-L4"}, {"key": "B", "text": "L4-L5"}, {"key": "C", "text": "S1-S2"}, {"key": "D", "text": "S3-S4"}], "correct": "C", "explanation": "Achilles reflex (ankle jerk) tests S1-S2 spinal levels via the tibial nerve."}, {"id": 714, "subject": "Anatomy", "difficulty": "Hard", "question": "Plantaris muscle rupture mimics:", "options": [{"key": "A", "text": "Achilles tendon rupture"}, {"key": "B", "text": "Medial gastrocnemius tear (tennis leg)"}, {"key": "C", "text": "Soleus injury"}, {"key": "D", "text": "DVT"}], "correct": "B", "explanation": "Plantaris rupture presents similar to medial gastrocnemius tear (tennis leg) with sudden posterior calf pain."}, {"id": 715, "subject": "Anatomy", "difficulty": "Medium", "question": "During push-off in gait, which muscle produces the most power?", "options": [{"key": "A", "text": "Tibialis anterior"}, {"key": "B", "text": "Soleus and gastrocnemius"}, {"key": "C", "text": "Quadriceps"}, {"key": "D", "text": "Hip extensors"}], "correct": "B", "explanation": "Ankle plantarflexors (gastrocnemius and soleus) generate the most power during push-off phase of gait."}, {"id": 716, "subject": "Anatomy", "difficulty": "Hard", "question": "Compartment syndrome of the posterior deep compartment affects:", "options": [{"key": "A", "text": "Tibialis anterior"}, {"key": "B", "text": "Tibialis posterior, FDL, FHL"}, {"key": "C", "text": "Gastrocnemius"}, {"key": "D", "text": "Peroneals"}], "correct": "B", "explanation": "Deep posterior compartment contains tibialis posterior, flexor digitorum longus, and flexor hallucis longus."}, {"id": 717, "subject": "Anatomy", "difficulty": "Hard", "question": "The speed of Achilles tendon vibration sensation is a test for:", "options": [{"key": "A", "text": "Tibial nerve function"}, {"key": "B", "text": "Peripheral vascular disease"}, {"key": "C", "text": "Ankle instability"}, {"key": "D", "text": "Tendon pathology"}], "correct": "A", "explanation": "Tuning fork vibration testing over the Achilles tendon area assesses large fiber sensory function and S1 dermatome."}, {"id": 718, "subject": "Anatomy", "difficulty": "Medium", "question": "Single-leg heel raise test requires minimum repetitions for normal function:", "options": [{"key": "A", "text": "5-10"}, {"key": "B", "text": "15-25"}, {"key": "C", "text": "30-40"}, {"key": "D", "text": "5"}], "correct": "B", "explanation": "Normal single-leg heel raise capacity is approximately 15-25 repetitions; less than 15 suggests calf weakness."}, {"id": 719, "subject": "Anatomy", "difficulty": "Medium", "question": "Medial gastrocnemius strain (tennis leg) most commonly occurs at:", "options": [{"key": "A", "text": "Calcaneal insertion"}, {"key": "B", "text": "Proximal musculotendinous junction of medial gastrocnemius"}, {"key": "C", "text": "Mid-belly"}, {"key": "D", "text": "Distal musculotendinous junction"}], "correct": "B", "explanation": "Tennis leg (medial gastrocnemius strain) typically occurs at the proximal musculotendinous junction with sudden calf pain during activity."}, {"id": 720, "subject": "Anatomy", "difficulty": "Easy", "question": "Femoral nerve is formed from which nerve roots?", "options": [{"key": "A", "text": "L1, L2, L3"}, {"key": "B", "text": "L2, L3, L4"}, {"key": "C", "text": "L3, L4, L5"}, {"key": "D", "text": "L1, L2, L3, L4"}], "correct": "B", "explanation": "Femoral nerve arises from the posterior divisions of L2, L3, L4 nerve roots of the lumbar plexus."}, {"id": 721, "subject": "Anatomy", "difficulty": "Easy", "question": "Femoral nerve exits the pelvis through:", "options": [{"key": "A", "text": "Greater sciatic foramen"}, {"key": "B", "text": "Femoral triangle deep to inguinal ligament"}, {"key": "C", "text": "Obturator foramen"}, {"key": "D", "text": "Lesser sciatic foramen"}], "correct": "B", "explanation": "Femoral nerve passes deep to the inguinal ligament (lateral to femoral vessels) to enter the femoral triangle."}, {"id": 722, "subject": "Anatomy", "difficulty": "Easy", "question": "The longest branch of femoral nerve is:", "options": [{"key": "A", "text": "Nerve to vastus medialis"}, {"key": "B", "text": "Saphenous nerve"}, {"key": "C", "text": "Nerve to rectus femoris"}, {"key": "D", "text": "Anterior cutaneous nerve of thigh"}], "correct": "B", "explanation": "Saphenous nerve is the longest branch of femoral nerve, accompanying the great saphenous vein to the medial foot."}, {"id": 723, "subject": "Anatomy", "difficulty": "Medium", "question": "Femoral nerve supplies all EXCEPT:", "options": [{"key": "A", "text": "Quadriceps femoris"}, {"key": "B", "text": "Sartorius"}, {"key": "C", "text": "Pectineus"}, {"key": "D", "text": "Adductor longus"}], "correct": "D", "explanation": "Femoral nerve supplies quadriceps, sartorius, and pectineus. Adductor longus is supplied by obturator nerve."}, {"id": 724, "subject": "Anatomy", "difficulty": "Easy", "question": "The saphenous nerve is a branch of femoral nerve that provides sensation to:", "options": [{"key": "A", "text": "Posterior thigh"}, {"key": "B", "text": "Medial leg and foot"}, {"key": "C", "text": "Lateral leg"}, {"key": "D", "text": "Sole of foot"}], "correct": "B", "explanation": "Saphenous nerve (purely sensory) supplies medial aspect of leg, ankle, and medial side of foot."}, {"id": 725, "subject": "Anatomy", "difficulty": "Medium", "question": "Femoral nerve injury proximal to inguinal ligament causes loss of:", "options": [{"key": "A", "text": "Knee extension only"}, {"key": "B", "text": "Knee extension and hip flexion, with sensory loss over anterior thigh"}, {"key": "C", "text": "Hip extension only"}, {"key": "D", "text": "Ankle dorsiflexion"}], "correct": "B", "explanation": "Proximal femoral nerve injury causes weakness of quadriceps (knee extension) and iliacus (hip flexion), with anterior thigh sensory loss."}, {"id": 726, "subject": "Anatomy", "difficulty": "Medium", "question": "In femoral triangle, the arrangement lateral to medial is:", "options": [{"key": "A", "text": "Nerve, Artery, Vein"}, {"key": "B", "text": "Vein, Artery, Nerve"}, {"key": "C", "text": "Artery, Nerve, Vein"}, {"key": "D", "text": "Nerve, Vein, Artery"}], "correct": "A", "explanation": "Lateral to medial in femoral triangle: Nerve, Artery, Vein — remembered by NAVY (Nerve, Artery, Vein, Y-fronts/lymphatics)."}, {"id": 727, "subject": "Anatomy", "difficulty": "Hard", "question": "Femoral nerve innervates which hip flexor muscle?", "options": [{"key": "A", "text": "Psoas major"}, {"key": "B", "text": "Iliacus"}, {"key": "C", "text": "Rectus femoris only"}, {"key": "D", "text": "TFL"}], "correct": "B", "explanation": "Femoral nerve innervates iliacus; psoas major is innervated by direct branches from L1-L3 ventral rami."}, {"id": 728, "subject": "Anatomy", "difficulty": "Medium", "question": "Saphenous nerve is at risk during:", "options": [{"key": "A", "text": "Total knee replacement"}, {"key": "B", "text": "Great saphenous vein harvesting"}, {"key": "C", "text": "Ankle arthroscopy"}, {"key": "D", "text": "Hip arthroplasty"}], "correct": "B", "explanation": "Saphenous nerve runs alongside the great saphenous vein and is commonly injured during vein harvesting for CABG."}, {"id": 729, "subject": "Anatomy", "difficulty": "Easy", "question": "Loss of patellar reflex indicates femoral nerve injury at level:", "options": [{"key": "A", "text": "L2"}, {"key": "B", "text": "L3-L4"}, {"key": "C", "text": "L5"}, {"key": "D", "text": "S1"}], "correct": "B", "explanation": "Patellar reflex (knee jerk) is mediated through L3-L4 via femoral nerve; its loss indicates injury at this level."}, {"id": 730, "subject": "Anatomy", "difficulty": "Hard", "question": "Femoral nerve passes through the femoral triangle in which compartment?", "options": [{"key": "A", "text": "Within femoral sheath"}, {"key": "B", "text": "Lateral to femoral sheath"}, {"key": "C", "text": "Medial to femoral sheath"}, {"key": "D", "text": "Posterior to femoral sheath"}], "correct": "B", "explanation": "Femoral nerve lies lateral to the femoral sheath (which contains artery and vein); it is NOT within the sheath."}, {"id": 731, "subject": "Anatomy", "difficulty": "Medium", "question": "Meralgia paresthetica is caused by compression of:", "options": [{"key": "A", "text": "Femoral nerve"}, {"key": "B", "text": "Lateral femoral cutaneous nerve"}, {"key": "C", "text": "Saphenous nerve"}, {"key": "D", "text": "Obturator nerve"}], "correct": "B", "explanation": "Meralgia paresthetica is entrapment of lateral femoral cutaneous nerve (L2, L3) at the inguinal ligament, causing anterolateral thigh numbness."}, {"id": 732, "subject": "Anatomy", "difficulty": "Hard", "question": "Nerve to sartorius branches from femoral nerve:", "options": [{"key": "A", "text": "Before entering femoral triangle"}, {"key": "B", "text": "Within the femoral triangle"}, {"key": "C", "text": "After exiting femoral triangle"}, {"key": "D", "text": "In the adductor canal"}], "correct": "B", "explanation": "The nerve to sartorius arises from the femoral nerve within the femoral triangle."}, {"id": 733, "subject": "Anatomy", "difficulty": "Hard", "question": "The adductor (Hunter's) canal contains:", "options": [{"key": "A", "text": "Femoral nerve, artery, vein"}, {"key": "B", "text": "Femoral artery, vein, and saphenous nerve"}, {"key": "C", "text": "Sciatic nerve and femoral artery"}, {"key": "D", "text": "Obturator nerve and femoral vein"}], "correct": "B", "explanation": "Hunter's canal contains: femoral artery and vein, saphenous nerve, and nerve to vastus medialis."}, {"id": 734, "subject": "Anatomy", "difficulty": "Medium", "question": "Femoral nerve block is performed at:", "options": [{"key": "A", "text": "Inguinal ligament level, lateral to femoral artery"}, {"key": "B", "text": "Mid-thigh level"}, {"key": "C", "text": "Knee level"}, {"key": "D", "text": "Posterior to femoral artery"}], "correct": "A", "explanation": "Femoral nerve block is done just below the inguinal ligament, lateral to the femoral artery pulse."}, {"id": 735, "subject": "Anatomy", "difficulty": "Hard", "question": "Femoral neuropathy most commonly results from:", "options": [{"key": "A", "text": "Disc herniation at L3-L4"}, {"key": "B", "text": "Diabetes mellitus (diabetic amyotrophy)"}, {"key": "C", "text": "Trauma to posterior thigh"}, {"key": "D", "text": "Piriformis syndrome"}], "correct": "B", "explanation": "Diabetic amyotrophy (diabetic lumbosacral radiculoplexus neuropathy) is the most common cause of femoral neuropathy."}, {"id": 736, "subject": "Anatomy", "difficulty": "Medium", "question": "Which test specifically assesses femoral nerve stretch?", "options": [{"key": "A", "text": "SLR test"}, {"key": "B", "text": "Prone knee bend (femoral nerve stretch test)"}, {"key": "C", "text": "SLUMP test"}, {"key": "D", "text": "FABER test"}], "correct": "B", "explanation": "Prone knee bend test stretches the femoral nerve; pain in anterior thigh indicates femoral nerve irritation."}, {"id": 737, "subject": "Anatomy", "difficulty": "Medium", "question": "Femoral nerve injury during hip arthroplasty most commonly causes:", "options": [{"key": "A", "text": "Foot drop"}, {"key": "B", "text": "Loss of knee extension (quadriceps weakness)"}, {"key": "C", "text": "Loss of hip abduction"}, {"key": "D", "text": "Ankle weakness"}], "correct": "B", "explanation": "Femoral nerve injury during hip surgery causes quadriceps weakness and loss of knee extension reflex."}, {"id": 738, "subject": "Anatomy", "difficulty": "Medium", "question": "The intermediate and medial cutaneous nerves of thigh are branches of:", "options": [{"key": "A", "text": "Lateral femoral cutaneous nerve"}, {"key": "B", "text": "Femoral nerve"}, {"key": "C", "text": "Obturator nerve"}, {"key": "D", "text": "Ilioinguinal nerve"}], "correct": "B", "explanation": "Anterior cutaneous branches (medial and intermediate) of femoral nerve supply the anterior and medial thigh skin."}, {"id": 739, "subject": "Anatomy", "difficulty": "Hard", "question": "Femoral hernia passes:", "options": [{"key": "A", "text": "Lateral to femoral vein"}, {"key": "B", "text": "Medial to femoral vein through femoral canal"}, {"key": "C", "text": "Through inguinal canal"}, {"key": "D", "text": "Through obturator foramen"}], "correct": "B", "explanation": "Femoral hernia descends through the femoral canal, which lies medial to the femoral vein."}, {"id": 740, "subject": "Anatomy", "difficulty": "Hard", "question": "Adductor canal block targets which nerve for knee surgery?", "options": [{"key": "A", "text": "Femoral nerve completely"}, {"key": "B", "text": "Saphenous nerve"}, {"key": "C", "text": "Obturator nerve"}, {"key": "D", "text": "Tibial nerve"}], "correct": "B", "explanation": "Adductor canal block targets saphenous nerve for sensory analgesia after knee surgery, preserving quadriceps strength."}, {"id": 741, "subject": "Anatomy", "difficulty": "Hard", "question": "Femoral nerve arises from which part of lumbar plexus?", "options": [{"key": "A", "text": "Anterior divisions of L2, L3, L4"}, {"key": "B", "text": "Posterior divisions of L2, L3, L4"}, {"key": "C", "text": "Anterior divisions of L1, L2, L3"}, {"key": "D", "text": "All divisions of L2, L3"}], "correct": "B", "explanation": "Femoral nerve arises from posterior divisions of L2, L3, L4 of lumbar plexus (dorsal divisions)."}, {"id": 742, "subject": "Anatomy", "difficulty": "Medium", "question": "Reverse straight leg raise (SLR) tests which nerve root specifically?", "options": [{"key": "A", "text": "L4, L5"}, {"key": "B", "text": "L2, L3, L4 (femoral nerve)"}, {"key": "C", "text": "S1, S2"}, {"key": "D", "text": "L5, S1"}], "correct": "B", "explanation": "Reverse (prone) SLR stretches the femoral nerve roots (L2-L4); pain in anterior thigh is a positive test."}, {"id": 743, "subject": "Anatomy", "difficulty": "Medium", "question": "Femoral nerve sensory distribution on the leg is via:", "options": [{"key": "A", "text": "Lateral sural nerve"}, {"key": "B", "text": "Saphenous nerve only"}, {"key": "C", "text": "Superficial peroneal nerve"}, {"key": "D", "text": "Sural nerve"}], "correct": "B", "explanation": "Saphenous nerve (femoral nerve branch) provides the only sensory distribution of femoral nerve below the knee."}, {"id": 744, "subject": "Anatomy", "difficulty": "Easy", "question": "Paralysis of quadriceps from femoral nerve injury causes difficulty in:", "options": [{"key": "A", "text": "Hip abduction"}, {"key": "B", "text": "Climbing stairs and rising from chair"}, {"key": "C", "text": "Ankle dorsiflexion"}, {"key": "D", "text": "Foot inversion"}], "correct": "B", "explanation": "Quadriceps weakness causes difficulty with weight-bearing knee extension activities like stair climbing and sit-to-stand."}, {"id": 745, "subject": "Anatomy", "difficulty": "Easy", "question": "Sciatic nerve is the largest nerve in the body arising from:", "options": [{"key": "A", "text": "L2-L5"}, {"key": "B", "text": "L4, L5, S1, S2, S3"}, {"key": "C", "text": "L3-S2"}, {"key": "D", "text": "L4-S2"}], "correct": "B", "explanation": "Sciatic nerve is formed from anterior rami of L4, L5, S1, S2, S3 — the largest nerve in the human body."}, {"id": 746, "subject": "Anatomy", "difficulty": "Easy", "question": "Sciatic nerve exits the pelvis through:", "options": [{"key": "A", "text": "Lesser sciatic foramen"}, {"key": "B", "text": "Greater sciatic foramen below piriformis"}, {"key": "C", "text": "Obturator foramen"}, {"key": "D", "text": "Above piriformis"}], "correct": "B", "explanation": "Sciatic nerve exits through the infrapiriform part of greater sciatic foramen in 85% of people."}, {"id": 747, "subject": "Anatomy", "difficulty": "Easy", "question": "Sciatic nerve divides into tibial and common peroneal nerves at:", "options": [{"key": "A", "text": "Gluteal region"}, {"key": "B", "text": "Mid-thigh"}, {"key": "C", "text": "Upper angle of popliteal fossa"}, {"key": "D", "text": "Knee joint"}], "correct": "C", "explanation": "Sciatic nerve typically divides into tibial and common peroneal nerves at the upper angle of the popliteal fossa."}, {"id": 748, "subject": "Anatomy", "difficulty": "Easy", "question": "The two components of the sciatic nerve are:", "options": [{"key": "A", "text": "Femoral and obturator nerves"}, {"key": "B", "text": "Tibial and common peroneal nerves"}, {"key": "C", "text": "Superficial and deep peroneal nerves"}, {"key": "D", "text": "Sural and saphenous nerves"}], "correct": "B", "explanation": "Sciatic nerve is actually two nerves (tibial and common peroneal) bound together by a common epineurial sheath."}, {"id": 749, "subject": "Anatomy", "difficulty": "Medium", "question": "Piriformis syndrome compresses the sciatic nerve causing:", "options": [{"key": "A", "text": "Anterior thigh pain"}, {"key": "B", "text": "Posterior thigh and leg pain mimicking sciatica"}, {"key": "C", "text": "Medial knee pain"}, {"key": "D", "text": "Foot drop only"}], "correct": "B", "explanation": "Piriformis syndrome causes sciatic nerve compression resulting in buttock pain radiating down the posterior thigh and leg."}, {"id": 750, "subject": "Anatomy", "difficulty": "Easy", "question": "Safe site for gluteal injection to avoid sciatic nerve is:", "options": [{"key": "A", "text": "Central buttock"}, {"key": "B", "text": "Upper outer quadrant of buttock"}, {"key": "C", "text": "Lower inner quadrant"}, {"key": "D", "text": "Lower outer quadrant"}], "correct": "B", "explanation": "Intramuscular injections should be given in the upper outer quadrant of the buttock to avoid the sciatic nerve."}, {"id": 751, "subject": "Anatomy", "difficulty": "Medium", "question": "Sciatic nerve supplies which muscles in the thigh?", "options": [{"key": "A", "text": "Quadriceps"}, {"key": "B", "text": "Hamstrings and adductor magnus (ischial part)"}, {"key": "C", "text": "Adductors"}, {"key": "D", "text": "Hip flexors"}], "correct": "B", "explanation": "Sciatic nerve innervates all hamstrings, short head of biceps femoris, and the ischial part of adductor magnus."}, {"id": 752, "subject": "Anatomy", "difficulty": "Medium", "question": "Complete sciatic nerve palsy causes:", "options": [{"key": "A", "text": "Foot drop only"}, {"key": "B", "text": "Loss of all movements below knee + posterior thigh weakness"}, {"key": "C", "text": "Quadriceps weakness"}, {"key": "D", "text": "Hip extension weakness"}], "correct": "B", "explanation": "Complete sciatic nerve palsy causes paralysis of hamstrings and all muscles below the knee, with sensory loss."}, {"id": 753, "subject": "Anatomy", "difficulty": "Medium", "question": "Straight leg raise (SLR) test is positive when pain radiates below knee at:", "options": [{"key": "A", "text": "Less than 30 degrees"}, {"key": "B", "text": "Less than 70 degrees of hip flexion"}, {"key": "C", "text": "90 degrees"}, {"key": "D", "text": "Only at full flexion"}], "correct": "B", "explanation": "SLR is positive when sciatic pain radiates below the knee at less than 70 degrees; 30-40 degrees = severe compression."}, {"id": 754, "subject": "Anatomy", "difficulty": "Medium", "question": "Bragard's sign (SLR + ankle dorsiflexion) increases:", "options": [{"key": "A", "text": "Femoral nerve tension"}, {"key": "B", "text": "Sciatic nerve tension"}, {"key": "C", "text": "Obturator nerve tension"}, {"key": "D", "text": "Sural nerve tension"}], "correct": "B", "explanation": "Ankle dorsiflexion added to SLR further stretches the sciatic nerve, increasing neural tension (Bragard's sign)."}, {"id": 755, "subject": "Anatomy", "difficulty": "Easy", "question": "Which disc herniation most commonly compresses the sciatic nerve?", "options": [{"key": "A", "text": "L3-L4 disc"}, {"key": "B", "text": "L4-L5 and L5-S1 disc"}, {"key": "C", "text": "L2-L3 disc"}, {"key": "D", "text": "L1-L2 disc"}], "correct": "B", "explanation": "L4-L5 (compressing L5) and L5-S1 (compressing S1) disc herniations are the most common causes of sciatica."}, {"id": 756, "subject": "Anatomy", "difficulty": "Hard", "question": "In sciatic nerve injury at the gluteal level, which movement is preserved?", "options": [{"key": "A", "text": "Knee flexion"}, {"key": "B", "text": "Hip extension by gluteus maximus"}, {"key": "C", "text": "Ankle dorsiflexion"}, {"key": "D", "text": "Toe extension"}], "correct": "B", "explanation": "Gluteus maximus is supplied by inferior gluteal nerve (not sciatic), so hip extension is preserved in sciatic nerve injury."}, {"id": 757, "subject": "Anatomy", "difficulty": "Medium", "question": "The SLUMP test stretches:", "options": [{"key": "A", "text": "Femoral nerve"}, {"key": "B", "text": "Sciatic nerve and its meningeal coverings"}, {"key": "C", "text": "Obturator nerve"}, {"key": "D", "text": "Lateral femoral cutaneous nerve"}], "correct": "B", "explanation": "SLUMP test creates dural and sciatic nerve tension through lumbar flexion, knee extension, and ankle dorsiflexion."}, {"id": 758, "subject": "Anatomy", "difficulty": "Hard", "question": "Sciatic nerve relation to quadratus femoris muscle:", "options": [{"key": "A", "text": "Anterior to it"}, {"key": "B", "text": "Posterior to it"}, {"key": "C", "text": "Medial to it"}, {"key": "D", "text": "Lateral to it"}], "correct": "B", "explanation": "Sciatic nerve descends posterior to quadratus femoris (and gemelli, obturator internus) in the gluteal region."}, {"id": 759, "subject": "Anatomy", "difficulty": "Hard", "question": "Hip replacement surgery sciatic nerve injury most commonly involves:", "options": [{"key": "A", "text": "Entire sciatic nerve equally"}, {"key": "B", "text": "Peroneal division more commonly"}, {"key": "C", "text": "Tibial division more commonly"}, {"key": "D", "text": "Only sensory fibers"}], "correct": "B", "explanation": "Peroneal division of sciatic nerve is more commonly injured during hip replacement due to its lateral position and less connective tissue."}, {"id": 760, "subject": "Anatomy", "difficulty": "Hard", "question": "Sciatic nerve variation where it passes through piriformis occurs in:", "options": [{"key": "A", "text": "5% of population"}, {"key": "B", "text": "15% of population"}, {"key": "C", "text": "50% of population"}, {"key": "D", "text": "All individuals"}], "correct": "B", "explanation": "In approximately 15% of individuals, the peroneal division passes through the piriformis muscle, predisposing to piriformis syndrome."}, {"id": 761, "subject": "Anatomy", "difficulty": "Medium", "question": "L4 nerve root compression causes:", "options": [{"key": "A", "text": "Lateral thigh numbness"}, {"key": "B", "text": "Medial leg numbness and weak quadriceps"}, {"key": "C", "text": "Foot drop"}, {"key": "D", "text": "Loss of ankle reflex"}], "correct": "B", "explanation": "L4 compression causes medial leg sensory loss (saphenous distribution), weak quadriceps, and reduced patellar reflex."}, {"id": 762, "subject": "Anatomy", "difficulty": "Medium", "question": "L5 nerve root compression causes:", "options": [{"key": "A", "text": "Patellar reflex loss"}, {"key": "B", "text": "Weak ankle dorsiflexion and great toe extension, with dorsal foot sensory loss"}, {"key": "C", "text": "Ankle reflex loss"}, {"key": "D", "text": "Medial thigh numbness"}], "correct": "B", "explanation": "L5 compression causes weakness of tibialis anterior, EHL (foot drop), and sensory loss over dorsum of foot."}, {"id": 763, "subject": "Anatomy", "difficulty": "Medium", "question": "S1 nerve root compression causes:", "options": [{"key": "A", "text": "Quadriceps weakness"}, {"key": "B", "text": "Weak plantarflexion, reduced Achilles reflex, lateral foot numbness"}, {"key": "C", "text": "Foot drop"}, {"key": "D", "text": "Anterior leg numbness"}], "correct": "B", "explanation": "S1 compression causes weak plantarflexors, absent Achilles reflex, and sensory loss over lateral foot and sole."}, {"id": 764, "subject": "Anatomy", "difficulty": "Hard", "question": "Sciatic nerve is palpable at:", "options": [{"key": "A", "text": "Mid-thigh posteriorly"}, {"key": "B", "text": "Midpoint between ischial tuberosity and greater trochanter"}, {"key": "C", "text": "Popliteal fossa"}, {"key": "D", "text": "Gluteal fold"}], "correct": "B", "explanation": "Sciatic nerve can be palpated at the midpoint between the ischial tuberosity and greater trochanter in the gluteal region."}, {"id": 765, "subject": "Anatomy", "difficulty": "Hard", "question": "Posterior cutaneous nerve of thigh (sciatic nerve's companion) arises from:", "options": [{"key": "A", "text": "L4, L5"}, {"key": "B", "text": "S1, S2, S3"}, {"key": "C", "text": "L5, S1"}, {"key": "D", "text": "S2, S3, S4"}], "correct": "B", "explanation": "Posterior femoral cutaneous nerve arises from S1, S2, S3 and runs with sciatic nerve in posterior thigh."}, {"id": 766, "subject": "Anatomy", "difficulty": "Hard", "question": "Sciatic nerve injury at the level of ischial tuberosity spares:", "options": [{"key": "A", "text": "Hamstrings"}, {"key": "B", "text": "Biceps femoris short head"}, {"key": "C", "text": "All hamstrings equally"}, {"key": "D", "text": "Gastrocnemius"}], "correct": "B", "explanation": "If injury is at the ischial tuberosity, hamstrings (which originate there) may be partially spared as their branches arise proximally."}, {"id": 767, "subject": "Anatomy", "difficulty": "Hard", "question": "The femoral component of sciatic nerve (L4, L5) runs in:", "options": [{"key": "A", "text": "Tibial division"}, {"key": "B", "text": "Peroneal division"}, {"key": "C", "text": "Equally in both"}, {"key": "D", "text": "Sural nerve"}], "correct": "B", "explanation": "L4 and L5 fibers predominantly run in the peroneal (common fibular) division of the sciatic nerve."}, {"id": 768, "subject": "Anatomy", "difficulty": "Medium", "question": "Wallet-sitting sciatica is caused by:", "options": [{"key": "A", "text": "Disc herniation"}, {"key": "B", "text": "Piriformis compression from wallet in back pocket"}, {"key": "C", "text": "SI joint dysfunction"}, {"key": "D", "text": "Hamstring tightness"}], "correct": "B", "explanation": "Prolonged sitting on a thick wallet compresses the piriformis region, irritating the underlying sciatic nerve."}, {"id": 769, "subject": "Anatomy", "difficulty": "Medium", "question": "Sciatic nerve block in posterior approach targets nerve at:", "options": [{"key": "A", "text": "Popliteal fossa only"}, {"key": "B", "text": "Subgluteal or gluteal level"}, {"key": "C", "text": "Thigh level only"}, {"key": "D", "text": "Inguinal ligament level"}], "correct": "B", "explanation": "Classical sciatic nerve block is performed at the gluteal or subgluteal level (Labat approach) for lower limb anesthesia."}, {"id": 770, "subject": "Anatomy", "difficulty": "Easy", "question": "Tibial nerve is the larger terminal branch of sciatic nerve arising from:", "options": [{"key": "A", "text": "L2, L3, L4"}, {"key": "B", "text": "L4, L5, S1, S2, S3"}, {"key": "C", "text": "L3, L4, L5"}, {"key": "D", "text": "S1, S2, S3"}], "correct": "B", "explanation": "Tibial nerve (medial popliteal nerve) arises from the tibial (medial) division of sciatic nerve — L4, L5, S1, S2, S3."}, {"id": 771, "subject": "Anatomy", "difficulty": "Medium", "question": "Tibial nerve enters the leg by passing:", "options": [{"key": "A", "text": "Anterior to popliteus"}, {"key": "B", "text": "Deep to popliteus and through soleal arch"}, {"key": "C", "text": "Lateral to popliteus"}, {"key": "D", "text": "Through interosseous membrane"}], "correct": "B", "explanation": "Tibial nerve passes deep to popliteus and then through the tendinous arch of soleus to enter the posterior compartment."}, {"id": 772, "subject": "Anatomy", "difficulty": "Medium", "question": "Tarsal tunnel syndrome involves compression of tibial nerve at:", "options": [{"key": "A", "text": "Popliteal fossa"}, {"key": "B", "text": "Behind medial malleolus under flexor retinaculum"}, {"key": "C", "text": "Mid-leg"}, {"key": "D", "text": "Plantar fascia"}], "correct": "B", "explanation": "Tarsal tunnel syndrome is entrapment of the tibial nerve (or its branches) beneath the flexor retinaculum posterior to medial malleolus."}, {"id": 773, "subject": "Anatomy", "difficulty": "Easy", "question": "Tibial nerve supplies which compartment of the leg?", "options": [{"key": "A", "text": "Anterior compartment"}, {"key": "B", "text": "Posterior compartment (superficial and deep)"}, {"key": "C", "text": "Lateral compartment"}, {"key": "D", "text": "All compartments equally"}], "correct": "B", "explanation": "Tibial nerve supplies all muscles of the posterior compartment: superficial (gastrocnemius, soleus, plantaris) and deep (tibialis posterior, FDL, FHL)."}, {"id": 774, "subject": "Anatomy", "difficulty": "Easy", "question": "Ankle jerk reflex is mediated by tibial nerve at spinal level:", "options": [{"key": "A", "text": "L3-L4"}, {"key": "B", "text": "L4-L5"}, {"key": "C", "text": "S1-S2"}, {"key": "D", "text": "S2-S3"}], "correct": "C", "explanation": "Achilles tendon reflex is mediated through S1-S2 via the tibial nerve."}, {"id": 775, "subject": "Anatomy", "difficulty": "Medium", "question": "Tibial nerve divides into medial and lateral plantar nerves at:", "options": [{"key": "A", "text": "Behind medial malleolus"}, {"key": "B", "text": "In the tarsal tunnel / beneath flexor retinaculum"}, {"key": "C", "text": "Mid-foot"}, {"key": "D", "text": "Heel"}], "correct": "B", "explanation": "Tibial nerve divides into medial and lateral plantar nerves within the tarsal tunnel under the flexor retinaculum."}, {"id": 776, "subject": "Anatomy", "difficulty": "Hard", "question": "Medial plantar nerve (tibial nerve branch) innervates:", "options": [{"key": "A", "text": "Lateral 1.5 toes"}, {"key": "B", "text": "Medial 3.5 toes and intrinsic muscles (LAFF)"}, {"key": "C", "text": "All intrinsic foot muscles"}, {"key": "D", "text": "Only skin of sole"}], "correct": "B", "explanation": "Medial plantar nerve innervates skin of medial 3.5 toes and muscles: Lumbrical 1, Abductor hallucis, Flexor hallucis brevis, Flexor digitorum brevis (LAFF)."}, {"id": 777, "subject": "Anatomy", "difficulty": "Hard", "question": "Lateral plantar nerve supplies:", "options": [{"key": "A", "text": "Medial 3.5 toes"}, {"key": "B", "text": "Lateral 1.5 toes and most intrinsic foot muscles"}, {"key": "C", "text": "Only plantar skin"}, {"key": "D", "text": "Dorsum of foot"}], "correct": "B", "explanation": "Lateral plantar nerve supplies lateral 1.5 toes and most intrinsic muscles (interossei, 3 lumbricals, adductor hallucis, flexor digiti minimi)."}, {"id": 778, "subject": "Anatomy", "difficulty": "Hard", "question": "Sural nerve is formed by branches of:", "options": [{"key": "A", "text": "Tibial nerve only"}, {"key": "B", "text": "Common peroneal nerve only"}, {"key": "C", "text": "Tibial nerve and common peroneal nerve (sural communicating branch)"}, {"key": "D", "text": "Saphenous and tibial nerve"}], "correct": "C", "explanation": "Sural nerve is formed by the medial sural cutaneous nerve (tibial) and sural communicating branch (peroneal)."}, {"id": 779, "subject": "Anatomy", "difficulty": "Medium", "question": "Tibial nerve injury at the popliteal fossa causes:", "options": [{"key": "A", "text": "Foot drop"}, {"key": "B", "text": "Loss of plantarflexion, toe flexion, and inversion with sensory loss over sole"}, {"key": "C", "text": "Loss of dorsiflexion only"}, {"key": "D", "text": "Hip flexion weakness"}], "correct": "B", "explanation": "Popliteal tibial nerve injury causes weakness of all posterior leg and foot intrinsic muscles with sole sensory loss."}, {"id": 780, "subject": "Anatomy", "difficulty": "Hard", "question": "Medial sural cutaneous nerve supplies:", "options": [{"key": "A", "text": "Sole of foot"}, {"key": "B", "text": "Lateral and posterior leg skin"}, {"key": "C", "text": "Dorsum of foot"}, {"key": "D", "text": "Anterior leg"}], "correct": "B", "explanation": "Medial sural cutaneous nerve (from tibial) supplies posterior and lateral leg; joins peroneal communicating branch to form sural nerve."}, {"id": 781, "subject": "Anatomy", "difficulty": "Hard", "question": "Tibial nerve in popliteal fossa lies in relation to popliteal artery:", "options": [{"key": "A", "text": "Medial and deep"}, {"key": "B", "text": "Superficial and lateral"}, {"key": "C", "text": "Deep to artery"}, {"key": "D", "text": "Anterior to artery"}], "correct": "B", "explanation": "In the popliteal fossa from superficial to deep: tibial nerve → popliteal vein → popliteal artery."}, {"id": 782, "subject": "Anatomy", "difficulty": "Hard", "question": "Jogger's foot (medial plantar nerve entrapment) presents with:", "options": [{"key": "A", "text": "Lateral heel pain"}, {"key": "B", "text": "Medial arch pain and numbness in medial toes"}, {"key": "C", "text": "Dorsal foot pain"}, {"key": "D", "text": "Lateral toe numbness"}], "correct": "B", "explanation": "Jogger's foot is entrapment of medial plantar nerve at the knot of Henry, causing medial arch pain radiating to medial toes."}, {"id": 783, "subject": "Anatomy", "difficulty": "Medium", "question": "Tibialis posterior is innervated by:", "options": [{"key": "A", "text": "Deep peroneal nerve"}, {"key": "B", "text": "Tibial nerve"}, {"key": "C", "text": "Superficial peroneal nerve"}, {"key": "D", "text": "Sural nerve"}], "correct": "B", "explanation": "Tibialis posterior is innervated by the tibial nerve (L4, L5), which is important in posterior tibialis tendinopathy assessment."}, {"id": 784, "subject": "Anatomy", "difficulty": "Medium", "question": "Flexor hallucis longus is innervated by:", "options": [{"key": "A", "text": "Superficial peroneal nerve"}, {"key": "B", "text": "Deep peroneal nerve"}, {"key": "C", "text": "Tibial nerve"}, {"key": "D", "text": "Sural nerve"}], "correct": "C", "explanation": "Flexor hallucis longus (deep posterior compartment) is innervated by the tibial nerve (S2, S3)."}, {"id": 785, "subject": "Anatomy", "difficulty": "Hard", "question": "Baxter's nerve (inferior calcaneal nerve) is a branch of:", "options": [{"key": "A", "text": "Medial plantar nerve"}, {"key": "B", "text": "Lateral plantar nerve"}, {"key": "C", "text": "Sural nerve"}, {"key": "D", "text": "Tibial nerve directly"}], "correct": "B", "explanation": "Baxter's nerve (nerve to abductor digiti minimi) is the first branch of lateral plantar nerve; its entrapment causes heel pain."}, {"id": 786, "subject": "Anatomy", "difficulty": "Medium", "question": "Tibial nerve calcaneal branches supply:", "options": [{"key": "A", "text": "Intrinsic toe muscles"}, {"key": "B", "text": "Skin of heel (plantar and medial)"}, {"key": "C", "text": "Achilles tendon"}, {"key": "D", "text": "Lateral ankle"}], "correct": "B", "explanation": "Medial calcaneal branches arise from tibial nerve to supply the medial and plantar heel skin."}, {"id": 787, "subject": "Anatomy", "difficulty": "Medium", "question": "In tarsal tunnel syndrome, Tinel's sign is positive at:", "options": [{"key": "A", "text": "Medial malleolus (tapping over tibial nerve)"}, {"key": "B", "text": "Lateral malleolus"}, {"key": "C", "text": "Popliteal fossa"}, {"key": "D", "text": "Plantar fascia"}], "correct": "A", "explanation": "Tinel's sign in tarsal tunnel syndrome: tapping posterior to medial malleolus reproduces tingling in the plantar foot."}, {"id": 788, "subject": "Anatomy", "difficulty": "Hard", "question": "Tibial nerve provides articular branches to:", "options": [{"key": "A", "text": "Hip joint"}, {"key": "B", "text": "Knee and ankle joints"}, {"key": "C", "text": "Only ankle joint"}, {"key": "D", "text": "SI joint"}], "correct": "B", "explanation": "Tibial nerve provides articular branches to both the knee joint (in popliteal fossa) and ankle joint."}, {"id": 789, "subject": "Anatomy", "difficulty": "Medium", "question": "Plantarflexion against resistance with intact sensation tests integrity of:", "options": [{"key": "A", "text": "S1-S2 and tibial nerve"}, {"key": "B", "text": "L4-L5 and peroneal nerve"}, {"key": "C", "text": "L3-L4 and femoral nerve"}, {"key": "D", "text": "S3-S4 and pudendal nerve"}], "correct": "A", "explanation": "Plantarflexion is primarily a tibial nerve function (gastrocnemius/soleus) testing S1-S2."}, {"id": 790, "subject": "Anatomy", "difficulty": "Hard", "question": "Tibial nerve posterior tarsal tunnel contents include all EXCEPT:", "options": [{"key": "A", "text": "Flexor hallucis longus tendon"}, {"key": "B", "text": "Tibial nerve"}, {"key": "C", "text": "Peroneal tendons"}, {"key": "D", "text": "Tibialis posterior tendon"}], "correct": "C", "explanation": "Tarsal tunnel (posterior) contains: tibialis posterior, FDL, tibial artery/vein, tibial nerve, FHL (Tom, Dick, ANd Harry). Peroneals pass behind lateral malleolus."}, {"id": 791, "subject": "Anatomy", "difficulty": "Hard", "question": "Sciatic nerve high division where tibial and peroneal separate in thigh occurs in:", "options": [{"key": "A", "text": "5% of individuals"}, {"key": "B", "text": "12% of individuals"}, {"key": "C", "text": "50% of individuals"}, {"key": "D", "text": "All individuals"}], "correct": "B", "explanation": "High division of sciatic nerve (separation in thigh rather than popliteal fossa) occurs in approximately 10-12% of individuals."}, {"id": 792, "subject": "Anatomy", "difficulty": "Hard", "question": "Tibial nerve motor branch to popliteus functions to:", "options": [{"key": "A", "text": "Extend knee"}, {"key": "B", "text": "Unlock knee by internally rotating tibia"}, {"key": "C", "text": "Flex knee"}, {"key": "D", "text": "Externally rotate tibia"}], "correct": "B", "explanation": "Popliteus (supplied by tibial nerve) unlocks the fully extended knee by internally rotating the tibia (or externally rotating femur)."}, {"id": 793, "subject": "Anatomy", "difficulty": "Medium", "question": "Loss of toe flexion and intrinsic foot muscle function results from tibial nerve injury at:", "options": [{"key": "A", "text": "Above knee (high injury)"}, {"key": "B", "text": "Below knee but above tarsal tunnel"}, {"key": "C", "text": "Tarsal tunnel level"}, {"key": "D", "text": "Plantar level"}], "correct": "C", "explanation": "Tibial nerve injury at the tarsal tunnel affects toe flexion and intrinsic muscles while preserving posterior leg muscles."}, {"id": 794, "subject": "Anatomy", "difficulty": "Medium", "question": "Tibial nerve supplies all posterior compartment leg muscles EXCEPT:", "options": [{"key": "A", "text": "Gastrocnemius"}, {"key": "B", "text": "Soleus"}, {"key": "C", "text": "Popliteus"}, {"key": "D", "text": "Peroneus longus"}], "correct": "D", "explanation": "Peroneus (fibularis) longus is in the lateral compartment and is innervated by the superficial peroneal nerve, not tibial nerve."}, {"id": 795, "subject": "Anatomy", "difficulty": "Hard", "question": "Common peroneal nerve is derived from which divisions?", "options": [{"key": "A", "text": "Anterior divisions L4, L5, S1, S2"}, {"key": "B", "text": "Posterior divisions L4, L5, S1, S2"}, {"key": "C", "text": "Anterior divisions L2, L3, L4"}, {"key": "D", "text": "Posterior divisions L2, L3, L4"}], "correct": "B", "explanation": "Common peroneal nerve arises from posterior divisions (dorsal divisions) of L4, L5, S1, S2 of the sciatic nerve."}, {"id": 796, "subject": "Anatomy", "difficulty": "Easy", "question": "Common peroneal nerve winds around:", "options": [{"key": "A", "text": "Medial malleolus"}, {"key": "B", "text": "Neck of fibula"}, {"key": "C", "text": "Head of tibia"}, {"key": "D", "text": "Lateral malleolus"}], "correct": "B", "explanation": "Common peroneal nerve wraps around the posterior aspect of the fibular neck, making it vulnerable to compression."}, {"id": 797, "subject": "Anatomy", "difficulty": "Easy", "question": "Foot drop is caused by injury to:", "options": [{"key": "A", "text": "Tibial nerve"}, {"key": "B", "text": "Common peroneal nerve"}, {"key": "C", "text": "Femoral nerve"}, {"key": "D", "text": "Sciatic nerve at S1 level"}], "correct": "B", "explanation": "Common peroneal nerve injury causes foot drop (inability to dorsiflex ankle) due to paralysis of anterior compartment muscles."}, {"id": 798, "subject": "Anatomy", "difficulty": "Easy", "question": "Common peroneal nerve divides into which two branches?", "options": [{"key": "A", "text": "Medial and lateral sural nerves"}, {"key": "B", "text": "Deep and superficial peroneal nerves"}, {"key": "C", "text": "Saphenous and sural nerves"}, {"key": "D", "text": "Tibial and fibular nerves"}], "correct": "B", "explanation": "Common peroneal nerve divides into deep peroneal (anterior compartment) and superficial peroneal (lateral compartment) nerves."}, {"id": 799, "subject": "Anatomy", "difficulty": "Easy", "question": "Deep peroneal nerve supplies:", "options": [{"key": "A", "text": "Lateral compartment muscles"}, {"key": "B", "text": "Anterior compartment muscles and first web space sensation"}, {"key": "C", "text": "Posterior compartment muscles"}, {"key": "D", "text": "Intrinsic foot muscles"}], "correct": "B", "explanation": "Deep peroneal nerve innervates anterior compartment (tibialis anterior, EHL, EDL, peroneus tertius) and first web space skin."}, {"id": 800, "subject": "Anatomy", "difficulty": "Easy", "question": "Superficial peroneal nerve supplies:", "options": [{"key": "A", "text": "Anterior leg muscles"}, {"key": "B", "text": "Lateral compartment muscles and dorsum of foot sensation"}, {"key": "C", "text": "Deep posterior leg muscles"}, {"key": "D", "text": "First web space only"}], "correct": "B", "explanation": "Superficial peroneal nerve innervates peroneus longus and brevis, and provides sensation to most of the dorsum of foot."}, {"id": 801, "subject": "Anatomy", "difficulty": "Hard", "question": "Anterior tarsal tunnel syndrome involves compression of:", "options": [{"key": "A", "text": "Tibial nerve"}, {"key": "B", "text": "Deep peroneal nerve under inferior extensor retinaculum"}, {"key": "C", "text": "Superficial peroneal nerve"}, {"key": "D", "text": "Sural nerve"}], "correct": "B", "explanation": "Anterior tarsal tunnel syndrome is entrapment of the deep peroneal nerve beneath the inferior extensor retinaculum on the dorsum of foot."}, {"id": 802, "subject": "Anatomy", "difficulty": "Medium", "question": "Common peroneal nerve injury at fibular neck causes sensory loss over:", "options": [{"key": "A", "text": "Sole of foot"}, {"key": "B", "text": "Dorsum of foot and lateral leg"}, {"key": "C", "text": "Medial leg"}, {"key": "D", "text": "Posterior thigh"}], "correct": "B", "explanation": "Peroneal nerve injury at the fibular neck causes sensory loss over the dorsum of foot and lateral leg."}, {"id": 803, "subject": "Anatomy", "difficulty": "Easy", "question": "The most common cause of common peroneal nerve palsy is:", "options": [{"key": "A", "text": "Diabetes"}, {"key": "B", "text": "Prolonged leg crossing / fibular neck compression"}, {"key": "C", "text": "L4-L5 disc herniation alone"}, {"key": "D", "text": "Deep vein thrombosis"}], "correct": "B", "explanation": "External compression at the fibular neck (habitual leg crossing, prolonged squatting, plaster cast) is the most common cause."}, {"id": 804, "subject": "Anatomy", "difficulty": "Medium", "question": "Deep peroneal nerve provides sensation ONLY to:", "options": [{"key": "A", "text": "Lateral 2 toes"}, {"key": "B", "text": "First web space (between first and second toes)"}, {"key": "C", "text": "Medial sole"}, {"key": "D", "text": "Lateral sole"}], "correct": "B", "explanation": "Deep peroneal nerve has a very limited cutaneous area: only the first dorsal web space (adjacent sides of 1st and 2nd toes)."}, {"id": 805, "subject": "Anatomy", "difficulty": "Easy", "question": "Foot drop gait pattern is characterized by:", "options": [{"key": "A", "text": "Trendelenburg gait"}, {"key": "B", "text": "Steppage gait (high stepping)"}, {"key": "C", "text": "Antalgic gait"}, {"key": "D", "text": "Scissor gait"}], "correct": "B", "explanation": "Foot drop causes steppage gait: excessive hip and knee flexion to clear the foot during swing phase to avoid tripping."}, {"id": 806, "subject": "Anatomy", "difficulty": "Easy", "question": "Peroneus longus and brevis are innervated by:", "options": [{"key": "A", "text": "Deep peroneal nerve"}, {"key": "B", "text": "Superficial peroneal nerve"}, {"key": "C", "text": "Sural nerve"}, {"key": "D", "text": "Tibial nerve"}], "correct": "B", "explanation": "Peroneus longus and brevis (lateral compartment) are innervated by the superficial peroneal nerve (L5, S1)."}, {"id": 807, "subject": "Anatomy", "difficulty": "Medium", "question": "Common peroneal nerve can be palpated at:", "options": [{"key": "A", "text": "Popliteal fossa only"}, {"key": "B", "text": "Posterior to the fibular head / fibular neck"}, {"key": "C", "text": "Lateral malleolus"}, {"key": "D", "text": "Anterior knee"}], "correct": "B", "explanation": "Common peroneal nerve is palpable as it winds around the fibular neck just distal to the fibular head."}, {"id": 808, "subject": "Anatomy", "difficulty": "Easy", "question": "Tibialis anterior is innervated by:", "options": [{"key": "A", "text": "Superficial peroneal nerve"}, {"key": "B", "text": "Deep peroneal nerve"}, {"key": "C", "text": "Tibial nerve"}, {"key": "D", "text": "Sural nerve"}], "correct": "B", "explanation": "Tibialis anterior (anterior compartment, primary ankle dorsiflexor) is innervated by the deep peroneal nerve (L4, L5)."}, {"id": 809, "subject": "Anatomy", "difficulty": "Medium", "question": "Extensor hallucis longus is innervated by:", "options": [{"key": "A", "text": "Tibial nerve"}, {"key": "B", "text": "Superficial peroneal nerve"}, {"key": "C", "text": "Deep peroneal nerve"}, {"key": "D", "text": "Sural nerve"}], "correct": "C", "explanation": "EHL (extends great toe, assists dorsiflexion) is innervated by the deep peroneal nerve (L5)."}, {"id": 810, "subject": "Anatomy", "difficulty": "Medium", "question": "L5 nerve root compression specifically weakens:", "options": [{"key": "A", "text": "Ankle plantarflexion"}, {"key": "B", "text": "Great toe extension (EHL) and ankle dorsiflexion"}, {"key": "C", "text": "Knee extension"}, {"key": "D", "text": "Foot inversion by tibialis posterior"}], "correct": "B", "explanation": "L5 supplies EHL (via deep peroneal) and contributes to tibialis anterior; L5 compression causes weak great toe extension and dorsiflexion."}, {"id": 811, "subject": "Anatomy", "difficulty": "Hard", "question": "Superficial peroneal nerve becomes subcutaneous at:", "options": [{"key": "A", "text": "Fibular neck"}, {"key": "B", "text": "Junction of middle and lower thirds of the lateral leg"}, {"key": "C", "text": "Ankle level"}, {"key": "D", "text": "Knee level"}], "correct": "B", "explanation": "Superficial peroneal nerve pierces the deep fascia at the junction of the middle and distal thirds of the lateral leg."}, {"id": 812, "subject": "Anatomy", "difficulty": "Medium", "question": "Lateral ankle sprain can injure:", "options": [{"key": "A", "text": "Tibial nerve"}, {"key": "B", "text": "Sural nerve and superficial peroneal nerve"}, {"key": "C", "text": "Deep peroneal nerve"}, {"key": "D", "text": "Saphenous nerve"}], "correct": "B", "explanation": "Lateral ankle sprain (inversion injury) can stretch or injure the sural nerve and superficial peroneal nerve."}, {"id": 813, "subject": "Anatomy", "difficulty": "Medium", "question": "Common peroneal nerve injury in acute compartment syndrome of the anterior compartment causes:", "options": [{"key": "A", "text": "Loss of plantarflexion"}, {"key": "B", "text": "Foot drop and dorsal foot numbness"}, {"key": "C", "text": "Calf weakness"}, {"key": "D", "text": "Knee flexion weakness"}], "correct": "B", "explanation": "Anterior compartment syndrome compresses the deep peroneal nerve, causing foot drop and first web space numbness."}, {"id": 814, "subject": "Anatomy", "difficulty": "Hard", "question": "Peroneal nerve conduction study for foot drop should be performed at:", "options": [{"key": "A", "text": "Ankle and below-knee sites only"}, {"key": "B", "text": "Fibular head, popliteal fossa, and below-knee sites"}, {"key": "C", "text": "Only popliteal fossa"}, {"key": "D", "text": "Thigh level only"}], "correct": "B", "explanation": "NCS for peroneal nerve foot drop should include stimulation at ankle, fibular head, and popliteal fossa to localize the lesion."}, {"id": 815, "subject": "Anatomy", "difficulty": "Easy", "question": "AFO (ankle-foot orthosis) is prescribed for foot drop to maintain ankle at:", "options": [{"key": "A", "text": "Plantarflexion"}, {"key": "B", "text": "Neutral (90 degrees) or slight dorsiflexion"}, {"key": "C", "text": "Full dorsiflexion"}, {"key": "D", "text": "Inversion"}], "correct": "B", "explanation": "AFO for foot drop holds the ankle at neutral/slight dorsiflexion to enable clearance during swing and stable heel strike."}, {"id": 816, "subject": "Anatomy", "difficulty": "Hard", "question": "Recurrent peroneal nerve at the ankle is a branch of:", "options": [{"key": "A", "text": "Superficial peroneal nerve"}, {"key": "B", "text": "Deep peroneal nerve"}, {"key": "C", "text": "Tibial nerve"}, {"key": "D", "text": "Sural nerve"}], "correct": "B", "explanation": "Recurrent articular branch of deep peroneal nerve supplies the ankle joint."}, {"id": 817, "subject": "Anatomy", "difficulty": "Easy", "question": "Peroneal nerve is most vulnerable to injury at:", "options": [{"key": "A", "text": "Mid-thigh"}, {"key": "B", "text": "Fibular neck"}, {"key": "C", "text": "Ankle"}, {"key": "D", "text": "Popliteal fossa"}], "correct": "B", "explanation": "The fibular neck is the most vulnerable site: nerve is superficial, fixed, and adjacent to bone — susceptible to compression/traction."}, {"id": 818, "subject": "Anatomy", "difficulty": "Medium", "question": "Nerve to extensor digitorum brevis is from:", "options": [{"key": "A", "text": "Superficial peroneal nerve"}, {"key": "B", "text": "Deep peroneal nerve"}, {"key": "C", "text": "Tibial nerve"}, {"key": "D", "text": "Lateral plantar nerve"}], "correct": "B", "explanation": "Extensor digitorum brevis (dorsal intrinsic foot muscle) is innervated by the deep peroneal nerve (L5, S1)."}, {"id": 819, "subject": "Anatomy", "difficulty": "Medium", "question": "In peroneal nerve palsy, which movement is preserved?", "options": [{"key": "A", "text": "Ankle dorsiflexion"}, {"key": "B", "text": "Ankle plantarflexion and inversion (tibial nerve function)"}, {"key": "C", "text": "Great toe extension"}, {"key": "D", "text": "Foot eversion"}], "correct": "B", "explanation": "Peroneal nerve palsy preserves tibial nerve functions: plantarflexion (gastrocnemius/soleus) and inversion (tibialis posterior)."}, {"id": 820, "subject": "Anatomy", "difficulty": "Easy", "question": "How many cervical vertebrae are there in the human spine?", "options": [{"key": "A", "text": "5"}, {"key": "B", "text": "6"}, {"key": "C", "text": "7"}, {"key": "D", "text": "8"}], "correct": "C", "explanation": "There are 7 cervical vertebrae (C1-C7), the smallest and most mobile vertebrae of the spinal column."}, {"id": 821, "subject": "Anatomy", "difficulty": "Easy", "question": "The atlas (C1) is unique because it has:", "options": [{"key": "A", "text": "A vertebral body and spinous process"}, {"key": "B", "text": "No vertebral body and no spinous process"}, {"key": "C", "text": "Two spinous processes"}, {"key": "D", "text": "A large vertebral body"}], "correct": "B", "explanation": "Atlas has no vertebral body (replaced by anterior arch) and no true spinous process (replaced by posterior tubercle)."}, {"id": 822, "subject": "Anatomy", "difficulty": "Easy", "question": "The dens (odontoid process) is a projection of:", "options": [{"key": "A", "text": "C1 (Atlas)"}, {"key": "B", "text": "C2 (Axis)"}, {"key": "C", "text": "C3"}, {"key": "D", "text": "Occiput"}], "correct": "B", "explanation": "The dens (odontoid process) is a toothlike projection of C2 (axis) that articulates with the anterior arch of C1."}, {"id": 823, "subject": "Anatomy", "difficulty": "Easy", "question": "Which cervical vertebra has the largest and most prominent spinous process?", "options": [{"key": "A", "text": "C3"}, {"key": "B", "text": "C5"}, {"key": "C", "text": "C6"}, {"key": "D", "text": "C7 (vertebra prominens)"}], "correct": "D", "explanation": "C7 is called vertebra prominens because it has the longest, most prominent non-bifid spinous process, palpable at the base of the neck."}, {"id": 824, "subject": "Anatomy", "difficulty": "Easy", "question": "Bifid spinous processes are a characteristic feature of which cervical vertebrae?", "options": [{"key": "A", "text": "C1 and C2"}, {"key": "B", "text": "C3 to C6"}, {"key": "C", "text": "C6 and C7"}, {"key": "D", "text": "C2 to C7"}], "correct": "B", "explanation": "Cervical vertebrae C3-C6 typically have bifid (split/forked) spinous processes, unlike C7 which is non-bifid."}, {"id": 825, "subject": "Anatomy", "difficulty": "Medium", "question": "The transverse foramen (foramen transversarium) transmits:", "options": [{"key": "A", "text": "Spinal nerves"}, {"key": "B", "text": "Vertebral artery and vein (C1-C6)"}, {"key": "C", "text": "Anterior spinal artery"}, {"key": "D", "text": "Lymphatics only"}], "correct": "B", "explanation": "Transverse foramen transmits vertebral artery, vertebral vein, and sympathetic plexus. Vertebral artery enters at C6 (typically)."}, {"id": 826, "subject": "Anatomy", "difficulty": "Medium", "question": "The uncinate processes (joints of Luschka) are found on:", "options": [{"key": "A", "text": "Thoracic vertebrae"}, {"key": "B", "text": "Lateral aspects of cervical vertebral bodies (C3-C7)"}, {"key": "C", "text": "Lumbar vertebrae"}, {"key": "D", "text": "Sacrum"}], "correct": "B", "explanation": "Uncinate processes (uncovertebral joints/Luschka joints) are bony projections on the superolateral cervical vertebral bodies C3-C7."}, {"id": 827, "subject": "Anatomy", "difficulty": "Medium", "question": "The normal cervical lordosis angle is approximately:", "options": [{"key": "A", "text": "10-20 degrees"}, {"key": "B", "text": "30-40 degrees"}, {"key": "C", "text": "50-60 degrees"}, {"key": "D", "text": "0-10 degrees"}], "correct": "B", "explanation": "Normal cervical lordosis measures approximately 30-40 degrees (Cobb angle C2-C7), creating the characteristic C-shaped curve."}, {"id": 828, "subject": "Anatomy", "difficulty": "Hard", "question": "The vertebral artery typically enters the transverse foramen at which level?", "options": [{"key": "A", "text": "C4"}, {"key": "B", "text": "C5"}, {"key": "C", "text": "C6"}, {"key": "D", "text": "C7"}], "correct": "C", "explanation": "The vertebral artery typically enters the transverse foramen at C6, though variations occur; it does NOT enter at C7."}, {"id": 829, "subject": "Anatomy", "difficulty": "Medium", "question": "The atlantoaxial joint (C1-C2) primarily allows which movement?", "options": [{"key": "A", "text": "Flexion and extension"}, {"key": "B", "text": "Rotation (50% of total cervical rotation)"}, {"key": "C", "text": "Lateral flexion"}, {"key": "D", "text": "Protraction"}], "correct": "B", "explanation": "The atlantoaxial joint provides approximately 50% of total cervical rotation (about 45 degrees each side)."}, {"id": 830, "subject": "Anatomy", "difficulty": "Medium", "question": "The atlantooccipital joint (C0-C1) primarily allows:", "options": [{"key": "A", "text": "Rotation"}, {"key": "B", "text": "Nodding (flexion-extension — 'yes' movement)"}, {"key": "C", "text": "Lateral flexion"}, {"key": "D", "text": "All movements equally"}], "correct": "B", "explanation": "Atlantooccipital joint allows nodding (flexion-extension), contributing about 15 degrees of flexion and 25 degrees of extension."}, {"id": 831, "subject": "Anatomy", "difficulty": "Hard", "question": "Superior articular facets of C1 (atlas) are oriented to articulate with:", "options": [{"key": "A", "text": "C2 inferior facets (flat, horizontal)"}, {"key": "B", "text": "Occipital condyles (concave, facing superomedially)"}, {"key": "C", "text": "Dens of axis"}, {"key": "D", "text": "C3 vertebra"}], "correct": "B", "explanation": "C1 superior articular facets are concave and kidney-shaped, articulating with the convex occipital condyles."}, {"id": 832, "subject": "Anatomy", "difficulty": "Hard", "question": "The pedicles of cervical vertebrae project:", "options": [{"key": "A", "text": "Directly laterally"}, {"key": "B", "text": "Posterolaterally at an oblique angle"}, {"key": "C", "text": "Directly posteriorly"}, {"key": "D", "text": "Anteromedially"}], "correct": "B", "explanation": "Cervical pedicles project posterolaterally, forming the boundaries of the intervertebral foramen."}, {"id": 833, "subject": "Anatomy", "difficulty": "Medium", "question": "Jefferson fracture involves:", "options": [{"key": "A", "text": "C2 dens fracture"}, {"key": "B", "text": "Burst fracture of C1 (atlas) ring"}, {"key": "C", "text": "C7 compression fracture"}, {"key": "D", "text": "Odontoid fracture"}], "correct": "B", "explanation": "Jefferson fracture is a burst fracture of the C1 ring caused by axial loading (e.g., diving into shallow water), splitting it into fragments."}, {"id": 834, "subject": "Anatomy", "difficulty": "Medium", "question": "Hangman's fracture involves:", "options": [{"key": "A", "text": "Atlas fracture"}, {"key": "B", "text": "Bilateral C2 pedicle fracture (traumatic spondylolisthesis of axis)"}, {"key": "C", "text": "C6-C7 dislocation"}, {"key": "D", "text": "Dens type II fracture"}], "correct": "B", "explanation": "Hangman's fracture is bilateral fracture through C2 pedicles (traumatic spondylolisthesis of axis), caused by hyperextension."}, {"id": 835, "subject": "Anatomy", "difficulty": "Hard", "question": "The spinal canal is largest at which cervical level?", "options": [{"key": "A", "text": "C1"}, {"key": "B", "text": "C5"}, {"key": "C", "text": "C7"}, {"key": "D", "text": "C4"}], "correct": "A", "explanation": "The spinal canal is largest at C1 (atlas) where it accommodates the dens anteriorly and spinal cord posteriorly."}, {"id": 836, "subject": "Anatomy", "difficulty": "Hard", "question": "Cervical disc height is greatest at which level?", "options": [{"key": "A", "text": "C2-C3"}, {"key": "B", "text": "C4-C5"}, {"key": "C", "text": "C5-C6"}, {"key": "D", "text": "C6-C7"}], "correct": "C", "explanation": "C5-C6 disc is the most mobile and largest cervical disc, and most commonly herniated level."}, {"id": 837, "subject": "Anatomy", "difficulty": "Hard", "question": "The uncovertebral joints (Luschka) are considered:", "options": [{"key": "A", "text": "True synovial joints from birth"}, {"key": "B", "text": "Acquired clefts/joints developing in second decade"}, {"key": "C", "text": "Cartilaginous joints"}, {"key": "D", "text": "Fibrous joints"}], "correct": "B", "explanation": "Luschka joints are not present at birth; they develop as acquired fissures in the lateral annulus during the second decade of life."}, {"id": 838, "subject": "Anatomy", "difficulty": "Easy", "question": "Most common level of cervical disc herniation is:", "options": [{"key": "A", "text": "C3-C4"}, {"key": "B", "text": "C4-C5"}, {"key": "C", "text": "C5-C6"}, {"key": "D", "text": "C7-T1"}], "correct": "C", "explanation": "C5-C6 is the most common level of cervical disc herniation, affecting the C6 nerve root."}, {"id": 839, "subject": "Anatomy", "difficulty": "Hard", "question": "Cervical vertebrae have a characteristic triangular-shaped vertebral foramen compared to:", "options": [{"key": "A", "text": "Thoracic (circular) and lumbar (triangular)"}, {"key": "B", "text": "Thoracic (triangular) and lumbar (circular)"}, {"key": "C", "text": "Both thoracic and lumbar (circular)"}, {"key": "D", "text": "Both thoracic and lumbar (oval)"}], "correct": "A", "explanation": "Cervical vertebral foramen is triangular, thoracic is circular/round (smallest), and lumbar is triangular (largest)."}, {"id": 840, "subject": "Anatomy", "difficulty": "Hard", "question": "The transverse process of cervical vertebrae is formed by:", "options": [{"key": "A", "text": "Only true transverse process"}, {"key": "B", "text": "Fusion of true transverse process and costal element (costotransverse bar)"}, {"key": "C", "text": "Only costal element"}, {"key": "D", "text": "Pedicle and lamina"}], "correct": "B", "explanation": "Cervical transverse processes have anterior and posterior tubercles connected by a costotransverse bar (costal element) forming the transverse foramen."}, {"id": 841, "subject": "Anatomy", "difficulty": "Medium", "question": "Cervical rib originates from which structure?", "options": [{"key": "A", "text": "C6 costal element"}, {"key": "B", "text": "C7 costal element (enlarged)"}, {"key": "C", "text": "T1 rib"}, {"key": "D", "text": "C5 transverse process"}], "correct": "B", "explanation": "Cervical rib is an enlarged costal element of C7 vertebra that may compress the brachial plexus or subclavian artery (thoracic outlet syndrome)."}, {"id": 842, "subject": "Anatomy", "difficulty": "Hard", "question": "The apophyseal (zygapophyseal/facet) joints of the cervical spine are oriented at:", "options": [{"key": "A", "text": "90 degrees (horizontal)"}, {"key": "B", "text": "45 degrees (between horizontal and vertical)"}, {"key": "C", "text": "Vertical (90 degrees from horizontal)"}, {"key": "D", "text": "Variable angles"}], "correct": "B", "explanation": "Cervical facet joints are oriented at approximately 45 degrees from horizontal, allowing flexion, extension, rotation, and lateral flexion."}, {"id": 843, "subject": "Anatomy", "difficulty": "Easy", "question": "The spinal cord ends (conus medullaris) at which level in adults?", "options": [{"key": "A", "text": "C7-T1"}, {"key": "B", "text": "L1-L2"}, {"key": "C", "text": "L4-L5"}, {"key": "D", "text": "S1"}], "correct": "B", "explanation": "The conus medullaris typically ends at L1-L2 in adults, though the cauda equina extends to S2."}, {"id": 844, "subject": "Anatomy", "difficulty": "Hard", "question": "The ratio of spinal canal diameter to vertebral body diameter (Pavlov's ratio) below which myelopathy risk increases:", "options": [{"key": "A", "text": "Below 0.8"}, {"key": "B", "text": "Below 1.0"}, {"key": "C", "text": "Below 1.5"}, {"key": "D", "text": "Below 0.5"}], "correct": "A", "explanation": "Pavlov's ratio (spinal canal AP diameter / vertebral body AP diameter) below 0.8 indicates developmental canal stenosis with myelopathy risk."}, {"id": 845, "subject": "Anatomy", "difficulty": "Medium", "question": "The transverse ligament of the atlas holds the dens against:", "options": [{"key": "A", "text": "Posterior arch of C1"}, {"key": "B", "text": "Anterior arch of C1"}, {"key": "C", "text": "C2 body posteriorly"}, {"key": "D", "text": "Occipital bone"}], "correct": "B", "explanation": "Transverse ligament holds the dens firmly against the posterior surface of the anterior arch of C1, preventing posterior subluxation."}, {"id": 846, "subject": "Anatomy", "difficulty": "Hard", "question": "The cruciform (cruciate) ligament of the atlas consists of:", "options": [{"key": "A", "text": "Transverse ligament only"}, {"key": "B", "text": "Transverse ligament + superior and inferior longitudinal bands"}, {"key": "C", "text": "Alar ligaments + transverse ligament"}, {"key": "D", "text": "Tectorial membrane + transverse ligament"}], "correct": "B", "explanation": "Cruciform ligament = transverse ligament of atlas + superior band (to occiput) + inferior band (to C2 body)."}, {"id": 847, "subject": "Anatomy", "difficulty": "Hard", "question": "Alar ligaments connect:", "options": [{"key": "A", "text": "C1 to C2"}, {"key": "B", "text": "Dens of axis to lateral margins of foramen magnum"}, {"key": "C", "text": "C2 to C3"}, {"key": "D", "text": "Occiput to C1"}], "correct": "B", "explanation": "Alar ligaments run from the apex of the dens to the lateral margins of the foramen magnum, limiting rotation."}, {"id": 848, "subject": "Anatomy", "difficulty": "Hard", "question": "The tectorial membrane is the upward continuation of:", "options": [{"key": "A", "text": "Anterior longitudinal ligament"}, {"key": "B", "text": "Posterior longitudinal ligament"}, {"key": "C", "text": "Ligamentum flavum"}, {"key": "D", "text": "Supraspinous ligament"}], "correct": "B", "explanation": "Tectorial membrane is the cranial continuation of the posterior longitudinal ligament, attaching to the occipital bone."}, {"id": 849, "subject": "Anatomy", "difficulty": "Hard", "question": "Ligamentum flavum is composed of:", "options": [{"key": "A", "text": "Collagen type I fibers"}, {"key": "B", "text": "Elastin fibers (80%) and collagen"}, {"key": "C", "text": "Fibrocartilage"}, {"key": "D", "text": "Dense irregular connective tissue"}], "correct": "B", "explanation": "Ligamentum flavum has the highest elastin content (80%) of any ligament in the body, allowing spine to return to neutral after flexion."}, {"id": 850, "subject": "Anatomy", "difficulty": "Hard", "question": "The posterior longitudinal ligament (PLL) is:", "options": [{"key": "A", "text": "Broader at disc levels, narrower at vertebral bodies"}, {"key": "B", "text": "Narrower at disc levels, broader at vertebral bodies"}, {"key": "C", "text": "Uniform throughout"}, {"key": "D", "text": "Only present in cervical spine"}], "correct": "A", "explanation": "PLL is broad at disc levels (2x width) and narrow at vertebral bodies, making lateral disc herniation more common."}, {"id": 851, "subject": "Anatomy", "difficulty": "Medium", "question": "OPLL (Ossification of Posterior Longitudinal Ligament) is most common in:", "options": [{"key": "A", "text": "Lumbar spine"}, {"key": "B", "text": "Cervical spine"}, {"key": "C", "text": "Thoracic spine"}, {"key": "D", "text": "Sacrum"}], "correct": "B", "explanation": "OPLL is most common in the cervical spine, particularly in East Asian populations, causing cervical myelopathy."}, {"id": 852, "subject": "Anatomy", "difficulty": "Hard", "question": "The anterior atlanto-axial membrane is an extension of:", "options": [{"key": "A", "text": "Anterior longitudinal ligament (cranially)"}, {"key": "B", "text": "Posterior longitudinal ligament"}, {"key": "C", "text": "Ligamentum flavum"}, {"key": "D", "text": "Tectorial membrane"}], "correct": "A", "explanation": "Anterior atlanto-axial membrane continues the anterior longitudinal ligament between the anterior arches of C1 and C2."}, {"id": 853, "subject": "Anatomy", "difficulty": "Medium", "question": "Cervical facet joint capsule laxity contributes to:", "options": [{"key": "A", "text": "Disc herniation"}, {"key": "B", "text": "Cervical instability and whiplash injury"}, {"key": "C", "text": "Vertebral artery compression"}, {"key": "D", "text": "Cord compression"}], "correct": "B", "explanation": "Facet joint capsule laxity (especially C2-C5) contributes to cervical instability following whiplash or repetitive microtrauma."}, {"id": 854, "subject": "Anatomy", "difficulty": "Medium", "question": "Atlanto-axial instability (AAI) is associated with:", "options": [{"key": "A", "text": "Ankylosing spondylitis"}, {"key": "B", "text": "Down syndrome (trisomy 21)"}, {"key": "C", "text": "Rheumatoid arthritis only"}, {"key": "D", "text": "Both B and C"}], "correct": "D", "explanation": "AAI is associated with both Down syndrome (ligamentous laxity) and rheumatoid arthritis (synovial joint erosion of transverse ligament)."}, {"id": 855, "subject": "Anatomy", "difficulty": "Hard", "question": "The intervertebral disc of the cervical spine has a relatively thin:", "options": [{"key": "A", "text": "Nucleus pulposus"}, {"key": "B", "text": "Annulus fibrosus in the posterior lateral region"}, {"key": "C", "text": "Anterior annulus"}, {"key": "D", "text": "Cartilaginous endplate"}], "correct": "B", "explanation": "The posterolateral annulus is thinnest in the cervical spine, making it the most common site for disc herniation and nerve root compression."}, {"id": 856, "subject": "Anatomy", "difficulty": "Medium", "question": "Uncinate process hypertrophy (spondylosis) in cervical spine most commonly causes:", "options": [{"key": "A", "text": "Disc herniation"}, {"key": "B", "text": "Foraminal stenosis and nerve root compression"}, {"key": "C", "text": "Cord compression alone"}, {"key": "D", "text": "Vertebral artery occlusion"}], "correct": "B", "explanation": "Osteophyte formation at the uncovertebral joints (Luschka) narrows the intervertebral foramen causing radiculopathy."}, {"id": 857, "subject": "Anatomy", "difficulty": "Medium", "question": "In whiplash injury, which structure is most commonly damaged?", "options": [{"key": "A", "text": "Vertebral artery"}, {"key": "B", "text": "Facet joint capsules and disc"}, {"key": "C", "text": "Ligamentum flavum"}, {"key": "D", "text": "Anterior longitudinal ligament only"}], "correct": "B", "explanation": "Whiplash (hyperextension-flexion injury) primarily damages facet joint capsules, disc, and paraspinal muscles."}, {"id": 858, "subject": "Anatomy", "difficulty": "Medium", "question": "The intervertebral foramen of the cervical spine is bounded by:", "options": [{"key": "A", "text": "Only pedicles"}, {"key": "B", "text": "Pedicles above and below, disc and vertebral body anteriorly, facet joint posteriorly"}, {"key": "C", "text": "Laminae and pedicles"}, {"key": "D", "text": "Vertebral bodies only"}], "correct": "B", "explanation": "Cervical IVF boundaries: pedicles (superior/inferior), vertebral body + disc (anterior), facet joint capsule (posterior)."}, {"id": 859, "subject": "Anatomy", "difficulty": "Hard", "question": "Spondylolysis in the cervical spine refers to:", "options": [{"key": "A", "text": "Disc degeneration"}, {"key": "B", "text": "Defect in the pars interarticularis (rare in cervical spine)"}, {"key": "C", "text": "Facet joint arthritis"}, {"key": "D", "text": "Cord compression"}], "correct": "B", "explanation": "Spondylolysis is a stress fracture/defect in the pars interarticularis; very rare in cervical spine unlike lumbar spine."}, {"id": 860, "subject": "Anatomy", "difficulty": "Hard", "question": "The apical ligament of the dens connects:", "options": [{"key": "A", "text": "Dens to transverse ligament"}, {"key": "B", "text": "Tip of dens to anterior margin of foramen magnum"}, {"key": "C", "text": "Dens to alar ligaments"}, {"key": "D", "text": "C1 to occiput"}], "correct": "B", "explanation": "Apical dental ligament connects the tip (apex) of the dens to the anterior margin of the foramen magnum."}, {"id": 861, "subject": "Anatomy", "difficulty": "Hard", "question": "Cervical spine hypomobility pattern in facet joint dysfunction causes:", "options": [{"key": "A", "text": "Capsular pattern: rotation most limited, then lateral flexion"}, {"key": "B", "text": "Equally limited in all directions"}, {"key": "C", "text": "Flexion most limited"}, {"key": "D", "text": "Extension most limited"}], "correct": "A", "explanation": "Cervical facet joint restriction follows a capsular pattern with rotation most limited, followed by lateral flexion."}, {"id": 862, "subject": "Anatomy", "difficulty": "Medium", "question": "The intervertebral disc nucleus pulposus is composed of:", "options": [{"key": "A", "text": "Dense collagen (Type I)"}, {"key": "B", "text": "Hydrophilic proteoglycans and Type II collagen"}, {"key": "C", "text": "Elastin predominantly"}, {"key": "D", "text": "Fibrocartilage throughout"}], "correct": "B", "explanation": "Nucleus pulposus contains water-attracting proteoglycans (aggrecan) and Type II collagen, giving it high water content (70-90%)."}, {"id": 863, "subject": "Anatomy", "difficulty": "Hard", "question": "Normal ADI (atlanto-dens interval) in adults is:", "options": [{"key": "A", "text": "Less than 3 mm"}, {"key": "B", "text": "Less than 5 mm"}, {"key": "C", "text": "5-10 mm"}, {"key": "D", "text": "Less than 1 mm"}], "correct": "A", "explanation": "Normal ADI (distance between anterior arch of C1 and dens) is less than 3 mm in adults; greater than 3 mm indicates ligamentous instability."}, {"id": 864, "subject": "Anatomy", "difficulty": "Hard", "question": "In children, normal ADI (atlanto-dens interval) is:", "options": [{"key": "A", "text": "Less than 3 mm"}, {"key": "B", "text": "Less than 5 mm"}, {"key": "C", "text": "Less than 7 mm"}, {"key": "D", "text": "Less than 10 mm"}], "correct": "B", "explanation": "In children, normal ADI can be up to 5 mm due to greater ligamentous laxity; adults 3 mm threshold applies differently."}, {"id": 865, "subject": "Anatomy", "difficulty": "Medium", "question": "The cervical zygapophyseal (facet) joints are classified as:", "options": [{"key": "A", "text": "Fibrous joints"}, {"key": "B", "text": "Cartilaginous joints"}, {"key": "C", "text": "Synovial plane joints"}, {"key": "D", "text": "Condyloid joints"}], "correct": "C", "explanation": "Cervical facet joints are synovial plane (gliding) joints with a joint capsule, synovial membrane, and articular cartilage."}, {"id": 866, "subject": "Anatomy", "difficulty": "Hard", "question": "Cervical instability is defined radiologically as translation greater than:", "options": [{"key": "A", "text": "2 mm"}, {"key": "B", "text": "3.5 mm or angulation >11 degrees"}, {"key": "C", "text": "5 mm"}, {"key": "D", "text": "1 mm"}], "correct": "B", "explanation": "White and Panjabi criteria: cervical instability = translation >3.5 mm or angular difference >11 degrees on flexion-extension X-ray."}, {"id": 867, "subject": "Anatomy", "difficulty": "Hard", "question": "The subaxial cervical spine (C3-C7) allows maximum rotation at which level?", "options": [{"key": "A", "text": "C3-C4"}, {"key": "B", "text": "C4-C5"}, {"key": "C", "text": "C6-C7"}, {"key": "D", "text": "Equal at all levels"}], "correct": "B", "explanation": "C4-C5 level contributes significantly to cervical rotation; however, combined C3-C5 segments provide greatest subaxial rotation."}, {"id": 868, "subject": "Anatomy", "difficulty": "Medium", "question": "Rheumatoid arthritis affects the cervical spine most commonly at:", "options": [{"key": "A", "text": "C5-C6 disc"}, {"key": "B", "text": "Atlantoaxial joint (C1-C2)"}, {"key": "C", "text": "C6-C7 facets"}, {"key": "D", "text": "Cervicothoracic junction"}], "correct": "B", "explanation": "RA most commonly causes atlantoaxial subluxation due to synovitis eroding the transverse ligament holding the dens."}, {"id": 869, "subject": "Anatomy", "difficulty": "Hard", "question": "The posterior atlanto-occipital membrane covers:", "options": [{"key": "A", "text": "Foramen magnum posteriorly and connects to C1 posterior arch"}, {"key": "B", "text": "Anterior foramen magnum"}, {"key": "C", "text": "C1 to C2 posteriorly"}, {"key": "D", "text": "Entire posterior cervical spine"}], "correct": "A", "explanation": "Posterior atlanto-occipital membrane spans from the posterior margin of foramen magnum to the posterior arch of C1."}, {"id": 870, "subject": "Anatomy", "difficulty": "Easy", "question": "Sternocleidomastoid (SCM) originates from:", "options": [{"key": "A", "text": "Mastoid process only"}, {"key": "B", "text": "Sternum and clavicle, inserts into mastoid process and superior nuchal line"}, {"key": "C", "text": "Occiput and mastoid"}, {"key": "D", "text": "Cervical vertebrae and mastoid"}], "correct": "B", "explanation": "SCM has two heads: sternal head (manubrium) and clavicular head, inserting into mastoid process and superior nuchal line."}, {"id": 871, "subject": "Anatomy", "difficulty": "Medium", "question": "Unilateral contraction of SCM produces:", "options": [{"key": "A", "text": "Ipsilateral rotation"}, {"key": "B", "text": "Ipsilateral lateral flexion and contralateral rotation"}, {"key": "C", "text": "Contralateral lateral flexion only"}, {"key": "D", "text": "Bilateral flexion"}], "correct": "B", "explanation": "SCM acting unilaterally: lateral flexes head to same side and rotates face to opposite side."}, {"id": 872, "subject": "Anatomy", "difficulty": "Easy", "question": "SCM is innervated by:", "options": [{"key": "A", "text": "Facial nerve (CN VII)"}, {"key": "B", "text": "Accessory nerve (CN XI) and C2, C3"}, {"key": "C", "text": "Vagus nerve (CN X)"}, {"key": "D", "text": "Hypoglossal nerve (CN XII)"}], "correct": "B", "explanation": "SCM is supplied by spinal accessory nerve (CN XI) for motor function and C2, C3 for proprioception/pain."}, {"id": 873, "subject": "Anatomy", "difficulty": "Hard", "question": "The deepest layer of cervical muscles (suboccipital muscles) includes:", "options": [{"key": "A", "text": "Trapezius and SCM"}, {"key": "B", "text": "Rectus capitis posterior major/minor and obliquus capitis superior/inferior"}, {"key": "C", "text": "Semispinalis capitis and splenius"}, {"key": "D", "text": "Longus colli and longus capitis"}], "correct": "B", "explanation": "Suboccipital muscles: rectus capitis posterior major, rectus capitis posterior minor, obliquus capitis superior, obliquus capitis inferior."}, {"id": 874, "subject": "Anatomy", "difficulty": "Hard", "question": "The suboccipital triangle is bounded by:", "options": [{"key": "A", "text": "Three SCM muscles"}, {"key": "B", "text": "Rectus capitis posterior major, obliquus capitis superior, obliquus capitis inferior"}, {"key": "C", "text": "Trapezius and semispinalis"}, {"key": "D", "text": "Splenius capitis and semispinalis"}], "correct": "B", "explanation": "Suboccipital triangle borders: RCP major (medial), obliquus superior (lateral), obliquus inferior (inferior); contains vertebral artery and suboccipital nerve."}, {"id": 875, "subject": "Anatomy", "difficulty": "Hard", "question": "The suboccipital nerve (C1 dorsal ramus) supplies:", "options": [{"key": "A", "text": "Skin of posterior head"}, {"key": "B", "text": "Suboccipital muscles (motor only)"}, {"key": "C", "text": "SCM and trapezius"}, {"key": "D", "text": "Semispinalis capitis"}], "correct": "B", "explanation": "C1 dorsal ramus (suboccipital nerve) is purely motor, supplying the four suboccipital muscles with no cutaneous branch."}, {"id": 876, "subject": "Anatomy", "difficulty": "Medium", "question": "Longus colli and longus capitis are:", "options": [{"key": "A", "text": "Posterior cervical muscles"}, {"key": "B", "text": "Deep anterior (prevertebral) cervical flexors"}, {"key": "C", "text": "Lateral cervical muscles"}, {"key": "D", "text": "Superficial flexors"}], "correct": "B", "explanation": "Longus colli and longus capitis are deep prevertebral muscles — primary deep cervical flexors stabilizing the craniovertebral junction."}, {"id": 877, "subject": "Anatomy", "difficulty": "Medium", "question": "Cranio-cervical flexion test (CCFT) assesses the function of:", "options": [{"key": "A", "text": "SCM and anterior scalenes"}, {"key": "B", "text": "Deep cervical flexors (longus colli, longus capitis)"}, {"key": "C", "text": "Trapezius upper fibers"}, {"key": "D", "text": "Suboccipital muscles"}], "correct": "B", "explanation": "CCFT uses pressure biofeedback to assess deep cervical flexor (longus colli/capitis) activation during nodding, important in neck pain."}, {"id": 878, "subject": "Anatomy", "difficulty": "Medium", "question": "The scalene muscles originate from cervical transverse processes and insert into:", "options": [{"key": "A", "text": "Clavicle"}, {"key": "B", "text": "First and second ribs"}, {"key": "C", "text": "Sternum"}, {"key": "D", "text": "Manubrium"}], "correct": "B", "explanation": "Anterior and middle scalenes insert into the first rib; posterior scalene inserts into the second rib."}, {"id": 879, "subject": "Anatomy", "difficulty": "Medium", "question": "Scalene muscles function as:", "options": [{"key": "A", "text": "Primary cervical extensors"}, {"key": "B", "text": "Accessory inspiratory muscles and lateral cervical flexors"}, {"key": "C", "text": "Primary cervical flexors"}, {"key": "D", "text": "Neck rotators only"}], "correct": "B", "explanation": "Scalenes elevate the first and second ribs (inspiration) and flex/laterally flex the cervical spine."}, {"id": 880, "subject": "Anatomy", "difficulty": "Medium", "question": "Cervical scalene muscle tightness can compress the brachial plexus causing:", "options": [{"key": "A", "text": "Carpal tunnel syndrome"}, {"key": "B", "text": "Thoracic outlet syndrome"}, {"key": "C", "text": "Cervical myelopathy"}, {"key": "D", "text": "Ulnar nerve entrapment at elbow"}], "correct": "B", "explanation": "Tight scalenes can compress the brachial plexus between anterior and middle scalenes (interscalene triangle), causing thoracic outlet syndrome."}, {"id": 881, "subject": "Anatomy", "difficulty": "Easy", "question": "Trapezius is innervated by:", "options": [{"key": "A", "text": "C3, C4 nerve roots only"}, {"key": "B", "text": "Spinal accessory nerve (CN XI) and C3, C4"}, {"key": "C", "text": "Dorsal scapular nerve"}, {"key": "D", "text": "Long thoracic nerve"}], "correct": "B", "explanation": "Trapezius is supplied by spinal accessory nerve (CN XI) for motor and C3, C4 for proprioception and sensation."}, {"id": 882, "subject": "Anatomy", "difficulty": "Medium", "question": "Semispinalis capitis is the largest muscle of the:", "options": [{"key": "A", "text": "Anterior neck"}, {"key": "B", "text": "Posterior neck (nuchal region)"}, {"key": "C", "text": "Lateral neck"}, {"key": "D", "text": "Deep prevertebral region"}], "correct": "B", "explanation": "Semispinalis capitis is the largest and most superficial of the deep cervical extensors in the posterior neck."}, {"id": 883, "subject": "Anatomy", "difficulty": "Medium", "question": "The greater occipital nerve (C2 dorsal ramus) supplies:", "options": [{"key": "A", "text": "Anterior scalp"}, {"key": "B", "text": "Posterior scalp sensation and suboccipital area"}, {"key": "C", "text": "Face and forehead"}, {"key": "D", "text": "Anterior neck skin"}], "correct": "B", "explanation": "Greater occipital nerve (medial branch of C2 dorsal ramus) supplies sensation to posterior scalp up to vertex of head."}, {"id": 884, "subject": "Anatomy", "difficulty": "Medium", "question": "Occipital neuralgia involves irritation of:", "options": [{"key": "A", "text": "Lesser occipital nerve only"}, {"key": "B", "text": "Greater occipital nerve (C2)"}, {"key": "C", "text": "Supraorbital nerve"}, {"key": "D", "text": "Auriculotemporal nerve"}], "correct": "B", "explanation": "Occipital neuralgia is characterized by paroxysmal shooting pain in the C2 (greater occipital nerve) distribution over the posterior scalp."}, {"id": 885, "subject": "Anatomy", "difficulty": "Hard", "question": "The nerve to subclavius and phrenic nerve arise from:", "options": [{"key": "A", "text": "Brachial plexus"}, {"key": "B", "text": "Cervical plexus (C3, C4, C5)"}, {"key": "C", "text": "Cranial nerves"}, {"key": "D", "text": "Thoracic plexus"}], "correct": "B", "explanation": "Phrenic nerve arises from C3, C4, C5 (cervical plexus); C4 is the primary root. Nerve to subclavius from C5."}, {"id": 886, "subject": "Anatomy", "difficulty": "Easy", "question": "During cervical stabilization exercises, the 'chin tuck' exercise activates:", "options": [{"key": "A", "text": "Upper trapezius and SCM"}, {"key": "B", "text": "Deep cervical flexors (longus colli)"}, {"key": "C", "text": "Suboccipital extensors"}, {"key": "D", "text": "Scalenes primarily"}], "correct": "B", "explanation": "Chin tuck (craniocervical flexion) activates deep cervical flexors (especially longus colli) and inhibits superficial flexors (SCM)."}, {"id": 887, "subject": "Anatomy", "difficulty": "Medium", "question": "Levator scapulae originates from:", "options": [{"key": "A", "text": "Spinous processes C1-C4"}, {"key": "B", "text": "Transverse processes C1-C4"}, {"key": "C", "text": "Spinous processes C4-C7"}, {"key": "D", "text": "Occiput and C1"}], "correct": "B", "explanation": "Levator scapulae originates from transverse processes of C1-C4 and inserts into the medial border/superior angle of the scapula."}, {"id": 888, "subject": "Anatomy", "difficulty": "Medium", "question": "Splenius capitis muscle action:", "options": [{"key": "A", "text": "Bilateral — flex neck; unilateral — rotate to opposite side"}, {"key": "B", "text": "Bilateral — extend head and neck; unilateral — rotate and laterally flex to same side"}, {"key": "C", "text": "Only lateral flexion"}, {"key": "D", "text": "Protrudes head forward"}], "correct": "B", "explanation": "Splenius capitis bilaterally extends the head; unilaterally it rotates and laterally flexes the head to the same side."}, {"id": 889, "subject": "Anatomy", "difficulty": "Hard", "question": "The anterior scalene muscle interval (interscalene triangle) is bounded by:", "options": [{"key": "A", "text": "SCM anteriorly, trapezius posteriorly"}, {"key": "B", "text": "Anterior scalene (medially), middle scalene (laterally), first rib (inferiorly)"}, {"key": "C", "text": "Two scalenes and clavicle"}, {"key": "D", "text": "Scalenes and SCM"}], "correct": "B", "explanation": "Interscalene triangle: anterior scalene medially, middle scalene laterally, first rib inferiorly — brachial plexus and subclavian artery pass through it."}, {"id": 890, "subject": "Anatomy", "difficulty": "Hard", "question": "Multifidus in the cervical spine plays a primary role in:", "options": [{"key": "A", "text": "Gross movement generation"}, {"key": "B", "text": "Intersegmental stability and proprioception"}, {"key": "C", "text": "Neck rotation"}, {"key": "D", "text": "Head extension"}], "correct": "B", "explanation": "Cervical multifidus provides fine intersegmental control and spinal stability; its dysfunction is associated with chronic neck pain."}, {"id": 891, "subject": "Anatomy", "difficulty": "Easy", "question": "Torticollis (wry neck) most commonly involves spasm of:", "options": [{"key": "A", "text": "Trapezius"}, {"key": "B", "text": "SCM (sternocleidomastoid)"}, {"key": "C", "text": "Levator scapulae"}, {"key": "D", "text": "Scalenes"}], "correct": "B", "explanation": "Torticollis presents with head tilted to ipsilateral side and face rotated to contralateral side due to SCM spasm/contracture."}, {"id": 892, "subject": "Anatomy", "difficulty": "Medium", "question": "Congenital muscular torticollis is caused by:", "options": [{"key": "A", "text": "C1-C2 bony anomaly"}, {"key": "B", "text": "Fibrosis of SCM (from birth trauma or ischemia)"}, {"key": "C", "text": "SCM nerve palsy"}, {"key": "D", "text": "Suboccipital muscle spasm"}], "correct": "B", "explanation": "Congenital muscular torticollis results from fibrosis and shortening of the SCM, often from difficult delivery or intrauterine positioning."}, {"id": 893, "subject": "Anatomy", "difficulty": "Hard", "question": "The rectus capitis posterior minor connects:", "options": [{"key": "A", "text": "C2 spinous process to occiput"}, {"key": "B", "text": "C1 posterior tubercle to occiput (medial inferior nuchal line)"}, {"key": "C", "text": "C1 lateral mass to occiput"}, {"key": "D", "text": "C2 to C1"}], "correct": "B", "explanation": "Rectus capitis posterior minor originates from C1 posterior tubercle and inserts into medial inferior nuchal line of occiput."}, {"id": 894, "subject": "Anatomy", "difficulty": "Medium", "question": "Which muscle group is responsible for forward head posture perpetuation?", "options": [{"key": "A", "text": "Deep cervical flexors"}, {"key": "B", "text": "Suboccipital extensors and upper trapezius (short/tight)"}, {"key": "C", "text": "SCM bilaterally"}, {"key": "D", "text": "Scalene muscles"}], "correct": "B", "explanation": "Forward head posture involves tight suboccipital extensors/upper trapezius and weak deep cervical flexors, creating a characteristic muscle imbalance."}, {"id": 895, "subject": "Anatomy", "difficulty": "Easy", "question": "The cervical plexus is formed by ventral rami of:", "options": [{"key": "A", "text": "C1-C3"}, {"key": "B", "text": "C1-C4"}, {"key": "C", "text": "C2-C5"}, {"key": "D", "text": "C1-C5"}], "correct": "B", "explanation": "Cervical plexus is formed by the ventral (anterior) rami of C1-C4 spinal nerves."}, {"id": 896, "subject": "Anatomy", "difficulty": "Easy", "question": "The brachial plexus is formed by ventral rami of:", "options": [{"key": "A", "text": "C4-C8"}, {"key": "B", "text": "C5-T1"}, {"key": "C", "text": "C5-T2"}, {"key": "D", "text": "C4-T1"}], "correct": "B", "explanation": "Brachial plexus arises from ventral rami of C5, C6, C7, C8, and T1 nerve roots."}, {"id": 897, "subject": "Anatomy", "difficulty": "Easy", "question": "C5 nerve root compression (C4-C5 disc) causes weakness of:", "options": [{"key": "A", "text": "Wrist extensors"}, {"key": "B", "text": "Shoulder abduction (deltoid) and elbow flexion"}, {"key": "C", "text": "Finger extensors"}, {"key": "D", "text": "Elbow extension"}], "correct": "B", "explanation": "C5 radiculopathy: weakness of deltoid (axillary n.) and biceps (musculocutaneous n.) with sensory loss over lateral arm."}, {"id": 898, "subject": "Anatomy", "difficulty": "Medium", "question": "C6 nerve root compression (C5-C6 disc) causes weakness of:", "options": [{"key": "A", "text": "Elbow extension and wrist flexion"}, {"key": "B", "text": "Wrist extension (ECRL, ECRB) and elbow flexion, with lateral forearm/thumb numbness"}, {"key": "C", "text": "Finger extension"}, {"key": "D", "text": "Intrinsic hand muscles"}], "correct": "B", "explanation": "C6 radiculopathy: weak wrist extensors and biceps, reduced brachioradialis reflex, sensory loss in lateral forearm, thumb and index finger."}, {"id": 899, "subject": "Anatomy", "difficulty": "Medium", "question": "C7 nerve root compression (C6-C7 disc) causes weakness of:", "options": [{"key": "A", "text": "Shoulder abduction"}, {"key": "B", "text": "Elbow extension (triceps) and wrist flexion, with middle finger numbness"}, {"key": "C", "text": "Wrist extension"}, {"key": "D", "text": "Intrinsic hand muscles"}], "correct": "B", "explanation": "C7 radiculopathy: weak triceps and wrist flexors, reduced triceps reflex, sensory loss in middle finger."}, {"id": 900, "subject": "Anatomy", "difficulty": "Medium", "question": "C8 nerve root compression (C7-T1 disc) causes:", "options": [{"key": "A", "text": "Biceps weakness"}, {"key": "B", "text": "Intrinsic hand muscle weakness (interossei) with medial forearm/ring-little finger numbness"}, {"key": "C", "text": "Shoulder weakness"}, {"key": "D", "text": "Wrist extension weakness"}], "correct": "B", "explanation": "C8 radiculopathy: weak intrinsics (finger abduction/adduction), reduced finger flexor reflex, sensory loss in medial forearm and ring/little fingers."}, {"id": 901, "subject": "Anatomy", "difficulty": "Easy", "question": "The reflex tested for C5-C6 level is:", "options": [{"key": "A", "text": "Triceps reflex"}, {"key": "B", "text": "Biceps and brachioradialis reflex"}, {"key": "C", "text": "Finger flexor reflex"}, {"key": "D", "text": "Jaw jerk"}], "correct": "B", "explanation": "Biceps reflex tests C5-C6; brachioradialis reflex primarily tests C6."}, {"id": 902, "subject": "Anatomy", "difficulty": "Easy", "question": "The triceps reflex tests which nerve root?", "options": [{"key": "A", "text": "C5"}, {"key": "B", "text": "C6"}, {"key": "C", "text": "C7"}, {"key": "D", "text": "C8"}], "correct": "C", "explanation": "Triceps jerk tests C7 nerve root via the radial nerve."}, {"id": 903, "subject": "Anatomy", "difficulty": "Hard", "question": "Horner's syndrome in cervical spine lesions involves:", "options": [{"key": "A", "text": "C5-C6 sympathetic fibers"}, {"key": "B", "text": "C8-T1 sympathetic fiber involvement (stellate ganglion)"}, {"key": "C", "text": "C3-C4 level"}, {"key": "D", "text": "Vagus nerve"}], "correct": "B", "explanation": "Cervical sympathetic chain (stellate ganglion at C7-T1) injury causes Horner's: ptosis, miosis, anhidrosis, enophthalmos."}, {"id": 904, "subject": "Anatomy", "difficulty": "Medium", "question": "The phrenic nerve (C3, C4, C5) innervates the diaphragm; injury above C4 causes:", "options": [{"key": "A", "text": "Partial respiratory weakness"}, {"key": "B", "text": "Complete respiratory paralysis (ventilator dependence)"}, {"key": "C", "text": "Intercostal muscle weakness only"}, {"key": "D", "text": "No respiratory effect"}], "correct": "B", "explanation": "Complete cervical cord injury above C4 paralyzes the phrenic nerve, causing apnea and requiring mechanical ventilation."}, {"id": 905, "subject": "Anatomy", "difficulty": "Medium", "question": "Cervical myelopathy signs include all EXCEPT:", "options": [{"key": "A", "text": "Hyperreflexia below lesion"}, {"key": "B", "text": "L'hermitte's sign"}, {"key": "C", "text": "Hoffman's sign"}, {"key": "D", "text": "Hyporeflexia below lesion"}], "correct": "D", "explanation": "Myelopathy (UMN lesion) causes hyperreflexia, positive Hoffman's sign, L'hermitte's sign, and clonus — NOT hyporeflexia."}, {"id": 906, "subject": "Anatomy", "difficulty": "Easy", "question": "Hoffman's sign tests for:", "options": [{"key": "A", "text": "Lower motor neuron lesion"}, {"key": "B", "text": "Upper motor neuron lesion (cervical myelopathy)"}, {"key": "C", "text": "Nerve root compression"}, {"key": "D", "text": "Peripheral neuropathy"}], "correct": "B", "explanation": "Hoffman's sign: flicking the middle fingernail produces reflex flexion of thumb and index finger, indicating UMN/myelopathy."}, {"id": 907, "subject": "Anatomy", "difficulty": "Medium", "question": "L'hermitte's sign (barber chair phenomenon) is:", "options": [{"key": "A", "text": "Pain on neck extension radiating to arms"}, {"key": "B", "text": "Electric shock-like sensation down the spine with neck flexion"}, {"key": "C", "text": "Shoulder pain with rotation"}, {"key": "D", "text": "Arm pain with Valsalva"}], "correct": "B", "explanation": "L'hermitte's sign: neck flexion causes electric shock-like sensation down the spine/limbs due to mechanical irritation of posterior columns."}, {"id": 908, "subject": "Anatomy", "difficulty": "Easy", "question": "Spurling's test (cervical compression test) is positive when:", "options": [{"key": "A", "text": "Distraction relieves arm pain"}, {"key": "B", "text": "Axial compression + lateral flexion toward symptomatic side reproduces arm pain"}, {"key": "C", "text": "Rotation away from pain reproduces symptoms"}, {"key": "D", "text": "Pain increases with neck flexion"}], "correct": "B", "explanation": "Spurling's: axial load with lateral flexion toward painful side narrows the foramen and reproduces radicular arm pain."}, {"id": 909, "subject": "Anatomy", "difficulty": "Easy", "question": "Cervical distraction test is positive when:", "options": [{"key": "A", "text": "Arm pain increases with traction"}, {"key": "B", "text": "Arm pain is relieved by manual traction (reduces foraminal compression)"}, {"key": "C", "text": "Neck pain increases"}, {"key": "D", "text": "Headache worsens"}], "correct": "B", "explanation": "Cervical distraction test: manual upward traction opens the foramina; relief of arm/radicular pain = positive (suggests radiculopathy)."}, {"id": 910, "subject": "Anatomy", "difficulty": "Hard", "question": "Upper limb tension test (ULTT1) primarily tests which nerve?", "options": [{"key": "A", "text": "Ulnar nerve"}, {"key": "B", "text": "Median nerve (C6, C7)"}, {"key": "C", "text": "Radial nerve"}, {"key": "D", "text": "Axillary nerve"}], "correct": "B", "explanation": "ULTT1 (median nerve bias): shoulder depression, abduction, ER, elbow extension, wrist/finger extension — tests median nerve mechanosensitivity."}, {"id": 911, "subject": "Anatomy", "difficulty": "Medium", "question": "The dorsal root ganglion (DRG) of cervical nerve roots is located:", "options": [{"key": "A", "text": "Within the spinal cord"}, {"key": "B", "text": "In the intervertebral foramen"}, {"key": "C", "text": "Posterior to the vertebral body"}, {"key": "D", "text": "Within the vertebral canal only"}], "correct": "B", "explanation": "DRG is located in the intervertebral foramen (or just medial to it), making it susceptible to compression from disc herniation or osteophytes."}, {"id": 912, "subject": "Anatomy", "difficulty": "Hard", "question": "C2 nerve root emerges between:", "options": [{"key": "A", "text": "Occiput and C1"}, {"key": "B", "text": "C1 and C2 (above C2 pedicle)"}, {"key": "C", "text": "C2 and C3"}, {"key": "D", "text": "C1 posterior arch"}], "correct": "B", "explanation": "C2 nerve root emerges between the posterior arch of C1 and the lamina of C2 (above C2 pedicle), unlike lower cervical roots."}, {"id": 913, "subject": "Anatomy", "difficulty": "Hard", "question": "In the cervical spine, nerve roots exit:", "options": [{"key": "A", "text": "Above their corresponding vertebrae (C1 exits above C1)"}, {"key": "B", "text": "Below their corresponding vertebrae except C1-C7 exit above; C8 exits below C7"}, {"key": "C", "text": "Always below the corresponding vertebra"}, {"key": "D", "text": "Between same-numbered vertebrae"}], "correct": "B", "explanation": "C1-C7 roots exit above their corresponding vertebra; C8 exits between C7 and T1 (there is no C8 vertebra)."}, {"id": 914, "subject": "Anatomy", "difficulty": "Medium", "question": "The greater auricular nerve (C2, C3) supplies sensation to:", "options": [{"key": "A", "text": "Anterior neck"}, {"key": "B", "text": "Skin over parotid, ear, and angle of mandible"}, {"key": "C", "text": "Posterior scalp"}, {"key": "D", "text": "Skin of upper chest"}], "correct": "B", "explanation": "Greater auricular nerve (cervical plexus C2, C3) supplies skin over parotid gland, lower ear, and angle of mandible."}, {"id": 915, "subject": "Anatomy", "difficulty": "Medium", "question": "Axillary nerve (C5, C6) arises from:", "options": [{"key": "A", "text": "Cervical plexus"}, {"key": "B", "text": "Posterior cord of brachial plexus"}, {"key": "C", "text": "Medial cord of brachial plexus"}, {"key": "D", "text": "Lateral cord of brachial plexus"}], "correct": "B", "explanation": "Axillary nerve arises from the posterior cord (C5, C6) of brachial plexus and supplies deltoid and teres minor."}, {"id": 916, "subject": "Anatomy", "difficulty": "Medium", "question": "Erb's palsy (upper brachial plexus palsy) involves:", "options": [{"key": "A", "text": "C8, T1 roots"}, {"key": "B", "text": "C5, C6 roots"}, {"key": "C", "text": "C7 root isolated"}, {"key": "D", "text": "C6, C7 roots"}], "correct": "B", "explanation": "Erb's palsy results from traction injury to C5-C6 roots; classic 'waiter's tip' position: arm adducted, IR, extended, pronated."}, {"id": 917, "subject": "Anatomy", "difficulty": "Medium", "question": "Klumpke's palsy (lower brachial plexus palsy) involves:", "options": [{"key": "A", "text": "C5, C6 roots"}, {"key": "B", "text": "C8, T1 roots (with possible Horner's syndrome)"}, {"key": "C", "text": "C7 root only"}, {"key": "D", "text": "C5, C6, C7 roots"}], "correct": "B", "explanation": "Klumpke's palsy (C8-T1) causes intrinsic hand weakness and claw hand; Horner's syndrome if T1 sympathetic fibers involved."}, {"id": 918, "subject": "Anatomy", "difficulty": "Hard", "question": "Thoracic outlet syndrome involving neurogenic type most commonly compresses:", "options": [{"key": "A", "text": "Median nerve in carpal tunnel"}, {"key": "B", "text": "Lower trunk of brachial plexus (C8-T1) at thoracic outlet"}, {"key": "C", "text": "Radial nerve at lateral epicondyle"}, {"key": "D", "text": "Ulnar nerve at cubital tunnel"}], "correct": "B", "explanation": "Neurogenic TOS compresses the lower trunk (C8-T1) between anterior/middle scalenes or cervical rib, causing medial arm/hand symptoms."}, {"id": 919, "subject": "Anatomy", "difficulty": "Medium", "question": "The nerve root most commonly affected in cervical disc herniation is:", "options": [{"key": "A", "text": "C4"}, {"key": "B", "text": "C6 (at C5-C6 level)"}, {"key": "C", "text": "C8"}, {"key": "D", "text": "C5"}], "correct": "B", "explanation": "C6 nerve root is most commonly compressed in cervical disc herniation (C5-C6 being the most common herniation level)."}, {"id": 920, "subject": "Anatomy", "difficulty": "Easy", "question": "How many thoracic vertebrae are present in human spine?", "options": [{"key": "A", "text": "10"}, {"key": "B", "text": "12"}, {"key": "C", "text": "14"}, {"key": "D", "text": "7"}], "correct": "B", "explanation": "Thoracic spine has 12 vertebrae (T1-T12), each articulating with a pair of ribs."}, {"id": 921, "subject": "Anatomy", "difficulty": "Easy", "question": "Which feature is unique to thoracic vertebrae?", "options": [{"key": "A", "text": "Bifid spinous process"}, {"key": "B", "text": "Costal facets for rib articulation"}, {"key": "C", "text": "Transverse foramen"}, {"key": "D", "text": "Large vertebral body"}], "correct": "B", "explanation": "Costal facets (superior, inferior, and transverse) are unique to thoracic vertebrae for rib attachment."}, {"id": 922, "subject": "Anatomy", "difficulty": "Medium", "question": "The spinous processes of mid-thoracic vertebrae (T5-T8) are directed:", "options": [{"key": "A", "text": "Horizontally"}, {"key": "B", "text": "Superiorly"}, {"key": "C", "text": "Steeply inferiorly"}, {"key": "D", "text": "Laterally"}], "correct": "C", "explanation": "T5-T8 spinous processes are steeply inferiorly directed, overlapping the vertebra below."}, {"id": 923, "subject": "Anatomy", "difficulty": "Medium", "question": "Which thoracic vertebra has the longest spinous process?", "options": [{"key": "A", "text": "T1"}, {"key": "B", "text": "T7"}, {"key": "C", "text": "T10"}, {"key": "D", "text": "T12"}], "correct": "B", "explanation": "T7 has the longest and most inferiorly directed spinous process in the thoracic region."}, {"id": 924, "subject": "Anatomy", "difficulty": "Easy", "question": "The vertebra prominens refers to which vertebra?", "options": [{"key": "A", "text": "T1"}, {"key": "B", "text": "C6"}, {"key": "C", "text": "C7"}, {"key": "D", "text": "T2"}], "correct": "C", "explanation": "C7 is called vertebra prominens due to its long, non-bifid spinous process, easily palpable."}, {"id": 925, "subject": "Anatomy", "difficulty": "Hard", "question": "Which thoracic vertebrae have ONLY superior and inferior costal facets (no transverse costal facet)?", "options": [{"key": "A", "text": "T1 and T2"}, {"key": "B", "text": "T10, T11, T12"}, {"key": "C", "text": "T5 and T6"}, {"key": "D", "text": "T3 and T4"}], "correct": "B", "explanation": "T10-T12 ribs articulate only with the body (not transverse process), so no transverse costal facets."}, {"id": 926, "subject": "Anatomy", "difficulty": "Medium", "question": "The pedicles of thoracic vertebrae arise from:", "options": [{"key": "A", "text": "Posterior body"}, {"key": "B", "text": "Upper part of vertebral body"}, {"key": "C", "text": "Junction of body and lamina"}, {"key": "D", "text": "Transverse process"}], "correct": "B", "explanation": "Pedicles arise from the upper part of the posterior surface of vertebral body in thoracic region."}, {"id": 927, "subject": "Anatomy", "difficulty": "Hard", "question": "T1 vertebra resembles which cervical vertebra in structure?", "options": [{"key": "A", "text": "C3"}, {"key": "B", "text": "C5"}, {"key": "C", "text": "C7"}, {"key": "D", "text": "C4"}], "correct": "C", "explanation": "T1 has a long non-bifid spinous process and a large superior costal facet, resembling C7."}, {"id": 928, "subject": "Anatomy", "difficulty": "Medium", "question": "Which feature distinguishes T12 from other thoracic vertebrae?", "options": [{"key": "A", "text": "Has no costal facets"}, {"key": "B", "text": "Has inferior articular facets like lumbar"}, {"key": "C", "text": "Has bifid spinous process"}, {"key": "D", "text": "Has transverse foramen"}], "correct": "B", "explanation": "T12 has inferior articular facets oriented like lumbar vertebrae (laterally facing), aiding transition."}, {"id": 929, "subject": "Anatomy", "difficulty": "Medium", "question": "The superior costal facets of thoracic vertebrae are located:", "options": [{"key": "A", "text": "On transverse process"}, {"key": "B", "text": "On upper posterolateral body"}, {"key": "C", "text": "On lamina"}, {"key": "D", "text": "On inferior pedicle"}], "correct": "B", "explanation": "Superior costal facets are on the upper posterolateral part of the vertebral body."}, {"id": 930, "subject": "Anatomy", "difficulty": "Easy", "question": "How many lumbar vertebrae are typically present?", "options": [{"key": "A", "text": "4"}, {"key": "B", "text": "5"}, {"key": "C", "text": "6"}, {"key": "D", "text": "3"}], "correct": "B", "explanation": "There are 5 lumbar vertebrae (L1-L5) in the normal human spine."}, {"id": 931, "subject": "Anatomy", "difficulty": "Easy", "question": "The largest vertebrae in the vertebral column are:", "options": [{"key": "A", "text": "Cervical"}, {"key": "B", "text": "Thoracic"}, {"key": "C", "text": "Lumbar"}, {"key": "D", "text": "Sacral"}], "correct": "C", "explanation": "Lumbar vertebrae have the largest and most massive bodies to bear maximum body weight."}, {"id": 932, "subject": "Anatomy", "difficulty": "Hard", "question": "The accessory process in lumbar vertebrae is a remnant of:", "options": [{"key": "A", "text": "Transverse process"}, {"key": "B", "text": "Costal element"}, {"key": "C", "text": "Superior articular process"}, {"key": "D", "text": "Spinous process"}], "correct": "B", "explanation": "The accessory process is a remnant of the true transverse process (costal element)."}, {"id": 933, "subject": "Anatomy", "difficulty": "Medium", "question": "The mamillary process is found on which structure of lumbar vertebra?", "options": [{"key": "A", "text": "Transverse process"}, {"key": "B", "text": "Spinous process"}, {"key": "C", "text": "Superior articular process"}, {"key": "D", "text": "Inferior articular process"}], "correct": "C", "explanation": "Mamillary process is a bony projection on the posterior surface of the superior articular process."}, {"id": 934, "subject": "Anatomy", "difficulty": "Medium", "question": "The orientation of lumbar facet joints is:", "options": [{"key": "A", "text": "Coronal plane"}, {"key": "B", "text": "Sagittal plane"}, {"key": "C", "text": "Sagittal/parasagittal plane"}, {"key": "D", "text": "Oblique 45°"}], "correct": "C", "explanation": "Lumbar facets are oriented in the sagittal/parasagittal plane, limiting rotation but allowing flexion/extension."}, {"id": 935, "subject": "Anatomy", "difficulty": "Medium", "question": "Which lumbar vertebra is most commonly involved in spondylolysis?", "options": [{"key": "A", "text": "L1"}, {"key": "B", "text": "L3"}, {"key": "C", "text": "L5"}, {"key": "D", "text": "L2"}], "correct": "C", "explanation": "L5 is most commonly affected in spondylolysis, a defect in the pars interarticularis."}, {"id": 936, "subject": "Anatomy", "difficulty": "Medium", "question": "The lumbosacral angle is normally:", "options": [{"key": "A", "text": "10-15°"}, {"key": "B", "text": "30-34°"}, {"key": "C", "text": "20-22°"}, {"key": "D", "text": "45-50°"}], "correct": "B", "explanation": "Normal lumbosacral angle (Ferguson's angle) is approximately 30-34°."}, {"id": 937, "subject": "Anatomy", "difficulty": "Hard", "question": "The transverse processes of lumbar vertebrae are homologous to:", "options": [{"key": "A", "text": "Ribs"}, {"key": "B", "text": "Costal processes (rudimentary ribs)"}, {"key": "C", "text": "Laminae"}, {"key": "D", "text": "Pedicles"}], "correct": "B", "explanation": "Lumbar transverse processes are costal processes — homologous to rudimentary ribs."}, {"id": 938, "subject": "Anatomy", "difficulty": "Hard", "question": "L5-S1 facet joint orientation is:", "options": [{"key": "A", "text": "More sagittal"}, {"key": "B", "text": "More coronal"}, {"key": "C", "text": "Pure transverse"}, {"key": "D", "text": "Horizontal"}], "correct": "B", "explanation": "L5-S1 facets are more coronally oriented compared to upper lumbar levels, aiding stability."}, {"id": 939, "subject": "Anatomy", "difficulty": "Easy", "question": "The spinal canal is largest in which region?", "options": [{"key": "A", "text": "Cervical"}, {"key": "B", "text": "Thoracic"}, {"key": "C", "text": "Lumbar"}, {"key": "D", "text": "Equal throughout"}], "correct": "C", "explanation": "The lumbar spinal canal is the largest in cross-sectional area among all vertebral regions."}, {"id": 940, "subject": "Anatomy", "difficulty": "Easy", "question": "The nucleus pulposus is derived from:", "options": [{"key": "A", "text": "Sclerotome"}, {"key": "B", "text": "Notochord"}, {"key": "C", "text": "Neural crest"}, {"key": "D", "text": "Dermatome"}], "correct": "B", "explanation": "Nucleus pulposus is a remnant of the embryonic notochord, present in the center of the disc."}, {"id": 941, "subject": "Anatomy", "difficulty": "Easy", "question": "The annulus fibrosus is composed of:", "options": [{"key": "A", "text": "Hyaline cartilage"}, {"key": "B", "text": "Fibrocartilage with concentric lamellae"}, {"key": "C", "text": "Dense irregular CT"}, {"key": "D", "text": "Elastic cartilage"}], "correct": "B", "explanation": "Annulus fibrosus consists of fibrocartilage arranged in concentric lamellae (15-25 layers)."}, {"id": 942, "subject": "Anatomy", "difficulty": "Medium", "question": "What percentage of intervertebral disc is water in young adults?", "options": [{"key": "A", "text": "40-50%"}, {"key": "B", "text": "70-90%"}, {"key": "C", "text": "20-30%"}, {"key": "D", "text": "50-60%"}], "correct": "B", "explanation": "Nucleus pulposus in young adults is 70-90% water, providing hydrostatic pressure and shock absorption."}, {"id": 943, "subject": "Anatomy", "difficulty": "Hard", "question": "The annular fibers in adjacent lamellae are oriented at approximately:", "options": [{"key": "A", "text": "Same direction"}, {"key": "B", "text": "90° to each other"}, {"key": "C", "text": "Alternating 30° to disc plane"}, {"key": "D", "text": "45° to each other"}], "correct": "C", "explanation": "Adjacent lamellae have fibers alternating at ~30° inclinations, resisting torsional forces."}, {"id": 944, "subject": "Anatomy", "difficulty": "Medium", "question": "Which region has the thinnest intervertebral discs?", "options": [{"key": "A", "text": "Cervical"}, {"key": "B", "text": "Thoracic"}, {"key": "C", "text": "Lumbar"}, {"key": "D", "text": "Lumbosacral"}], "correct": "B", "explanation": "Thoracic discs are the thinnest, being approximately 5mm in height."}, {"id": 945, "subject": "Anatomy", "difficulty": "Medium", "question": "The disc-to-vertebral body height ratio is greatest in:", "options": [{"key": "A", "text": "Cervical region"}, {"key": "B", "text": "Thoracic region"}, {"key": "C", "text": "Lumbar region"}, {"key": "D", "text": "Sacral region"}], "correct": "C", "explanation": "Lumbar region has the highest disc-to-body ratio (~1:3), contributing to greater mobility."}, {"id": 946, "subject": "Anatomy", "difficulty": "Medium", "question": "The cartilaginous endplate functions to:", "options": [{"key": "A", "text": "Connect disc to periosteum"}, {"key": "B", "text": "Allow nutrient diffusion and anchor disc"}, {"key": "C", "text": "Provide rotation"}, {"key": "D", "text": "None of the above"}], "correct": "B", "explanation": "Endplates allow nutrient diffusion (discs are avascular) and anchor the disc to adjacent vertebral bodies."}, {"id": 947, "subject": "Anatomy", "difficulty": "Easy", "question": "Disc herniation most commonly occurs in which direction?", "options": [{"key": "A", "text": "Anterior"}, {"key": "B", "text": "Posterolateral"}, {"key": "C", "text": "Direct posterior"}, {"key": "D", "text": "Lateral"}], "correct": "B", "explanation": "Posterolateral herniation is most common as the posterior longitudinal ligament is thinner/absent here."}, {"id": 948, "subject": "Anatomy", "difficulty": "Easy", "question": "Which spinal level has the highest incidence of disc herniation?", "options": [{"key": "A", "text": "T10-T11"}, {"key": "B", "text": "L1-L2"}, {"key": "C", "text": "L4-L5 and L5-S1"}, {"key": "D", "text": "C5-C6"}], "correct": "C", "explanation": "L4-L5 and L5-S1 account for >90% of lumbar disc herniations due to maximum stress."}, {"id": 949, "subject": "Anatomy", "difficulty": "Medium", "question": "The nucleus pulposus in adults is avascular and receives nutrition by:", "options": [{"key": "A", "text": "Direct arterial supply"}, {"key": "B", "text": "Imbibition and diffusion"}, {"key": "C", "text": "Lymphatics"}, {"key": "D", "text": "Venous plexus"}], "correct": "B", "explanation": "Avascular nucleus pulposus receives nutrients by diffusion and imbibition through cartilaginous endplates."}, {"id": 950, "subject": "Anatomy", "difficulty": "Medium", "question": "Schmorl's nodes represent:", "options": [{"key": "A", "text": "Disc calcification"}, {"key": "B", "text": "Herniation of disc into vertebral body"}, {"key": "C", "text": "Osteophyte formation"}, {"key": "D", "text": "Annular tear"}], "correct": "B", "explanation": "Schmorl's nodes are vertical disc herniations through the endplate into the vertebral body."}, {"id": 951, "subject": "Anatomy", "difficulty": "Hard", "question": "The outer one-third of annulus fibrosus is innervated by:", "options": [{"key": "A", "text": "Recurrent meningeal nerve"}, {"key": "B", "text": "Sinuvertebral nerve"}, {"key": "C", "text": "Posterior primary ramus"}, {"key": "D", "text": "Both A and B"}], "correct": "D", "explanation": "Both the sinuvertebral (recurrent meningeal) nerve innervates the outer annulus, making tears painful."}, {"id": 952, "subject": "Anatomy", "difficulty": "Medium", "question": "The largest disc in the spine is located at:", "options": [{"key": "A", "text": "C5-C6"}, {"key": "B", "text": "T12-L1"}, {"key": "C", "text": "L5-S1"}, {"key": "D", "text": "L4-L5"}], "correct": "C", "explanation": "L5-S1 has the largest intervertebral disc in the spine in terms of cross-sectional area."}, {"id": 953, "subject": "Anatomy", "difficulty": "Easy", "question": "During aging, nucleus pulposus becomes:", "options": [{"key": "A", "text": "More hydrated"}, {"key": "B", "text": "Fibrotic and dehydrated"}, {"key": "C", "text": "Softer and gelatinous"}, {"key": "D", "text": "More vascular"}], "correct": "B", "explanation": "With aging, nucleus pulposus loses water content, becomes fibrotic, reducing shock-absorbing capacity."}, {"id": 954, "subject": "Anatomy", "difficulty": "Medium", "question": "Intradiscal pressure is highest during:", "options": [{"key": "A", "text": "Lying supine"}, {"key": "B", "text": "Standing"}, {"key": "C", "text": "Sitting with flexion"}, {"key": "D", "text": "Walking"}], "correct": "C", "explanation": "Sitting with forward flexion produces the highest intradiscal pressure (Nachemson's studies)."}, {"id": 955, "subject": "Anatomy", "difficulty": "Medium", "question": "The anterior longitudinal ligament (ALL) extends from:", "options": [{"key": "A", "text": "C1 to sacrum"}, {"key": "B", "text": "Occiput to sacrum"}, {"key": "C", "text": "C3 to L5"}, {"key": "D", "text": "Atlas to coccyx"}], "correct": "B", "explanation": "ALL extends from the basilar part of occiput (anterior tubercle of atlas) to the sacrum."}, {"id": 956, "subject": "Anatomy", "difficulty": "Medium", "question": "The posterior longitudinal ligament (PLL) is broader at:", "options": [{"key": "A", "text": "Upper levels"}, {"key": "B", "text": "Lower lumbar levels"}, {"key": "C", "text": "Mid-thoracic"}, {"key": "D", "text": "Cervical region"}], "correct": "A", "explanation": "PLL is broader superiorly and becomes narrower at lower lumbar levels, predisposing to posterolateral disc herniation."}, {"id": 957, "subject": "Anatomy", "difficulty": "Easy", "question": "The ligamentum flavum is composed predominantly of:", "options": [{"key": "A", "text": "Collagen type I"}, {"key": "B", "text": "Collagen type II"}, {"key": "C", "text": "Elastin fibers"}, {"key": "D", "text": "Fibrocartilage"}], "correct": "C", "explanation": "Ligamentum flavum is ~80% elastin, giving it yellow color and elasticity, preventing disc buckling during extension."}, {"id": 958, "subject": "Anatomy", "difficulty": "Easy", "question": "Ligamentum flavum connects:", "options": [{"key": "A", "text": "Spinous processes"}, {"key": "B", "text": "Adjacent laminae"}, {"key": "C", "text": "Adjacent pedicles"}, {"key": "D", "text": "Transverse processes"}], "correct": "B", "explanation": "Ligamentum flavum connects adjacent laminae of thoracic and lumbar vertebrae."}, {"id": 959, "subject": "Anatomy", "difficulty": "Easy", "question": "The interspinous ligament connects:", "options": [{"key": "A", "text": "Adjacent transverse processes"}, {"key": "B", "text": "Adjacent spinous processes"}, {"key": "C", "text": "Spinous process to lamina"}, {"key": "D", "text": "Lamina to pedicle"}], "correct": "B", "explanation": "Interspinous ligament connects adjacent spinous processes from root to apex."}, {"id": 960, "subject": "Anatomy", "difficulty": "Medium", "question": "The supraspinous ligament extends from:", "options": [{"key": "A", "text": "C1 to sacrum"}, {"key": "B", "text": "C7 to L5 or sacrum"}, {"key": "C", "text": "Occiput to C7"}, {"key": "D", "text": "T1 to L5"}], "correct": "B", "explanation": "Supraspinous ligament runs from C7 to L5 (or sacrum), connecting tips of spinous processes."}, {"id": 961, "subject": "Anatomy", "difficulty": "Medium", "question": "The ligamentum nuchae is the cervical continuation of:", "options": [{"key": "A", "text": "Interspinous ligament"}, {"key": "B", "text": "Supraspinous ligament"}, {"key": "C", "text": "Posterior longitudinal ligament"}, {"key": "D", "text": "Ligamentum flavum"}], "correct": "B", "explanation": "Ligamentum nuchae is the expanded supraspinous ligament in the cervical region."}, {"id": 962, "subject": "Anatomy", "difficulty": "Easy", "question": "The intertransverse ligament connects:", "options": [{"key": "A", "text": "Adjacent spinous processes"}, {"key": "B", "text": "Adjacent laminae"}, {"key": "C", "text": "Adjacent transverse processes"}, {"key": "D", "text": "Transverse process to rib"}], "correct": "C", "explanation": "Intertransverse ligament connects adjacent transverse processes, limiting lateral flexion."}, {"id": 963, "subject": "Anatomy", "difficulty": "Medium", "question": "Which ligament is taut in flexion of spine?", "options": [{"key": "A", "text": "Anterior longitudinal ligament"}, {"key": "B", "text": "Ligamentum flavum"}, {"key": "C", "text": "Posterior longitudinal ligament"}, {"key": "D", "text": "Both B and C"}], "correct": "D", "explanation": "Both ligamentum flavum and PLL become taut during spinal flexion, resisting excessive movement."}, {"id": 964, "subject": "Anatomy", "difficulty": "Easy", "question": "The ALL is taut in which spinal movement?", "options": [{"key": "A", "text": "Flexion"}, {"key": "B", "text": "Extension"}, {"key": "C", "text": "Rotation"}, {"key": "D", "text": "Lateral flexion"}], "correct": "B", "explanation": "The anterior longitudinal ligament becomes taut during spinal extension, resisting hyperextension."}, {"id": 965, "subject": "Anatomy", "difficulty": "Medium", "question": "Ossification of the posterior longitudinal ligament (OPLL) most commonly occurs in:", "options": [{"key": "A", "text": "Lumbar spine"}, {"key": "B", "text": "Cervical spine"}, {"key": "C", "text": "Thoracic spine"}, {"key": "D", "text": "Lumbosacral junction"}], "correct": "B", "explanation": "OPLL most commonly affects the cervical spine and can cause myelopathy."}, {"id": 966, "subject": "Anatomy", "difficulty": "Easy", "question": "Which spinal ligament prevents excessive hyperextension?", "options": [{"key": "A", "text": "Ligamentum flavum"}, {"key": "B", "text": "Posterior longitudinal ligament"}, {"key": "C", "text": "Anterior longitudinal ligament"}, {"key": "D", "text": "Intertransverse"}], "correct": "C", "explanation": "The ALL is the primary restraint against hyperextension of the vertebral column."}, {"id": 967, "subject": "Anatomy", "difficulty": "Medium", "question": "The costotransverse ligament connects:", "options": [{"key": "A", "text": "Rib to spinous process"}, {"key": "B", "text": "Rib tubercle to transverse process"}, {"key": "C", "text": "Rib head to vertebral body"}, {"key": "D", "text": "Rib to lamina"}], "correct": "B", "explanation": "Costotransverse ligament connects the rib tubercle to the transverse process of the corresponding vertebra."}, {"id": 968, "subject": "Anatomy", "difficulty": "Medium", "question": "Hypertrophy of ligamentum flavum contributes to:", "options": [{"key": "A", "text": "Disc herniation"}, {"key": "B", "text": "Lumbar spinal stenosis"}, {"key": "C", "text": "Scoliosis"}, {"key": "D", "text": "Spondylolisthesis"}], "correct": "B", "explanation": "Ligamentum flavum hypertrophy is a major cause of acquired lumbar spinal canal stenosis."}, {"id": 969, "subject": "Anatomy", "difficulty": "Hard", "question": "The radiate ligament of head of rib connects:", "options": [{"key": "A", "text": "Rib to transverse process"}, {"key": "B", "text": "Rib head to two adjacent vertebral bodies and disc"}, {"key": "C", "text": "Rib to PLL"}, {"key": "D", "text": "Rib to lamina"}], "correct": "B", "explanation": "The radiate ligament fans from rib head to the bodies of two adjacent vertebrae and the intervening disc."}, {"id": 970, "subject": "Anatomy", "difficulty": "Medium", "question": "Normal thoracic kyphosis angle is approximately:", "options": [{"key": "A", "text": "10-20°"}, {"key": "B", "text": "20-40°"}, {"key": "C", "text": "40-50°"}, {"key": "D", "text": "50-70°"}], "correct": "B", "explanation": "Normal thoracic kyphosis measured by Cobb method is approximately 20-40°."}, {"id": 971, "subject": "Anatomy", "difficulty": "Medium", "question": "Which movement is most restricted in the thoracic spine?", "options": [{"key": "A", "text": "Extension"}, {"key": "B", "text": "Lateral flexion"}, {"key": "C", "text": "Rotation"}, {"key": "D", "text": "Flexion"}], "correct": "C", "explanation": "Rotation is most limited in thoracic spine due to rib cage, coronally oriented facets, and overlapping spinous processes."}, {"id": 972, "subject": "Anatomy", "difficulty": "Hard", "question": "The coupled motion in thoracic spine is:", "options": [{"key": "A", "text": "Flexion with rotation"}, {"key": "B", "text": "Lateral flexion with ipsilateral rotation"}, {"key": "C", "text": "Rotation with lateral flexion to same side"}, {"key": "D", "text": "Lateral flexion with contralateral rotation"}], "correct": "D", "explanation": "In upper thoracic spine, lateral flexion couples with contralateral rotation."}, {"id": 973, "subject": "Anatomy", "difficulty": "Medium", "question": "The thoracic spine contributes approximately how much to total spinal rotation?", "options": [{"key": "A", "text": "15°"}, {"key": "B", "text": "35°"}, {"key": "C", "text": "50°"}, {"key": "D", "text": "70°"}], "correct": "B", "explanation": "Thoracic spine contributes approximately 35° (each side) to total spinal axial rotation."}, {"id": 974, "subject": "Anatomy", "difficulty": "Medium", "question": "Normal lumbar lordosis angle is:", "options": [{"key": "A", "text": "10-20°"}, {"key": "B", "text": "20-45°"}, {"key": "C", "text": "40-60°"}, {"key": "D", "text": "50-70°"}], "correct": "C", "explanation": "Normal lumbar lordosis is approximately 40-60°, with significant individual variation."}, {"id": 975, "subject": "Anatomy", "difficulty": "Easy", "question": "Which movement is maximum in lumbar spine?", "options": [{"key": "A", "text": "Rotation"}, {"key": "B", "text": "Lateral flexion"}, {"key": "C", "text": "Flexion-Extension"}, {"key": "D", "text": "Circumduction"}], "correct": "C", "explanation": "Flexion-extension is maximum in lumbar spine; rotation is highly restricted by sagittal facets."}, {"id": 976, "subject": "Anatomy", "difficulty": "Medium", "question": "The lumbar spine contributes approximately how much total rotation?", "options": [{"key": "A", "text": "5° per side"}, {"key": "B", "text": "15-20° per side"}, {"key": "C", "text": "30° per side"}, {"key": "D", "text": "45° per side"}], "correct": "A", "explanation": "Total lumbar rotation is only ~5° per side, limited by sagittally-oriented facet joints."}, {"id": 977, "subject": "Anatomy", "difficulty": "Medium", "question": "During lumbar extension, the nucleus pulposus moves:", "options": [{"key": "A", "text": "Posteriorly"}, {"key": "B", "text": "Anteriorly"}, {"key": "C", "text": "Superiorly"}, {"key": "D", "text": "Remains stationary"}], "correct": "B", "explanation": "During extension, the disc is compressed posteriorly, pushing nucleus anteriorly."}, {"id": 978, "subject": "Anatomy", "difficulty": "Hard", "question": "The instant axis of rotation for lumbar flexion-extension is located in:", "options": [{"key": "A", "text": "Posterior annulus"}, {"key": "B", "text": "Nucleus pulposus"}, {"key": "C", "text": "Anterior vertebral body"}, {"key": "D", "text": "Spinous process"}], "correct": "B", "explanation": "The instantaneous axis of rotation for lumbar segmental motion is within the nucleus pulposus."}, {"id": 979, "subject": "Anatomy", "difficulty": "Medium", "question": "L4-L5 disc herniation most commonly compresses:", "options": [{"key": "A", "text": "L3 nerve root"}, {"key": "B", "text": "L4 nerve root"}, {"key": "C", "text": "L5 nerve root"}, {"key": "D", "text": "S1 nerve root"}], "correct": "C", "explanation": "At L4-L5 level, a posterolateral disc herniation compresses the traversing L5 nerve root."}, {"id": 980, "subject": "Anatomy", "difficulty": "Medium", "question": "L5-S1 disc herniation most commonly compresses:", "options": [{"key": "A", "text": "L4 nerve root"}, {"key": "B", "text": "L5 nerve root"}, {"key": "C", "text": "S1 nerve root"}, {"key": "D", "text": "S2 nerve root"}], "correct": "C", "explanation": "At L5-S1, the traversing S1 nerve root is most commonly compressed by posterolateral herniation."}, {"id": 981, "subject": "Anatomy", "difficulty": "Easy", "question": "Cauda equina syndrome is caused by:", "options": [{"key": "A", "text": "L1-L2 disc herniation laterally"}, {"key": "B", "text": "Massive central disc herniation at L4-L5 or below"}, {"key": "C", "text": "Foraminal stenosis at L5"}, {"key": "D", "text": "Facet joint arthritis"}], "correct": "B", "explanation": "Large central disc herniation compresses multiple cauda equina nerve roots, causing CES."}, {"id": 982, "subject": "Anatomy", "difficulty": "Easy", "question": "The straight leg raise (SLR) test stretches which nerve root?", "options": [{"key": "A", "text": "L2-L3"}, {"key": "B", "text": "L3-L4"}, {"key": "C", "text": "L4-S1 (sciatic nerve)"}, {"key": "D", "text": "S2-S3"}], "correct": "C", "explanation": "SLR stretches L4, L5, S1 nerve roots via the sciatic nerve; positive if pain reproduces below knee."}, {"id": 983, "subject": "Anatomy", "difficulty": "Medium", "question": "Crossed straight leg raise (CSLR) is more specific for:", "options": [{"key": "A", "text": "Lateral disc herniation"}, {"key": "B", "text": "Large central or paracentral disc herniation"}, {"key": "C", "text": "Facet joint pain"}, {"key": "D", "text": "Piriformis syndrome"}], "correct": "B", "explanation": "CSLR (contralateral leg raising reproducing ipsilateral leg pain) indicates large medial disc herniation."}, {"id": 984, "subject": "Anatomy", "difficulty": "Medium", "question": "The conus medullaris typically ends at which vertebral level in adults?", "options": [{"key": "A", "text": "T12"}, {"key": "B", "text": "L1-L2"}, {"key": "C", "text": "L3"}, {"key": "D", "text": "L4"}], "correct": "B", "explanation": "The spinal cord typically ends at L1-L2 in adults (conus medullaris level)."}, {"id": 985, "subject": "Anatomy", "difficulty": "Medium", "question": "The cauda equina occupies which space?", "options": [{"key": "A", "text": "Epidural space"}, {"key": "B", "text": "Subdural space"}, {"key": "C", "text": "Subarachnoid space"}, {"key": "D", "text": "Intradural-extramedullary space"}], "correct": "C", "explanation": "Cauda equina nerve roots descend within the subarachnoid (thecal) space."}, {"id": 986, "subject": "Anatomy", "difficulty": "Medium", "question": "Epidural space contains:", "options": [{"key": "A", "text": "CSF"}, {"key": "B", "text": "Fat, venous plexus, lymphatics, nerve roots"}, {"key": "C", "text": "Spinal cord only"}, {"key": "D", "text": "Dural sac"}], "correct": "B", "explanation": "Epidural space contains fat, internal vertebral venous plexus, lymphatics, and spinal nerve roots."}, {"id": 987, "subject": "Anatomy", "difficulty": "Medium", "question": "The dural sac in adults typically ends at:", "options": [{"key": "A", "text": "L3-L4"}, {"key": "B", "text": "L4-L5"}, {"key": "C", "text": "S1-S2"}, {"key": "D", "text": "S2-S3"}], "correct": "C", "explanation": "The dural sac typically ends at S1-S2, below which is the filum terminale externum."}, {"id": 988, "subject": "Anatomy", "difficulty": "Medium", "question": "The intervertebral foramen of the lumbar spine is bounded anteriorly by:", "options": [{"key": "A", "text": "Facet joint"}, {"key": "B", "text": "Intervertebral disc and vertebral bodies"}, {"key": "C", "text": "Pedicles superiorly and inferiorly"}, {"key": "D", "text": "Ligamentum flavum"}], "correct": "B", "explanation": "The IVF is bounded anteriorly by the intervertebral disc and adjacent vertebral bodies."}, {"id": 989, "subject": "Anatomy", "difficulty": "Medium", "question": "Ossification of vertebral body begins from:", "options": [{"key": "A", "text": "Primary ossification center in centrum"}, {"key": "B", "text": "Secondary ossification centers in neural arches"}, {"key": "C", "text": "Endochondral ossification in epiphyseal ring"}, {"key": "D", "text": "Membranous ossification"}], "correct": "A", "explanation": "Primary ossification center appears in the centrum of vertebral body during fetal life."}, {"id": 990, "subject": "Anatomy", "difficulty": "Hard", "question": "Ring apophysis of vertebra appears at approximately:", "options": [{"key": "A", "text": "5 years"}, {"key": "B", "text": "8 years"}, {"key": "C", "text": "12-14 years"}, {"key": "D", "text": "18-20 years"}], "correct": "C", "explanation": "Ring apophysis (secondary ossification center at disc-body junction) appears at puberty (12-14 years)."}, {"id": 991, "subject": "Anatomy", "difficulty": "Medium", "question": "Spina bifida occulta most commonly occurs at:", "options": [{"key": "A", "text": "T12"}, {"key": "B", "text": "L5-S1"}, {"key": "C", "text": "L3"}, {"key": "D", "text": "L1"}], "correct": "B", "explanation": "Spina bifida occulta most commonly occurs at L5 or S1 due to failure of posterior arch fusion."}, {"id": 992, "subject": "Anatomy", "difficulty": "Medium", "question": "Hemivertebra is a congenital anomaly due to:", "options": [{"key": "A", "text": "Failure of segmentation"}, {"key": "B", "text": "Failure of formation of half the vertebra"}, {"key": "C", "text": "Absence of pedicle"}, {"key": "D", "text": "Disc calcification"}], "correct": "B", "explanation": "Hemivertebra results from failure of formation/development of one half of a vertebra, causing congenital scoliosis."}, {"id": 993, "subject": "Anatomy", "difficulty": "Easy", "question": "Lumbar facet (zygapophyseal) joints are classified as:", "options": [{"key": "A", "text": "Fibrous joints"}, {"key": "B", "text": "Cartilaginous joints"}, {"key": "C", "text": "Synovial joints"}, {"key": "D", "text": "Amphiarthrosis"}], "correct": "C", "explanation": "Facet joints are true synovial joints with hyaline cartilage, joint capsule, and synovial membrane."}, {"id": 994, "subject": "Anatomy", "difficulty": "Medium", "question": "Which nerve innervates lumbar facet joints?", "options": [{"key": "A", "text": "Sinuvertebral nerve"}, {"key": "B", "text": "Medial branch of posterior primary ramus"}, {"key": "C", "text": "Lateral branch of posterior primary ramus"}, {"key": "D", "text": "Anterior primary ramus"}], "correct": "B", "explanation": "Each facet joint is innervated by medial branches of posterior rami from two adjacent levels."}, {"id": 995, "subject": "Anatomy", "difficulty": "Hard", "question": "In the thoracic spine, the superior articular facets face:", "options": [{"key": "A", "text": "Anteriorly and slightly laterally"}, {"key": "B", "text": "Posteriorly and slightly medially"}, {"key": "C", "text": "Superiorly"}, {"key": "D", "text": "Inferiorly"}], "correct": "B", "explanation": "Thoracic superior articular facets face posteriorly and slightly laterally, limiting flexion-extension."}, {"id": 996, "subject": "Anatomy", "difficulty": "Medium", "question": "The intervertebral foramen transmits:", "options": [{"key": "A", "text": "Only dorsal root ganglion"}, {"key": "B", "text": "Spinal nerve, spinal artery, veins, sinuvertebral nerve"}, {"key": "C", "text": "Only sinuvertebral nerve"}, {"key": "D", "text": "Only venous plexus"}], "correct": "B", "explanation": "The IVF transmits: spinal nerve (and DRG), radicular arteries/veins, and sinuvertebral nerve."}, {"id": 997, "subject": "Anatomy", "difficulty": "Hard", "question": "The spinal cord occupies what proportion of the spinal canal in thoracic region?", "options": [{"key": "A", "text": "10-20%"}, {"key": "B", "text": "30-40%"}, {"key": "C", "text": "50-60%"}, {"key": "D", "text": "75-80%"}], "correct": "C", "explanation": "The spinal cord occupies about 50-60% of the thoracic canal (less CSF reserve than cervical)."}, {"id": 998, "subject": "Anatomy", "difficulty": "Medium", "question": "The thoracic kyphosis and lumbar lordosis are classified as:", "options": [{"key": "A", "text": "Primary and primary curves"}, {"key": "B", "text": "Secondary and secondary curves"}, {"key": "C", "text": "Primary (kyphosis) and secondary (lordosis)"}, {"key": "D", "text": "Both secondary curves"}], "correct": "C", "explanation": "Thoracic kyphosis is a primary (fetal) curve; lumbar lordosis develops secondarily (when walking)."}, {"id": 999, "subject": "Anatomy", "difficulty": "Easy", "question": "Scoliosis is defined as lateral curvature of spine more than:", "options": [{"key": "A", "text": "5°"}, {"key": "B", "text": "10°"}, {"key": "C", "text": "15°"}, {"key": "D", "text": "20°"}], "correct": "B", "explanation": "Scoliosis is defined as a lateral curvature of >10° measured by Cobb method on X-ray."}, {"id": 1000, "subject": "Anatomy", "difficulty": "Medium", "question": "The Cobb angle in scoliosis is measured between:", "options": [{"key": "A", "text": "Two adjacent vertebrae"}, {"key": "B", "text": "End vertebrae of the curve"}, {"key": "C", "text": "Neutral vertebrae"}, {"key": "D", "text": "Apical vertebrae"}], "correct": "B", "explanation": "Cobb angle is measured between the superior endplate of the uppermost and inferior endplate of lowermost vertebra of the curve."}, {"id": 1001, "subject": "Anatomy", "difficulty": "Medium", "question": "The artery of Adamkiewicz is a major feeder of:", "options": [{"key": "A", "text": "Cervical cord"}, {"key": "B", "text": "Thoracolumbar spinal cord"}, {"key": "C", "text": "Cauda equina only"}, {"key": "D", "text": "Sacral cord"}], "correct": "B", "explanation": "Artery of Adamkiewicz (arteria radicularis magna) is the major feeder of the lower thoracic and lumbar cord."}, {"id": 1002, "subject": "Anatomy", "difficulty": "Hard", "question": "The artery of Adamkiewicz typically arises from the aorta at:", "options": [{"key": "A", "text": "T1-T4"}, {"key": "B", "text": "T9-T12 (left side)"}, {"key": "C", "text": "L1-L3"}, {"key": "D", "text": "T5-T8"}], "correct": "B", "explanation": "It usually arises from the left intercostal/lumbar artery at T9-T12 (80% on left side)."}, {"id": 1003, "subject": "Anatomy", "difficulty": "Medium", "question": "The internal vertebral venous plexus (Batson's plexus) is:", "options": [{"key": "A", "text": "Valved venous system"}, {"key": "B", "text": "Valveless venous plexus"}, {"key": "C", "text": "Part of portal system"}, {"key": "D", "text": "Arterial plexus"}], "correct": "B", "explanation": "Batson's plexus is a valveless venous plexus, allowing retrograde spread of tumor/infection to spine."}, {"id": 1004, "subject": "Anatomy", "difficulty": "Medium", "question": "The thoracolumbar fascia encases which muscles?", "options": [{"key": "A", "text": "Erector spinae and quadratus lumborum"}, {"key": "B", "text": "Psoas only"}, {"key": "C", "text": "Obliques only"}, {"key": "D", "text": "Rectus abdominis"}], "correct": "A", "explanation": "Thoracolumbar fascia (posterior and anterior layers) encases erector spinae and quadratus lumborum."}, {"id": 1005, "subject": "Anatomy", "difficulty": "Easy", "question": "The multifidus muscle is most developed in which spinal region?", "options": [{"key": "A", "text": "Cervical"}, {"key": "B", "text": "Thoracic"}, {"key": "C", "text": "Lumbar"}, {"key": "D", "text": "Sacral"}], "correct": "C", "explanation": "Multifidus is most massive in the lumbar region, providing segmental stability."}, {"id": 1006, "subject": "Anatomy", "difficulty": "Easy", "question": "Spondylolysis is a defect in:", "options": [{"key": "A", "text": "Vertebral body"}, {"key": "B", "text": "Pedicle"}, {"key": "C", "text": "Pars interarticularis"}, {"key": "D", "text": "Transverse process"}], "correct": "C", "explanation": "Spondylolysis is a stress fracture or defect in the pars interarticularis (isthmus) of the neural arch."}, {"id": 1007, "subject": "Anatomy", "difficulty": "Easy", "question": "Spondylolisthesis refers to:", "options": [{"key": "A", "text": "Fracture of vertebral body"}, {"key": "B", "text": "Forward slippage of one vertebra over another"}, {"key": "C", "text": "Lateral displacement"}, {"key": "D", "text": "Posterior displacement"}], "correct": "B", "explanation": "Spondylolisthesis is the anterior displacement of a vertebra relative to the one below it."}, {"id": 1008, "subject": "Anatomy", "difficulty": "Medium", "question": "Meyerding Grade II spondylolisthesis is:", "options": [{"key": "A", "text": "0-25% slip"}, {"key": "B", "text": "26-50% slip"}, {"key": "C", "text": "51-75% slip"}, {"key": "D", "text": "76-100% slip"}], "correct": "B", "explanation": "Meyerding Grade II = 26-50% forward slippage of the vertebral body."}, {"id": 1009, "subject": "Anatomy", "difficulty": "Medium", "question": "Degenerative spondylolisthesis most commonly occurs at:", "options": [{"key": "A", "text": "L2-L3"}, {"key": "B", "text": "L3-L4"}, {"key": "C", "text": "L4-L5"}, {"key": "D", "text": "L5-S1"}], "correct": "C", "explanation": "Degenerative spondylolisthesis (without pars defect) most commonly occurs at L4-L5."}, {"id": 1010, "subject": "Anatomy", "difficulty": "Medium", "question": "Scheuermann's disease involves:", "options": [{"key": "A", "text": "Scoliosis with vertebral rotation"}, {"key": "B", "text": "Thoracic hyperkyphosis with anterior vertebral wedging >5° at ≥3 consecutive levels"}, {"key": "C", "text": "Spondylolysis at T10"}, {"key": "D", "text": "Disc calcification in children"}], "correct": "B", "explanation": "Scheuermann's disease is adolescent kyphosis defined by >5° anterior wedging at ≥3 consecutive thoracic vertebrae."}, {"id": 1011, "subject": "Anatomy", "difficulty": "Medium", "question": "The L4 nerve root exits:", "options": [{"key": "A", "text": "Above L4 pedicle"}, {"key": "B", "text": "Below L4 pedicle (L4-L5 foramen)"}, {"key": "C", "text": "At L3-L4 foramen"}, {"key": "D", "text": "Below L5 pedicle"}], "correct": "B", "explanation": "In lumbar spine, nerve roots exit below the same-numbered pedicle (L4 exits via L4-L5 foramen)."}, {"id": 1012, "subject": "Anatomy", "difficulty": "Medium", "question": "The dermatomal distribution of L4 nerve root includes:", "options": [{"key": "A", "text": "Medial leg and great toe"}, {"key": "B", "text": "Lateral leg and dorsum of foot"}, {"key": "C", "text": "Lateral aspect of foot and heel"}, {"key": "D", "text": "Posterior thigh"}], "correct": "A", "explanation": "L4 dermatome covers medial leg, medial malleolus, and medial foot to great toe."}, {"id": 1013, "subject": "Anatomy", "difficulty": "Medium", "question": "The L5 nerve root supplies which muscle (key muscle)?", "options": [{"key": "A", "text": "Tibialis anterior"}, {"key": "B", "text": "Extensor hallucis longus"}, {"key": "C", "text": "Gastrocnemius"}, {"key": "D", "text": "Biceps femoris"}], "correct": "B", "explanation": "Extensor hallucis longus (big toe extension) is the key muscle for L5 nerve root testing."}, {"id": 1014, "subject": "Anatomy", "difficulty": "Easy", "question": "Diminished ankle jerk (Achilles reflex) indicates involvement of:", "options": [{"key": "A", "text": "L3 root"}, {"key": "B", "text": "L4 root"}, {"key": "C", "text": "L5 root"}, {"key": "D", "text": "S1 root"}], "correct": "D", "explanation": "Ankle jerk (Achilles reflex) is mediated by S1 nerve root; absent/diminished in S1 compression."}, {"id": 1015, "subject": "Anatomy", "difficulty": "Medium", "question": "The pedicle-to-pedicle distance on AP X-ray represents:", "options": [{"key": "A", "text": "Spinal canal width"}, {"key": "B", "text": "Interpediculate distance"}, {"key": "C", "text": "Vertebral body width"}, {"key": "D", "text": "Foraminal width"}], "correct": "B", "explanation": "Interpediculate distance on AP view = the transverse diameter of spinal canal at that level."}, {"id": 1016, "subject": "Anatomy", "difficulty": "Easy", "question": "The gold standard investigation for lumbar disc herniation is:", "options": [{"key": "A", "text": "Plain X-ray"}, {"key": "B", "text": "CT scan"}, {"key": "C", "text": "MRI spine"}, {"key": "D", "text": "Myelography"}], "correct": "C", "explanation": "MRI is the gold standard for evaluating disc herniation, nerve root compression, and soft tissue."}, {"id": 1017, "subject": "Anatomy", "difficulty": "Easy", "question": "On MRI T2 images, a normal hydrated disc appears:", "options": [{"key": "A", "text": "Hypointense (dark)"}, {"key": "B", "text": "Hyperintense (bright/white)"}, {"key": "C", "text": "Isointense"}, {"key": "D", "text": "Absent signal"}], "correct": "B", "explanation": "Normal hydrated nucleus pulposus is bright (hyperintense) on T2 MRI due to high water content."}, {"id": 1018, "subject": "Anatomy", "difficulty": "Medium", "question": "The spinal canal sagittal diameter in lumbar region is normally:", "options": [{"key": "A", "text": "8-10 mm"}, {"key": "B", "text": "15-25 mm"}, {"key": "C", "text": "12-14 mm"}, {"key": "D", "text": "6-8 mm"}], "correct": "B", "explanation": "Normal lumbar spinal canal sagittal diameter is 15-25 mm; <12 mm = absolute stenosis."}, {"id": 1019, "subject": "Anatomy", "difficulty": "Medium", "question": "The thoracolumbar junction is considered to be:", "options": [{"key": "A", "text": "T10-T11"}, {"key": "B", "text": "T11-L1"}, {"key": "C", "text": "L1-L2"}, {"key": "D", "text": "T9-T10"}], "correct": "B", "explanation": "T11-L1 constitutes the thoracolumbar junction, a common site for fractures and transitional stress."}, {"id": 1020, "subject": "Anatomy", "difficulty": "Medium", "question": "Burst fractures are most common at:", "options": [{"key": "A", "text": "Cervical spine"}, {"key": "B", "text": "Thoracolumbar junction"}, {"key": "C", "text": "Mid-lumbar"}, {"key": "D", "text": "Upper thoracic"}], "correct": "B", "explanation": "Thoracolumbar junction (T11-L2) is the most common site for burst fractures due to transitional biomechanics."}, {"id": 1021, "subject": "Anatomy", "difficulty": "Medium", "question": "The Denis three-column model of spinal stability includes:", "options": [{"key": "A", "text": "Anterior, posterior, lateral columns"}, {"key": "B", "text": "Anterior, middle, posterior columns"}, {"key": "C", "text": "Left, right, middle columns"}, {"key": "D", "text": "Osseous, ligamentous, disc columns"}], "correct": "B", "explanation": "Denis described anterior, middle, and posterior columns; injury to ≥2 columns = unstable."}, {"id": 1022, "subject": "Anatomy", "difficulty": "Easy", "question": "The thoracic vertebrae participate in which joints with the ribs?", "options": [{"key": "A", "text": "Costovertebral and costotransverse joints"}, {"key": "B", "text": "Costochondral joints only"}, {"key": "C", "text": "Sternochondral joints"}, {"key": "D", "text": "Costo-sternal joints"}], "correct": "A", "explanation": "Ribs articulate with thoracic vertebrae via costovertebral (head) and costotransverse (tubercle) joints."}, {"id": 1023, "subject": "Anatomy", "difficulty": "Medium", "question": "Which ligament prevents excessive distraction of vertebral bodies?", "options": [{"key": "A", "text": "Ligamentum flavum"}, {"key": "B", "text": "ALL"}, {"key": "C", "text": "Posterior longitudinal ligament"}, {"key": "D", "text": "Interspinous ligament"}], "correct": "B", "explanation": "ALL resists distraction (separation) of vertebral bodies and hyperextension."}, {"id": 1024, "subject": "Anatomy", "difficulty": "Hard", "question": "The posterior tension band of the spine consists of:", "options": [{"key": "A", "text": "ALL and disc"}, {"key": "B", "text": "Facet joints, posterior ligaments, and paraspinal muscles"}, {"key": "C", "text": "Vertebral body alone"}, {"key": "D", "text": "Anterior longitudinal ligament only"}], "correct": "B", "explanation": "The posterior tension band includes posterior ligamentous complex, facets, and muscles, resisting flexion forces."}, {"id": 1025, "subject": "Anatomy", "difficulty": "Hard", "question": "Segmental instability in lumbar spine on flexion-extension X-rays is defined as translation of:", "options": [{"key": "A", "text": ">2 mm"}, {"key": "B", "text": ">3 mm"}, {"key": "C", "text": ">4 mm"}, {"key": "D", "text": ">5 mm"}], "correct": "C", "explanation": "Lumbar instability is defined as >4 mm translation or >10° angulation on dynamic (flexion-extension) X-rays."}, {"id": 1026, "subject": "Anatomy", "difficulty": "Hard", "question": "The sinuvertebral (recurrent meningeal) nerve re-enters the spinal canal through:", "options": [{"key": "A", "text": "Anterior foramen"}, {"key": "B", "text": "Posterior foramen"}, {"key": "C", "text": "Intervertebral foramen"}, {"key": "D", "text": "Sacral hiatus"}], "correct": "C", "explanation": "The sinuvertebral nerve branches from the spinal nerve and re-enters the IVF to innervate dura, PLL, and outer annulus."}, {"id": 1027, "subject": "Anatomy", "difficulty": "Easy", "question": "How many sacral vertebrae fuse to form the sacrum?", "options": [{"key": "A", "text": "3"}, {"key": "B", "text": "4"}, {"key": "C", "text": "5"}, {"key": "D", "text": "6"}], "correct": "C", "explanation": "Sacrum is formed by fusion of 5 sacral vertebrae (S1-S5), usually complete by age 25-30."}, {"id": 1028, "subject": "Anatomy", "difficulty": "Easy", "question": "The sacral promontory is the anterior edge of:", "options": [{"key": "A", "text": "S2 body"}, {"key": "B", "text": "S1 superior surface"}, {"key": "C", "text": "S3 body"}, {"key": "D", "text": "Sacral base"}], "correct": "B", "explanation": "Sacral promontory is the prominent anterior edge of S1 superior surface; landmark for pelvic measurements."}, {"id": 1029, "subject": "Anatomy", "difficulty": "Easy", "question": "The base of sacrum articulates with:", "options": [{"key": "A", "text": "Coccyx"}, {"key": "B", "text": "L5 vertebra"}, {"key": "C", "text": "Ilium"}, {"key": "D", "text": "L4 vertebra"}], "correct": "B", "explanation": "The base (superior surface) of sacrum articulates with L5 vertebra at the lumbosacral joint."}, {"id": 1030, "subject": "Anatomy", "difficulty": "Easy", "question": "The apex of sacrum articulates with:", "options": [{"key": "A", "text": "L5"}, {"key": "B", "text": "Ilium"}, {"key": "C", "text": "Coccyx"}, {"key": "D", "text": "Ischium"}], "correct": "C", "explanation": "The apex (inferior tip) of sacrum articulates with the base of the coccyx."}, {"id": 1031, "subject": "Anatomy", "difficulty": "Medium", "question": "The anterior sacral foramina transmit:", "options": [{"key": "A", "text": "Posterior rami of sacral nerves"}, {"key": "B", "text": "Anterior rami of sacral nerves and lateral sacral vessels"}, {"key": "C", "text": "Dorsal sacral nerves only"}, {"key": "D", "text": "Only blood vessels"}], "correct": "B", "explanation": "Anterior sacral foramina transmit anterior (ventral) rami of S1-S4 and lateral sacral vessels."}, {"id": 1032, "subject": "Anatomy", "difficulty": "Medium", "question": "The posterior sacral foramina transmit:", "options": [{"key": "A", "text": "Anterior rami of sacral nerves"}, {"key": "B", "text": "Posterior rami of sacral nerves"}, {"key": "C", "text": "Pudendal nerve"}, {"key": "D", "text": "Obturator nerve"}], "correct": "B", "explanation": "Posterior sacral foramina transmit posterior (dorsal) rami of S1-S4 sacral nerves."}, {"id": 1033, "subject": "Anatomy", "difficulty": "Medium", "question": "How many pairs of anterior sacral foramina are present?", "options": [{"key": "A", "text": "3"}, {"key": "B", "text": "4"}, {"key": "C", "text": "5"}, {"key": "D", "text": "2"}], "correct": "B", "explanation": "There are 4 pairs of anterior sacral foramina (S1-S4); S5 exits via sacral hiatus."}, {"id": 1034, "subject": "Anatomy", "difficulty": "Easy", "question": "The sacral canal is a continuation of:", "options": [{"key": "A", "text": "Epidural space only"}, {"key": "B", "text": "Spinal canal/vertebral canal"}, {"key": "C", "text": "Pelvic cavity"}, {"key": "D", "text": "Sacral hiatus"}], "correct": "B", "explanation": "Sacral canal is the continuation of the vertebral (spinal) canal within the sacrum."}, {"id": 1035, "subject": "Anatomy", "difficulty": "Medium", "question": "The sacral hiatus is formed by failure of fusion of laminae of:", "options": [{"key": "A", "text": "S1-S2"}, {"key": "B", "text": "S3-S4"}, {"key": "C", "text": "S4-S5"}, {"key": "D", "text": "S5 (and often S4)"}], "correct": "D", "explanation": "Sacral hiatus is a gap in the posterior wall at S5 (and often S4) due to unfused laminae."}, {"id": 1036, "subject": "Anatomy", "difficulty": "Hard", "question": "The sacral cornua are remnants of:", "options": [{"key": "A", "text": "Spinous processes of S5"}, {"key": "B", "text": "Inferior articular processes of S5"}, {"key": "C", "text": "Transverse processes of S5"}, {"key": "D", "text": "Pedicles of S5"}], "correct": "B", "explanation": "Sacral cornua are the inferior articular processes of S5, flanking the sacral hiatus."}, {"id": 1037, "subject": "Anatomy", "difficulty": "Easy", "question": "The sacral hiatus is the site of entry for:", "options": [{"key": "A", "text": "Spinal anaesthesia"}, {"key": "B", "text": "Caudal epidural anaesthesia"}, {"key": "C", "text": "Lumbar epidural only"}, {"key": "D", "text": "Pudendal nerve block"}], "correct": "B", "explanation": "Caudal epidural anaesthesia is administered through the sacral hiatus into the sacral canal."}, {"id": 1038, "subject": "Anatomy", "difficulty": "Easy", "question": "The auricular surface of sacrum articulates with:", "options": [{"key": "A", "text": "L5"}, {"key": "B", "text": "Coccyx"}, {"key": "C", "text": "Ilium"}, {"key": "D", "text": "Ischium"}], "correct": "C", "explanation": "The ear-shaped auricular surface on the lateral sacrum articulates with the ilium at the SI joint."}, {"id": 1039, "subject": "Anatomy", "difficulty": "Hard", "question": "The sacral tuberosity (roughened area behind auricular surface) provides attachment to:", "options": [{"key": "A", "text": "Anterior sacroiliac ligament"}, {"key": "B", "text": "Interosseous sacroiliac ligament"}, {"key": "C", "text": "Sacrospinous ligament"}, {"key": "D", "text": "Sacrotuberous ligament"}], "correct": "B", "explanation": "The interosseous SI ligament, the strongest ligament in the body, attaches to the sacral tuberosity."}, {"id": 1040, "subject": "Anatomy", "difficulty": "Easy", "question": "The pelvic surface of sacrum is:", "options": [{"key": "A", "text": "Convex"}, {"key": "B", "text": "Flat"}, {"key": "C", "text": "Concave"}, {"key": "D", "text": "Irregular"}], "correct": "C", "explanation": "The pelvic (anterior) surface of sacrum is concave, forming the posterior wall of the pelvic cavity."}, {"id": 1041, "subject": "Anatomy", "difficulty": "Medium", "question": "The median sacral crest represents fused:", "options": [{"key": "A", "text": "Pedicles"}, {"key": "B", "text": "Transverse processes"}, {"key": "C", "text": "Spinous processes"}, {"key": "D", "text": "Laminae"}], "correct": "C", "explanation": "Median sacral crest represents the fused rudimentary spinous processes of sacral vertebrae."}, {"id": 1042, "subject": "Anatomy", "difficulty": "Medium", "question": "The lateral sacral crest represents fused:", "options": [{"key": "A", "text": "Spinous processes"}, {"key": "B", "text": "Transverse processes"}, {"key": "C", "text": "Laminae"}, {"key": "D", "text": "Articular processes"}], "correct": "B", "explanation": "Lateral sacral crests are formed by the fused transverse processes of the sacral vertebrae."}, {"id": 1043, "subject": "Anatomy", "difficulty": "Hard", "question": "The intermediate sacral crest represents fused:", "options": [{"key": "A", "text": "Spinous processes"}, {"key": "B", "text": "Transverse processes"}, {"key": "C", "text": "Articular processes"}, {"key": "D", "text": "Laminae"}], "correct": "C", "explanation": "Intermediate sacral crest is formed by the fused articular processes of sacral vertebrae."}, {"id": 1044, "subject": "Anatomy", "difficulty": "Medium", "question": "The sacrum tilts anteriorly; the angle between sacral axis and horizontal is called:", "options": [{"key": "A", "text": "Sacral slope"}, {"key": "B", "text": "Pelvic incidence"}, {"key": "C", "text": "Ferguson's angle"}, {"key": "D", "text": "Cobb angle"}], "correct": "A", "explanation": "Sacral slope is the angle between the superior S1 endplate and horizontal, normally ~40°."}, {"id": 1045, "subject": "Anatomy", "difficulty": "Hard", "question": "The sacral index (SI) represents:", "options": [{"key": "A", "text": "Ratio of sacral width to height"}, {"key": "B", "text": "Sacral canal diameter"}, {"key": "C", "text": "Sacral promontory angle"}, {"key": "D", "text": "None of the above"}], "correct": "A", "explanation": "Sacral index = (maximum sacral width / sacral length) × 100; used in sex determination."}, {"id": 1046, "subject": "Anatomy", "difficulty": "Medium", "question": "Sexing of sacrum: female sacrum compared to male is:", "options": [{"key": "A", "text": "Longer and narrower"}, {"key": "B", "text": "Shorter, wider, and less curved"}, {"key": "C", "text": "Taller and more curved"}, {"key": "D", "text": "Identical"}], "correct": "B", "explanation": "Female sacrum is shorter, wider, less curved (flatter), with a wider sacral canal than male."}, {"id": 1047, "subject": "Anatomy", "difficulty": "Easy", "question": "The coccyx is formed by fusion of how many rudimentary vertebrae?", "options": [{"key": "A", "text": "2-3"}, {"key": "B", "text": "3-5"}, {"key": "C", "text": "4-6"}, {"key": "D", "text": "2"}], "correct": "B", "explanation": "Coccyx typically consists of 3-5 (usually 4) fused rudimentary coccygeal vertebrae."}, {"id": 1048, "subject": "Anatomy", "difficulty": "Easy", "question": "The coccyx articulates superiorly with:", "options": [{"key": "A", "text": "L5"}, {"key": "B", "text": "S4"}, {"key": "C", "text": "Sacral apex (S5)"}, {"key": "D", "text": "Ischium"}], "correct": "C", "explanation": "Coccyx articulates with the apex of the sacrum (S5) via the sacrococcygeal joint."}, {"id": 1049, "subject": "Anatomy", "difficulty": "Medium", "question": "The coccygeal cornua articulate with:", "options": [{"key": "A", "text": "Sacral cornua"}, {"key": "B", "text": "Sacral hiatus"}, {"key": "C", "text": "Ischial tuberosity"}, {"key": "D", "text": "Pubic symphysis"}], "correct": "A", "explanation": "Coccygeal cornua (superior articular processes of Co1) articulate with the sacral cornua."}, {"id": 1050, "subject": "Anatomy", "difficulty": "Medium", "question": "The gluteus maximus attaches to the coccyx via:", "options": [{"key": "A", "text": "Posterior sacrococcygeal ligament"}, {"key": "B", "text": "Lateral border and posterior surface of coccyx"}, {"key": "C", "text": "Coccygeal cornua"}, {"key": "D", "text": "Sacrospinous ligament"}], "correct": "B", "explanation": "Gluteus maximus has an origin from the lateral border and posterior surface of the lower sacrum and coccyx."}, {"id": 1051, "subject": "Anatomy", "difficulty": "Easy", "question": "Coccydynia refers to:", "options": [{"key": "A", "text": "Sacroiliac joint pain"}, {"key": "B", "text": "Pain in the coccygeal region"}, {"key": "C", "text": "Lumbar nerve pain"}, {"key": "D", "text": "Piriformis pain"}], "correct": "B", "explanation": "Coccydynia is pain in and around the coccyx region, often after direct trauma or childbirth."}, {"id": 1052, "subject": "Anatomy", "difficulty": "Medium", "question": "The muscle arising from the anterior (pelvic) surface of coccyx is:", "options": [{"key": "A", "text": "Piriformis"}, {"key": "B", "text": "Obturator internus"}, {"key": "C", "text": "Coccygeus"}, {"key": "D", "text": "Levator ani"}], "correct": "C", "explanation": "Coccygeus muscle arises from the ischial spine and inserts into the lateral border of coccyx and sacrum."}, {"id": 1053, "subject": "Anatomy", "difficulty": "Medium", "question": "The sacrococcygeal joint is classified as:", "options": [{"key": "A", "text": "Synovial"}, {"key": "B", "text": "Synchondrosis (cartilaginous)"}, {"key": "C", "text": "Fibrous"}, {"key": "D", "text": "Pivot joint"}], "correct": "B", "explanation": "Sacrococcygeal joint is a symphysis (secondary cartilaginous/fibrocartilaginous joint)."}, {"id": 1054, "subject": "Anatomy", "difficulty": "Hard", "question": "The filum terminale externum attaches to the:", "options": [{"key": "A", "text": "Sacral hiatus"}, {"key": "B", "text": "Posterior coccyx"}, {"key": "C", "text": "Sacral cornua"}, {"key": "D", "text": "Coccygeal apex"}], "correct": "D", "explanation": "Filum terminale externum (extension of dura) blends with periosteum at the coccygeal apex."}, {"id": 1055, "subject": "Anatomy", "difficulty": "Medium", "question": "Anococcygeal ligament/raphe connects:", "options": [{"key": "A", "text": "Coccyx to ischium"}, {"key": "B", "text": "Coccyx to anal sphincter and perineal body"}, {"key": "C", "text": "Coccyx to sacrum"}, {"key": "D", "text": "Coccyx to pubis"}], "correct": "B", "explanation": "Anococcygeal raphe/ligament connects the coccyx to the external anal sphincter."}, {"id": 1056, "subject": "Anatomy", "difficulty": "Medium", "question": "The coccygeal plexus is formed by:", "options": [{"key": "A", "text": "S4, S5, Co1 nerve roots"}, {"key": "B", "text": "L5, S1, S2"}, {"key": "C", "text": "S1, S2, S3"}, {"key": "D", "text": "S3, S4, S5"}], "correct": "A", "explanation": "The coccygeal plexus is formed by the anterior rami of S4, S5, and Co1."}, {"id": 1057, "subject": "Anatomy", "difficulty": "Medium", "question": "The sacroiliac (SI) joint is classified as:", "options": [{"key": "A", "text": "Fibrous joint only"}, {"key": "B", "text": "Synovial joint (diarthrosis)"}, {"key": "C", "text": "Mixed joint — partly synovial, partly syndesmosis"}, {"key": "D", "text": "Pure synchondrosis"}], "correct": "C", "explanation": "SI joint has an anterior synovial portion and a posterior syndesmotic (interosseous ligament) portion."}, {"id": 1058, "subject": "Anatomy", "difficulty": "Hard", "question": "The articular cartilage on the sacral side of SI joint is:", "options": [{"key": "A", "text": "Fibrocartilage"}, {"key": "B", "text": "Hyaline cartilage (thicker)"}, {"key": "C", "text": "Elastic cartilage"}, {"key": "D", "text": "No cartilage"}], "correct": "B", "explanation": "Sacral articular surface is hyaline cartilage (2-3x thicker); iliac side is fibrocartilage."}, {"id": 1059, "subject": "Anatomy", "difficulty": "Hard", "question": "The synovial portion of SI joint occupies:", "options": [{"key": "A", "text": "Entire joint"}, {"key": "B", "text": "Posterior 1/3 only"}, {"key": "C", "text": "Anterior and inferior part"}, {"key": "D", "text": "Superior part only"}], "correct": "C", "explanation": "The synovial part of SI joint is in the anterior-inferior portion; posterior is ligamentous."}, {"id": 1060, "subject": "Anatomy", "difficulty": "Easy", "question": "The strongest ligament of the body is:", "options": [{"key": "A", "text": "Anterior sacroiliac ligament"}, {"key": "B", "text": "Posterior sacroiliac ligament"}, {"key": "C", "text": "Interosseous sacroiliac ligament"}, {"key": "D", "text": "Sacrotuberous ligament"}], "correct": "C", "explanation": "The interosseous sacroiliac ligament is the strongest ligament in the human body."}, {"id": 1061, "subject": "Anatomy", "difficulty": "Medium", "question": "The interosseous sacroiliac ligament lies:", "options": [{"key": "A", "text": "Anterior to the joint"}, {"key": "B", "text": "Posterior to the joint surface (in the sacral tuberosity region)"}, {"key": "C", "text": "Inferior to the joint"}, {"key": "D", "text": "Superior to the joint"}], "correct": "B", "explanation": "Interosseous SI ligament lies deep, filling the space between sacral tuberosity and iliac tuberosity."}, {"id": 1062, "subject": "Anatomy", "difficulty": "Medium", "question": "The anterior sacroiliac ligament is a thickening of:", "options": [{"key": "A", "text": "Joint capsule anteriorly"}, {"key": "B", "text": "Iliolumbar ligament"}, {"key": "C", "text": "Interosseous ligament"}, {"key": "D", "text": "Sacrotuberous ligament"}], "correct": "A", "explanation": "The anterior sacroiliac ligament is a thickening of the anterior and inferior joint capsule."}, {"id": 1063, "subject": "Anatomy", "difficulty": "Medium", "question": "The posterior sacroiliac ligament is divided into:", "options": [{"key": "A", "text": "Short and long posterior SI ligaments"}, {"key": "B", "text": "Superior and inferior parts"}, {"key": "C", "text": "Medial and lateral parts"}, {"key": "D", "text": "It is a single band"}], "correct": "A", "explanation": "The posterior SI ligament has short (horizontal) and long (vertical/oblique) parts."}, {"id": 1064, "subject": "Anatomy", "difficulty": "Hard", "question": "The long posterior sacroiliac ligament blends with:", "options": [{"key": "A", "text": "Sacrospinous ligament"}, {"key": "B", "text": "Sacrotuberous ligament"}, {"key": "C", "text": "Iliolumbar ligament"}, {"key": "D", "text": "Anterior longitudinal ligament"}], "correct": "B", "explanation": "The long posterior SI ligament blends inferiorly with the sacrotuberous ligament."}, {"id": 1065, "subject": "Anatomy", "difficulty": "Easy", "question": "The sacrotuberous ligament connects:", "options": [{"key": "A", "text": "Sacrum to ischial spine"}, {"key": "B", "text": "Sacrum/coccyx/PSIS to ischial tuberosity"}, {"key": "C", "text": "Sacrum to pubis"}, {"key": "D", "text": "Ilium to ischium"}], "correct": "B", "explanation": "Sacrotuberous ligament connects the lateral sacrum, coccyx, and PSIS to the ischial tuberosity."}, {"id": 1066, "subject": "Anatomy", "difficulty": "Easy", "question": "The sacrospinous ligament connects:", "options": [{"key": "A", "text": "Sacrum/coccyx to ischial spine"}, {"key": "B", "text": "Sacrum to ischial tuberosity"}, {"key": "C", "text": "PSIS to ASIS"}, {"key": "D", "text": "Ilium to sacrum"}], "correct": "A", "explanation": "Sacrospinous ligament connects the lateral sacrum and coccyx to the ischial spine."}, {"id": 1067, "subject": "Anatomy", "difficulty": "Medium", "question": "The sacrospinous and sacrotuberous ligaments convert the greater sciatic notch into the:", "options": [{"key": "A", "text": "Lesser sciatic foramen"}, {"key": "B", "text": "Greater sciatic foramen"}, {"key": "C", "text": "Obturator foramen"}, {"key": "D", "text": "Pudendal canal"}], "correct": "B", "explanation": "These ligaments convert the greater sciatic notch into the greater sciatic foramen."}, {"id": 1068, "subject": "Anatomy", "difficulty": "Medium", "question": "Which structure passes through the greater sciatic foramen ABOVE piriformis?", "options": [{"key": "A", "text": "Sciatic nerve"}, {"key": "B", "text": "Superior gluteal nerve and vessels"}, {"key": "C", "text": "Pudendal nerve"}, {"key": "D", "text": "Inferior gluteal nerve"}], "correct": "B", "explanation": "Superior gluteal nerve and vessels pass above piriformis through the greater sciatic foramen."}, {"id": 1069, "subject": "Anatomy", "difficulty": "Medium", "question": "The iliolumbar ligament connects:", "options": [{"key": "A", "text": "L4-L5 transverse processes to iliac crest"}, {"key": "B", "text": "L5 transverse process to iliac crest"}, {"key": "C", "text": "PSIS to L5"}, {"key": "D", "text": "Ilium to sacrum"}], "correct": "B", "explanation": "Iliolumbar ligament runs from L5 transverse process (primarily) to the iliac crest."}, {"id": 1070, "subject": "Anatomy", "difficulty": "Hard", "question": "The iliolumbar ligament resists:", "options": [{"key": "A", "text": "Extension of lumbar spine"}, {"key": "B", "text": "Anterior translation and axial rotation of L5 on sacrum"}, {"key": "C", "text": "Lateral flexion only"}, {"key": "D", "text": "Posterior translation of L5"}], "correct": "B", "explanation": "Iliolumbar ligament is the primary restraint against anterior translation and rotation of L5 on sacrum."}, {"id": 1071, "subject": "Anatomy", "difficulty": "Hard", "question": "Innervation of the SI joint is by branches from:", "options": [{"key": "A", "text": "L4-S2 posterior and anterior rami"}, {"key": "B", "text": "S1-S4 anterior rami only"}, {"key": "C", "text": "L2-L4 roots"}, {"key": "D", "text": "Pudendal nerve"}], "correct": "A", "explanation": "SI joint innervation is complex: posterior capsule by L4-S1 posterior rami; anterior by L4-S2 anterior rami."}, {"id": 1072, "subject": "Anatomy", "difficulty": "Easy", "question": "The primary movement at the SI joint is:", "options": [{"key": "A", "text": "Gliding"}, {"key": "B", "text": "Nutation and counternutation"}, {"key": "C", "text": "Rotation"}, {"key": "D", "text": "Translation"}], "correct": "B", "explanation": "The SI joint's primary movements are nutation (sacral flexion) and counternutation (sacral extension)."}, {"id": 1073, "subject": "Anatomy", "difficulty": "Medium", "question": "Nutation of sacrum refers to:", "options": [{"key": "A", "text": "Sacral base moves posteriorly, apex anteriorly"}, {"key": "B", "text": "Sacral base moves anteriorly, apex posteriorly"}, {"key": "C", "text": "Sacrum rotates laterally"}, {"key": "D", "text": "No movement"}], "correct": "B", "explanation": "Nutation: sacral base tilts anteriorly-inferiorly, apex moves posteriorly (like nodding forward)."}, {"id": 1074, "subject": "Anatomy", "difficulty": "Medium", "question": "Counternutation of sacrum refers to:", "options": [{"key": "A", "text": "Sacral base moves anteriorly"}, {"key": "B", "text": "Sacral base moves posteriorly, apex anteriorly"}, {"key": "C", "text": "Lateral rotation of sacrum"}, {"key": "D", "text": "Caudal translation"}], "correct": "B", "explanation": "Counternutation is the reverse: sacral base moves posteriorly, apex anteriorly."}, {"id": 1075, "subject": "Anatomy", "difficulty": "Hard", "question": "Nutation tightens which ligaments?", "options": [{"key": "A", "text": "Anterior sacroiliac ligament"}, {"key": "B", "text": "Sacrotuberous and sacrospinous ligaments"}, {"key": "C", "text": "Iliolumbar ligament only"}, {"key": "D", "text": "Posterior sacroiliac ligament"}], "correct": "B", "explanation": "Nutation tightens sacrotuberous, sacrospinous, and interosseous SI ligaments, stabilizing the joint."}, {"id": 1076, "subject": "Anatomy", "difficulty": "Medium", "question": "During standing, the sacrum tends to:", "options": [{"key": "A", "text": "Counternutate"}, {"key": "B", "text": "Nutate"}, {"key": "C", "text": "Remain neutral"}, {"key": "D", "text": "Rotate laterally"}], "correct": "B", "explanation": "Weight bearing in standing causes nutation of the sacrum (self-locking mechanism of the SI joint)."}, {"id": 1077, "subject": "Anatomy", "difficulty": "Hard", "question": "The 'form closure' of SI joint refers to:", "options": [{"key": "A", "text": "Ligamentous tension creating stability"}, {"key": "B", "text": "Bony configuration and joint surface geometry providing stability"}, {"key": "C", "text": "Muscle contraction stability"}, {"key": "D", "text": "All of the above"}], "correct": "B", "explanation": "Form closure = stability from the interlocking shape of bony surfaces and cartilage (passive mechanism)."}, {"id": 1078, "subject": "Anatomy", "difficulty": "Hard", "question": "The 'force closure' of SI joint refers to:", "options": [{"key": "A", "text": "Bony locking mechanism"}, {"key": "B", "text": "Compression by muscles and ligaments (active mechanism)"}, {"key": "C", "text": "Joint fluid pressure"}, {"key": "D", "text": "Capsular tension only"}], "correct": "B", "explanation": "Force closure = additional compression/stability provided by muscles (biceps femoris, gluteus maximus, etc.)."}, {"id": 1079, "subject": "Anatomy", "difficulty": "Medium", "question": "The total range of motion at SI joint is approximately:", "options": [{"key": "A", "text": "0° (no movement)"}, {"key": "B", "text": "1-4°"}, {"key": "C", "text": "10-15°"}, {"key": "D", "text": "20-30°"}], "correct": "B", "explanation": "SI joint has very limited mobility: approximately 1-4° of rotation and 1-2 mm translation."}, {"id": 1080, "subject": "Anatomy", "difficulty": "Hard", "question": "Which muscle is considered a key 'force closure' stabilizer of SI joint?", "options": [{"key": "A", "text": "Psoas major"}, {"key": "B", "text": "Biceps femoris (long head)"}, {"key": "C", "text": "Rectus femoris"}, {"key": "D", "text": "Sartorius"}], "correct": "B", "explanation": "Biceps femoris (via sacrotuberous ligament) and gluteus maximus are key force closure muscles of SI joint."}, {"id": 1081, "subject": "Anatomy", "difficulty": "Hard", "question": "Pelvic incidence (PI) is defined as:", "options": [{"key": "A", "text": "Angle between sacral endplate and horizontal"}, {"key": "B", "text": "Angle between a line perpendicular to sacral endplate and a line from midpoint of sacral endplate to femoral head center"}, {"key": "C", "text": "Lumbar lordosis angle"}, {"key": "D", "text": "Pelvic tilt angle"}], "correct": "B", "explanation": "Pelvic incidence = angle between perpendicular to S1 endplate and line to femoral head axis; it is a fixed anatomical parameter."}, {"id": 1082, "subject": "Anatomy", "difficulty": "Medium", "question": "Posterior pelvic pain during pregnancy is most commonly due to:", "options": [{"key": "A", "text": "Lumbar disc herniation"}, {"key": "B", "text": "SI joint dysfunction due to relaxin-induced ligament laxity"}, {"key": "C", "text": "Piriformis syndrome"}, {"key": "D", "text": "Coccydynia"}], "correct": "B", "explanation": "Relaxin hormone causes SI joint ligament laxity in pregnancy, leading to posterior pelvic/SI pain."}, {"id": 1083, "subject": "Anatomy", "difficulty": "Easy", "question": "The FABER (Patrick's) test provokes:", "options": [{"key": "A", "text": "Lumbar disc pain"}, {"key": "B", "text": "Hip joint and SI joint pain"}, {"key": "C", "text": "Piriformis only"}, {"key": "D", "text": "Femoral nerve stretch"}], "correct": "B", "explanation": "FABER (Flexion, ABduction, External Rotation) stresses both the hip joint and SI joint."}, {"id": 1084, "subject": "Anatomy", "difficulty": "Easy", "question": "The FADIR test is used to assess:", "options": [{"key": "A", "text": "SI joint dysfunction"}, {"key": "B", "text": "Piriformis syndrome and hip impingement"}, {"key": "C", "text": "Lumbar stenosis"}, {"key": "D", "text": "Coccydynia"}], "correct": "B", "explanation": "FADIR (Flexion, ADduction, Internal Rotation) tests for hip impingement and piriformis syndrome."}, {"id": 1085, "subject": "Anatomy", "difficulty": "Medium", "question": "Gaenslen's test is specific for:", "options": [{"key": "A", "text": "Hip pathology"}, {"key": "B", "text": "Sacroiliac joint dysfunction"}, {"key": "C", "text": "L4-L5 disc herniation"}, {"key": "D", "text": "Piriformis"}], "correct": "B", "explanation": "Gaenslen's test (one hip in hyperextension, other in flexion) stresses the SI joint."}, {"id": 1086, "subject": "Anatomy", "difficulty": "Medium", "question": "The posterior shear (thigh thrust) test for SI joint involves:", "options": [{"key": "A", "text": "Flexion of trunk"}, {"key": "B", "text": "Axial load through flexed hip applying posterior shear to SI joint"}, {"key": "C", "text": "Extension of hip"}, {"key": "D", "text": "Rotation of pelvis"}], "correct": "B", "explanation": "Thigh thrust test applies posterior shear through the femur to provoke SI joint pain."}, {"id": 1087, "subject": "Anatomy", "difficulty": "Medium", "question": "The compression test for SI joint is performed by applying:", "options": [{"key": "A", "text": "Anterior-posterior force on ASIS"}, {"key": "B", "text": "Medially directed force on iliac crests (belt test)"}, {"key": "C", "text": "Distraction force on iliac crests"}, {"key": "D", "text": "Downward pressure on symphysis"}], "correct": "B", "explanation": "SI compression test compresses the iliac crests medially to stress the posterior SI structures."}, {"id": 1088, "subject": "Anatomy", "difficulty": "Medium", "question": "The distraction test for SI joint stresses:", "options": [{"key": "A", "text": "Anterior SI ligaments"}, {"key": "B", "text": "Posterior SI ligaments and interosseous ligament"}, {"key": "C", "text": "Sacrotuberous ligament only"}, {"key": "D", "text": "Anterior capsule"}], "correct": "A", "explanation": "Distraction (gapping) test stretches the anterior SI ligaments by pushing ASIS laterally."}, {"id": 1089, "subject": "Anatomy", "difficulty": "Easy", "question": "Ankylosing spondylitis classically starts at:", "options": [{"key": "A", "text": "Lumbar spine"}, {"key": "B", "text": "Sacroiliac joints bilaterally"}, {"key": "C", "text": "Cervical spine"}, {"key": "D", "text": "Hip joints"}], "correct": "B", "explanation": "Ankylosing spondylitis (AS) characteristically begins with bilateral sacroiliitis and ascends."}, {"id": 1090, "subject": "Anatomy", "difficulty": "Medium", "question": "On X-ray, sacroiliitis grading system uses how many grades?", "options": [{"key": "A", "text": "3"}, {"key": "B", "text": "4"}, {"key": "C", "text": "5"}, {"key": "D", "text": "6"}], "correct": "C", "explanation": "NY criteria grades sacroiliitis 0-IV: 0=normal, I=suspicious, II=minimal, III=moderate, IV=ankylosis."}, {"id": 1091, "subject": "Anatomy", "difficulty": "Easy", "question": "The HLA-B27 antigen is strongly associated with:", "options": [{"key": "A", "text": "Rheumatoid arthritis of SI joint"}, {"key": "B", "text": "Ankylosing spondylitis and spondyloarthropathies"}, {"key": "C", "text": "Osteoarthritis of SI joint"}, {"key": "D", "text": "Infective sacroiliitis"}], "correct": "B", "explanation": "HLA-B27 is present in ~90% of ankylosing spondylitis patients; strongly linked to spondyloarthropathies."}, {"id": 1092, "subject": "Anatomy", "difficulty": "Easy", "question": "The 'bamboo spine' appearance on X-ray is due to:", "options": [{"key": "A", "text": "Osteophyte formation"}, {"key": "B", "text": "Ossification of annulus fibrosus (syndesmophytes) in AS"}, {"key": "C", "text": "Disc calcification"}, {"key": "D", "text": "Posterior element fusion only"}], "correct": "B", "explanation": "Bamboo spine in AS = bridging syndesmophytes along the spine, creating a bamboo-like appearance."}, {"id": 1093, "subject": "Anatomy", "difficulty": "Hard", "question": "Osteitis condensans ilii (OCI) affects:", "options": [{"key": "A", "text": "Sacrum bilaterally"}, {"key": "B", "text": "Inferior iliac portion adjacent to SI joint bilaterally"}, {"key": "C", "text": "Entire ilium"}, {"key": "D", "text": "SI joint unilaterally"}], "correct": "B", "explanation": "OCI = triangular sclerosis of the inferior iliac bone near the SI joint, usually bilateral in multiparous women."}, {"id": 1094, "subject": "Anatomy", "difficulty": "Medium", "question": "Piriformis muscle originates from:", "options": [{"key": "A", "text": "Posterior ilium"}, {"key": "B", "text": "Anterior surface of S2-S4 and greater sciatic notch"}, {"key": "C", "text": "Ischial tuberosity"}, {"key": "D", "text": "Sacral cornua"}], "correct": "B", "explanation": "Piriformis originates from the pelvic surface (anterior) of S2-S4 sacral segments and greater sciatic notch."}, {"id": 1095, "subject": "Anatomy", "difficulty": "Easy", "question": "Piriformis syndrome causes pain due to:", "options": [{"key": "A", "text": "Compression of femoral nerve"}, {"key": "B", "text": "Irritation/compression of sciatic nerve by piriformis"}, {"key": "C", "text": "SI joint hypermobility"}, {"key": "D", "text": "L5 disc herniation"}], "correct": "B", "explanation": "Piriformis syndrome occurs when the piriformis irritates/compresses the sciatic nerve in the gluteal region."}, {"id": 1096, "subject": "Anatomy", "difficulty": "Medium", "question": "The Pace test (resisted abduction-ER of hip in seated position) is positive in:", "options": [{"key": "A", "text": "Hip osteoarthritis"}, {"key": "B", "text": "Piriformis syndrome"}, {"key": "C", "text": "SI joint pain"}, {"key": "D", "text": "Greater trochanteric bursitis"}], "correct": "B", "explanation": "Pace test reproduces pain by activating the piriformis against resistance, suggesting piriformis syndrome."}, {"id": 1097, "subject": "Anatomy", "difficulty": "Easy", "question": "The sciatic nerve is formed by:", "options": [{"key": "A", "text": "L4-S3 nerve roots"}, {"key": "B", "text": "L2-L4 nerve roots"}, {"key": "C", "text": "S1-S3 roots only"}, {"key": "D", "text": "L5-S2 roots only"}], "correct": "A", "explanation": "Sciatic nerve = L4, L5, S1, S2, S3 roots; the largest nerve in the body."}, {"id": 1098, "subject": "Anatomy", "difficulty": "Easy", "question": "The pudendal nerve arises from:", "options": [{"key": "A", "text": "L2-L4"}, {"key": "B", "text": "S2-S4"}, {"key": "C", "text": "S1-S3"}, {"key": "D", "text": "L5-S1"}], "correct": "B", "explanation": "Pudendal nerve arises from S2, S3, S4 anterior rami and exits through the greater sciatic foramen."}, {"id": 1099, "subject": "Anatomy", "difficulty": "Hard", "question": "Alcock's canal (pudendal canal) is located in:", "options": [{"key": "A", "text": "Greater sciatic foramen"}, {"key": "B", "text": "Lateral wall of ischiorectal fossa (obturator fascia)"}, {"key": "C", "text": "Lesser sciatic foramen"}, {"key": "D", "text": "Sacral canal"}], "correct": "B", "explanation": "Alcock's canal is a fascial canal in the lateral wall of the ischiorectal fossa transmitting the pudendal nerve."}, {"id": 1100, "subject": "Anatomy", "difficulty": "Hard", "question": "The nerve to piriformis arises from:", "options": [{"key": "A", "text": "L4-L5"}, {"key": "B", "text": "S1-S2"}, {"key": "C", "text": "S2-S3"}, {"key": "D", "text": "L5-S1"}], "correct": "B", "explanation": "The nerve to piriformis arises from S1 and S2 anterior rami directly."}, {"id": 1101, "subject": "Anatomy", "difficulty": "Medium", "question": "The superior gluteal nerve (L4-S1) exits:", "options": [{"key": "A", "text": "Below piriformis"}, {"key": "B", "text": "Above piriformis through greater sciatic foramen"}, {"key": "C", "text": "Through lesser sciatic foramen"}, {"key": "D", "text": "Through obturator foramen"}], "correct": "B", "explanation": "Superior gluteal nerve and vessels exit the greater sciatic foramen ABOVE piriformis."}, {"id": 1102, "subject": "Anatomy", "difficulty": "Medium", "question": "The inferior gluteal nerve exits:", "options": [{"key": "A", "text": "Above piriformis"}, {"key": "B", "text": "Below piriformis through greater sciatic foramen"}, {"key": "C", "text": "Through lesser sciatic foramen"}, {"key": "D", "text": "Through obturator foramen"}], "correct": "B", "explanation": "Inferior gluteal nerve (L5-S2) exits BELOW piriformis through the greater sciatic foramen."}, {"id": 1103, "subject": "Anatomy", "difficulty": "Hard", "question": "The nerve to obturator internus arises from:", "options": [{"key": "A", "text": "L3-L4"}, {"key": "B", "text": "L5-S2"}, {"key": "C", "text": "S2-S3"}, {"key": "D", "text": "S1-S2"}], "correct": "B", "explanation": "Nerve to obturator internus arises from L5, S1, S2 and exits via greater sciatic foramen below piriformis."}, {"id": 1104, "subject": "Anatomy", "difficulty": "Medium", "question": "Sacral sparing in spinal cord injury indicates:", "options": [{"key": "A", "text": "Complete injury"}, {"key": "B", "text": "Injury below S1"}, {"key": "C", "text": "Incomplete injury with preserved S4-S5 function"}, {"key": "D", "text": "No significance"}], "correct": "C", "explanation": "Sacral sparing (preserved perianal sensation/rectal tone/great toe flexion) indicates incomplete SCI."}, {"id": 1105, "subject": "Anatomy", "difficulty": "Medium", "question": "The dermatome for perianal and perineal sensation is:", "options": [{"key": "A", "text": "L5"}, {"key": "B", "text": "S1"}, {"key": "C", "text": "S3"}, {"key": "D", "text": "S4-S5"}], "correct": "D", "explanation": "Perianal and perineal sensation is supplied by S4-S5 dermatomes (saddle area)."}, {"id": 1106, "subject": "Anatomy", "difficulty": "Medium", "question": "The true pelvis is bounded superiorly by:", "options": [{"key": "A", "text": "Pelvic floor"}, {"key": "B", "text": "Pelvic inlet (linea terminalis)"}, {"key": "C", "text": "Sacral promontory only"}, {"key": "D", "text": "Iliac crest"}], "correct": "B", "explanation": "True pelvis is bounded superiorly by the pelvic inlet (linea terminalis/pelvic brim)."}, {"id": 1107, "subject": "Anatomy", "difficulty": "Hard", "question": "The pelvic inlet (brim) is formed by:", "options": [{"key": "A", "text": "Sacral promontory, ala of sacrum, arcuate line, pectineal line, pubic crest"}, {"key": "B", "text": "Ischial tuberosities only"}, {"key": "C", "text": "Coccyx and pubis"}, {"key": "D", "text": "Iliac crests"}], "correct": "A", "explanation": "Pelvic inlet = sacral promontory + ala of sacrum + arcuate line + pectineal line + pubic symphysis superior."}, {"id": 1108, "subject": "Anatomy", "difficulty": "Hard", "question": "The obstetric conjugate (true conjugate) is measured from:", "options": [{"key": "A", "text": "Sacral promontory to inferior symphysis"}, {"key": "B", "text": "Sacral promontory to posterior superior pubic symphysis"}, {"key": "C", "text": "Coccyx to pubic arch"}, {"key": "D", "text": "S2 to pubic symphysis"}], "correct": "B", "explanation": "Obstetric conjugate = shortest AP diameter of pelvis; from sacral promontory to posterior surface of pubic symphysis."}, {"id": 1109, "subject": "Anatomy", "difficulty": "Hard", "question": "The diagonal conjugate is measured from:", "options": [{"key": "A", "text": "Sacral promontory to inferior margin of symphysis pubis"}, {"key": "B", "text": "Sacral promontory to superior symphysis"}, {"key": "C", "text": "Coccyx to symphysis"}, {"key": "D", "text": "S2 to pubis"}], "correct": "A", "explanation": "Diagonal conjugate (clinically measurable) = sacral promontory to inferior border of pubic symphysis; normally >12.5 cm."}, {"id": 1110, "subject": "Anatomy", "difficulty": "Medium", "question": "The pelvic outlet is bounded by:", "options": [{"key": "A", "text": "Pelvic brim anteriorly"}, {"key": "B", "text": "Symphysis pubis, ischial tuberosities, sacrotuberous ligament, coccyx"}, {"key": "C", "text": "Iliac wings"}, {"key": "D", "text": "Ischial spines only"}], "correct": "B", "explanation": "Pelvic outlet boundaries: symphysis pubis (anterior), ischial tuberosities (lateral), sacrotuberous ligaments, coccyx (posterior)."}, {"id": 1111, "subject": "Anatomy", "difficulty": "Medium", "question": "The interspinous diameter of the pelvis (narrowest diameter) is between:", "options": [{"key": "A", "text": "Iliac crests"}, {"key": "B", "text": "Ischial spines"}, {"key": "C", "text": "Ischial tuberosities"}, {"key": "D", "text": "Sacral ala"}], "correct": "B", "explanation": "The interspinous diameter (between ischial spines) is the narrowest pelvic diameter, normally ≥10.5 cm."}, {"id": 1112, "subject": "Anatomy", "difficulty": "Easy", "question": "The gold standard imaging for sacroiliac joint inflammation is:", "options": [{"key": "A", "text": "Plain X-ray"}, {"key": "B", "text": "CT scan"}, {"key": "C", "text": "MRI with STIR sequence"}, {"key": "D", "text": "Bone scan"}], "correct": "C", "explanation": "MRI (STIR/T2 fat-suppressed) is gold standard for detecting early sacroiliitis (bone marrow edema)."}, {"id": 1113, "subject": "Anatomy", "difficulty": "Medium", "question": "CT scan of SI joint is best for detecting:", "options": [{"key": "A", "text": "Bone marrow edema"}, {"key": "B", "text": "Structural/bony changes: erosions, sclerosis, ankylosis"}, {"key": "C", "text": "Soft tissue inflammation"}, {"key": "D", "text": "Nerve root compression"}], "correct": "B", "explanation": "CT is superior for structural changes (erosions, sclerosis, joint space changes) in sacroiliitis."}, {"id": 1114, "subject": "Anatomy", "difficulty": "Medium", "question": "Ferguson's view (X-ray) is used for:", "options": [{"key": "A", "text": "Lumbar disc"}, {"key": "B", "text": "Sacroiliac joint visualization"}, {"key": "C", "text": "Coccyx lateral view"}, {"key": "D", "text": "Lumbar lordosis measurement"}], "correct": "B", "explanation": "Ferguson's view (AP pelvis with 25-30° cephalad angulation) provides en-face view of SI joints."}, {"id": 1115, "subject": "Anatomy", "difficulty": "Medium", "question": "On MRI, active sacroiliitis shows as:", "options": [{"key": "A", "text": "T1 hypointense, T2/STIR hyperintense (bone marrow edema)"}, {"key": "B", "text": "T1 hyperintense"}, {"key": "C", "text": "Only T1 changes"}, {"key": "D", "text": "Normal signal"}], "correct": "A", "explanation": "Active sacroiliitis = subchondral bone marrow edema: T1 low, STIR/T2 fat-sat high signal."}, {"id": 1116, "subject": "Anatomy", "difficulty": "Medium", "question": "Sacral insufficiency fracture is best diagnosed by:", "options": [{"key": "A", "text": "Plain X-ray"}, {"key": "B", "text": "CT scan"}, {"key": "C", "text": "MRI or bone scan"}, {"key": "D", "text": "Ultrasound"}], "correct": "C", "explanation": "Sacral insufficiency fractures (in osteoporosis) are best seen on MRI or bone scan; X-rays often miss them."}, {"id": 1117, "subject": "Anatomy", "difficulty": "Hard", "question": "Zone I sacral fractures (Denis classification) involve:", "options": [{"key": "A", "text": "Sacral canal"}, {"key": "B", "text": "Sacral ala (lateral to neural foramina)"}, {"key": "C", "text": "Neural foramina"}, {"key": "D", "text": "Coccyx"}], "correct": "B", "explanation": "Denis Zone I = lateral sacral ala, lateral to neural foramina; least neurological risk."}, {"id": 1118, "subject": "Anatomy", "difficulty": "Hard", "question": "Zone II sacral fractures involve:", "options": [{"key": "A", "text": "Lateral to foramina"}, {"key": "B", "text": "Through the neural foramina"}, {"key": "C", "text": "The sacral canal (central)"}, {"key": "D", "text": "Coccyx only"}], "correct": "B", "explanation": "Denis Zone II fractures pass through the sacral neural foramina; risk of root injury."}, {"id": 1119, "subject": "Anatomy", "difficulty": "Hard", "question": "Zone III sacral fractures (Denis) involve:", "options": [{"key": "A", "text": "Lateral ala"}, {"key": "B", "text": "Foramina only"}, {"key": "C", "text": "Central sacral canal"}, {"key": "D", "text": "Coccyx"}], "correct": "C", "explanation": "Denis Zone III = central fractures involving the sacral canal; highest risk of cauda equina injury."}, {"id": 1120, "subject": "Anatomy", "difficulty": "Hard", "question": "H-type (bilateral Zone II + transverse) sacral fracture is associated with:", "options": [{"key": "A", "text": "Isolated L5 injury"}, {"key": "B", "text": "Bilateral sacral root injury and cauda equina syndrome"}, {"key": "C", "text": "Only pelvic ring disruption"}, {"key": "D", "text": "Coccydynia"}], "correct": "B", "explanation": "H-type (U-type) sacral fracture = bilateral vertical + transverse component; high risk of neurological injury."}, {"id": 1121, "subject": "Anatomy", "difficulty": "Medium", "question": "Sacrococcygeal teratoma is most common in:", "options": [{"key": "A", "text": "Male infants"}, {"key": "B", "text": "Female infants"}, {"key": "C", "text": "Equal in both sexes"}, {"key": "D", "text": "Adults only"}], "correct": "B", "explanation": "Sacrococcygeal teratoma is the most common neonatal tumor; 3-4x more common in females."}, {"id": 1122, "subject": "Anatomy", "difficulty": "Medium", "question": "Tarlov cysts are:", "options": [{"key": "A", "text": "Meningeal cysts along sacral nerve root sleeves"}, {"key": "B", "text": "Disc cysts"}, {"key": "C", "text": "Epidermoid cysts in sacral canal"}, {"key": "D", "text": "SI joint ganglia"}], "correct": "A", "explanation": "Tarlov (perineural) cysts are dilated nerve root sleeve/meningeal cysts, common at sacral levels."}, {"id": 1123, "subject": "Anatomy", "difficulty": "Medium", "question": "The sacral hiatus is used clinically NOT only for caudal epidural but also for:", "options": [{"key": "A", "text": "Lumbar puncture"}, {"key": "B", "text": "Intrathecal drug delivery only at sacral level"}, {"key": "C", "text": "Sacral nerve root blocks"}, {"key": "D", "text": "All of the above"}], "correct": "C", "explanation": "The sacral hiatus is also used for sacral nerve root blocks and caudal corticosteroid injections."}, {"id": 1124, "subject": "Anatomy", "difficulty": "Medium", "question": "Alar dysgenesis (sacral agenesis) is associated with maternal:", "options": [{"key": "A", "text": "Hypothyroidism"}, {"key": "B", "text": "Diabetes mellitus"}, {"key": "C", "text": "Hypertension"}, {"key": "D", "text": "Rubella infection"}], "correct": "B", "explanation": "Sacral agenesis/caudal regression syndrome is strongly associated with maternal diabetes mellitus."}, {"id": 1125, "subject": "Anatomy", "difficulty": "Hard", "question": "The 'trident sacrum' configuration on X-ray suggests:", "options": [{"key": "A", "text": "Normal variant"}, {"key": "B", "text": "Sacral agenesis"}, {"key": "C", "text": "Down syndrome"}, {"key": "D", "text": "Achondroplasia"}], "correct": "C", "explanation": "Trident sacrum (short sacrum with hypoplastic S1) is a feature of Down syndrome."}, {"id": 1126, "subject": "Anatomy", "difficulty": "Medium", "question": "The erector spinae muscle group attaches to sacrum via:", "options": [{"key": "A", "text": "Sacrotuberous ligament"}, {"key": "B", "text": "Thoracolumbar fascia and sacral crest"}, {"key": "C", "text": "Posterior SI ligament"}, {"key": "D", "text": "Sacrospinous ligament"}], "correct": "B", "explanation": "Erector spinae (iliocostalis, longissimus, spinalis) attach to sacrum via thoracolumbar fascia and sacral crests."}, {"id": 1127, "subject": "Anatomy", "difficulty": "Medium", "question": "The levator ani muscle attaches to:", "options": [{"key": "A", "text": "Coccyx and anococcygeal raphe"}, {"key": "B", "text": "Sacral promontory"}, {"key": "C", "text": "Sacral cornua only"}, {"key": "D", "text": "Ischial spine"}], "correct": "A", "explanation": "Levator ani (including coccygeus) inserts into the coccyx and anococcygeal raphe, forming the pelvic floor."}, {"id": 1128, "subject": "Anatomy", "difficulty": "Easy", "question": "The gluteus maximus originates from:", "options": [{"key": "A", "text": "ASIS only"}, {"key": "B", "text": "Posterior ilium, sacrum, coccyx, and sacrotuberous ligament"}, {"key": "C", "text": "Greater trochanter"}, {"key": "D", "text": "Ischial tuberosity"}], "correct": "B", "explanation": "Gluteus maximus has a broad origin from the posterior ilium, sacrum, coccyx, and sacrotuberous ligament."}, {"id": 1129, "subject": "Anatomy", "difficulty": "Hard", "question": "Which muscle's contraction can cause counternutation of sacrum?", "options": [{"key": "A", "text": "Rectus abdominis and hip flexors"}, {"key": "B", "text": "Erector spinae and gluteus maximus"}, {"key": "C", "text": "Psoas major"}, {"key": "D", "text": "Multifidus alone"}], "correct": "A", "explanation": "Rectus abdominis (flexion) and hip flexors cause posterior pelvic tilt/counternutation of sacrum."}, {"id": 1130, "subject": "Anatomy", "difficulty": "Medium", "question": "The lumbosacral trunk is formed by:", "options": [{"key": "A", "text": "L5 anterior ramus only"}, {"key": "B", "text": "Part of L4 and all of L5 anterior rami"}, {"key": "C", "text": "L4-L5 posterior rami"}, {"key": "D", "text": "L3-L5 anterior rami"}], "correct": "B", "explanation": "Lumbosacral trunk = part of L4 + entire L5 anterior rami; joins sacral plexus."}, {"id": 1131, "subject": "Anatomy", "difficulty": "Medium", "question": "Sacral spinal stenosis most commonly causes:", "options": [{"key": "A", "text": "Lumbar radiculopathy"}, {"key": "B", "text": "Cauda equina syndrome and neurogenic claudication"}, {"key": "C", "text": "Myelopathy"}, {"key": "D", "text": "Upper motor neuron signs"}], "correct": "B", "explanation": "Stenosis at sacral level compresses cauda equina roots, causing neurogenic claudication/CES."}, {"id": 1132, "subject": "Anatomy", "difficulty": "Medium", "question": "The pelvic splanchnic nerves (nervi erigentes) arise from:", "options": [{"key": "A", "text": "T10-L2 (sympathetic)"}, {"key": "B", "text": "S2-S4 (parasympathetic)"}, {"key": "C", "text": "L1-L2 only"}, {"key": "D", "text": "S1-S2"}], "correct": "B", "explanation": "Pelvic splanchnic nerves carry parasympathetic supply to pelvic organs, arising from S2, S3, S4."}, {"id": 1133, "subject": "Anatomy", "difficulty": "Hard", "question": "The presacral nerve (superior hypogastric plexus) is located at:", "options": [{"key": "A", "text": "L1-L2 level"}, {"key": "B", "text": "L5-S1 anterior to sacral promontory"}, {"key": "C", "text": "S2-S3 level"}, {"key": "D", "text": "Posterior sacrum"}], "correct": "B", "explanation": "Superior hypogastric plexus (presacral nerve) lies anterior to the sacral promontory at L5-S1."}, {"id": 1134, "subject": "Anatomy", "difficulty": "Medium", "question": "Referred pain from SI joint is most commonly felt in:", "options": [{"key": "A", "text": "Groin only"}, {"key": "B", "text": "Posterior thigh to knee, buttock, and lower lumbar region"}, {"key": "C", "text": "Foot and ankle"}, {"key": "D", "text": "Anterior thigh"}], "correct": "B", "explanation": "SI joint pain refers to the posterior thigh (above knee), buttock, and lower lumbar/sacral region."}, {"id": 1135, "subject": "Anatomy", "difficulty": "Medium", "question": "Active SLR (straight leg raise) test is used to assess:", "options": [{"key": "A", "text": "Disc herniation"}, {"key": "B", "text": "Load transfer through pelvis and SI joint stability"}, {"key": "C", "text": "Hip flexor strength only"}, {"key": "D", "text": "Hamstring flexibility"}], "correct": "B", "explanation": "Active SLR test evaluates force closure of the SI joint; positive if pain with raising leg from supine."}, {"id": 1136, "subject": "Anatomy", "difficulty": "Medium", "question": "The P4 (posterior pelvic pain provocation) test applies load through:", "options": [{"key": "A", "text": "Symphysis pubis"}, {"key": "B", "text": "Flexed hip with posterior shear on SI joint"}, {"key": "C", "text": "ASIS"}, {"key": "D", "text": "Coccyx"}], "correct": "B", "explanation": "P4/thigh thrust test: examiner applies posterior shear via the femur through the flexed hip onto SI joint."}, {"id": 1137, "subject": "Anatomy", "difficulty": "Hard", "question": "Which set of 5 SI joint provocation tests, if 3/5 positive, is most diagnostic?", "options": [{"key": "A", "text": "FABER, SLR, Gaenslen, distraction, compression"}, {"key": "B", "text": "Distraction, thigh thrust, compression, Gaenslen, sacral thrust"}, {"key": "C", "text": "SLR, FADIR, Pace, Thomas, Ober"}, {"key": "D", "text": "None standardized"}], "correct": "B", "explanation": "Laslett's cluster of 5 SI tests (distraction, thigh thrust, compression, Gaenslen's, sacral thrust): ≥3/5 positive is diagnostic."}, {"id": 1138, "subject": "Anatomy", "difficulty": "Easy", "question": "How many pairs of ribs are present in the human thoracic cage?", "options": [{"key": "A", "text": "10"}, {"key": "B", "text": "11"}, {"key": "C", "text": "12"}, {"key": "D", "text": "14"}], "correct": "C", "explanation": "There are 12 pairs of ribs in the human thoracic cage (24 ribs total)."}, {"id": 1139, "subject": "Anatomy", "difficulty": "Easy", "question": "True ribs are those that:", "options": [{"key": "A", "text": "Articulate with sternum via costal cartilage directly"}, {"key": "B", "text": "Do not articulate with sternum"}, {"key": "C", "text": "Float freely"}, {"key": "D", "text": "Articulate only with vertebrae"}], "correct": "A", "explanation": "True ribs (1-7) have their own costal cartilage connecting directly to the sternum."}, {"id": 1140, "subject": "Anatomy", "difficulty": "Easy", "question": "False ribs include which rib numbers?", "options": [{"key": "A", "text": "1-7"}, {"key": "B", "text": "8-12"}, {"key": "C", "text": "8-10"}, {"key": "D", "text": "11-12"}], "correct": "B", "explanation": "False ribs (8-12) either join the cartilage above (8-10) or are floating (11-12)."}, {"id": 1141, "subject": "Anatomy", "difficulty": "Easy", "question": "Floating ribs are:", "options": [{"key": "A", "text": "Ribs 10-12"}, {"key": "B", "text": "Ribs 11 and 12"}, {"key": "C", "text": "Ribs 9-12"}, {"key": "D", "text": "Ribs 10 and 11"}], "correct": "B", "explanation": "Floating ribs (11 and 12) have no anterior attachment; their costal cartilages are free."}, {"id": 1142, "subject": "Anatomy", "difficulty": "Medium", "question": "The head of a typical rib articulates with:", "options": [{"key": "A", "text": "One vertebral body only"}, {"key": "B", "text": "Two adjacent vertebral bodies and the intervertebral disc"}, {"key": "C", "text": "Transverse process only"}, {"key": "D", "text": "Sternum"}], "correct": "B", "explanation": "A typical rib head (2-9) articulates with two adjacent vertebral bodies and the intervening disc."}, {"id": 1143, "subject": "Anatomy", "difficulty": "Easy", "question": "The tubercle of a rib articulates with:", "options": [{"key": "A", "text": "Adjacent vertebral body"}, {"key": "B", "text": "Transverse process of corresponding vertebra"}, {"key": "C", "text": "Sternum"}, {"key": "D", "text": "Costal cartilage"}], "correct": "B", "explanation": "The rib tubercle articulates with the transverse process of the numerically corresponding vertebra."}, {"id": 1144, "subject": "Anatomy", "difficulty": "Easy", "question": "The costal groove is located on the:", "options": [{"key": "A", "text": "Superior surface of rib"}, {"key": "B", "text": "Inferior inner surface of rib"}, {"key": "C", "text": "Anterior surface of rib"}, {"key": "D", "text": "Outer surface of rib"}], "correct": "B", "explanation": "The costal groove on the inferior inner border of the rib lodges the intercostal vein, artery, and nerve (VAN from above)."}, {"id": 1145, "subject": "Anatomy", "difficulty": "Easy", "question": "The order of structures in the costal groove (superior to inferior) is:", "options": [{"key": "A", "text": "Nerve, Artery, Vein"}, {"key": "B", "text": "Vein, Artery, Nerve"}, {"key": "C", "text": "Artery, Vein, Nerve"}, {"key": "D", "text": "Vein, Nerve, Artery"}], "correct": "B", "explanation": "VAN = Vein (most superior), Artery, Nerve (most inferior) in the costal groove."}, {"id": 1146, "subject": "Anatomy", "difficulty": "Medium", "question": "The angle of the rib is the site where the rib:", "options": [{"key": "A", "text": "Articulates with vertebra"}, {"key": "B", "text": "Bends sharply anterolaterally"}, {"key": "C", "text": "Connects to costal cartilage"}, {"key": "D", "text": "Gives origin to intercostal muscle"}], "correct": "B", "explanation": "The angle of the rib is the point of sharpest curvature, where erector spinae attach and the rib bends forward."}, {"id": 1147, "subject": "Anatomy", "difficulty": "Easy", "question": "Which rib is the shortest and broadest?", "options": [{"key": "A", "text": "Rib 1"}, {"key": "B", "text": "Rib 2"}, {"key": "C", "text": "Rib 7"}, {"key": "D", "text": "Rib 12"}], "correct": "A", "explanation": "Rib 1 is the shortest, broadest, and most curved of all ribs."}, {"id": 1148, "subject": "Anatomy", "difficulty": "Medium", "question": "The groove for the subclavian artery is found on:", "options": [{"key": "A", "text": "Rib 2"}, {"key": "B", "text": "Rib 1 (posterior surface)"}, {"key": "C", "text": "Rib 3"}, {"key": "D", "text": "Clavicle"}], "correct": "B", "explanation": "Rib 1 has a groove for the subclavian artery on its superior surface (posterior to the scalene tubercle)."}, {"id": 1149, "subject": "Anatomy", "difficulty": "Medium", "question": "The scalene tubercle (Lisfranc tubercle) is an attachment for:", "options": [{"key": "A", "text": "Serratus anterior"}, {"key": "B", "text": "Scalenus anterior (anterior scalene)"}, {"key": "C", "text": "Scalenus medius"}, {"key": "D", "text": "Subclavius"}], "correct": "B", "explanation": "Scalene tubercle on the superior surface of rib 1 is the insertion of the scalenus anterior muscle."}, {"id": 1150, "subject": "Anatomy", "difficulty": "Hard", "question": "Rib 1 has how many articular facets on its head?", "options": [{"key": "A", "text": "One"}, {"key": "B", "text": "Two"}, {"key": "C", "text": "Three"}], "correct": "A", "explanation": "Rib 1 (like ribs 10-12) has only ONE articular facet on its head, articulating with T1 only."}, {"id": 1151, "subject": "Anatomy", "difficulty": "Medium", "question": "Which rib has the highest risk of injury to the brachial plexus and subclavian vessels when fractured?", "options": [{"key": "A", "text": "Rib 4"}, {"key": "B", "text": "Rib 1"}, {"key": "C", "text": "Rib 7"}, {"key": "D", "text": "Rib 12"}], "correct": "B", "explanation": "Fracture of rib 1 risks injury to the brachial plexus and subclavian vessels due to proximity."}, {"id": 1152, "subject": "Anatomy", "difficulty": "Medium", "question": "Cervical rib is an anomalous rib arising from:", "options": [{"key": "A", "text": "C6"}, {"key": "B", "text": "C7"}, {"key": "C", "text": "T1"}, {"key": "D", "text": "C5"}], "correct": "B", "explanation": "Cervical rib arises from C7 vertebra; can compress subclavian artery/brachial plexus (thoracic outlet syndrome)."}, {"id": 1153, "subject": "Anatomy", "difficulty": "Medium", "question": "The costal cartilage of which rib is the longest?", "options": [{"key": "A", "text": "Rib 1"}, {"key": "B", "text": "Rib 7"}, {"key": "C", "text": "Rib 10"}, {"key": "D", "text": "Rib 5"}], "correct": "B", "explanation": "Rib 7 has the longest costal cartilage among the true ribs."}, {"id": 1154, "subject": "Anatomy", "difficulty": "Medium", "question": "The neck of the rib connects:", "options": [{"key": "A", "text": "Head to body (shaft)"}, {"key": "B", "text": "Tubercle to angle"}, {"key": "C", "text": "Costal cartilage to body"}, {"key": "D", "text": "Head to tubercle"}], "correct": "D", "explanation": "The neck is the constricted portion connecting the head to the tubercle of the rib."}, {"id": 1155, "subject": "Anatomy", "difficulty": "Medium", "question": "The costovertebral joint is classified as:", "options": [{"key": "A", "text": "Fibrous joint"}, {"key": "B", "text": "Cartilaginous joint"}, {"key": "C", "text": "Synovial plane joint"}, {"key": "D", "text": "Pivot joint"}], "correct": "C", "explanation": "Costovertebral joints (head of rib with vertebral body) are synovial plane joints."}, {"id": 1156, "subject": "Anatomy", "difficulty": "Hard", "question": "The intra-articular ligament of the costovertebral joint divides the joint into:", "options": [{"key": "A", "text": "No division"}, {"key": "B", "text": "Two cavities (superior and inferior)"}, {"key": "C", "text": "Three compartments"}, {"key": "D", "text": "Anterior and posterior parts"}], "correct": "B", "explanation": "The intra-articular ligament divides the costovertebral joint into two synovial cavities (for the two vertebral facets)."}, {"id": 1157, "subject": "Anatomy", "difficulty": "Hard", "question": "Ribs 10, 11, and 12 differ from typical ribs because:", "options": [{"key": "A", "text": "They are floating"}, {"key": "B", "text": "They have only one facet on the head"}, {"key": "C", "text": "They lack a tubercle"}, {"key": "D", "text": "Both B and C for 11 and 12"}], "correct": "D", "explanation": "Ribs 11 and 12 have a single head facet and no tubercle (no costotransverse joint); rib 10 has a single facet only."}, {"id": 1158, "subject": "Anatomy", "difficulty": "Medium", "question": "The pump handle movement of ribs primarily increases:", "options": [{"key": "A", "text": "Transverse diameter of thorax"}, {"key": "B", "text": "AP (anteroposterior) diameter of thorax"}, {"key": "C", "text": "Vertical diameter of thorax"}, {"key": "D", "text": "Oblique diameter"}], "correct": "B", "explanation": "Upper ribs move in a pump-handle manner, elevating the sternum and increasing AP diameter."}, {"id": 1159, "subject": "Anatomy", "difficulty": "Medium", "question": "The bucket handle movement of ribs primarily increases:", "options": [{"key": "A", "text": "AP diameter"}, {"key": "B", "text": "Transverse diameter of thorax"}, {"key": "C", "text": "Vertical diameter"}, {"key": "D", "text": "No change in diameter"}], "correct": "B", "explanation": "Lower ribs move in a bucket-handle manner, swinging outward to increase transverse (lateral) diameter."}, {"id": 1160, "subject": "Anatomy", "difficulty": "Hard", "question": "The caliper movement is seen in:", "options": [{"key": "A", "text": "Rib 1"}, {"key": "B", "text": "Floating ribs (11-12)"}, {"key": "C", "text": "Middle ribs"}, {"key": "D", "text": "Upper ribs"}], "correct": "B", "explanation": "Floating ribs (11-12) move in a caliper (pincer) motion, moving laterally during inspiration."}, {"id": 1161, "subject": "Anatomy", "difficulty": "Easy", "question": "The sternum consists of how many parts?", "options": [{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}], "correct": "B", "explanation": "Sternum has 3 parts: manubrium, body (gladiolus), and xiphoid process."}, {"id": 1162, "subject": "Anatomy", "difficulty": "Easy", "question": "The sternal angle (angle of Louis/Ludwig) is the junction between:", "options": [{"key": "A", "text": "Manubrium and body of sternum"}, {"key": "B", "text": "Body and xiphoid process"}, {"key": "C", "text": "Manubrium and clavicle"}, {"key": "D", "text": "Rib 1 and manubrium"}], "correct": "A", "explanation": "Sternal angle (of Louis) = manubriosternal joint; at level of T4-T5 disc and 2nd costal cartilage."}, {"id": 1163, "subject": "Anatomy", "difficulty": "Easy", "question": "The sternal angle is a landmark for:", "options": [{"key": "A", "text": "Rib 1 attachment"}, {"key": "B", "text": "Rib 2 costal cartilage, carina, aortic arch, T4-T5 level"}, {"key": "C", "text": "Rib 3 attachment"}, {"key": "D", "text": "Xiphoid process"}], "correct": "B", "explanation": "Sternal angle is a key landmark: marks rib 2 cartilage, bifurcation of trachea (carina), aortic arch, T4-T5 disc."}, {"id": 1164, "subject": "Anatomy", "difficulty": "Medium", "question": "The xiphisternal joint is at the level of:", "options": [{"key": "A", "text": "T8"}, {"key": "B", "text": "T9"}, {"key": "C", "text": "T10"}, {"key": "D", "text": "T7"}], "correct": "B", "explanation": "The xiphisternal junction (body-xiphoid) is at the level of T9."}, {"id": 1165, "subject": "Anatomy", "difficulty": "Medium", "question": "The jugular (suprasternal) notch is at the level of:", "options": [{"key": "A", "text": "T1-T2"}, {"key": "B", "text": "T2-T3"}, {"key": "C", "text": "T3"}, {"key": "D", "text": "T4"}], "correct": "B", "explanation": "The jugular notch of the manubrium is at the level of the T2-T3 intervertebral disc."}, {"id": 1166, "subject": "Anatomy", "difficulty": "Medium", "question": "The manubrium articulates with which ribs?", "options": [{"key": "A", "text": "Ribs 1 and 2 only"}, {"key": "B", "text": "Ribs 1 and upper half of rib 2"}, {"key": "C", "text": "Ribs 1-3"}, {"key": "D", "text": "Rib 1 only"}], "correct": "B", "explanation": "The manubrium articulates with rib 1 (directly) and the upper part of rib 2 at the sternal angle."}, {"id": 1167, "subject": "Anatomy", "difficulty": "Medium", "question": "The body of sternum articulates with which ribs?", "options": [{"key": "A", "text": "Ribs 2-7"}, {"key": "B", "text": "Lower half of rib 2 through rib 7"}, {"key": "C", "text": "Ribs 3-7"}, {"key": "D", "text": "Ribs 1-6"}], "correct": "B", "explanation": "The sternal body articulates with lower half of rib 2 cartilage through rib 7 cartilage."}, {"id": 1168, "subject": "Anatomy", "difficulty": "Hard", "question": "The xiphoid process ossifies completely by approximately:", "options": [{"key": "A", "text": "20 years"}, {"key": "B", "text": "40 years"}, {"key": "C", "text": "Birth"}, {"key": "D", "text": "60 years"}], "correct": "B", "explanation": "Xiphoid process is cartilaginous at birth, begins ossifying in early adulthood, completes ~40 years."}, {"id": 1169, "subject": "Anatomy", "difficulty": "Hard", "question": "Sternal angle is a synovial joint of type:", "options": [{"key": "A", "text": "Ball and socket"}, {"key": "B", "text": "Saddle"}, {"key": "C", "text": "Plane (gliding)"}, {"key": "D", "text": "Hinge"}], "correct": "C", "explanation": "Manubriosternal joint is a symphysis (fibrocartilaginous) or synovial plane joint; allows slight angular movement."}, {"id": 1170, "subject": "Anatomy", "difficulty": "Hard", "question": "The primary ossification center of the sternum develops from:", "options": [{"key": "A", "text": "Membranous ossification"}, {"key": "B", "text": "Two lateral sternal bars that fuse"}, {"key": "C", "text": "Single central bar"}, {"key": "D", "text": "Neural crest cells"}], "correct": "B", "explanation": "Sternum develops from two lateral sternal bars derived from mesoderm that fuse in the midline."}, {"id": 1171, "subject": "Anatomy", "difficulty": "Easy", "question": "Pectus excavatum (funnel chest) is a deformity of:", "options": [{"key": "A", "text": "Ribs only"}, {"key": "B", "text": "Sternum depressed inward (posterior displacement)"}, {"key": "C", "text": "Laterally displaced sternum"}, {"key": "D", "text": "Manubrium only"}], "correct": "B", "explanation": "Pectus excavatum = posterior depression of sternum, reducing AP thoracic diameter."}, {"id": 1172, "subject": "Anatomy", "difficulty": "Easy", "question": "Pectus carinatum (pigeon chest) refers to:", "options": [{"key": "A", "text": "Posterior sternal depression"}, {"key": "B", "text": "Anterior protrusion of sternum"}, {"key": "C", "text": "Lateral rib flaring"}, {"key": "D", "text": "Rib absence"}], "correct": "B", "explanation": "Pectus carinatum = anterior protrusion of sternum (like a bird keel), opposite of pectus excavatum."}, {"id": 1173, "subject": "Anatomy", "difficulty": "Easy", "question": "The external intercostal muscle fibers run in which direction?", "options": [{"key": "A", "text": "Downward and backward (posteroinferior)"}, {"key": "B", "text": "Downward and forward (anteroinferior)"}, {"key": "C", "text": "Horizontally"}, {"key": "D", "text": "Upward and forward"}], "correct": "B", "explanation": "External intercostal fibers run downward and forward (like hands in pockets); active in inspiration."}, {"id": 1174, "subject": "Anatomy", "difficulty": "Easy", "question": "The internal intercostal muscle fibers run in which direction?", "options": [{"key": "A", "text": "Same as external intercostals"}, {"key": "B", "text": "Downward and backward (at right angles to external)"}, {"key": "C", "text": "Horizontally"}, {"key": "D", "text": "Upward and backward"}], "correct": "B", "explanation": "Internal intercostal fibers run downward and backward (perpendicular to external), active in forced expiration."}, {"id": 1175, "subject": "Anatomy", "difficulty": "Medium", "question": "The innermost intercostal muscles are separated from internal intercostals by:", "options": [{"key": "A", "text": "Intercostal vein"}, {"key": "B", "text": "Intercostal nerve and vessels"}, {"key": "C", "text": "Endothoracic fascia"}, {"key": "D", "text": "Parietal pleura"}], "correct": "B", "explanation": "The intercostal nerve (and vessels) run between the internal and innermost intercostal muscles."}, {"id": 1176, "subject": "Anatomy", "difficulty": "Medium", "question": "The external intercostal muscle is replaced anteriorly (near sternum) by:", "options": [{"key": "A", "text": "Internal intercostal"}, {"key": "B", "text": "External intercostal membrane"}, {"key": "C", "text": "Innermost intercostal"}, {"key": "D", "text": "Transversus thoracis"}], "correct": "B", "explanation": "Anteriorly, the external intercostal is replaced by the external intercostal membrane (aponeurosis)."}, {"id": 1177, "subject": "Anatomy", "difficulty": "Medium", "question": "The internal intercostal muscle is replaced posteriorly (near vertebral column) by:", "options": [{"key": "A", "text": "Innermost intercostal"}, {"key": "B", "text": "Internal intercostal membrane"}, {"key": "C", "text": "Transversus thoracis"}, {"key": "D", "text": "Erector spinae"}], "correct": "B", "explanation": "Posteriorly, the internal intercostal is replaced by the internal intercostal membrane (aponeurosis)."}, {"id": 1178, "subject": "Anatomy", "difficulty": "Medium", "question": "Transversus thoracis (sternocostalis) lies on the:", "options": [{"key": "A", "text": "Outer thoracic wall"}, {"key": "B", "text": "Inner surface of anterior thoracic wall"}, {"key": "C", "text": "Posterior thoracic wall"}, {"key": "D", "text": "Lateral thoracic wall"}], "correct": "B", "explanation": "Transversus thoracis is on the inner surface of the anterior chest wall, deep to internal intercostals."}, {"id": 1179, "subject": "Anatomy", "difficulty": "Hard", "question": "The subcostal muscles are located:", "options": [{"key": "A", "text": "Anteriorly"}, {"key": "B", "text": "Laterally"}, {"key": "C", "text": "Posteriorly (near angles of ribs)"}, {"key": "D", "text": "Along the costal margin"}], "correct": "C", "explanation": "Subcostal muscles are found in the posterior thorax near rib angles; they span 2-3 intercostal spaces."}, {"id": 1180, "subject": "Anatomy", "difficulty": "Easy", "question": "Which intercostal muscles are the primary muscles of quiet inspiration?", "options": [{"key": "A", "text": "Internal intercostals"}, {"key": "B", "text": "External intercostals"}, {"key": "C", "text": "Innermost intercostals"}, {"key": "D", "text": "Subcostal muscles"}], "correct": "B", "explanation": "External intercostal muscles elevate the ribs during quiet inspiration, increasing thoracic volume."}, {"id": 1181, "subject": "Anatomy", "difficulty": "Hard", "question": "The interchondral part of the internal intercostal muscle is active in:", "options": [{"key": "A", "text": "Quiet expiration"}, {"key": "B", "text": "Quiet inspiration"}, {"key": "C", "text": "Forced expiration only"}, {"key": "D", "text": "No respiratory role"}], "correct": "B", "explanation": "The interchondral (parasternal) portion of internal intercostals paradoxically aids inspiration."}, {"id": 1182, "subject": "Anatomy", "difficulty": "Easy", "question": "The intercostal nerve is the anterior ramus of which spinal nerve?", "options": [{"key": "A", "text": "Posterior ramus of thoracic spinal nerve"}, {"key": "B", "text": "Anterior ramus of thoracic spinal nerve (T1-T11)"}, {"key": "C", "text": "Ventral root only"}, {"key": "D", "text": "Mixed spinal nerve"}], "correct": "B", "explanation": "Intercostal nerves are the anterior (ventral) rami of thoracic spinal nerves T1-T11."}, {"id": 1183, "subject": "Anatomy", "difficulty": "Medium", "question": "The subcostal nerve is the anterior ramus of:", "options": [{"key": "A", "text": "T11"}, {"key": "B", "text": "T12"}, {"key": "C", "text": "L1"}, {"key": "D", "text": "T10"}], "correct": "B", "explanation": "The subcostal nerve is the anterior ramus of T12, running below rib 12."}, {"id": 1184, "subject": "Anatomy", "difficulty": "Medium", "question": "The intercostal nerve gives a lateral cutaneous branch at:", "options": [{"key": "A", "text": "Anterior axillary line"}, {"key": "B", "text": "Midaxillary line"}, {"key": "C", "text": "Posterior axillary line"}, {"key": "D", "text": "Angle of the rib"}], "correct": "B", "explanation": "The lateral cutaneous branch pierces the intercostal muscles at the midaxillary line."}, {"id": 1185, "subject": "Anatomy", "difficulty": "Hard", "question": "The first intercostal nerve differs from others because it:", "options": [{"key": "A", "text": "Has no lateral cutaneous branch and most fibers join brachial plexus"}, {"key": "B", "text": "Supplies two intercostal spaces"}, {"key": "C", "text": "Has no anterior cutaneous branch"}, {"key": "D", "text": "Is purely motor"}], "correct": "A", "explanation": "The 1st intercostal nerve mostly joins the brachial plexus; it has no significant lateral cutaneous branch."}, {"id": 1186, "subject": "Anatomy", "difficulty": "Medium", "question": "The intercostal arteries arise primarily from:", "options": [{"key": "A", "text": "Internal thoracic and aorta (posterior intercostal)"}, {"key": "B", "text": "Subclavian artery only"}, {"key": "C", "text": "Axillary artery"}, {"key": "D", "text": "Pulmonary artery"}], "correct": "A", "explanation": "Anterior intercostal arteries from internal thoracic; posterior intercostal arteries from thoracic aorta (3-11)."}, {"id": 1187, "subject": "Anatomy", "difficulty": "Easy", "question": "The internal thoracic (mammary) artery is a branch of:", "options": [{"key": "A", "text": "Subclavian artery"}, {"key": "B", "text": "Axillary artery"}, {"key": "C", "text": "Aorta"}, {"key": "D", "text": "Brachiocephalic trunk"}], "correct": "A", "explanation": "Internal thoracic artery arises from the first part of the subclavian artery."}, {"id": 1188, "subject": "Anatomy", "difficulty": "Medium", "question": "Intercostal nerve block is performed:", "options": [{"key": "A", "text": "At the rib angle posteriorly"}, {"key": "B", "text": "At midaxillary line"}, {"key": "C", "text": "At costal margin anteriorly"}, {"key": "D", "text": "All of the above"}], "correct": "A", "explanation": "Intercostal nerve block is most effectively performed at the angle of the rib (posterior) where the nerve is most accessible."}, {"id": 1189, "subject": "Anatomy", "difficulty": "Easy", "question": "Intercostal drain (chest tube) is inserted in which intercostal space typically for pneumothorax?", "options": [{"key": "A", "text": "2nd ICS, midclavicular line"}, {"key": "B", "text": "5th ICS, anterior axillary line (safe triangle)"}, {"key": "C", "text": "7th ICS, posterior axillary line"}, {"key": "D", "text": "1st ICS"}], "correct": "B", "explanation": "For pneumothorax, chest drain is placed in the 'safe triangle' — 5th ICS, anterior axillary line."}, {"id": 1190, "subject": "Anatomy", "difficulty": "Medium", "question": "The 'safe triangle' for chest tube insertion is bounded by:", "options": [{"key": "A", "text": "Pectoralis major, latissimus dorsi, axillary apex"}, {"key": "B", "text": "Anterior border latissimus dorsi, lateral border pectoralis major, above nipple line"}, {"key": "C", "text": "Midaxillary line only"}, {"key": "D", "text": "Rib 5 only"}], "correct": "B", "explanation": "Safe triangle = anterior border of latissimus dorsi, lateral pectoralis major, above rib 5 (nipple level)."}, {"id": 1191, "subject": "Anatomy", "difficulty": "Easy", "question": "During thoracocentesis, the needle should be inserted:", "options": [{"key": "A", "text": "Above the upper border of the rib"}, {"key": "B", "text": "Just above the lower rib (superior to lower rib of space)"}, {"key": "C", "text": "In the middle of the intercostal space"}, {"key": "D", "text": "Below the upper rib"}], "correct": "B", "explanation": "Needle is inserted above the upper border of the LOWER rib to avoid VAN (vein, artery, nerve) in the costal groove."}, {"id": 1192, "subject": "Anatomy", "difficulty": "Easy", "question": "The diaphragm is the primary muscle of:", "options": [{"key": "A", "text": "Expiration"}, {"key": "B", "text": "Inspiration"}, {"key": "C", "text": "Stabilization only"}, {"key": "D", "text": "Both inspiration and expiration equally"}], "correct": "B", "explanation": "The diaphragm is the primary muscle of inspiration, responsible for ~75% of tidal breathing."}, {"id": 1193, "subject": "Anatomy", "difficulty": "Hard", "question": "The diaphragm descends from which embryological structure?", "options": [{"key": "A", "text": "Septum transversum, pleuroperitoneal folds, mesentery of esophagus, body wall"}, {"key": "B", "text": "Neural crest only"}, {"key": "C", "text": "Splanchnic mesoderm only"}, {"key": "D", "text": "Somitic myoblasts alone"}], "correct": "A", "explanation": "Diaphragm develops from: septum transversum (central tendon), pleuroperitoneal folds, esophageal mesentery, and body wall."}, {"id": 1194, "subject": "Anatomy", "difficulty": "Medium", "question": "The central tendon of the diaphragm is derived from:", "options": [{"key": "A", "text": "Septum transversum"}, {"key": "B", "text": "Pleuroperitoneal folds"}, {"key": "C", "text": "Somites"}, {"key": "D", "text": "Neural crest"}], "correct": "A", "explanation": "The central tendon (trefoil-shaped) is derived from the septum transversum."}, {"id": 1195, "subject": "Anatomy", "difficulty": "Medium", "question": "The crura of the diaphragm arise from:", "options": [{"key": "A", "text": "Lower ribs"}, {"key": "B", "text": "Lumbar vertebrae (L1-L3 on right, L1-L2 on left)"}, {"key": "C", "text": "Sacrum"}, {"key": "D", "text": "Iliac crest"}], "correct": "B", "explanation": "Right crus arises from L1-L3; left crus from L1-L2 lumbar vertebral bodies and intervertebral discs."}, {"id": 1196, "subject": "Anatomy", "difficulty": "Medium", "question": "The median arcuate ligament of the diaphragm is formed by:", "options": [{"key": "A", "text": "Fusion of the two crura over the aorta"}, {"key": "B", "text": "Medial lumbocostal arch"}, {"key": "C", "text": "Lateral lumbocostal arch"}, {"key": "D", "text": "Rib attachment"}], "correct": "A", "explanation": "Median arcuate ligament = fibrous arch formed by the two crura crossing over the aorta."}, {"id": 1197, "subject": "Anatomy", "difficulty": "Medium", "question": "The medial arcuate ligament of the diaphragm arches over:", "options": [{"key": "A", "text": "Aorta"}, {"key": "B", "text": "Psoas major muscle"}, {"key": "C", "text": "Quadratus lumborum"}, {"key": "D", "text": "Kidney"}], "correct": "B", "explanation": "Medial arcuate ligament arches over the psoas major muscle (from vertebral body to transverse process)."}, {"id": 1198, "subject": "Anatomy", "difficulty": "Medium", "question": "The lateral arcuate ligament of the diaphragm arches over:", "options": [{"key": "A", "text": "Psoas major"}, {"key": "B", "text": "Quadratus lumborum muscle"}, {"key": "C", "text": "Kidney"}, {"key": "D", "text": "Aorta"}], "correct": "B", "explanation": "Lateral arcuate ligament arches over the quadratus lumborum (from transverse process to rib 12)."}, {"id": 1199, "subject": "Anatomy", "difficulty": "Easy", "question": "The aortic opening (hiatus) in the diaphragm is at level:", "options": [{"key": "A", "text": "T8"}, {"key": "B", "text": "T10"}, {"key": "C", "text": "T12"}, {"key": "D", "text": "L1"}], "correct": "C", "explanation": "The aortic hiatus is at T12, transmitting the aorta, thoracic duct, and azygos vein."}, {"id": 1200, "subject": "Anatomy", "difficulty": "Easy", "question": "The oesophageal opening in the diaphragm is at level:", "options": [{"key": "A", "text": "T8"}, {"key": "B", "text": "T10"}, {"key": "C", "text": "T12"}, {"key": "D", "text": "L1"}], "correct": "B", "explanation": "The oesophageal hiatus is at T10, transmitting the oesophagus and vagal trunks."}, {"id": 1201, "subject": "Anatomy", "difficulty": "Easy", "question": "The caval opening (for inferior vena cava) in the diaphragm is at level:", "options": [{"key": "A", "text": "T8"}, {"key": "B", "text": "T10"}, {"key": "C", "text": "T12"}, {"key": "D", "text": "T6"}], "correct": "A", "explanation": "The caval opening is at T8 in the central tendon, transmitting the IVC and right phrenic nerve."}, {"id": 1202, "subject": "Anatomy", "difficulty": "Medium", "question": "Which structure passes through the aortic hiatus of diaphragm?", "options": [{"key": "A", "text": "Oesophagus, vagus"}, {"key": "B", "text": "Aorta, thoracic duct, azygos vein"}, {"key": "C", "text": "IVC, right phrenic nerve"}, {"key": "D", "text": "Sympathetic chain"}], "correct": "B", "explanation": "Aortic hiatus (T12) transmits: descending aorta, thoracic duct, and azygos vein."}, {"id": 1203, "subject": "Anatomy", "difficulty": "Medium", "question": "Which structure passes through the oesophageal hiatus?", "options": [{"key": "A", "text": "Aorta and thoracic duct"}, {"key": "B", "text": "Oesophagus and vagal trunks (anterior and posterior)"}, {"key": "C", "text": "IVC and phrenic nerve"}, {"key": "D", "text": "Sympathetic chain only"}], "correct": "B", "explanation": "Oesophageal hiatus (T10) transmits: oesophagus and vagal trunks (anterior=left vagus, posterior=right vagus)."}, {"id": 1204, "subject": "Anatomy", "difficulty": "Hard", "question": "The right phrenic nerve pierces the diaphragm through:", "options": [{"key": "A", "text": "Aortic hiatus"}, {"key": "B", "text": "Oesophageal hiatus"}, {"key": "C", "text": "Caval opening (central tendon)"}, {"key": "D", "text": "Separate muscular opening"}], "correct": "C", "explanation": "Right phrenic nerve passes through the caval opening (T8) along with the IVC."}, {"id": 1205, "subject": "Anatomy", "difficulty": "Hard", "question": "The left phrenic nerve pierces the diaphragm:", "options": [{"key": "A", "text": "Through caval opening"}, {"key": "B", "text": "Through oesophageal hiatus"}, {"key": "C", "text": "Through the muscle itself (separate opening left of centre)"}, {"key": "D", "text": "Through aortic hiatus"}], "correct": "C", "explanation": "Left phrenic nerve pierces the muscular part of the diaphragm separately, left of centre."}, {"id": 1206, "subject": "Anatomy", "difficulty": "Hard", "question": "The sympathetic chain passes behind the diaphragm under:", "options": [{"key": "A", "text": "Median arcuate ligament"}, {"key": "B", "text": "Lateral arcuate ligament"}, {"key": "C", "text": "Medial arcuate ligament"}, {"key": "D", "text": "Directly through the crus"}], "correct": "C", "explanation": "Sympathetic trunks pass deep to the medial arcuate ligament on each side."}, {"id": 1207, "subject": "Anatomy", "difficulty": "Hard", "question": "The splanchnic nerves pierce the diaphragm:", "options": [{"key": "A", "text": "Through aortic hiatus"}, {"key": "B", "text": "Through the crura"}, {"key": "C", "text": "Lateral arcuate ligament"}, {"key": "D", "text": "Medial arcuate ligament"}], "correct": "B", "explanation": "Splanchnic nerves (greater, lesser, least) pierce the crura of the diaphragm to reach the abdomen."}, {"id": 1208, "subject": "Anatomy", "difficulty": "Easy", "question": "The motor nerve supply to the diaphragm is:", "options": [{"key": "A", "text": "Vagus nerve"}, {"key": "B", "text": "Phrenic nerve (C3, C4, C5)"}, {"key": "C", "text": "Intercostal nerves only"}, {"key": "D", "text": "Thoracic sympathetic"}], "correct": "B", "explanation": "Phrenic nerve (C3, C4, C5) provides ENTIRE motor supply to diaphragm. Mnemonic: C3,4,5 keeps you alive."}, {"id": 1209, "subject": "Anatomy", "difficulty": "Medium", "question": "The sensory supply to the central part of the diaphragm is by:", "options": [{"key": "A", "text": "Intercostal nerves"}, {"key": "B", "text": "Phrenic nerve (C3-C5)"}, {"key": "C", "text": "Vagus nerve"}, {"key": "D", "text": "Subcostal nerve"}], "correct": "B", "explanation": "The phrenic nerve (C3-C5) provides sensory supply to the central diaphragm and pericardium."}, {"id": 1210, "subject": "Anatomy", "difficulty": "Medium", "question": "The peripheral diaphragm receives sensory supply from:", "options": [{"key": "A", "text": "Phrenic nerve"}, {"key": "B", "text": "Lower 6 intercostal nerves (T7-T12)"}, {"key": "C", "text": "Vagus nerve"}, {"key": "D", "text": "Subcostal nerve only"}], "correct": "B", "explanation": "Peripheral diaphragm (musculotendinous rim) is supplied sensory by lower 6 intercostal nerves."}, {"id": 1211, "subject": "Anatomy", "difficulty": "Easy", "question": "Referred pain from diaphragmatic irritation (e.g., subphrenic abscess) is felt at:", "options": [{"key": "A", "text": "Epigastrium"}, {"key": "B", "text": "Shoulder tip (C3-C4 dermatome)"}, {"key": "C", "text": "Lumbar region"}, {"key": "D", "text": "Groin"}], "correct": "B", "explanation": "Diaphragmatic irritation refers pain to the shoulder tip via the phrenic nerve (C3-C4)."}, {"id": 1212, "subject": "Anatomy", "difficulty": "Easy", "question": "The diaphragm descends during inspiration because:", "options": [{"key": "A", "text": "Rib cage contracts"}, {"key": "B", "text": "Central tendon is pulled inferiorly by muscular contraction"}, {"key": "C", "text": "Abdominal muscles contract"}, {"key": "D", "text": "Intercostals pull it down"}], "correct": "B", "explanation": "Diaphragm contraction causes the dome to descend (central tendon moves caudally), increasing vertical thoracic diameter."}, {"id": 1213, "subject": "Anatomy", "difficulty": "Medium", "question": "During quiet breathing, the diaphragm descends approximately:", "options": [{"key": "A", "text": "1 cm"}, {"key": "B", "text": "1.5 cm"}, {"key": "C", "text": "3-5 cm"}, {"key": "D", "text": "8-10 cm"}], "correct": "B", "explanation": "Diaphragm excursion during quiet breathing is about 1.5 cm; deep breathing up to 7-10 cm."}, {"id": 1214, "subject": "Anatomy", "difficulty": "Easy", "question": "The right dome of diaphragm is higher than left because:", "options": [{"key": "A", "text": "Heart pushes it up"}, {"key": "B", "text": "Liver pushes it up from below"}, {"key": "C", "text": "Stomach pushes left dome down"}, {"key": "D", "text": "Spleen on right"}], "correct": "B", "explanation": "The liver (right lobe) supports and elevates the right dome; stomach gas depresses the left dome."}, {"id": 1215, "subject": "Anatomy", "difficulty": "Medium", "question": "The right dome of the diaphragm is normally at the level of:", "options": [{"key": "A", "text": "4th rib"}, {"key": "B", "text": "5th rib (mid-clavicular line)"}, {"key": "C", "text": "6th rib"}, {"key": "D", "text": "7th rib"}], "correct": "B", "explanation": "Right dome of the diaphragm is at the 5th rib in the mid-clavicular line (at end-expiration)."}, {"id": 1216, "subject": "Anatomy", "difficulty": "Medium", "question": "A congenital diaphragmatic hernia (Bochdalek hernia) occurs through:", "options": [{"key": "A", "text": "Oesophageal hiatus"}, {"key": "B", "text": "Pleuroperitoneal canal (posterolateral defect)"}, {"key": "C", "text": "Foramen of Morgagni"}, {"key": "D", "text": "Central tendon"}], "correct": "B", "explanation": "Bochdalek hernia is a posterolateral defect (left > right) due to failure of closure of pleuroperitoneal canal."}, {"id": 1217, "subject": "Anatomy", "difficulty": "Medium", "question": "Foramen of Morgagni hernia is located:", "options": [{"key": "A", "text": "Posterolateral"}, {"key": "B", "text": "Anteriorly (parasternal, between sternal and costal origins)"}, {"key": "C", "text": "Centrally"}, {"key": "D", "text": "Posteriorly"}], "correct": "B", "explanation": "Morgagni hernia is an anterior parasternal defect, between the sternal and costal diaphragm origins."}, {"id": 1218, "subject": "Anatomy", "difficulty": "Easy", "question": "Sliding hiatus hernia is most common type and involves:", "options": [{"key": "A", "text": "Stomach fundus herniating alongside oesophagus"}, {"key": "B", "text": "Gastro-oesophageal junction sliding into thorax"}, {"key": "C", "text": "Entire stomach in thorax"}, {"key": "D", "text": "Only oesophagus herniation"}], "correct": "B", "explanation": "Sliding (Type I) hiatus hernia = GE junction and cardia of stomach slide into thorax through oesophageal hiatus."}, {"id": 1219, "subject": "Anatomy", "difficulty": "Medium", "question": "Para-oesophageal (rolling) hiatus hernia involves:", "options": [{"key": "A", "text": "GE junction herniation"}, {"key": "B", "text": "Stomach fundus herniating alongside oesophagus (GE junction stays in abdomen)"}, {"key": "C", "text": "Entire bowel herniation"}, {"key": "D", "text": "Diaphragm paralysis"}], "correct": "B", "explanation": "Para-oesophageal hernia: fundus of stomach rolls through hiatus while GE junction remains below diaphragm."}, {"id": 1220, "subject": "Anatomy", "difficulty": "Medium", "question": "The costodiaphragmatic recess is:", "options": [{"key": "A", "text": "The space between lung and pericardium"}, {"key": "B", "text": "The lowest pleural recess between costal and diaphragmatic pleura"}, {"key": "C", "text": "Behind the sternum"}, {"key": "D", "text": "Between two lobes of lung"}], "correct": "B", "explanation": "Costodiaphragmatic recess is the most dependent pleural recess; fluid collects here first."}, {"id": 1221, "subject": "Anatomy", "difficulty": "Medium", "question": "During maximal inspiration, the diaphragm can descend up to:", "options": [{"key": "A", "text": "3 cm"}, {"key": "B", "text": "5 cm"}, {"key": "C", "text": "7-10 cm"}, {"key": "D", "text": "15 cm"}], "correct": "C", "explanation": "In deep/maximal inspiration, diaphragm can descend 7-10 cm below its resting position."}, {"id": 1222, "subject": "Anatomy", "difficulty": "Medium", "question": "Boyle's law as applied to breathing states:", "options": [{"key": "A", "text": "Pressure is proportional to volume"}, {"key": "B", "text": "At constant temperature, pressure and volume are inversely proportional"}, {"key": "C", "text": "Temperature determines lung volume"}, {"key": "D", "text": "Pressure equals volume"}], "correct": "B", "explanation": "Boyle's law: P∝1/V (constant temp); as thoracic volume increases during inspiration, pressure drops below atmospheric."}, {"id": 1223, "subject": "Anatomy", "difficulty": "Easy", "question": "Tidal volume in a normal adult at rest is approximately:", "options": [{"key": "A", "text": "200 mL"}, {"key": "B", "text": "500 mL"}, {"key": "C", "text": "1200 mL"}, {"key": "D", "text": "2500 mL"}], "correct": "B", "explanation": "Normal tidal volume (TV) is approximately 500 mL (0.5 L) during quiet breathing."}, {"id": 1224, "subject": "Anatomy", "difficulty": "Medium", "question": "Functional residual capacity (FRC) is:", "options": [{"key": "A", "text": "TV + IRV"}, {"key": "B", "text": "ERV + RV"}, {"key": "C", "text": "TLC - TV"}, {"key": "D", "text": "VC + RV"}], "correct": "B", "explanation": "FRC = Expiratory Reserve Volume + Residual Volume; the volume remaining after normal quiet expiration."}, {"id": 1225, "subject": "Anatomy", "difficulty": "Easy", "question": "Quiet expiration is:", "options": [{"key": "A", "text": "Active process requiring muscular contraction"}, {"key": "B", "text": "Passive process (elastic recoil of lungs and chest wall)"}, {"key": "C", "text": "Driven by intercostal muscles"}, {"key": "D", "text": "Driven by abdominal muscles"}], "correct": "B", "explanation": "Quiet expiration is passive, driven by elastic recoil of lungs and chest wall (no muscular effort needed)."}, {"id": 1226, "subject": "Anatomy", "difficulty": "Easy", "question": "Accessory muscles of inspiration include:", "options": [{"key": "A", "text": "Abdominal muscles and internal intercostals"}, {"key": "B", "text": "Sternocleidomastoid, scalenes, pectoralis minor"}, {"key": "C", "text": "Latissimus dorsi and gluteus maximus"}, {"key": "D", "text": "Erector spinae only"}], "correct": "B", "explanation": "Accessory inspiratory muscles: SCM, scalenes, pectoralis minor, serratus anterior activate during forced/labored breathing."}, {"id": 1227, "subject": "Anatomy", "difficulty": "Easy", "question": "Primary muscles of forced expiration are:", "options": [{"key": "A", "text": "External intercostals and diaphragm"}, {"key": "B", "text": "Abdominal muscles (rectus, obliques, transversus) and internal intercostals"}, {"key": "C", "text": "Scalenes and SCM"}, {"key": "D", "text": "Pectoralis major"}], "correct": "B", "explanation": "Forced expiration uses abdominal muscles (to push diaphragm up) and internal intercostal muscles."}, {"id": 1228, "subject": "Anatomy", "difficulty": "Medium", "question": "Paradoxical breathing (see-saw respiration) is characterized by:", "options": [{"key": "A", "text": "Chest and abdomen both rise together"}, {"key": "B", "text": "Chest falls and abdomen rises during inspiration (diaphragm paralysis)"}, {"key": "C", "text": "Abdomen only moves"}, {"key": "D", "text": "Increased tidal volume"}], "correct": "B", "explanation": "Paradoxical breathing: diaphragm paralysis causes abdomen to fall and chest to rise during inspiration abnormally."}, {"id": 1229, "subject": "Anatomy", "difficulty": "Medium", "question": "The diaphragm performs which action on the abdominal compartment during inspiration?", "options": [{"key": "A", "text": "Decreases intra-abdominal pressure"}, {"key": "B", "text": "Increases intra-abdominal pressure (viscera compressed)"}, {"key": "C", "text": "No effect"}, {"key": "D", "text": "Lateral expansion of abdomen"}], "correct": "B", "explanation": "Diaphragm descent during inspiration compresses abdominal contents, increasing intra-abdominal pressure."}, {"id": 1230, "subject": "Anatomy", "difficulty": "Easy", "question": "A tension pneumothorax causes the mediastinum to shift:", "options": [{"key": "A", "text": "Toward the affected side"}, {"key": "B", "text": "Away from the affected side"}, {"key": "C", "text": "No mediastinal shift"}, {"key": "D", "text": "Inferiorly"}], "correct": "B", "explanation": "Tension pneumothorax causes mediastinal shift AWAY from the affected side due to increasing pressure."}, {"id": 1231, "subject": "Anatomy", "difficulty": "Medium", "question": "Flail chest occurs when:", "options": [{"key": "A", "text": "Single rib fracture"}, {"key": "B", "text": "Two or more ribs fractured in two or more places (segment loses bony continuity)"}, {"key": "C", "text": "Sternum fractures only"}, {"key": "D", "text": "Diaphragm rupture"}], "correct": "B", "explanation": "Flail chest = ≥3 consecutive ribs fractured in ≥2 places, creating a free-floating segment with paradoxical movement."}, {"id": 1232, "subject": "Anatomy", "difficulty": "Medium", "question": "The most common site for rib fractures is:", "options": [{"key": "A", "text": "Posterior (near costovertebral joint)"}, {"key": "B", "text": "Lateral (near angle of rib)"}, {"key": "C", "text": "Anterior (near sternum)"}, {"key": "D", "text": "At the neck of rib"}], "correct": "B", "explanation": "Ribs fracture most commonly at the angle (lateral), the weakest and most prominent part."}, {"id": 1233, "subject": "Anatomy", "difficulty": "Medium", "question": "A pleural effusion of more than how much fluid is detectable on a plain chest X-ray?", "options": [{"key": "A", "text": "50 mL"}, {"key": "B", "text": "100 mL"}, {"key": "C", "text": "200-300 mL"}, {"key": "D", "text": "500 mL"}], "correct": "C", "explanation": "Approximately 200-300 mL of pleural fluid is needed before it becomes visible on an erect PA chest X-ray."}, {"id": 1234, "subject": "Anatomy", "difficulty": "Easy", "question": "The angle of Louis is used clinically to:", "options": [{"key": "A", "text": "Locate rib 2, carina, aortic arch, T4-T5 level"}, {"key": "B", "text": "Locate rib 1 only"}, {"key": "C", "text": "Measure lordosis"}, {"key": "D", "text": "None of the above"}], "correct": "A", "explanation": "Sternal angle of Louis is an important clinical landmark for locating rib 2, carina, aortic arch, and T4-T5 disc."}, {"id": 1235, "subject": "Anatomy", "difficulty": "Medium", "question": "Diaphragmatic palsy (hemidiaphragm paralysis) is detected on X-ray as:", "options": [{"key": "A", "text": "Lowered ipsilateral hemidiaphragm"}, {"key": "B", "text": "Elevated ipsilateral hemidiaphragm"}, {"key": "C", "text": "Mediastinal shift away from lesion"}, {"key": "D", "text": "Rib notching"}], "correct": "B", "explanation": "Paralyzed hemidiaphragm appears elevated on chest X-ray and moves paradoxically on fluoroscopy (sniff test)."}, {"id": 1236, "subject": "Anatomy", "difficulty": "Medium", "question": "Rib notching on chest X-ray (inferior rib margins) is a sign of:", "options": [{"key": "A", "text": "Osteoporosis"}, {"key": "B", "text": "Coarctation of aorta"}, {"key": "C", "text": "Ankylosing spondylitis"}, {"key": "D", "text": "Rickets"}], "correct": "B", "explanation": "Rib notching (inferior rib cortical erosions) is caused by dilated intercostal collateral vessels in coarctation of aorta."}, {"id": 1237, "subject": "Anatomy", "difficulty": "Medium", "question": "Cervical rib can cause thoracic outlet syndrome compressing:", "options": [{"key": "A", "text": "Femoral nerve and artery"}, {"key": "B", "text": "Brachial plexus (lower trunk) and subclavian artery"}, {"key": "C", "text": "Phrenic nerve"}, {"key": "D", "text": "Radial nerve only"}], "correct": "B", "explanation": "Cervical rib compresses the lower trunk of brachial plexus (C8-T1) and/or subclavian artery."}, {"id": 1238, "subject": "Anatomy", "difficulty": "Hard", "question": "The 'bucket handle' tear in meniscus is named after:", "options": [{"key": "A", "text": "Rib movement pattern in breathing"}, {"key": "B", "text": "Shape of tear resembling rib bucket-handle motion"}, {"key": "C", "text": "Both"}, {"key": "D", "text": "Neither"}], "correct": "A", "explanation": "The bucket handle meniscal tear is named after the rib bucket-handle movement in respiration."}, {"id": 1239, "subject": "Anatomy", "difficulty": "Medium", "question": "Tietze syndrome is:", "options": [{"key": "A", "text": "Costochondral cartilage inflammation without swelling"}, {"key": "B", "text": "Painful swelling of costochondral junctions (usually 2nd-3rd rib)"}, {"key": "C", "text": "Rib stress fracture"}, {"key": "D", "text": "Rib osteomyelitis"}], "correct": "B", "explanation": "Tietze syndrome = painful non-suppurative swelling of one or more costochondral junctions (usually 2nd-3rd)."}, {"id": 1240, "subject": "Anatomy", "difficulty": "Medium", "question": "Costochondritis differs from Tietze syndrome because:", "options": [{"key": "A", "text": "It is more painful"}, {"key": "B", "text": "It lacks swelling/tenderness at a specific cartilage"}, {"key": "C", "text": "It involves multiple rib joints with tenderness but no swelling"}, {"key": "D", "text": "It is infectious"}], "correct": "C", "explanation": "Costochondritis = multiple costochondral junction pain/tenderness WITHOUT visible/palpable swelling (unlike Tietze)."}, {"id": 1241, "subject": "Anatomy", "difficulty": "Hard", "question": "Ribs ossify from:", "options": [{"key": "A", "text": "One primary and two secondary centers"}, {"key": "B", "text": "One primary centre in the angle"}, {"key": "C", "text": "Three primary centers"}, {"key": "D", "text": "Membranous ossification"}], "correct": "A", "explanation": "Ribs ossify from one primary center (body) and secondary centers at head and tubercle."}, {"id": 1242, "subject": "Anatomy", "difficulty": "Hard", "question": "Failure of fusion of sternal bars results in:", "options": [{"key": "A", "text": "Pectus excavatum"}, {"key": "B", "text": "Sternal cleft (bifid sternum)"}, {"key": "C", "text": "Pectus carinatum"}, {"key": "D", "text": "Sternal foramen only"}], "correct": "B", "explanation": "Failure of fusion of lateral sternal bars results in sternal cleft (bifid sternum)."}, {"id": 1243, "subject": "Anatomy", "difficulty": "Hard", "question": "Sternal foramen is:", "options": [{"key": "A", "text": "Always pathological"}, {"key": "B", "text": "A common normal variant (foramina in body of sternum)"}, {"key": "C", "text": "Related to malignancy"}, {"key": "D", "text": "Due to trauma always"}], "correct": "B", "explanation": "Sternal foramen is a common normal variant (benign) occurring in ~6% of people; important to recognize on imaging."}, {"id": 1244, "subject": "Anatomy", "difficulty": "Medium", "question": "Serratus anterior originates from:", "options": [{"key": "A", "text": "Scapula"}, {"key": "B", "text": "Outer surfaces of upper 8-9 ribs"}, {"key": "C", "text": "Sternum"}, {"key": "D", "text": "Clavicle"}], "correct": "B", "explanation": "Serratus anterior arises from the outer surfaces of the lateral aspects of the upper 8-9 ribs."}, {"id": 1245, "subject": "Anatomy", "difficulty": "Medium", "question": "Pectoralis minor originates from:", "options": [{"key": "A", "text": "Coracoid process"}, {"key": "B", "text": "3rd-5th ribs (outer surface)"}, {"key": "C", "text": "Clavicle"}, {"key": "D", "text": "Manubrium"}], "correct": "B", "explanation": "Pectoralis minor arises from the 3rd, 4th, and 5th ribs and inserts into the coracoid process."}, {"id": 1246, "subject": "Anatomy", "difficulty": "Medium", "question": "The subclavius muscle is attached to:", "options": [{"key": "A", "text": "Rib 1 (junction of rib and costal cartilage)"}, {"key": "B", "text": "Rib 2"}, {"key": "C", "text": "Clavicle and sternum"}, {"key": "D", "text": "Rib 3"}], "correct": "A", "explanation": "Subclavius arises from the junction of rib 1 and its costal cartilage and inserts into the clavicle."}, {"id": 1247, "subject": "Anatomy", "difficulty": "Hard", "question": "The levatores costarum muscles elevate the ribs and are innervated by:", "options": [{"key": "A", "text": "Intercostal nerves"}, {"key": "B", "text": "Posterior rami of thoracic spinal nerves"}, {"key": "C", "text": "Phrenic nerve"}, {"key": "D", "text": "Vagus nerve"}], "correct": "B", "explanation": "Levatores costarum (short and long) are innervated by the posterior (dorsal) rami of thoracic spinal nerves."}, {"id": 1248, "subject": "Anatomy", "difficulty": "Hard", "question": "The sternocostal joints (between costal cartilages and sternum) are classified as:", "options": [{"key": "A", "text": "Fibrous"}, {"key": "B", "text": "Cartilaginous (synchondrosis) for rib 1; synovial for 2-7"}, {"key": "C", "text": "Synovial only"}, {"key": "D", "text": "All fibrous"}], "correct": "B", "explanation": "1st sternocostal joint is a primary cartilaginous joint (synchondrosis); 2nd-7th are synovial plane joints."}, {"id": 1249, "subject": "Anatomy", "difficulty": "Medium", "question": "The internal thoracic artery terminates by dividing into:", "options": [{"key": "A", "text": "Anterior intercostal arteries"}, {"key": "B", "text": "Musculophrenic and superior epigastric arteries"}, {"key": "C", "text": "Lateral thoracic artery"}, {"key": "D", "text": "Phrenic arteries"}], "correct": "B", "explanation": "Internal thoracic artery divides at 6th intercostal space into musculophrenic and superior epigastric arteries."}, {"id": 1250, "subject": "Anatomy", "difficulty": "Medium", "question": "The azygos vein drains into:", "options": [{"key": "A", "text": "SVC at T4 level"}, {"key": "B", "text": "IVC"}, {"key": "C", "text": "Portal vein"}, {"key": "D", "text": "Brachiocephalic vein"}], "correct": "A", "explanation": "Azygos vein arches over the root of right lung and drains into the SVC at the level of T4."}, {"id": 1251, "subject": "Anatomy", "difficulty": "Easy", "question": "Winged scapula results from injury to which nerve that runs on the thoracic wall?", "options": [{"key": "A", "text": "Axillary nerve"}, {"key": "B", "text": "Long thoracic nerve (of Bell) — C5, C6, C7"}, {"key": "C", "text": "Thoracodorsal nerve"}, {"key": "D", "text": "Suprascapular nerve"}], "correct": "B", "explanation": "Long thoracic nerve (C5, C6, C7) runs on the lateral thoracic wall supplying serratus anterior; injury causes winged scapula."}, {"id": 1252, "subject": "Anatomy", "difficulty": "Easy", "question": "During expiration, the diaphragm:", "options": [{"key": "A", "text": "Contracts further"}, {"key": "B", "text": "Relaxes and ascends"}, {"key": "C", "text": "Remains stationary"}, {"key": "D", "text": "Descends more"}], "correct": "B", "explanation": "During expiration, the diaphragm relaxes and passively ascends due to elastic recoil of the lungs."}, {"id": 1253, "subject": "Anatomy", "difficulty": "Easy", "question": "The phrenic nerve arises from which cervical nerve roots?", "options": [{"key": "A", "text": "C2, C3, C4"}, {"key": "B", "text": "C3, C4, C5"}, {"key": "C", "text": "C4, C5, C6"}, {"key": "D", "text": "C5, C6, C7"}], "correct": "B", "explanation": "Phrenic nerve = C3, C4, C5 (mainly C4). Mnemonic: C3,4,5 keeps the diaphragm alive."}, {"id": 1254, "subject": "Anatomy", "difficulty": "Medium", "question": "The thoracic duct enters the thorax through:", "options": [{"key": "A", "text": "Caval opening"}, {"key": "B", "text": "Oesophageal hiatus"}, {"key": "C", "text": "Aortic hiatus"}, {"key": "D", "text": "Separate opening between crura"}], "correct": "C", "explanation": "The thoracic duct enters the thorax through the aortic hiatus (T12) alongside the aorta."}, {"id": 1255, "subject": "Anatomy", "difficulty": "Easy", "question": "The costo-diaphragmatic angle on chest X-ray is obliterated by:", "options": [{"key": "A", "text": "Pneumothorax"}, {"key": "B", "text": "Pleural effusion"}, {"key": "C", "text": "Consolidation only"}, {"key": "D", "text": "Normal in most"}], "correct": "B", "explanation": "Pleural effusion fills the costo-diaphragmatic recess, obliterating the costophrenic angle on X-ray."}, {"id": 1256, "subject": "Anatomy", "difficulty": "Easy", "question": "Which bone forms the forehead?", "options": [{"key": "A", "text": "Parietal bone"}, {"key": "B", "text": "Frontal bone"}, {"key": "C", "text": "Occipital bone"}, {"key": "D", "text": "Temporal bone"}], "correct": "B", "explanation": "Frontal bone forms the forehead and roof of orbits."}, {"id": 1257, "subject": "Anatomy", "difficulty": "Medium", "question": "How many bones form the neurocranium?", "options": [{"key": "A", "text": "6"}, {"key": "B", "text": "8"}, {"key": "C", "text": "14"}, {"key": "D", "text": "22"}], "correct": "B", "explanation": "The neurocranium (cranial vault) is formed by 8 bones."}, {"id": 1258, "subject": "Anatomy", "difficulty": "Easy", "question": "Which suture lies between the two parietal bones?", "options": [{"key": "A", "text": "Coronal suture"}, {"key": "B", "text": "Lambdoid suture"}, {"key": "C", "text": "Sagittal suture"}, {"key": "D", "text": "Squamous suture"}], "correct": "C", "explanation": "Sagittal suture joins the two parietal bones in midline."}, {"id": 1259, "subject": "Anatomy", "difficulty": "Easy", "question": "The coronal suture lies between which bones?", "options": [{"key": "A", "text": "Frontal and parietal"}, {"key": "B", "text": "Parietal and occipital"}, {"key": "C", "text": "Temporal and parietal"}, {"key": "D", "text": "Frontal and temporal"}], "correct": "A", "explanation": "Coronal suture separates frontal bone from the two parietal bones."}, {"id": 1260, "subject": "Anatomy", "difficulty": "Easy", "question": "Lambdoid suture is found between which bones?", "options": [{"key": "A", "text": "Frontal and parietal"}, {"key": "B", "text": "Parietal and occipital"}, {"key": "C", "text": "Temporal and occipital"}, {"key": "D", "text": "Parietal and temporal"}], "correct": "B", "explanation": "Lambdoid suture lies between parietal bones and occipital bone."}, {"id": 1261, "subject": "Anatomy", "difficulty": "Medium", "question": "Pterion is a clinically important junction of how many bones?", "options": [{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}], "correct": "C", "explanation": "Pterion is the meeting point of frontal, parietal, temporal and sphenoid bones (4 bones)."}, {"id": 1262, "subject": "Anatomy", "difficulty": "Medium", "question": "Which artery runs deep to the pterion, making it clinically significant?", "options": [{"key": "A", "text": "Middle meningeal artery"}, {"key": "B", "text": "Superficial temporal artery"}, {"key": "C", "text": "Maxillary artery"}, {"key": "D", "text": "Occipital artery"}], "correct": "A", "explanation": "Middle meningeal artery runs beneath the pterion and is vulnerable to injury here."}, {"id": 1263, "subject": "Anatomy", "difficulty": "Easy", "question": "The foramen magnum is located in which bone?", "options": [{"key": "A", "text": "Sphenoid"}, {"key": "B", "text": "Temporal"}, {"key": "C", "text": "Occipital"}, {"key": "D", "text": "Ethmoid"}], "correct": "C", "explanation": "Foramen magnum is a large opening in the occipital bone transmitting the spinal cord."}, {"id": 1264, "subject": "Anatomy", "difficulty": "Easy", "question": "Which structure passes through the foramen magnum?", "options": [{"key": "A", "text": "Vagus nerve"}, {"key": "B", "text": "Spinal cord"}, {"key": "C", "text": "Glossopharyngeal nerve"}, {"key": "D", "text": "Facial nerve"}], "correct": "B", "explanation": "The spinal cord, vertebral arteries and spinal roots of accessory nerve pass through foramen magnum."}, {"id": 1265, "subject": "Anatomy", "difficulty": "Easy", "question": "The mastoid process is part of which bone?", "options": [{"key": "A", "text": "Frontal bone"}, {"key": "B", "text": "Temporal bone"}, {"key": "C", "text": "Occipital bone"}, {"key": "D", "text": "Sphenoid bone"}], "correct": "B", "explanation": "Mastoid process is a projection of the temporal bone, site of SCM insertion."}, {"id": 1266, "subject": "Anatomy", "difficulty": "Easy", "question": "Which bone houses the organs of hearing and balance?", "options": [{"key": "A", "text": "Sphenoid"}, {"key": "B", "text": "Ethmoid"}, {"key": "C", "text": "Temporal"}, {"key": "D", "text": "Occipital"}], "correct": "C", "explanation": "Temporal bone contains the middle and inner ear structures."}, {"id": 1267, "subject": "Anatomy", "difficulty": "Easy", "question": "The external occipital protuberance is a landmark on which bone?", "options": [{"key": "A", "text": "Parietal"}, {"key": "B", "text": "Occipital"}, {"key": "C", "text": "Temporal"}, {"key": "D", "text": "Frontal"}], "correct": "B", "explanation": "It is a midline bony prominence on the squamous part of occipital bone."}, {"id": 1268, "subject": "Anatomy", "difficulty": "Medium", "question": "Superior nuchal line is the attachment site for which muscle?", "options": [{"key": "A", "text": "Trapezius"}, {"key": "B", "text": "Splenius capitis"}, {"key": "C", "text": "Levator scapulae"}, {"key": "D", "text": "Longus capitis"}], "correct": "A", "explanation": "Trapezius attaches along the superior nuchal line of the occipital bone."}, {"id": 1269, "subject": "Anatomy", "difficulty": "Medium", "question": "Which cranial fossa contains the cerebellum?", "options": [{"key": "A", "text": "Anterior cranial fossa"}, {"key": "B", "text": "Middle cranial fossa"}, {"key": "C", "text": "Posterior cranial fossa"}, {"key": "D", "text": "None of the above"}], "correct": "C", "explanation": "Posterior cranial fossa houses the cerebellum, pons and medulla."}, {"id": 1270, "subject": "Anatomy", "difficulty": "Hard", "question": "The styloid process serves as attachment for how many muscles?", "options": [{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}], "correct": "C", "explanation": "Three muscles attach: stylohyoid, styloglossus and stylopharyngeus."}, {"id": 1271, "subject": "Anatomy", "difficulty": "Easy", "question": "Which bone forms the chin (mandible) joint with the skull called?", "options": [{"key": "A", "text": "Sternoclavicular joint"}, {"key": "B", "text": "Temporomandibular joint"}, {"key": "C", "text": "Atlanto-occipital joint"}, {"key": "D", "text": "Zygomatic joint"}], "correct": "B", "explanation": "TMJ is formed between the mandibular condyle and temporal bone."}, {"id": 1272, "subject": "Anatomy", "difficulty": "Medium", "question": "The zygomatic arch is formed by processes of which two bones?", "options": [{"key": "A", "text": "Frontal and maxilla"}, {"key": "B", "text": "Temporal and zygomatic"}, {"key": "C", "text": "Parietal and sphenoid"}, {"key": "D", "text": "Maxilla and palatine"}], "correct": "B", "explanation": "Zygomatic arch is formed by the temporal process of zygomatic bone and zygomatic process of temporal bone."}, {"id": 1273, "subject": "Anatomy", "difficulty": "Easy", "question": "Which is the only movable bone of the skull?", "options": [{"key": "A", "text": "Maxilla"}, {"key": "B", "text": "Mandible"}, {"key": "C", "text": "Vomer"}, {"key": "D", "text": "Zygomatic bone"}], "correct": "B", "explanation": "Mandible articulates at the TMJ and is the only freely movable skull bone."}, {"id": 1274, "subject": "Anatomy", "difficulty": "Hard", "question": "The foramen ovale transmits which cranial nerve?", "options": [{"key": "A", "text": "Maxillary nerve (V2)"}, {"key": "B", "text": "Mandibular nerve (V3)"}, {"key": "C", "text": "Ophthalmic nerve (V1)"}, {"key": "D", "text": "Facial nerve (VII)"}], "correct": "B", "explanation": "Foramen ovale in the sphenoid bone transmits the mandibular division of trigeminal nerve."}, {"id": 1275, "subject": "Anatomy", "difficulty": "Medium", "question": "Glabella is a landmark located on which bone?", "options": [{"key": "A", "text": "Frontal bone"}, {"key": "B", "text": "Nasal bone"}, {"key": "C", "text": "Maxilla"}, {"key": "D", "text": "Ethmoid bone"}], "correct": "A", "explanation": "Glabella is the smooth area between the eyebrows on the frontal bone."}, {"id": 1276, "subject": "Anatomy", "difficulty": "Medium", "question": "Inion refers to which bony landmark?", "options": [{"key": "A", "text": "Mastoid process"}, {"key": "B", "text": "External occipital protuberance"}, {"key": "C", "text": "Glabella"}, {"key": "D", "text": "Bregma"}], "correct": "B", "explanation": "Inion is the anatomical name for the external occipital protuberance."}, {"id": 1277, "subject": "Anatomy", "difficulty": "Medium", "question": "Bregma is the meeting point of which sutures?", "options": [{"key": "A", "text": "Coronal and sagittal"}, {"key": "B", "text": "Sagittal and lambdoid"}, {"key": "C", "text": "Coronal and squamous"}, {"key": "D", "text": "Lambdoid and squamous"}], "correct": "A", "explanation": "Bregma is where coronal and sagittal sutures intersect."}, {"id": 1278, "subject": "Anatomy", "difficulty": "Hard", "question": "Asterion is the junction of which sutures?", "options": [{"key": "A", "text": "Coronal, sagittal, squamous"}, {"key": "B", "text": "Lambdoid, occipitomastoid, parietomastoid"}, {"key": "C", "text": "Sagittal, lambdoid, coronal"}, {"key": "D", "text": "Squamous, frontal, parietal"}], "correct": "B", "explanation": "Asterion marks the junction of lambdoid, occipitomastoid and parietomastoid sutures."}, {"id": 1279, "subject": "Anatomy", "difficulty": "Medium", "question": "Which skull landmark is used to assess head posture clinically?", "options": [{"key": "A", "text": "Tragus of ear"}, {"key": "B", "text": "Inion"}, {"key": "C", "text": "Bregma"}, {"key": "D", "text": "Glabella"}], "correct": "A", "explanation": "The tragus is commonly used as a bony landmark for forward head posture assessment."}, {"id": 1280, "subject": "Anatomy", "difficulty": "Medium", "question": "The hyoid bone is suspended in the neck and connected to the skull by which muscle group?", "options": [{"key": "A", "text": "Suprahyoid muscles"}, {"key": "B", "text": "Infrahyoid muscles"}, {"key": "C", "text": "Scalene muscles"}, {"key": "D", "text": "Prevertebral muscles"}], "correct": "A", "explanation": "Suprahyoid muscles (e.g., digastric, mylohyoid) connect the hyoid bone to the skull/mandible."}, {"id": 1281, "subject": "Anatomy", "difficulty": "Easy", "question": "How many cervical vertebrae are present in the human spine?", "options": [{"key": "A", "text": "5"}, {"key": "B", "text": "6"}, {"key": "C", "text": "7"}, {"key": "D", "text": "8"}], "correct": "C", "explanation": "There are 7 cervical vertebrae, C1 to C7."}, {"id": 1282, "subject": "Anatomy", "difficulty": "Easy", "question": "Which cervical vertebra is known as the Atlas?", "options": [{"key": "A", "text": "C1"}, {"key": "B", "text": "C2"}, {"key": "C", "text": "C6"}, {"key": "D", "text": "C7"}], "correct": "A", "explanation": "C1 is called the Atlas as it supports the skull like the mythological figure."}, {"id": 1283, "subject": "Anatomy", "difficulty": "Easy", "question": "Which cervical vertebra is known as the Axis?", "options": [{"key": "A", "text": "C1"}, {"key": "B", "text": "C2"}, {"key": "C", "text": "C5"}, {"key": "D", "text": "C7"}], "correct": "B", "explanation": "C2 is called the Axis due to the odontoid process (dens) around which Atlas rotates."}, {"id": 1284, "subject": "Anatomy", "difficulty": "Medium", "question": "The Atlas vertebra lacks which typical vertebral feature?", "options": [{"key": "A", "text": "Transverse process"}, {"key": "B", "text": "Vertebral body"}, {"key": "C", "text": "Lamina"}, {"key": "D", "text": "Articular facets"}], "correct": "B", "explanation": "Atlas has no vertebral body; it is a ring-shaped bone."}, {"id": 1285, "subject": "Anatomy", "difficulty": "Easy", "question": "The odontoid process (dens) is found on which vertebra?", "options": [{"key": "A", "text": "C1"}, {"key": "B", "text": "C2"}, {"key": "C", "text": "C3"}, {"key": "D", "text": "C7"}], "correct": "B", "explanation": "Dens projects upward from the body of axis (C2) and articulates with anterior arch of atlas."}, {"id": 1286, "subject": "Anatomy", "difficulty": "Medium", "question": "Which ligament holds the dens against the anterior arch of atlas?", "options": [{"key": "A", "text": "Ligamentum flavum"}, {"key": "B", "text": "Transverse ligament of atlas"}, {"key": "C", "text": "Anterior longitudinal ligament"}, {"key": "D", "text": "Nuchal ligament"}], "correct": "B", "explanation": "Transverse ligament of atlas stabilizes the dens, preventing posterior displacement."}, {"id": 1287, "subject": "Anatomy", "difficulty": "Easy", "question": "C7 vertebra is also known as?", "options": [{"key": "A", "text": "Atlas"}, {"key": "B", "text": "Axis"}, {"key": "C", "text": "Vertebra prominens"}, {"key": "D", "text": "Typical vertebra"}], "correct": "C", "explanation": "C7 has a long, palpable spinous process, hence called vertebra prominens."}, {"id": 1288, "subject": "Anatomy", "difficulty": "Medium", "question": "Which joint allows the major part of cervical rotation movement?", "options": [{"key": "A", "text": "Atlanto-occipital joint"}, {"key": "B", "text": "Atlanto-axial joint"}, {"key": "C", "text": "C3-C4 facet joint"}, {"key": "D", "text": "C6-C7 facet joint"}], "correct": "B", "explanation": "Atlanto-axial joint accounts for nearly 50% of total cervical rotation."}, {"id": 1289, "subject": "Anatomy", "difficulty": "Medium", "question": "Which movement primarily occurs at the atlanto-occipital joint?", "options": [{"key": "A", "text": "Rotation"}, {"key": "B", "text": "Flexion-extension (nodding)"}, {"key": "C", "text": "Lateral flexion"}, {"key": "D", "text": "Circumduction"}], "correct": "B", "explanation": "Atlanto-occipital joint allows nodding (flexion-extension), the 'yes' movement."}, {"id": 1290, "subject": "Anatomy", "difficulty": "Hard", "question": "Uncovertebral joints (joints of Luschka) are typically found at which spinal level?", "options": [{"key": "A", "text": "Thoracic spine"}, {"key": "B", "text": "Lumbar spine"}, {"key": "C", "text": "Cervical spine (C3-C7)"}, {"key": "D", "text": "Sacral spine"}], "correct": "C", "explanation": "Uncovertebral joints are unique to the cervical spine, located at C3 to C7."}, {"id": 1291, "subject": "Anatomy", "difficulty": "Medium", "question": "The transverse foramen in cervical vertebrae transmits which structure?", "options": [{"key": "A", "text": "Spinal nerve"}, {"key": "B", "text": "Vertebral artery"}, {"key": "C", "text": "Internal carotid artery"}, {"key": "D", "text": "Sympathetic chain"}], "correct": "B", "explanation": "Vertebral artery and accompanying veins pass through the transverse foramina of C1-C6."}, {"id": 1292, "subject": "Anatomy", "difficulty": "Hard", "question": "At which cervical level does the vertebral artery typically NOT pass through the transverse foramen?", "options": [{"key": "A", "text": "C3"}, {"key": "B", "text": "C5"}, {"key": "C", "text": "C6"}, {"key": "D", "text": "C7"}], "correct": "D", "explanation": "Vertebral artery usually enters the transverse foramen at C6 and ascends; C7 transverse foramen usually transmits only a small vein."}, {"id": 1293, "subject": "Anatomy", "difficulty": "Easy", "question": "Which cervical vertebra has the largest spinous process?", "options": [{"key": "A", "text": "C1"}, {"key": "B", "text": "C3"}, {"key": "C", "text": "C5"}, {"key": "D", "text": "C7"}], "correct": "D", "explanation": "C7 has the longest and most prominent spinous process among cervical vertebrae."}, {"id": 1294, "subject": "Anatomy", "difficulty": "Medium", "question": "The cervical lordosis curve is classified as which type of curve?", "options": [{"key": "A", "text": "Primary curve"}, {"key": "B", "text": "Secondary curve"}, {"key": "C", "text": "Pathological curve"}, {"key": "D", "text": "Fixed curve"}], "correct": "B", "explanation": "Cervical lordosis is a secondary (compensatory) curve that develops after birth."}, {"id": 1295, "subject": "Anatomy", "difficulty": "Medium", "question": "Spondylosis commonly affects which cervical level due to high mobility?", "options": [{"key": "A", "text": "C1-C2"}, {"key": "B", "text": "C3-C4"}, {"key": "C", "text": "C5-C6"}, {"key": "D", "text": "C7-T1"}], "correct": "C", "explanation": "C5-C6 is a common site of degenerative changes due to high mechanical stress."}, {"id": 1296, "subject": "Anatomy", "difficulty": "Medium", "question": "Which ligament limits excessive flexion of the cervical spine?", "options": [{"key": "A", "text": "Anterior longitudinal ligament"}, {"key": "B", "text": "Posterior longitudinal ligament"}, {"key": "C", "text": "Ligamentum nuchae"}, {"key": "D", "text": "Transverse ligament"}], "correct": "C", "explanation": "Ligamentum nuchae, along with posterior structures, limits excessive cervical flexion."}, {"id": 1297, "subject": "Anatomy", "difficulty": "Medium", "question": "The ligamentum nuchae is a continuation of which ligament in the neck region?", "options": [{"key": "A", "text": "Anterior longitudinal ligament"}, {"key": "B", "text": "Supraspinous ligament"}, {"key": "C", "text": "Posterior longitudinal ligament"}, {"key": "D", "text": "Interspinous ligament"}], "correct": "B", "explanation": "Ligamentum nuchae is the cervical continuation of the supraspinous ligament."}, {"id": 1298, "subject": "Anatomy", "difficulty": "Hard", "question": "Cervical spinal nerves exit above their corresponding vertebra except which one?", "options": [{"key": "A", "text": "C4"}, {"key": "B", "text": "C6"}, {"key": "C", "text": "C7"}, {"key": "D", "text": "C8"}], "correct": "D", "explanation": "C8 nerve root exits below C7 vertebra since there is no C8 vertebra; all others exit above."}, {"id": 1299, "subject": "Anatomy", "difficulty": "Easy", "question": "Whiplash injury most commonly affects which spinal region?", "options": [{"key": "A", "text": "Lumbar spine"}, {"key": "B", "text": "Thoracic spine"}, {"key": "C", "text": "Cervical spine"}, {"key": "D", "text": "Sacral spine"}], "correct": "C", "explanation": "Whiplash is a hyperextension-hyperflexion injury commonly affecting the cervical spine."}, {"id": 1300, "subject": "Anatomy", "difficulty": "Hard", "question": "Which test assesses the integrity of the transverse ligament of atlas?", "options": [{"key": "A", "text": "Sharp-Purser test"}, {"key": "B", "text": "Spurling's test"}, {"key": "C", "text": "Lhermitte's sign"}, {"key": "D", "text": "Vertebral artery test"}], "correct": "A", "explanation": "Sharp-Purser test evaluates atlanto-axial instability due to transverse ligament laxity."}, {"id": 1301, "subject": "Anatomy", "difficulty": "Medium", "question": "Klippel-Feil syndrome is characterized by congenital fusion of which structures?", "options": [{"key": "A", "text": "Lumbar vertebrae"}, {"key": "B", "text": "Cervical vertebrae"}, {"key": "C", "text": "Thoracic ribs"}, {"key": "D", "text": "Sacral vertebrae"}], "correct": "B", "explanation": "Klippel-Feil syndrome involves congenital fusion of two or more cervical vertebrae."}, {"id": 1302, "subject": "Anatomy", "difficulty": "Medium", "question": "Which cervical vertebrae are considered 'typical' cervical vertebrae?", "options": [{"key": "A", "text": "C1 and C2"}, {"key": "B", "text": "C1 and C7"}, {"key": "C", "text": "C3 to C6"}, {"key": "D", "text": "C6 and C7"}], "correct": "C", "explanation": "C3 to C6 share common typical features unlike the atypical C1, C2, C7."}, {"id": 1303, "subject": "Anatomy", "difficulty": "Medium", "question": "The bifid spinous process is a characteristic feature of which vertebrae?", "options": [{"key": "A", "text": "C1 and C2"}, {"key": "B", "text": "Typical cervical vertebrae (C2-C6)"}, {"key": "C", "text": "Thoracic vertebrae"}, {"key": "D", "text": "Lumbar vertebrae"}], "correct": "B", "explanation": "Most cervical vertebrae (C2-C6) have a bifid (split) spinous process tip."}, {"id": 1304, "subject": "Anatomy", "difficulty": "Hard", "question": "Facet joint orientation in cervical spine favours which combined movement pattern?", "options": [{"key": "A", "text": "Pure flexion only"}, {"key": "B", "text": "Coupled lateral flexion with rotation to the same side"}, {"key": "C", "text": "Pure rotation only"}, {"key": "D", "text": "Coupled flexion with extension"}], "correct": "B", "explanation": "Cervical facet orientation produces coupled motion: lateral flexion and rotation occur to the same side."}, {"id": 1305, "subject": "Anatomy", "difficulty": "Medium", "question": "Cervical spine forward head posture increases load on which structures?", "options": [{"key": "A", "text": "Anterior cervical muscles only"}, {"key": "B", "text": "Posterior cervical extensors and upper trapezius"}, {"key": "C", "text": "Lumbar discs only"}, {"key": "D", "text": "Hip flexors"}], "correct": "B", "explanation": "Forward head posture increases compressive and tensile load on posterior cervical extensors and upper trapezius."}, {"id": 1306, "subject": "Anatomy", "difficulty": "Easy", "question": "Sternocleidomastoid (SCM) muscle has how many heads of origin?", "options": [{"key": "A", "text": "One"}, {"key": "B", "text": "Two"}, {"key": "C", "text": "Three"}, {"key": "D", "text": "Four"}], "correct": "B", "explanation": "SCM has a sternal head and a clavicular head of origin."}, {"id": 1307, "subject": "Anatomy", "difficulty": "Easy", "question": "The sternal head of SCM originates from?", "options": [{"key": "A", "text": "Manubrium sterni"}, {"key": "B", "text": "Medial third of clavicle"}, {"key": "C", "text": "Mastoid process"}, {"key": "D", "text": "Superior nuchal line"}], "correct": "A", "explanation": "Sternal head arises from the anterior surface of the manubrium sterni."}, {"id": 1308, "subject": "Anatomy", "difficulty": "Easy", "question": "The clavicular head of SCM originates from?", "options": [{"key": "A", "text": "Manubrium sterni"}, {"key": "B", "text": "Medial 1/3 of clavicle"}, {"key": "C", "text": "Acromion process"}, {"key": "D", "text": "Coracoid process"}], "correct": "B", "explanation": "Clavicular head arises from the medial third (superior surface) of the clavicle."}, {"id": 1309, "subject": "Anatomy", "difficulty": "Easy", "question": "Where does the sternocleidomastoid insert?", "options": [{"key": "A", "text": "Hyoid bone"}, {"key": "B", "text": "Mastoid process and lateral half of superior nuchal line"}, {"key": "C", "text": "Spinous process of C7"}, {"key": "D", "text": "Acromion process"}], "correct": "B", "explanation": "SCM inserts onto the mastoid process and lateral half of the superior nuchal line."}, {"id": 1310, "subject": "Anatomy", "difficulty": "Easy", "question": "Which nerve provides motor innervation to SCM?", "options": [{"key": "A", "text": "Hypoglossal nerve (CN XII)"}, {"key": "B", "text": "Accessory nerve (CN XI)"}, {"key": "C", "text": "Facial nerve (CN VII)"}, {"key": "D", "text": "Vagus nerve (CN X)"}], "correct": "B", "explanation": "Spinal accessory nerve (CN XI) supplies motor innervation to SCM."}, {"id": 1311, "subject": "Anatomy", "difficulty": "Hard", "question": "Sensory (proprioceptive) supply to SCM is from which spinal nerves?", "options": [{"key": "A", "text": "C1-C2"}, {"key": "B", "text": "C2-C3"}, {"key": "C", "text": "C3-C4"}, {"key": "D", "text": "C5-C6"}], "correct": "B", "explanation": "Ventral rami of C2-C3 provide proprioceptive fibers to SCM."}, {"id": 1312, "subject": "Anatomy", "difficulty": "Medium", "question": "Unilateral contraction of SCM produces which movement?", "options": [{"key": "A", "text": "Bilateral neck flexion"}, {"key": "B", "text": "Ipsilateral lateral flexion with contralateral rotation"}, {"key": "C", "text": "Bilateral extension"}, {"key": "D", "text": "Ipsilateral rotation"}], "correct": "B", "explanation": "Unilateral SCM action causes lateral flexion to same side with rotation of face to opposite side."}, {"id": 1313, "subject": "Anatomy", "difficulty": "Medium", "question": "Bilateral contraction of SCM produces which action?", "options": [{"key": "A", "text": "Neck extension"}, {"key": "B", "text": "Neck flexion (and assists in forced inspiration)"}, {"key": "C", "text": "Lateral flexion"}, {"key": "D", "text": "Rotation only"}], "correct": "B", "explanation": "Bilateral SCM contraction flexes the cervical spine and elevates the sternum during forced inspiration."}, {"id": 1314, "subject": "Anatomy", "difficulty": "Medium", "question": "Which condition is associated with shortening/fibrosis of SCM in infants?", "options": [{"key": "A", "text": "Torticollis"}, {"key": "B", "text": "Klippel-Feil syndrome"}, {"key": "C", "text": "Whiplash"}, {"key": "D", "text": "Cervical rib"}], "correct": "A", "explanation": "Congenital muscular torticollis results from fibrosis/shortening of SCM, causing head tilt."}, {"id": 1315, "subject": "Anatomy", "difficulty": "Medium", "question": "In congenital torticollis due to right SCM tightness, the head typically tilts to which side?", "options": [{"key": "A", "text": "Right side with chin pointing left"}, {"key": "B", "text": "Left side with chin pointing right"}, {"key": "C", "text": "Straight with no tilt"}, {"key": "D", "text": "Right side with chin pointing right"}], "correct": "A", "explanation": "Tight right SCM causes ipsilateral (right) lateral flexion with contralateral (left) rotation of chin."}, {"id": 1316, "subject": "Anatomy", "difficulty": "Medium", "question": "SCM forms the boundary between which two triangles of the neck?", "options": [{"key": "A", "text": "Anterior and posterior triangle"}, {"key": "B", "text": "Submandibular and carotid triangle"}, {"key": "C", "text": "Muscular and carotid triangle"}, {"key": "D", "text": "Occipital and supraclavicular triangle"}], "correct": "A", "explanation": "SCM divides the neck into anterior and posterior triangles."}, {"id": 1317, "subject": "Anatomy", "difficulty": "Medium", "question": "Which artery lies deep to the SCM muscle?", "options": [{"key": "A", "text": "Vertebral artery"}, {"key": "B", "text": "Common carotid artery"}, {"key": "C", "text": "Subclavian artery"}, {"key": "D", "text": "Facial artery"}], "correct": "B", "explanation": "Common carotid artery and internal jugular vein lie deep to SCM within the carotid sheath."}, {"id": 1318, "subject": "Anatomy", "difficulty": "Easy", "question": "Torticollis caused by SCM is also known as?", "options": [{"key": "A", "text": "Wry neck"}, {"key": "B", "text": "Whiplash neck"}, {"key": "C", "text": "Military neck"}, {"key": "D", "text": "Swan neck"}], "correct": "A", "explanation": "Torticollis due to SCM dysfunction is commonly called wry neck."}, {"id": 1319, "subject": "Anatomy", "difficulty": "Medium", "question": "Which special test helps assess SCM tightness in infants?", "options": [{"key": "A", "text": "Adam's forward bend test"}, {"key": "B", "text": "Passive cervical rotation/lateral flexion ROM test"}, {"key": "C", "text": "Spurling's test"}, {"key": "D", "text": "Romberg's test"}], "correct": "B", "explanation": "Assessing passive cervical lateral flexion and rotation ROM helps detect SCM tightness in torticollis."}, {"id": 1320, "subject": "Anatomy", "difficulty": "Medium", "question": "Accessory nerve (CN XI) after supplying SCM continues to supply which other muscle?", "options": [{"key": "A", "text": "Trapezius"}, {"key": "B", "text": "Levator scapulae"}, {"key": "C", "text": "Splenius capitis"}, {"key": "D", "text": "Rhomboid major"}], "correct": "A", "explanation": "CN XI passes through posterior triangle to also innervate the trapezius muscle."}, {"id": 1321, "subject": "Anatomy", "difficulty": "Medium", "question": "SCM acts as an accessory muscle of which physiological function?", "options": [{"key": "A", "text": "Swallowing"}, {"key": "B", "text": "Forced inspiration"}, {"key": "C", "text": "Phonation"}, {"key": "D", "text": "Mastication"}], "correct": "B", "explanation": "SCM elevates the sternum and assists forced/deep inspiration when neck is fixed."}, {"id": 1322, "subject": "Anatomy", "difficulty": "Hard", "question": "In which surgical/clinical procedure is the SCM commonly used as a landmark?", "options": [{"key": "A", "text": "Lumbar puncture"}, {"key": "B", "text": "Central venous catheterization (internal jugular vein)"}, {"key": "C", "text": "Knee arthroscopy"}, {"key": "D", "text": "Hip replacement"}], "correct": "B", "explanation": "SCM triangle landmarks are used for internal jugular vein central line placement."}, {"id": 1323, "subject": "Anatomy", "difficulty": "Medium", "question": "Tightness of both SCM muscles bilaterally commonly contributes to which postural deformity?", "options": [{"key": "A", "text": "Forward head posture"}, {"key": "B", "text": "Scoliosis"}, {"key": "C", "text": "Kyphosis of thoracic spine"}, {"key": "D", "text": "Genu valgum"}], "correct": "A", "explanation": "Bilateral SCM tightness contributes to forward head posture due to its flexor action on lower cervical spine."}, {"id": 1324, "subject": "Anatomy", "difficulty": "Hard", "question": "Which muscle works synergistically with SCM during contralateral rotation of the neck?", "options": [{"key": "A", "text": "Ipsilateral splenius capitis"}, {"key": "B", "text": "Contralateral splenius capitis"}, {"key": "C", "text": "Ipsilateral trapezius"}, {"key": "D", "text": "Contralateral levator scapulae"}], "correct": "A", "explanation": "SCM and ipsilateral splenius capitis act together to rotate the head to the same side as splenius."}, {"id": 1325, "subject": "Anatomy", "difficulty": "Medium", "question": "Physiotherapy management of congenital torticollis primarily includes?", "options": [{"key": "A", "text": "Surgical release only"}, {"key": "B", "text": "Passive stretching and positioning exercises"}, {"key": "C", "text": "Heat therapy only"}, {"key": "D", "text": "Strengthening of tight SCM"}], "correct": "B", "explanation": "Conservative management of torticollis emphasizes passive stretching, positioning, and active ROM exercises."}, {"id": 1326, "subject": "Anatomy", "difficulty": "Easy", "question": "How many scalene muscles are present on each side of the neck?", "options": [{"key": "A", "text": "Two"}, {"key": "B", "text": "Three"}, {"key": "C", "text": "Four"}, {"key": "D", "text": "Five"}], "correct": "B", "explanation": "There are three scalene muscles: anterior, middle, and posterior scalene."}, {"id": 1327, "subject": "Anatomy", "difficulty": "Medium", "question": "Scalenus anterior originates from which structures?", "options": [{"key": "A", "text": "Transverse processes of C3-C6"}, {"key": "B", "text": "Transverse processes of C2-C7"}, {"key": "C", "text": "Spinous processes of C3-C6"}, {"key": "D", "text": "Transverse processes of C4-C6"}], "correct": "A", "explanation": "Scalenus anterior arises from anterior tubercles of transverse processes of C3-C6."}, {"id": 1328, "subject": "Anatomy", "difficulty": "Medium", "question": "Scalenus anterior inserts onto which structure?", "options": [{"key": "A", "text": "First rib (scalene tubercle)"}, {"key": "B", "text": "Second rib"}, {"key": "C", "text": "Manubrium sterni"}, {"key": "D", "text": "Clavicle"}], "correct": "A", "explanation": "Scalenus anterior inserts on the scalene tubercle of the first rib."}, {"id": 1329, "subject": "Anatomy", "difficulty": "Medium", "question": "Scalenus medius is the largest and longest of the scalene muscles, inserting onto?", "options": [{"key": "A", "text": "First rib (posterior to subclavian artery groove)"}, {"key": "B", "text": "Second rib"}, {"key": "C", "text": "Clavicle"}, {"key": "D", "text": "Manubrium"}], "correct": "A", "explanation": "Scalenus medius inserts on the first rib, posterior to the subclavian artery groove."}, {"id": 1330, "subject": "Anatomy", "difficulty": "Medium", "question": "Scalenus posterior inserts onto which rib?", "options": [{"key": "A", "text": "First rib"}, {"key": "B", "text": "Second rib"}, {"key": "C", "text": "Third rib"}, {"key": "D", "text": "Fourth rib"}], "correct": "B", "explanation": "Scalenus posterior, the smallest scalene, inserts on the outer surface of the second rib."}, {"id": 1331, "subject": "Anatomy", "difficulty": "Medium", "question": "Which structures pass between scalenus anterior and scalenus medius?", "options": [{"key": "A", "text": "Subclavian vein only"}, {"key": "B", "text": "Brachial plexus and subclavian artery"}, {"key": "C", "text": "Phrenic nerve only"}, {"key": "D", "text": "Vagus nerve"}], "correct": "B", "explanation": "The interscalene triangle transmits the brachial plexus trunks and subclavian artery."}, {"id": 1332, "subject": "Anatomy", "difficulty": "Medium", "question": "The subclavian vein passes in relation to scalenus anterior how?", "options": [{"key": "A", "text": "Posterior to scalenus anterior"}, {"key": "B", "text": "Anterior to scalenus anterior"}, {"key": "C", "text": "Through scalenus anterior"}, {"key": "D", "text": "Lateral to scalenus medius"}], "correct": "B", "explanation": "Subclavian vein passes anterior to scalenus anterior, while subclavian artery passes posterior to it."}, {"id": 1333, "subject": "Anatomy", "difficulty": "Medium", "question": "Which nerve runs on the anterior surface of scalenus anterior muscle?", "options": [{"key": "A", "text": "Vagus nerve"}, {"key": "B", "text": "Phrenic nerve"}, {"key": "C", "text": "Hypoglossal nerve"}, {"key": "D", "text": "Accessory nerve"}], "correct": "B", "explanation": "Phrenic nerve (C3-C5) runs obliquely on the anterior surface of scalenus anterior."}, {"id": 1334, "subject": "Anatomy", "difficulty": "Medium", "question": "Compression of the brachial plexus and subclavian vessels between scalene muscles and first rib is known as?", "options": [{"key": "A", "text": "Carpal tunnel syndrome"}, {"key": "B", "text": "Thoracic outlet syndrome"}, {"key": "C", "text": "Cubital tunnel syndrome"}, {"key": "D", "text": "Piriformis syndrome"}], "correct": "B", "explanation": "Thoracic outlet syndrome can result from neurovascular compression in the interscalene triangle."}, {"id": 1335, "subject": "Anatomy", "difficulty": "Medium", "question": "Which clinical test is used to assess thoracic outlet syndrome involving scalene muscles?", "options": [{"key": "A", "text": "Adson's test"}, {"key": "B", "text": "Lachman test"}, {"key": "C", "text": "Thomas test"}, {"key": "D", "text": "Ober's test"}], "correct": "A", "explanation": "Adson's test assesses radial pulse changes with neck rotation/extension to detect TOS."}, {"id": 1336, "subject": "Anatomy", "difficulty": "Medium", "question": "Bilateral contraction of scalene muscles produces which action on the cervical spine?", "options": [{"key": "A", "text": "Extension"}, {"key": "B", "text": "Flexion"}, {"key": "C", "text": "Lateral flexion only"}, {"key": "D", "text": "Rotation only"}], "correct": "B", "explanation": "Bilateral scalene contraction flexes the cervical spine (with fixed ribs) and assists inspiration."}, {"id": 1337, "subject": "Anatomy", "difficulty": "Hard", "question": "Scalene muscles are innervated by which nerves?", "options": [{"key": "A", "text": "Cervical plexus and brachial plexus branches (C3-C8 ventral rami)"}, {"key": "B", "text": "Accessory nerve only"}, {"key": "C", "text": "Phrenic nerve only"}, {"key": "D", "text": "Vagus nerve"}], "correct": "A", "explanation": "Scalenes receive direct branches from cervical and brachial plexus ventral rami (C3-C8)."}, {"id": 1338, "subject": "Anatomy", "difficulty": "Medium", "question": "Scalene muscles act as accessory muscles of which respiratory function?", "options": [{"key": "A", "text": "Forced expiration"}, {"key": "B", "text": "Forced inspiration (elevate ribs 1 and 2)"}, {"key": "C", "text": "Normal quiet expiration"}, {"key": "D", "text": "Swallowing"}], "correct": "B", "explanation": "Scalenes elevate the first and second ribs to assist forced inspiration."}, {"id": 1339, "subject": "Anatomy", "difficulty": "Hard", "question": "Which scalene muscle is most implicated in compressing the brachial plexus in thoracic outlet syndrome?", "options": [{"key": "A", "text": "Scalenus anterior"}, {"key": "B", "text": "Scalenus medius"}, {"key": "C", "text": "Scalenus posterior"}, {"key": "D", "text": "All equally"}], "correct": "A", "explanation": "Scalenus anterior tightness/hypertrophy is most commonly implicated in neurogenic TOS."}, {"id": 1340, "subject": "Anatomy", "difficulty": "Hard", "question": "The interscalene triangle is bounded anteriorly, posteriorly and inferiorly by which structures?", "options": [{"key": "A", "text": "Scalenus anterior, scalenus medius, first rib"}, {"key": "B", "text": "SCM, trapezius, clavicle"}, {"key": "C", "text": "Scalenus medius, scalenus posterior, second rib"}, {"key": "D", "text": "Longus colli, longus capitis, hyoid"}], "correct": "A", "explanation": "Interscalene triangle boundaries: scalenus anterior (front), scalenus medius (back), first rib (base)."}, {"id": 1341, "subject": "Anatomy", "difficulty": "Hard", "question": "A cervical rib, when present, most commonly arises from which vertebra and predisposes to which condition?", "options": [{"key": "A", "text": "C7; thoracic outlet syndrome"}, {"key": "B", "text": "C5; whiplash"}, {"key": "C", "text": "C1; torticollis"}, {"key": "D", "text": "C6; carpal tunnel syndrome"}], "correct": "A", "explanation": "A cervical rib usually arises from C7 and can compress the brachial plexus, causing TOS."}, {"id": 1342, "subject": "Anatomy", "difficulty": "Medium", "question": "In physiotherapy, scalene stretching is commonly prescribed to relieve symptoms of?", "options": [{"key": "A", "text": "Lateral epicondylitis"}, {"key": "B", "text": "Thoracic outlet syndrome"}, {"key": "C", "text": "Plantar fasciitis"}, {"key": "D", "text": "De Quervain's tenosynovitis"}], "correct": "B", "explanation": "Scalene stretching helps decompress the interscalene triangle in TOS management."}, {"id": 1343, "subject": "Anatomy", "difficulty": "Hard", "question": "Which muscle lies posterior to scalenus medius, forming part of the floor of posterior triangle?", "options": [{"key": "A", "text": "Levator scapulae"}, {"key": "B", "text": "Trapezius"}, {"key": "C", "text": "Splenius cervicis"}, {"key": "D", "text": "Longus colli"}], "correct": "A", "explanation": "Levator scapulae lies posterior to scalenus medius, both forming the floor of posterior triangle of neck."}, {"id": 1344, "subject": "Anatomy", "difficulty": "Hard", "question": "Costoclavicular syndrome, a form of TOS, involves compression between which structures?", "options": [{"key": "A", "text": "Clavicle and first rib"}, {"key": "B", "text": "Scalene muscles only"}, {"key": "C", "text": "Pectoralis minor and ribs"}, {"key": "D", "text": "Cervical rib and clavicle"}], "correct": "A", "explanation": "Costoclavicular syndrome involves compression of neurovascular bundle between clavicle and first rib."}, {"id": 1345, "subject": "Anatomy", "difficulty": "Medium", "question": "Scalene muscles are classified functionally as part of which muscle group of the neck?", "options": [{"key": "A", "text": "Posterior extensor group"}, {"key": "B", "text": "Lateral flexor/accessory respiratory group"}, {"key": "C", "text": "Suprahyoid group"}, {"key": "D", "text": "Infrahyoid group"}], "correct": "B", "explanation": "Scalenes act as lateral flexors of the cervical spine and accessory muscles of respiration."}, {"id": 1346, "subject": "Anatomy", "difficulty": "Medium", "question": "Which deep neck flexor muscle is commonly weak in patients with forward head posture?", "options": [{"key": "A", "text": "Longus colli"}, {"key": "B", "text": "Trapezius"}, {"key": "C", "text": "Levator scapulae"}, {"key": "D", "text": "Splenius capitis"}], "correct": "A", "explanation": "Longus colli (deep cervical flexor) is often weak/inhibited in forward head posture."}, {"id": 1347, "subject": "Anatomy", "difficulty": "Easy", "question": "Trapezius muscle is innervated by which cranial nerve?", "options": [{"key": "A", "text": "Facial nerve (CN VII)"}, {"key": "B", "text": "Accessory nerve (CN XI)"}, {"key": "C", "text": "Vagus nerve (CN X)"}, {"key": "D", "text": "Hypoglossal nerve (CN XII)"}], "correct": "B", "explanation": "Spinal accessory nerve (CN XI) provides primary motor supply to trapezius."}, {"id": 1348, "subject": "Anatomy", "difficulty": "Medium", "question": "Levator scapulae originates from transverse processes of which vertebrae?", "options": [{"key": "A", "text": "C1-C4"}, {"key": "B", "text": "C3-C7"}, {"key": "C", "text": "C5-T1"}, {"key": "D", "text": "C1-C2"}], "correct": "A", "explanation": "Levator scapulae arises from transverse processes of C1-C4 and inserts on the medial border of scapula."}, {"id": 1349, "subject": "Anatomy", "difficulty": "Medium", "question": "Splenius capitis muscle action when contracting bilaterally is?", "options": [{"key": "A", "text": "Flexion of neck"}, {"key": "B", "text": "Extension of head and neck"}, {"key": "C", "text": "Lateral flexion only"}, {"key": "D", "text": "Rotation only"}], "correct": "B", "explanation": "Bilateral splenius capitis contraction extends the head and neck."}, {"id": 1350, "subject": "Anatomy", "difficulty": "Hard", "question": "Suboccipital triangle is formed by which three muscles?", "options": [{"key": "A", "text": "Rectus capitis posterior major, obliquus capitis superior, obliquus capitis inferior"}, {"key": "B", "text": "Rectus capitis posterior minor, longus capitis, longus colli"}, {"key": "C", "text": "SCM, trapezius, splenius capitis"}, {"key": "D", "text": "Scalenus anterior, medius, posterior"}], "correct": "A", "explanation": "The suboccipital triangle boundaries are rectus capitis posterior major, obliquus capitis superior and inferior."}, {"id": 1351, "subject": "Anatomy", "difficulty": "Hard", "question": "Which artery lies within the suboccipital triangle?", "options": [{"key": "A", "text": "Vertebral artery"}, {"key": "B", "text": "Common carotid artery"}, {"key": "C", "text": "External carotid artery"}, {"key": "D", "text": "Subclavian artery"}], "correct": "A", "explanation": "Vertebral artery (third part) and suboccipital nerve lie within the suboccipital triangle."}, {"id": 1352, "subject": "Anatomy", "difficulty": "Medium", "question": "Greater occipital nerve, often involved in cervicogenic headache, arises from which spinal level?", "options": [{"key": "A", "text": "C1 dorsal ramus"}, {"key": "B", "text": "C2 dorsal ramus"}, {"key": "C", "text": "C3 dorsal ramus"}, {"key": "D", "text": "C4 dorsal ramus"}], "correct": "B", "explanation": "Greater occipital nerve is the medial branch of the dorsal ramus of C2."}, {"id": 1353, "subject": "Anatomy", "difficulty": "Medium", "question": "Cervicogenic headache commonly involves referred pain from which upper cervical structures?", "options": [{"key": "A", "text": "Upper cervical (C1-C3) joints and muscles"}, {"key": "B", "text": "Lower cervical (C5-C7) joints"}, {"key": "C", "text": "Thoracic spine only"}, {"key": "D", "text": "Lumbar spine"}], "correct": "A", "explanation": "Cervicogenic headache typically originates from C1-C3 spinal segments and associated structures."}, {"id": 1354, "subject": "Anatomy", "difficulty": "Medium", "question": "Longus colli and longus capitis are classified as which type of cervical muscles?", "options": [{"key": "A", "text": "Superficial extensors"}, {"key": "B", "text": "Deep anterior (flexor) muscles"}, {"key": "C", "text": "Lateral rotators"}, {"key": "D", "text": "Suprahyoid muscles"}], "correct": "B", "explanation": "Longus colli and longus capitis are deep prevertebral flexor muscles of the cervical spine."}, {"id": 1355, "subject": "Anatomy", "difficulty": "Medium", "question": "Craniocervical flexion test (CCFT) is primarily used to assess function of which muscle?", "options": [{"key": "A", "text": "Upper trapezius"}, {"key": "B", "text": "Deep cervical flexors (longus colli/capitis)"}, {"key": "C", "text": "Scalenus anterior"}, {"key": "D", "text": "Splenius capitis"}], "correct": "B", "explanation": "CCFT assesses the endurance and activation of deep cervical flexor muscles."}, {"id": 1356, "subject": "Neuroanatomy", "difficulty": "Easy", "question": "Which part of the brain is responsible for voluntary motor control?", "options": [{"key": "A", "text": "Cerebellum"}, {"key": "B", "text": "Primary motor cortex (precentral gyrus)"}, {"key": "C", "text": "Thalamus"}, {"key": "D", "text": "Hypothalamus"}], "correct": "B", "explanation": "Primary motor cortex in the precentral gyrus (Brodmann area 4) controls voluntary movement."}, {"id": 1357, "subject": "Neuroanatomy", "difficulty": "Easy", "question": "Primary motor cortex is located in which lobe?", "options": [{"key": "A", "text": "Frontal lobe"}, {"key": "B", "text": "Parietal lobe"}, {"key": "C", "text": "Temporal lobe"}, {"key": "D", "text": "Occipital lobe"}], "correct": "A", "explanation": "Precentral gyrus of the frontal lobe houses the primary motor cortex."}, {"id": 1358, "subject": "Neuroanatomy", "difficulty": "Easy", "question": "Primary somatosensory cortex is located in which gyrus?", "options": [{"key": "A", "text": "Precentral gyrus"}, {"key": "B", "text": "Postcentral gyrus"}, {"key": "C", "text": "Superior temporal gyrus"}, {"key": "D", "text": "Cingulate gyrus"}], "correct": "B", "explanation": "Postcentral gyrus of parietal lobe is the primary somatosensory cortex."}, {"id": 1359, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Broca's area, responsible for speech production, is located in which lobe?", "options": [{"key": "A", "text": "Frontal lobe"}, {"key": "B", "text": "Parietal lobe"}, {"key": "C", "text": "Temporal lobe"}, {"key": "D", "text": "Occipital lobe"}], "correct": "A", "explanation": "Broca's area lies in the inferior frontal gyrus, usually left hemisphere."}, {"id": 1360, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Wernicke's area, responsible for language comprehension, is located in which lobe?", "options": [{"key": "A", "text": "Frontal lobe"}, {"key": "B", "text": "Temporal lobe"}, {"key": "C", "text": "Occipital lobe"}, {"key": "D", "text": "Parietal lobe"}], "correct": "B", "explanation": "Wernicke's area is located in the posterior superior temporal gyrus."}, {"id": 1361, "subject": "Neuroanatomy", "difficulty": "Easy", "question": "Primary visual cortex is located in which lobe?", "options": [{"key": "A", "text": "Frontal lobe"}, {"key": "B", "text": "Parietal lobe"}, {"key": "C", "text": "Temporal lobe"}, {"key": "D", "text": "Occipital lobe"}], "correct": "D", "explanation": "Primary visual cortex (V1) lies around the calcarine sulcus of occipital lobe."}, {"id": 1362, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Primary auditory cortex is located in which gyrus?", "options": [{"key": "A", "text": "Superior temporal gyrus"}, {"key": "B", "text": "Postcentral gyrus"}, {"key": "C", "text": "Precentral gyrus"}, {"key": "D", "text": "Cingulate gyrus"}], "correct": "A", "explanation": "Primary auditory cortex lies in the superior temporal gyrus (Heschl's gyrus)."}, {"id": 1363, "subject": "Neuroanatomy", "difficulty": "Easy", "question": "Which part of the brain coordinates balance and fine motor movements?", "options": [{"key": "A", "text": "Cerebrum"}, {"key": "B", "text": "Cerebellum"}, {"key": "C", "text": "Hypothalamus"}, {"key": "D", "text": "Medulla oblongata"}], "correct": "B", "explanation": "Cerebellum is responsible for coordination, balance, and fine-tuning of voluntary movement."}, {"id": 1364, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Damage to the cerebellum typically results in which clinical sign?", "options": [{"key": "A", "text": "Spastic paralysis"}, {"key": "B", "text": "Ataxia and dysmetria"}, {"key": "C", "text": "Sensory loss"}, {"key": "D", "text": "Aphasia"}], "correct": "B", "explanation": "Cerebellar lesions cause ataxia, dysmetria, and intention tremor."}, {"id": 1365, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The basal ganglia are primarily involved in?", "options": [{"key": "A", "text": "Sensory processing"}, {"key": "B", "text": "Regulation of voluntary movement"}, {"key": "C", "text": "Memory formation"}, {"key": "D", "text": "Hearing"}], "correct": "B", "explanation": "Basal ganglia help regulate and modulate voluntary movement and motor planning."}, {"id": 1366, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Parkinson's disease results from degeneration of which structure?", "options": [{"key": "A", "text": "Substantia nigra"}, {"key": "B", "text": "Cerebellum"}, {"key": "C", "text": "Hippocampus"}, {"key": "D", "text": "Corpus callosum"}], "correct": "A", "explanation": "Loss of dopaminergic neurons in substantia nigra causes Parkinson's disease."}, {"id": 1367, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The thalamus functions primarily as?", "options": [{"key": "A", "text": "Motor control center"}, {"key": "B", "text": "Relay station for sensory information"}, {"key": "C", "text": "Memory storage center"}, {"key": "D", "text": "Respiratory center"}], "correct": "B", "explanation": "Thalamus relays and processes most sensory information to the cerebral cortex."}, {"id": 1368, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The hypothalamus regulates which of the following?", "options": [{"key": "A", "text": "Voluntary movement"}, {"key": "B", "text": "Autonomic functions and homeostasis"}, {"key": "C", "text": "Hearing"}, {"key": "D", "text": "Vision"}], "correct": "B", "explanation": "Hypothalamus controls autonomic nervous system, temperature, hunger, and endocrine function via pituitary."}, {"id": 1369, "subject": "Neuroanatomy", "difficulty": "Easy", "question": "Which brainstem structure controls vital functions like heart rate and respiration?", "options": [{"key": "A", "text": "Midbrain"}, {"key": "B", "text": "Pons"}, {"key": "C", "text": "Medulla oblongata"}, {"key": "D", "text": "Cerebellum"}], "correct": "C", "explanation": "Medulla oblongata contains cardiac and respiratory centers controlling vital functions."}, {"id": 1370, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The corpus callosum primarily functions to?", "options": [{"key": "A", "text": "Connect cerebellum to brainstem"}, {"key": "B", "text": "Connect the two cerebral hemispheres"}, {"key": "C", "text": "Relay sensory information"}, {"key": "D", "text": "Control respiration"}], "correct": "B", "explanation": "Corpus callosum is the largest white matter tract connecting left and right cerebral hemispheres."}, {"id": 1371, "subject": "Neuroanatomy", "difficulty": "Hard", "question": "Which cranial nerve nuclei are located in the midbrain?", "options": [{"key": "A", "text": "CN III and IV"}, {"key": "B", "text": "CN V and VI"}, {"key": "C", "text": "CN IX and X"}, {"key": "D", "text": "CN XI and XII"}], "correct": "A", "explanation": "Oculomotor (III) and trochlear (IV) nerve nuclei are located in the midbrain."}, {"id": 1372, "subject": "Neuroanatomy", "difficulty": "Hard", "question": "Which cranial nerve nuclei are primarily located in the pons?", "options": [{"key": "A", "text": "CN I and II"}, {"key": "B", "text": "CN V, VI, VII, VIII"}, {"key": "C", "text": "CN IX and X"}, {"key": "D", "text": "CN XI and XII"}], "correct": "B", "explanation": "Trigeminal, abducens, facial and vestibulocochlear nerve nuclei lie in the pons."}, {"id": 1373, "subject": "Neuroanatomy", "difficulty": "Hard", "question": "Which cranial nerves arise from the medulla oblongata?", "options": [{"key": "A", "text": "CN IX, X, XI, XII"}, {"key": "B", "text": "CN III, IV"}, {"key": "C", "text": "CN V, VI"}, {"key": "D", "text": "CN I, II"}], "correct": "A", "explanation": "Glossopharyngeal, vagus, accessory and hypoglossal nerves arise from the medulla."}, {"id": 1374, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The limbic system is primarily associated with which function?", "options": [{"key": "A", "text": "Motor coordination"}, {"key": "B", "text": "Emotion and memory"}, {"key": "C", "text": "Hearing"}, {"key": "D", "text": "Balance"}], "correct": "B", "explanation": "Limbic system (hippocampus, amygdala, cingulate gyrus) regulates emotion and memory."}, {"id": 1375, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The hippocampus is primarily responsible for?", "options": [{"key": "A", "text": "Memory formation"}, {"key": "B", "text": "Motor planning"}, {"key": "C", "text": "Visual processing"}, {"key": "D", "text": "Hearing"}], "correct": "A", "explanation": "Hippocampus plays a key role in formation of new long-term memories."}, {"id": 1376, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Internal capsule contains which important pathway?", "options": [{"key": "A", "text": "Corticospinal tract fibers"}, {"key": "B", "text": "Optic nerve fibers only"}, {"key": "C", "text": "Cerebellar fibers only"}, {"key": "D", "text": "Auditory fibers only"}], "correct": "A", "explanation": "Internal capsule carries ascending and descending fibers including the corticospinal tract."}, {"id": 1377, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "A stroke affecting the internal capsule commonly results in?", "options": [{"key": "A", "text": "Pure sensory loss only"}, {"key": "B", "text": "Contralateral hemiplegia"}, {"key": "C", "text": "Ipsilateral hemiplegia"}, {"key": "D", "text": "Bilateral paralysis"}], "correct": "B", "explanation": "Lesions of internal capsule cause contralateral hemiplegia due to corticospinal tract involvement."}, {"id": 1378, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The Circle of Willis is formed by anastomosis of which arteries?", "options": [{"key": "A", "text": "Carotid and vertebrobasilar systems"}, {"key": "B", "text": "Carotid arteries only"}, {"key": "C", "text": "Vertebral arteries only"}, {"key": "D", "text": "Subclavian arteries only"}], "correct": "A", "explanation": "Circle of Willis is formed by anastomosis between internal carotid and vertebrobasilar arterial systems."}, {"id": 1379, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Middle cerebral artery occlusion most commonly affects which area function?", "options": [{"key": "A", "text": "Lower limb motor/sensory function"}, {"key": "B", "text": "Face and upper limb motor/sensory function"}, {"key": "C", "text": "Vision only"}, {"key": "D", "text": "Hearing only"}], "correct": "B", "explanation": "MCA supplies the lateral cerebral cortex controlling face and upper limb, hence face/arm weakness predominates."}, {"id": 1380, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Anterior cerebral artery occlusion most commonly affects which area function?", "options": [{"key": "A", "text": "Face and upper limb"}, {"key": "B", "text": "Lower limb motor/sensory function"}, {"key": "C", "text": "Hearing"}, {"key": "D", "text": "Vision"}], "correct": "B", "explanation": "ACA supplies medial cerebral cortex, controlling the lower limb, causing leg weakness predominantly."}, {"id": 1381, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "CSF is primarily produced by which structure?", "options": [{"key": "A", "text": "Arachnoid villi"}, {"key": "B", "text": "Choroid plexus"}, {"key": "C", "text": "Pia mater"}, {"key": "D", "text": "Dura mater"}], "correct": "B", "explanation": "Choroid plexus in the ventricles produces cerebrospinal fluid."}, {"id": 1382, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "CSF is reabsorbed into venous circulation through which structure?", "options": [{"key": "A", "text": "Choroid plexus"}, {"key": "B", "text": "Arachnoid villi"}, {"key": "C", "text": "Pia mater"}, {"key": "D", "text": "Falx cerebri"}], "correct": "B", "explanation": "Arachnoid villi/granulations reabsorb CSF into the dural venous sinuses."}, {"id": 1383, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The reticular activating system (RAS), responsible for consciousness/arousal, is located in?", "options": [{"key": "A", "text": "Cerebellum"}, {"key": "B", "text": "Brainstem"}, {"key": "C", "text": "Occipital lobe"}, {"key": "D", "text": "Hippocampus"}], "correct": "B", "explanation": "RAS is located in the brainstem and regulates wakefulness and arousal."}, {"id": 1384, "subject": "Neuroanatomy", "difficulty": "Easy", "question": "Which lobe of the brain is primarily responsible for executive functions and personality?", "options": [{"key": "A", "text": "Frontal lobe"}, {"key": "B", "text": "Parietal lobe"}, {"key": "C", "text": "Temporal lobe"}, {"key": "D", "text": "Occipital lobe"}], "correct": "A", "explanation": "Frontal lobe (prefrontal cortex) governs executive function, judgment, and personality."}, {"id": 1385, "subject": "Neuroanatomy", "difficulty": "Hard", "question": "Decorticate posturing (arms flexed, legs extended) indicates a lesion at which level?", "options": [{"key": "A", "text": "Above the level of red nucleus (cerebral hemispheres/internal capsule)"}, {"key": "B", "text": "Below the level of red nucleus (brainstem)"}, {"key": "C", "text": "Spinal cord"}, {"key": "D", "text": "Cerebellum"}], "correct": "A", "explanation": "Decorticate posturing indicates lesion above red nucleus, while decerebrate indicates brainstem lesion below it."}, {"id": 1386, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The spinal cord extends from foramen magnum to which vertebral level in adults?", "options": [{"key": "A", "text": "L1-L2"}, {"key": "B", "text": "L4-L5"}, {"key": "C", "text": "S1-S2"}, {"key": "D", "text": "T12-L1"}], "correct": "A", "explanation": "Adult spinal cord typically terminates at the level of L1-L2 vertebra (conus medullaris)."}, {"id": 1387, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The tapering end of the spinal cord is called?", "options": [{"key": "A", "text": "Cauda equina"}, {"key": "B", "text": "Conus medullaris"}, {"key": "C", "text": "Filum terminale"}, {"key": "D", "text": "Medullary cone"}], "correct": "B", "explanation": "Conus medullaris is the cone-shaped termination of the spinal cord."}, {"id": 1388, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Cauda equina refers to?", "options": [{"key": "A", "text": "The tapering tip of spinal cord"}, {"key": "B", "text": "Bundle of nerve roots below conus medullaris"}, {"key": "C", "text": "A fold of dura mater"}, {"key": "D", "text": "The central canal of spinal cord"}], "correct": "B", "explanation": "Cauda equina is the bundle of lumbar, sacral and coccygeal nerve roots below the conus medullaris."}, {"id": 1389, "subject": "Neuroanatomy", "difficulty": "Easy", "question": "How many pairs of spinal nerves arise from the spinal cord?", "options": [{"key": "A", "text": "29 pairs"}, {"key": "B", "text": "31 pairs"}, {"key": "C", "text": "33 pairs"}, {"key": "D", "text": "35 pairs"}], "correct": "B", "explanation": "There are 31 pairs of spinal nerves: 8 cervical, 12 thoracic, 5 lumbar, 5 sacral, 1 coccygeal."}, {"id": 1390, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "How many pairs of cervical spinal nerves are there?", "options": [{"key": "A", "text": "7"}, {"key": "B", "text": "8"}, {"key": "C", "text": "6"}, {"key": "D", "text": "9"}], "correct": "B", "explanation": "There are 8 pairs of cervical spinal nerves despite only 7 cervical vertebrae."}, {"id": 1391, "subject": "Neuroanatomy", "difficulty": "Easy", "question": "The corticospinal tract is primarily responsible for?", "options": [{"key": "A", "text": "Proprioception"}, {"key": "B", "text": "Voluntary motor control"}, {"key": "C", "text": "Pain and temperature sensation"}, {"key": "D", "text": "Vibration sense"}], "correct": "B", "explanation": "Corticospinal (pyramidal) tract carries voluntary motor commands from cortex to spinal cord."}, {"id": 1392, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Where do most corticospinal tract fibers decussate?", "options": [{"key": "A", "text": "Spinal cord"}, {"key": "B", "text": "Pons"}, {"key": "C", "text": "Pyramids of medulla oblongata"}, {"key": "D", "text": "Midbrain"}], "correct": "C", "explanation": "Approximately 85-90% of corticospinal fibers cross at the pyramidal decussation in the medulla."}, {"id": 1393, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The lateral corticospinal tract controls which type of movement?", "options": [{"key": "A", "text": "Axial/proximal muscles"}, {"key": "B", "text": "Distal limb muscles (fine voluntary movement)"}, {"key": "C", "text": "Autonomic functions"}, {"key": "D", "text": "Reflexes only"}], "correct": "B", "explanation": "Lateral corticospinal tract, after decussation, controls distal limb muscles for fine voluntary movement."}, {"id": 1394, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The dorsal column-medial lemniscus pathway carries which type of sensation?", "options": [{"key": "A", "text": "Pain and temperature"}, {"key": "B", "text": "Fine touch, vibration, and proprioception"}, {"key": "C", "text": "Crude touch only"}, {"key": "D", "text": "Autonomic sensation"}], "correct": "B", "explanation": "Dorsal columns carry fine touch, vibration, and conscious proprioception."}, {"id": 1395, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Where does the dorsal column-medial lemniscus pathway decussate?", "options": [{"key": "A", "text": "Spinal cord"}, {"key": "B", "text": "Medulla oblongata"}, {"key": "C", "text": "Pons"}, {"key": "D", "text": "Thalamus"}], "correct": "B", "explanation": "DCML pathway fibers cross in the medulla as internal arcuate fibers forming the medial lemniscus."}, {"id": 1396, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The spinothalamic tract primarily carries which sensations?", "options": [{"key": "A", "text": "Fine touch and proprioception"}, {"key": "B", "text": "Pain and temperature"}, {"key": "C", "text": "Vibration"}, {"key": "D", "text": "Stereognosis"}], "correct": "B", "explanation": "Lateral spinothalamic tract carries pain and temperature sensation."}, {"id": 1397, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Where does the spinothalamic tract decussate?", "options": [{"key": "A", "text": "Medulla oblongata"}, {"key": "B", "text": "Within 1-2 spinal cord segments of entry"}, {"key": "C", "text": "Pons"}, {"key": "D", "text": "Thalamus"}], "correct": "B", "explanation": "Spinothalamic tract fibers cross within 1-2 segments at the level of the spinal cord."}, {"id": 1398, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Brown-Sequard syndrome results from?", "options": [{"key": "A", "text": "Complete spinal cord transection"}, {"key": "B", "text": "Hemisection of the spinal cord"}, {"key": "C", "text": "Anterior cord compression only"}, {"key": "D", "text": "Posterior column lesion only"}], "correct": "B", "explanation": "Brown-Sequard syndrome is caused by hemisection of the spinal cord."}, {"id": 1399, "subject": "Neuroanatomy", "difficulty": "Hard", "question": "In Brown-Sequard syndrome, ipsilateral loss occurs in which modalities?", "options": [{"key": "A", "text": "Pain and temperature"}, {"key": "B", "text": "Motor function and proprioception/vibration"}, {"key": "C", "text": "Pain only"}, {"key": "D", "text": "Temperature only"}], "correct": "B", "explanation": "Ipsilateral loss occurs in motor (corticospinal) and proprioception/vibration (dorsal column) below lesion."}, {"id": 1400, "subject": "Neuroanatomy", "difficulty": "Hard", "question": "In Brown-Sequard syndrome, contralateral loss occurs in which modality?", "options": [{"key": "A", "text": "Motor function"}, {"key": "B", "text": "Proprioception"}, {"key": "C", "text": "Pain and temperature"}, {"key": "D", "text": "Vibration"}], "correct": "C", "explanation": "Contralateral pain and temperature loss occurs due to crossed spinothalamic tract below the lesion."}, {"id": 1401, "subject": "Neuroanatomy", "difficulty": "Hard", "question": "Anterior cord syndrome typically spares which sensory modality?", "options": [{"key": "A", "text": "Pain and temperature"}, {"key": "B", "text": "Proprioception and vibration sense (dorsal columns)"}, {"key": "C", "text": "Crude touch"}, {"key": "D", "text": "Motor function"}], "correct": "B", "explanation": "Anterior cord syndrome spares dorsal column function (proprioception/vibration) but affects motor and pain/temp."}, {"id": 1402, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Central cord syndrome classically presents with weakness more pronounced in which limbs?", "options": [{"key": "A", "text": "Lower limbs more than upper limbs"}, {"key": "B", "text": "Upper limbs more than lower limbs"}, {"key": "C", "text": "Equal in all four limbs"}, {"key": "D", "text": "Only one limb"}], "correct": "B", "explanation": "Central cord syndrome causes greater weakness in upper limbs than lower limbs due to central tract organization."}, {"id": 1403, "subject": "Neuroanatomy", "difficulty": "Easy", "question": "The spinal cord is protected by three meningeal layers; name them from outer to inner.", "options": [{"key": "A", "text": "Pia, arachnoid, dura"}, {"key": "B", "text": "Dura, arachnoid, pia"}, {"key": "C", "text": "Arachnoid, dura, pia"}, {"key": "D", "text": "Dura, pia, arachnoid"}], "correct": "B", "explanation": "From outermost to innermost: dura mater, arachnoid mater, pia mater."}, {"id": 1404, "subject": "Neuroanatomy", "difficulty": "Easy", "question": "Cerebrospinal fluid in the spinal cord is found in which space?", "options": [{"key": "A", "text": "Epidural space"}, {"key": "B", "text": "Subdural space"}, {"key": "C", "text": "Subarachnoid space"}, {"key": "D", "text": "Subpial space"}], "correct": "C", "explanation": "CSF circulates within the subarachnoid space surrounding the spinal cord."}, {"id": 1405, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Lumbar puncture is commonly performed at which vertebral level to avoid spinal cord injury?", "options": [{"key": "A", "text": "L1-L2"}, {"key": "B", "text": "L3-L4 or L4-L5"}, {"key": "C", "text": "T12-L1"}, {"key": "D", "text": "S1-S2"}], "correct": "B", "explanation": "Lumbar puncture is done below the conus medullaris, typically at L3-L4 or L4-L5."}, {"id": 1406, "subject": "Neuroanatomy", "difficulty": "Hard", "question": "Autonomic dysreflexia is a clinical concern in spinal cord injuries above which level?", "options": [{"key": "A", "text": "T6"}, {"key": "B", "text": "L1"}, {"key": "C", "text": "S1"}, {"key": "D", "text": "C2"}], "correct": "A", "explanation": "Autonomic dysreflexia commonly occurs in SCI at or above T6 level."}, {"id": 1407, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Spinal shock following spinal cord injury is characterized by?", "options": [{"key": "A", "text": "Hyperreflexia immediately after injury"}, {"key": "B", "text": "Temporary loss of all reflexes below the lesion"}, {"key": "C", "text": "Permanent loss of sensation only"}, {"key": "D", "text": "Increased muscle tone immediately"}], "correct": "B", "explanation": "Spinal shock causes temporary areflexia and flaccid paralysis below the level of injury."}, {"id": 1408, "subject": "Neuroanatomy", "difficulty": "Hard", "question": "The first reflex to return after spinal shock is typically?", "options": [{"key": "A", "text": "Patellar reflex"}, {"key": "B", "text": "Bulbocavernosus reflex"}, {"key": "C", "text": "Babinski reflex"}, {"key": "D", "text": "Achilles reflex"}], "correct": "B", "explanation": "Bulbocavernosus reflex is usually the first reflex to return, signaling the end of spinal shock."}, {"id": 1409, "subject": "Neuroanatomy", "difficulty": "Hard", "question": "Complete spinal cord injury at C4 level would most critically affect which function?", "options": [{"key": "A", "text": "Hand grip"}, {"key": "B", "text": "Independent breathing (diaphragm function)"}, {"key": "C", "text": "Hip flexion"}, {"key": "D", "text": "Ankle dorsiflexion"}], "correct": "B", "explanation": "C4 level injury severely compromises diaphragm function (C3-C5 phrenic nerve), risking respiratory failure."}, {"id": 1410, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "ASIA Impairment Scale grade A indicates?", "options": [{"key": "A", "text": "Complete motor and sensory loss"}, {"key": "B", "text": "Sensory incomplete, motor complete"}, {"key": "C", "text": "Motor incomplete below level"}, {"key": "D", "text": "Normal motor and sensory function"}], "correct": "A", "explanation": "ASIA A indicates a complete spinal cord injury with no motor or sensory function preserved in S4-S5."}, {"id": 1411, "subject": "Neuroanatomy", "difficulty": "Easy", "question": "Dermatome is defined as?", "options": [{"key": "A", "text": "Area of skin supplied by a single muscle"}, {"key": "B", "text": "Area of skin supplied by a single spinal nerve"}, {"key": "C", "text": "Area of muscle supplied by a single nerve root"}, {"key": "D", "text": "Area supplied by cranial nerves only"}], "correct": "B", "explanation": "A dermatome is the area of skin innervated by sensory fibers of a single spinal nerve root."}, {"id": 1412, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The C5 dermatome typically corresponds to which area?", "options": [{"key": "A", "text": "Thumb"}, {"key": "B", "text": "Lateral aspect of upper arm (deltoid area)"}, {"key": "C", "text": "Little finger"}, {"key": "D", "text": "Nipple line"}], "correct": "B", "explanation": "C5 dermatome covers the lateral arm over the deltoid region."}, {"id": 1413, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The C6 dermatome typically corresponds to which area?", "options": [{"key": "A", "text": "Thumb and lateral forearm"}, {"key": "B", "text": "Little finger"}, {"key": "C", "text": "Medial arm"}, {"key": "D", "text": "Axilla"}], "correct": "A", "explanation": "C6 dermatome covers the thumb, index finger, and lateral forearm."}, {"id": 1414, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The C7 dermatome typically corresponds to which area?", "options": [{"key": "A", "text": "Thumb"}, {"key": "B", "text": "Middle finger"}, {"key": "C", "text": "Little finger"}, {"key": "D", "text": "Lateral forearm"}], "correct": "B", "explanation": "C7 dermatome covers the middle finger."}, {"id": 1415, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The C8 dermatome typically corresponds to which area?", "options": [{"key": "A", "text": "Thumb"}, {"key": "B", "text": "Middle finger"}, {"key": "C", "text": "Little finger and medial forearm"}, {"key": "D", "text": "Lateral arm"}], "correct": "C", "explanation": "C8 dermatome covers the little finger and medial side of the hand/forearm."}, {"id": 1416, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The T4 dermatome level corresponds to which landmark?", "options": [{"key": "A", "text": "Umbilicus"}, {"key": "B", "text": "Nipple line"}, {"key": "C", "text": "Xiphoid process"}, {"key": "D", "text": "Inguinal region"}], "correct": "B", "explanation": "T4 dermatome corresponds to the nipple line."}, {"id": 1417, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The T10 dermatome level corresponds to which landmark?", "options": [{"key": "A", "text": "Nipple line"}, {"key": "B", "text": "Xiphoid process"}, {"key": "C", "text": "Umbilicus"}, {"key": "D", "text": "Pubic region"}], "correct": "C", "explanation": "T10 dermatome corresponds to the level of the umbilicus."}, {"id": 1418, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The L1 dermatome typically corresponds to which area?", "options": [{"key": "A", "text": "Inguinal/groin region"}, {"key": "B", "text": "Anterior thigh"}, {"key": "C", "text": "Medial leg"}, {"key": "D", "text": "Lateral foot"}], "correct": "A", "explanation": "L1 dermatome covers the inguinal/groin region."}, {"id": 1419, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The L4 dermatome typically corresponds to which area?", "options": [{"key": "A", "text": "Lateral foot"}, {"key": "B", "text": "Medial leg and medial malleolus"}, {"key": "C", "text": "Posterior thigh"}, {"key": "D", "text": "Buttock"}], "correct": "B", "explanation": "L4 dermatome covers the medial leg including the medial malleolus."}, {"id": 1420, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The L5 dermatome typically corresponds to which area?", "options": [{"key": "A", "text": "Medial malleolus"}, {"key": "B", "text": "Dorsum of foot and great toe"}, {"key": "C", "text": "Lateral malleolus/little toe"}, {"key": "D", "text": "Posterior thigh"}], "correct": "B", "explanation": "L5 dermatome covers the dorsum of the foot and great toe."}, {"id": 1421, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The S1 dermatome typically corresponds to which area?", "options": [{"key": "A", "text": "Medial leg"}, {"key": "B", "text": "Dorsum of foot"}, {"key": "C", "text": "Lateral foot, heel and little toe"}, {"key": "D", "text": "Anterior thigh"}], "correct": "C", "explanation": "S1 dermatome covers the lateral foot, heel and little toe (sole region)."}, {"id": 1422, "subject": "Neuroanatomy", "difficulty": "Hard", "question": "The perianal/saddle region corresponds to which dermatomes?", "options": [{"key": "A", "text": "L4-L5"}, {"key": "B", "text": "S3-S5"}, {"key": "C", "text": "T12-L1"}, {"key": "D", "text": "S1-S2"}], "correct": "B", "explanation": "Saddle area sensation corresponds to S3-S5 dermatomes; saddle anesthesia suggests cauda equina syndrome."}, {"id": 1423, "subject": "Neuroanatomy", "difficulty": "Hard", "question": "Saddle anesthesia is a red flag sign for which condition?", "options": [{"key": "A", "text": "Carpal tunnel syndrome"}, {"key": "B", "text": "Cauda equina syndrome"}, {"key": "C", "text": "Cervical radiculopathy"}, {"key": "D", "text": "Thoracic outlet syndrome"}], "correct": "B", "explanation": "Saddle anesthesia (S3-S5) is a hallmark red flag for cauda equina syndrome requiring urgent referral."}, {"id": 1424, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Herpes zoster (shingles) rash typically follows the distribution of?", "options": [{"key": "A", "text": "A peripheral nerve"}, {"key": "B", "text": "A single dermatome"}, {"key": "C", "text": "Multiple dermatomes randomly"}, {"key": "D", "text": "A myotome"}], "correct": "B", "explanation": "Herpes zoster reactivates in a dorsal root ganglion and presents along a single dermatome."}, {"id": 1425, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Dermatome mapping is clinically useful for diagnosing which condition?", "options": [{"key": "A", "text": "Muscle strain"}, {"key": "B", "text": "Nerve root compression/radiculopathy"}, {"key": "C", "text": "Tendon rupture"}, {"key": "D", "text": "Ligament sprain"}], "correct": "B", "explanation": "Sensory testing along dermatomes helps localize the level of nerve root compression in radiculopathy."}, {"id": 1426, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Which dermatome is tested by sensation over the nipple line during a neurological exam?", "options": [{"key": "A", "text": "T4"}, {"key": "B", "text": "T6"}, {"key": "C", "text": "T10"}, {"key": "D", "text": "T12"}], "correct": "A", "explanation": "T4 dermatome level is classically tested at the nipple line."}, {"id": 1427, "subject": "Neuroanatomy", "difficulty": "Hard", "question": "The axilla region corresponds approximately to which dermatome?", "options": [{"key": "A", "text": "C5"}, {"key": "B", "text": "T1-T2"}, {"key": "C", "text": "C8"}, {"key": "D", "text": "L1"}], "correct": "B", "explanation": "The axilla and medial arm correspond approximately to T1-T2 dermatomes."}, {"id": 1428, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Dermatomal pattern of pain radiating down the posterior thigh and lateral leg to the foot suggests irritation of which nerve root?", "options": [{"key": "A", "text": "L4"}, {"key": "B", "text": "L5/S1"}, {"key": "C", "text": "C7"}, {"key": "D", "text": "T12"}], "correct": "B", "explanation": "Sciatic pain radiating posteriorly to the foot commonly follows L5/S1 dermatomal distribution."}, {"id": 1429, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "In a patient with numbness over the lateral three and a half fingers, which dermatome/nerve is likely involved?", "options": [{"key": "A", "text": "C6/median nerve distribution"}, {"key": "B", "text": "C8/ulnar nerve distribution"}, {"key": "C", "text": "T1 distribution"}, {"key": "D", "text": "L5 distribution"}], "correct": "A", "explanation": "Numbness over thumb, index, middle and half of ring finger suggests C6 dermatome/median nerve involvement."}, {"id": 1430, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "A patient presents with numbness of the little finger and medial forearm; which nerve root is most likely affected?", "options": [{"key": "A", "text": "C5"}, {"key": "B", "text": "C6"}, {"key": "C", "text": "C7"}, {"key": "D", "text": "C8"}], "correct": "D", "explanation": "C8 dermatome covers the little finger and medial forearm, often involving ulnar nerve pathway."}, {"id": 1431, "subject": "Neuroanatomy", "difficulty": "Hard", "question": "Dermatomes overlap significantly such that loss of a single nerve root typically causes?", "options": [{"key": "A", "text": "Complete anesthesia in that area"}, {"key": "B", "text": "Partial sensory loss due to overlap from adjacent roots"}, {"key": "C", "text": "No sensory change at all"}, {"key": "D", "text": "Hyperesthesia only"}], "correct": "B", "explanation": "Due to dermatomal overlap, a single root lesion usually causes partial rather than complete sensory loss."}, {"id": 1432, "subject": "Neuroanatomy", "difficulty": "Easy", "question": "Myotome is defined as?", "options": [{"key": "A", "text": "Area of skin supplied by a nerve root"}, {"key": "B", "text": "Group of muscles supplied by a single spinal nerve root"}, {"key": "C", "text": "A single muscle's nerve supply"}, {"key": "D", "text": "Sensory distribution of a dermatome"}], "correct": "B", "explanation": "A myotome is the group of muscles innervated by a single spinal nerve root."}, {"id": 1433, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Which myotome is responsible for shoulder abduction (deltoid)?", "options": [{"key": "A", "text": "C4"}, {"key": "B", "text": "C5"}, {"key": "C", "text": "C6"}, {"key": "D", "text": "C7"}], "correct": "B", "explanation": "C5 myotome primarily tests shoulder abduction via deltoid muscle."}, {"id": 1434, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Which myotome is responsible for elbow flexion (biceps)?", "options": [{"key": "A", "text": "C5"}, {"key": "B", "text": "C6"}, {"key": "C", "text": "C7"}, {"key": "D", "text": "C8"}], "correct": "B", "explanation": "C6 myotome is tested via elbow flexion (biceps) and wrist extension."}, {"id": 1435, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Which myotome is responsible for elbow extension (triceps)?", "options": [{"key": "A", "text": "C5"}, {"key": "B", "text": "C6"}, {"key": "C", "text": "C7"}, {"key": "D", "text": "C8"}], "correct": "C", "explanation": "C7 myotome is tested via elbow extension (triceps) and wrist flexion."}, {"id": 1436, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Which myotome is responsible for finger flexion?", "options": [{"key": "A", "text": "C6"}, {"key": "B", "text": "C7"}, {"key": "C", "text": "C8"}, {"key": "D", "text": "T1"}], "correct": "C", "explanation": "C8 myotome is tested via finger flexion (flexor digitorum)."}, {"id": 1437, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Which myotome is responsible for finger abduction (small hand muscles)?", "options": [{"key": "A", "text": "C7"}, {"key": "B", "text": "C8"}, {"key": "C", "text": "T1"}, {"key": "D", "text": "T2"}], "correct": "C", "explanation": "T1 myotome is tested via finger abduction using intrinsic hand muscles."}, {"id": 1438, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Which myotome is primarily responsible for diaphragm function?", "options": [{"key": "A", "text": "C2-C3"}, {"key": "B", "text": "C3-C5"}, {"key": "C", "text": "C6-C8"}, {"key": "D", "text": "T1-T2"}], "correct": "B", "explanation": "Phrenic nerve from C3-C5 ('C3,4,5 keep the diaphragm alive') innervates the diaphragm."}, {"id": 1439, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Which myotome is responsible for hip flexion?", "options": [{"key": "A", "text": "L1-L2"}, {"key": "B", "text": "L3-L4"}, {"key": "C", "text": "L4-L5"}, {"key": "D", "text": "L5-S1"}], "correct": "A", "explanation": "L1-L2 myotome is primarily tested via hip flexion (iliopsoas)."}, {"id": 1440, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Which myotome is responsible for knee extension (quadriceps)?", "options": [{"key": "A", "text": "L2"}, {"key": "B", "text": "L3-L4"}, {"key": "C", "text": "L5"}, {"key": "D", "text": "S1"}], "correct": "B", "explanation": "L3-L4 myotome is tested via knee extension using the quadriceps muscle."}, {"id": 1441, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Which myotome is responsible for ankle dorsiflexion (tibialis anterior)?", "options": [{"key": "A", "text": "L3"}, {"key": "B", "text": "L4"}, {"key": "C", "text": "L5"}, {"key": "D", "text": "S1"}], "correct": "B", "explanation": "L4 myotome is classically tested via ankle dorsiflexion (tibialis anterior)."}, {"id": 1442, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Which myotome is responsible for great toe extension (extensor hallucis longus)?", "options": [{"key": "A", "text": "L3"}, {"key": "B", "text": "L4"}, {"key": "C", "text": "L5"}, {"key": "D", "text": "S2"}], "correct": "C", "explanation": "L5 myotome is tested via great toe extension (extensor hallucis longus)."}, {"id": 1443, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Which myotome is responsible for ankle plantarflexion (gastrocnemius/soleus)?", "options": [{"key": "A", "text": "L4"}, {"key": "B", "text": "L5"}, {"key": "C", "text": "S1"}, {"key": "D", "text": "S2"}], "correct": "C", "explanation": "S1 myotome is tested via ankle plantarflexion and eversion."}, {"id": 1444, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Which myotome is primarily responsible for knee flexion?", "options": [{"key": "A", "text": "L3-L4"}, {"key": "B", "text": "L5-S1"}, {"key": "C", "text": "S2-S3"}, {"key": "D", "text": "L1-L2"}], "correct": "B", "explanation": "Knee flexion (hamstrings) is primarily mediated by L5-S1 myotome."}, {"id": 1445, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Loss of ankle jerk reflex is associated with which nerve root lesion?", "options": [{"key": "A", "text": "L3"}, {"key": "B", "text": "L4"}, {"key": "C", "text": "S1"}, {"key": "D", "text": "S2"}], "correct": "C", "explanation": "Ankle jerk (Achilles reflex) primarily tests S1 nerve root integrity."}, {"id": 1446, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Loss of knee jerk reflex is associated with which nerve root lesion?", "options": [{"key": "A", "text": "L2-L4"}, {"key": "B", "text": "L5-S1"}, {"key": "C", "text": "S1-S2"}, {"key": "D", "text": "C5-C6"}], "correct": "A", "explanation": "Knee jerk (patellar reflex) primarily tests L2-L4 (mainly L3-L4) nerve root integrity."}, {"id": 1447, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Loss of biceps jerk reflex is associated with which nerve root?", "options": [{"key": "A", "text": "C5-C6"}, {"key": "B", "text": "C7-C8"}, {"key": "C", "text": "C8-T1"}, {"key": "D", "text": "T1-T2"}], "correct": "A", "explanation": "Biceps reflex tests primarily C5-C6 nerve root integrity."}, {"id": 1448, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Loss of triceps jerk reflex is associated with which nerve root?", "options": [{"key": "A", "text": "C5-C6"}, {"key": "B", "text": "C6-C7"}, {"key": "C", "text": "C7-C8"}, {"key": "D", "text": "C8-T1"}], "correct": "C", "explanation": "Triceps reflex primarily tests C7-C8 nerve root integrity."}, {"id": 1449, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Myotomal testing in physiotherapy is done primarily using which method?", "options": [{"key": "A", "text": "Passive range of motion"}, {"key": "B", "text": "Resisted isometric muscle testing"}, {"key": "C", "text": "Reflex hammer testing only"}, {"key": "D", "text": "Light touch sensation testing"}], "correct": "B", "explanation": "Myotome testing is performed via resisted isometric contraction of key muscles for each spinal level."}, {"id": 1450, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "A patient unable to perform resisted ankle dorsiflexion likely has involvement of which nerve root?", "options": [{"key": "A", "text": "L3"}, {"key": "B", "text": "L4"}, {"key": "C", "text": "L5"}, {"key": "D", "text": "S1"}], "correct": "B", "explanation": "Weakness of ankle dorsiflexion (tibialis anterior) indicates L4 myotome involvement (or deep peroneal nerve)."}, {"id": 1451, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Footdrop with weak ankle dorsiflexion and toe extension most commonly indicates lesion at which level?", "options": [{"key": "A", "text": "L3"}, {"key": "B", "text": "L4-L5"}, {"key": "C", "text": "S1-S2"}, {"key": "D", "text": "S3-S4"}], "correct": "B", "explanation": "Footdrop typically results from L4-L5 nerve root or common peroneal nerve dysfunction."}, {"id": 1452, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Myotome testing is clinically combined with which other assessments for complete neurological examination?", "options": [{"key": "A", "text": "Dermatome testing and deep tendon reflexes"}, {"key": "B", "text": "Range of motion testing only"}, {"key": "C", "text": "Special orthopedic tests only"}, {"key": "D", "text": "Vital sign monitoring"}], "correct": "A", "explanation": "A complete neurological exam includes myotome (motor), dermatome (sensory), and reflex testing together."}, {"id": 1453, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Cervical myotome C4 is primarily responsible for which action?", "options": [{"key": "A", "text": "Shoulder elevation (trapezius/shoulder shrug)"}, {"key": "B", "text": "Elbow flexion"}, {"key": "C", "text": "Wrist extension"}, {"key": "D", "text": "Finger flexion"}], "correct": "A", "explanation": "C4 myotome is tested via shoulder shrug/elevation, mediated through trapezius and levator scapulae."}, {"id": 1454, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "Which spinal tract is responsible for unconscious proprioception to the cerebellum?", "options": [{"key": "A", "text": "Lateral spinothalamic tract"}, {"key": "B", "text": "Spinocerebellar tract"}, {"key": "C", "text": "Corticospinal tract"}, {"key": "D", "text": "Dorsal column tract"}], "correct": "B", "explanation": "Spinocerebellar tracts carry unconscious proprioceptive information to the cerebellum for coordination."}, {"id": 1455, "subject": "Neuroanatomy", "difficulty": "Medium", "question": "The femoral nerve, testing knee extension, arises primarily from which myotome level?", "options": [{"key": "A", "text": "L1-L2"}, {"key": "B", "text": "L2-L4"}, {"key": "C", "text": "L5-S1"}, {"key": "D", "text": "S2-S3"}], "correct": "B", "explanation": "Femoral nerve arises from L2-L4 ventral rami, innervating quadriceps for knee extension."}, {"id": 1456, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The surgical neck of humerus is closely related to which nerve, injury of which causes deltoid paralysis?", "options": [{"key": "A", "text": "Radial nerve"}, {"key": "B", "text": "Axillary nerve"}, {"key": "C", "text": "Musculocutaneous nerve"}, {"key": "D", "text": "Ulnar nerve"}], "correct": "B", "explanation": "Axillary nerve winds around the surgical neck of humerus and is vulnerable in fractures here."}, {"id": 1457, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Radial nerve injury at the radial (spiral) groove of humerus most commonly results in?", "options": [{"key": "A", "text": "Claw hand"}, {"key": "B", "text": "Wrist drop"}, {"key": "C", "text": "Ape thumb deformity"}, {"key": "D", "text": "Winging of scapula"}], "correct": "B", "explanation": "Radial nerve injury in spiral groove causes wrist drop due to paralysis of wrist/finger extensors."}, {"id": 1458, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which carpal bone is most commonly fractured following a fall on outstretched hand?", "options": [{"key": "A", "text": "Lunate"}, {"key": "B", "text": "Scaphoid"}, {"key": "C", "text": "Trapezium"}, {"key": "D", "text": "Hamate"}], "correct": "B", "explanation": "Scaphoid is the most commonly fractured carpal bone, often missed on initial X-ray."}, {"id": 1459, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Avascular necrosis is a common complication of fracture of which carpal bone due to retrograde blood supply?", "options": [{"key": "A", "text": "Scaphoid"}, {"key": "B", "text": "Pisiform"}, {"key": "C", "text": "Triquetrum"}, {"key": "D", "text": "Capitate"}], "correct": "A", "explanation": "Scaphoid has retrograde blood supply, making proximal pole fractures prone to avascular necrosis."}, {"id": 1460, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The radial styloid process is normally longer/more distal than the ulnar styloid by approximately?", "options": [{"key": "A", "text": "1 cm"}, {"key": "B", "text": "2.5 cm"}, {"key": "C", "text": "5 cm"}, {"key": "D", "text": "Equal length"}], "correct": "A", "explanation": "Radial styloid is normally about 1 cm more distal than the ulnar styloid process."}, {"id": 1461, "subject": "Mixed Revision", "difficulty": "Hard", "question": "In a Colles' fracture, the distal fragment of radius is typically displaced in which direction?", "options": [{"key": "A", "text": "Anteriorly (volarly)"}, {"key": "B", "text": "Posteriorly (dorsally)"}, {"key": "C", "text": "Medially"}, {"key": "D", "text": "Laterally only"}], "correct": "B", "explanation": "Colles' fracture shows dorsal (posterior) displacement of the distal radial fragment, the classic 'dinner fork' deformity."}, {"id": 1462, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The carrying angle of the elbow is increased in which condition?", "options": [{"key": "A", "text": "Cubitus varus"}, {"key": "B", "text": "Cubitus valgus"}, {"key": "C", "text": "Genu varum"}, {"key": "D", "text": "Genu valgum"}], "correct": "B", "explanation": "Cubitus valgus refers to an increased carrying angle at the elbow."}, {"id": 1463, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which ligament of the shoulder is most commonly injured in anterior shoulder dislocation?", "options": [{"key": "A", "text": "Coracoacromial ligament"}, {"key": "B", "text": "Inferior glenohumeral ligament"}, {"key": "C", "text": "Coracoclavicular ligament"}, {"key": "D", "text": "Transverse humeral ligament"}], "correct": "B", "explanation": "Inferior glenohumeral ligament complex is the primary stabilizer injured in anterior dislocation."}, {"id": 1464, "subject": "Mixed Revision", "difficulty": "Hard", "question": "A Bankart lesion refers to injury of which structure following anterior shoulder dislocation?", "options": [{"key": "A", "text": "Rotator cuff tendon"}, {"key": "B", "text": "Anteroinferior glenoid labrum"}, {"key": "C", "text": "Acromioclavicular ligament"}, {"key": "D", "text": "Long head of biceps tendon"}], "correct": "B", "explanation": "Bankart lesion is detachment of the anteroinferior glenoid labrum from recurrent anterior dislocation."}, {"id": 1465, "subject": "Mixed Revision", "difficulty": "Hard", "question": "A Hill-Sachs lesion is a compression fracture occurring at which site after anterior dislocation?", "options": [{"key": "A", "text": "Posterolateral humeral head"}, {"key": "B", "text": "Glenoid rim"}, {"key": "C", "text": "Coracoid process"}, {"key": "D", "text": "Acromion"}], "correct": "A", "explanation": "Hill-Sachs lesion is an impaction fracture of the posterolateral humeral head against the glenoid rim."}, {"id": 1466, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The elbow joint is classified as which type of synovial joint?", "options": [{"key": "A", "text": "Ball and socket"}, {"key": "B", "text": "Hinge (uniaxial)"}, {"key": "C", "text": "Saddle"}, {"key": "D", "text": "Pivot"}], "correct": "B", "explanation": "Humeroulnar joint of the elbow is a uniaxial hinge joint allowing flexion-extension."}, {"id": 1467, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The proximal radioulnar joint is classified as which type of joint?", "options": [{"key": "A", "text": "Hinge joint"}, {"key": "B", "text": "Pivot joint"}, {"key": "C", "text": "Saddle joint"}, {"key": "D", "text": "Plane joint"}], "correct": "B", "explanation": "Proximal radioulnar joint is a pivot joint allowing pronation and supination."}, {"id": 1468, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which wrist ligament tear is most associated with scapholunate instability?", "options": [{"key": "A", "text": "Triangular fibrocartilage complex"}, {"key": "B", "text": "Scapholunate interosseous ligament"}, {"key": "C", "text": "Radial collateral ligament"}, {"key": "D", "text": "Ulnar collateral ligament"}], "correct": "B", "explanation": "Scapholunate interosseous ligament injury causes scapholunate dissociation/instability."}, {"id": 1469, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which special test is used to detect a SLAP lesion of the shoulder?", "options": [{"key": "A", "text": "O'Brien's test"}, {"key": "B", "text": "Neer's test"}, {"key": "C", "text": "Empty can test"}, {"key": "D", "text": "Drop arm test"}], "correct": "A", "explanation": "O'Brien's (active compression) test is used to detect superior labrum anterior-posterior (SLAP) lesions."}, {"id": 1470, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which rotator cuff muscle is the primary initiator of shoulder abduction in the first 15 degrees?", "options": [{"key": "A", "text": "Infraspinatus"}, {"key": "B", "text": "Supraspinatus"}, {"key": "C", "text": "Teres minor"}, {"key": "D", "text": "Subscapularis"}], "correct": "B", "explanation": "Supraspinatus initiates the first 15 degrees of shoulder abduction before deltoid takes over."}, {"id": 1471, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which rotator cuff muscle is the primary internal rotator of the shoulder?", "options": [{"key": "A", "text": "Supraspinatus"}, {"key": "B", "text": "Infraspinatus"}, {"key": "C", "text": "Teres minor"}, {"key": "D", "text": "Subscapularis"}], "correct": "D", "explanation": "Subscapularis is the main internal rotator among rotator cuff muscles."}, {"id": 1472, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The long head of biceps brachii originates from which structure?", "options": [{"key": "A", "text": "Coracoid process"}, {"key": "B", "text": "Supraglenoid tubercle of scapula"}, {"key": "C", "text": "Infraglenoid tubercle of scapula"}, {"key": "D", "text": "Glenoid neck"}], "correct": "B", "explanation": "Long head of biceps arises from the supraglenoid tubercle of the scapula."}, {"id": 1473, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Triceps brachii is innervated by which nerve?", "options": [{"key": "A", "text": "Median nerve"}, {"key": "B", "text": "Radial nerve"}, {"key": "C", "text": "Ulnar nerve"}, {"key": "D", "text": "Axillary nerve"}], "correct": "B", "explanation": "All three heads of triceps brachii are supplied by the radial nerve."}, {"id": 1474, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which forearm muscle is the primary supinator independent of elbow position?", "options": [{"key": "A", "text": "Biceps brachii"}, {"key": "B", "text": "Supinator"}, {"key": "C", "text": "Brachioradialis"}, {"key": "D", "text": "Pronator teres"}], "correct": "B", "explanation": "Supinator muscle works independent of elbow flexion angle, unlike biceps which is more effective when elbow flexed."}, {"id": 1475, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Pronator teres is innervated by which nerve?", "options": [{"key": "A", "text": "Radial nerve"}, {"key": "B", "text": "Median nerve"}, {"key": "C", "text": "Ulnar nerve"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "B", "explanation": "Pronator teres receives innervation from the median nerve."}, {"id": 1476, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which intrinsic hand muscles are supplied by the median nerve (LOAF muscles) except?", "options": [{"key": "A", "text": "Lateral 2 lumbricals"}, {"key": "B", "text": "Opponens pollicis"}, {"key": "C", "text": "Abductor pollicis brevis"}, {"key": "D", "text": "Flexor digiti minimi"}], "correct": "D", "explanation": "Flexor digiti minimi is supplied by ulnar nerve, not part of median-innervated LOAF muscles."}, {"id": 1477, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Erb's palsy results from injury to which roots of the brachial plexus?", "options": [{"key": "A", "text": "C5-C6"}, {"key": "B", "text": "C8-T1"}, {"key": "C", "text": "C7-C8"}, {"key": "D", "text": "C6-C7"}], "correct": "A", "explanation": "Erb's palsy (waiter's tip deformity) results from upper trunk (C5-C6) injury."}, {"id": 1478, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Klumpke's palsy results from injury to which roots of the brachial plexus?", "options": [{"key": "A", "text": "C5-C6"}, {"key": "B", "text": "C7-C8"}, {"key": "C", "text": "C8-T1"}, {"key": "D", "text": "C6-C7"}], "correct": "C", "explanation": "Klumpke's palsy results from lower trunk (C8-T1) injury, causing claw hand."}, {"id": 1479, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Median nerve injury at the wrist classically produces which deformity on attempted fist making?", "options": [{"key": "A", "text": "Claw hand"}, {"key": "B", "text": "Ape thumb deformity"}, {"key": "C", "text": "Wrist drop"}, {"key": "D", "text": "Winged scapula"}], "correct": "B", "explanation": "Median nerve injury causes ape thumb deformity due to loss of thenar muscle function."}, {"id": 1480, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Ulnar nerve injury at the wrist produces which classic hand deformity?", "options": [{"key": "A", "text": "Claw hand (ulnar claw)"}, {"key": "B", "text": "Ape thumb deformity"}, {"key": "C", "text": "Wrist drop"}, {"key": "D", "text": "Pope's blessing sign"}], "correct": "A", "explanation": "Ulnar nerve injury causes claw hand due to unopposed action of extensor digitorum on ring/little fingers."}, {"id": 1481, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Radial nerve provides sensory innervation to which area of the hand?", "options": [{"key": "A", "text": "Dorsal web space between thumb and index finger"}, {"key": "B", "text": "Palmar aspect of little finger"}, {"key": "C", "text": "Palmar aspect of thumb"}, {"key": "D", "text": "Medial palm"}], "correct": "A", "explanation": "Radial nerve's superficial branch supplies sensation to the dorsal first web space."}, {"id": 1482, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Carpal tunnel syndrome results from compression of which nerve?", "options": [{"key": "A", "text": "Ulnar nerve"}, {"key": "B", "text": "Median nerve"}, {"key": "C", "text": "Radial nerve"}, {"key": "D", "text": "Musculocutaneous nerve"}], "correct": "B", "explanation": "Carpal tunnel syndrome is caused by median nerve compression beneath the flexor retinaculum."}, {"id": 1483, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Winging of scapula is caused by paralysis of which muscle, innervated by the long thoracic nerve?", "options": [{"key": "A", "text": "Trapezius"}, {"key": "B", "text": "Serratus anterior"}, {"key": "C", "text": "Rhomboid major"}, {"key": "D", "text": "Levator scapulae"}], "correct": "B", "explanation": "Serratus anterior paralysis (long thoracic nerve injury) causes medial winging of the scapula."}, {"id": 1484, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The femoral neck is most vulnerable to fracture in elderly due to which factor?", "options": [{"key": "A", "text": "Increased cortical thickness"}, {"key": "B", "text": "Osteoporosis and retrograde blood supply"}, {"key": "C", "text": "Strong ligamentous support"}, {"key": "D", "text": "Thick periosteum"}], "correct": "B", "explanation": "Osteoporosis combined with tenuous retrograde blood supply via retinacular vessels predisposes to femoral neck fractures."}, {"id": 1485, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which artery is the primary blood supply to the femoral head in adults?", "options": [{"key": "A", "text": "Medial circumflex femoral artery"}, {"key": "B", "text": "Obturator artery via ligamentum teres"}, {"key": "C", "text": "Lateral circumflex femoral artery"}, {"key": "D", "text": "Inferior gluteal artery"}], "correct": "A", "explanation": "Medial circumflex femoral artery provides the major blood supply to the femoral head via retinacular vessels."}, {"id": 1486, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which tibial landmark serves as the attachment site for the patellar ligament?", "options": [{"key": "A", "text": "Medial tibial condyle"}, {"key": "B", "text": "Tibial tuberosity"}, {"key": "C", "text": "Tibial plateau"}, {"key": "D", "text": "Medial malleolus"}], "correct": "B", "explanation": "Patellar ligament attaches to the tibial tuberosity."}, {"id": 1487, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The fibula does not bear significant body weight but serves as attachment for which structures?", "options": [{"key": "A", "text": "Quadriceps muscles"}, {"key": "B", "text": "Lateral collateral ligament and several leg muscles"}, {"key": "C", "text": "Patellar ligament"}, {"key": "D", "text": "Anterior cruciate ligament"}], "correct": "B", "explanation": "Fibula provides attachment for lateral collateral ligament and muscles like biceps femoris, peroneal muscles."}, {"id": 1488, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which tarsal bone is the largest and forms the heel?", "options": [{"key": "A", "text": "Talus"}, {"key": "B", "text": "Calcaneus"}, {"key": "C", "text": "Navicular"}, {"key": "D", "text": "Cuboid"}], "correct": "B", "explanation": "Calcaneus is the largest tarsal bone, forming the heel and bearing weight during stance."}, {"id": 1489, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The talus articulates with the tibia and fibula to form which joint?", "options": [{"key": "A", "text": "Subtalar joint"}, {"key": "B", "text": "Ankle (talocrural) joint"}, {"key": "C", "text": "Midtarsal joint"}, {"key": "D", "text": "Tarsometatarsal joint"}], "correct": "B", "explanation": "Talus articulates superiorly with tibia and fibula forming the talocrural (ankle) joint."}, {"id": 1490, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Avascular necrosis of the talus is a known risk after fracture due to which feature?", "options": [{"key": "A", "text": "Rich periosteal blood supply"}, {"key": "B", "text": "Retrograde blood supply with limited collateral circulation"}, {"key": "C", "text": "No cartilage covering"}, {"key": "D", "text": "Strong muscular attachments"}], "correct": "B", "explanation": "Talus has limited blood supply with no muscular attachments, making it prone to avascular necrosis after fracture."}, {"id": 1491, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The hip joint is classified as which type of synovial joint?", "options": [{"key": "A", "text": "Hinge joint"}, {"key": "B", "text": "Ball and socket joint"}, {"key": "C", "text": "Saddle joint"}, {"key": "D", "text": "Condyloid joint"}], "correct": "B", "explanation": "Hip joint is a multiaxial ball and socket joint between femoral head and acetabulum."}, {"id": 1492, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which ligament of the hip is the strongest and prevents excessive extension?", "options": [{"key": "A", "text": "Ligamentum teres"}, {"key": "B", "text": "Iliofemoral ligament (Y-ligament of Bigelow)"}, {"key": "C", "text": "Pubofemoral ligament"}, {"key": "D", "text": "Ischiofemoral ligament"}], "correct": "B", "explanation": "Iliofemoral ligament is the strongest ligament of the body, limiting hip extension."}, {"id": 1493, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The knee joint's anterior cruciate ligament primarily prevents which movement?", "options": [{"key": "A", "text": "Posterior translation of tibia"}, {"key": "B", "text": "Anterior translation of tibia on femur"}, {"key": "C", "text": "Varus stress"}, {"key": "D", "text": "Valgus stress"}], "correct": "B", "explanation": "ACL primarily resists anterior translation of the tibia relative to the femur."}, {"id": 1494, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which special test is most sensitive for detecting ACL rupture?", "options": [{"key": "A", "text": "Lachman test"}, {"key": "B", "text": "McMurray test"}, {"key": "C", "text": "Valgus stress test"}, {"key": "D", "text": "Thomas test"}], "correct": "A", "explanation": "Lachman test is considered the most sensitive clinical test for ACL integrity."}, {"id": 1495, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The unhappy triad (O'Donoghue's triad) of knee injury involves ACL, MCL and which structure?", "options": [{"key": "A", "text": "Lateral meniscus"}, {"key": "B", "text": "Medial meniscus"}, {"key": "C", "text": "PCL"}, {"key": "D", "text": "Patellar tendon"}], "correct": "B", "explanation": "Unhappy triad classically involves ACL, MCL, and medial meniscus injury together."}, {"id": 1496, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The ankle joint is most stable in which position due to talar dome shape?", "options": [{"key": "A", "text": "Plantarflexion"}, {"key": "B", "text": "Dorsiflexion"}, {"key": "C", "text": "Neutral position"}, {"key": "D", "text": "Eversion"}], "correct": "B", "explanation": "The wider anterior talar dome fits snugly into the mortise during dorsiflexion, making the ankle most stable."}, {"id": 1497, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which ligament of the ankle is most commonly sprained in an inversion injury?", "options": [{"key": "A", "text": "Deltoid ligament"}, {"key": "B", "text": "Anterior talofibular ligament"}, {"key": "C", "text": "Posterior talofibular ligament"}, {"key": "D", "text": "Calcaneofibular ligament"}], "correct": "B", "explanation": "Anterior talofibular ligament is the most frequently injured ligament in ankle inversion sprains."}, {"id": 1498, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which quadriceps muscle is the only one that crosses both hip and knee joints?", "options": [{"key": "A", "text": "Vastus lateralis"}, {"key": "B", "text": "Rectus femoris"}, {"key": "C", "text": "Vastus medialis"}, {"key": "D", "text": "Vastus intermedius"}], "correct": "B", "explanation": "Rectus femoris is biarticular, crossing both the hip and knee joints."}, {"id": 1499, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Hamstring muscles are innervated by which nerve, except the short head of biceps femoris?", "options": [{"key": "A", "text": "Femoral nerve"}, {"key": "B", "text": "Tibial division of sciatic nerve"}, {"key": "C", "text": "Common peroneal division of sciatic nerve"}, {"key": "D", "text": "Obturator nerve"}], "correct": "B", "explanation": "Tibial division of sciatic nerve supplies most hamstrings; short head of biceps femoris is innervated by common peroneal division."}, {"id": 1500, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Gluteus medius is most important for preventing which gait abnormality?", "options": [{"key": "A", "text": "Steppage gait"}, {"key": "B", "text": "Trendelenburg gait"}, {"key": "C", "text": "Antalgic gait"}, {"key": "D", "text": "Scissor gait"}], "correct": "B", "explanation": "Weak gluteus medius causes a Trendelenburg gait with pelvic drop on the contralateral side during stance."}, {"id": 1501, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which gluteal muscle is the primary hip extensor used in climbing stairs and rising from sitting?", "options": [{"key": "A", "text": "Gluteus medius"}, {"key": "B", "text": "Gluteus minimus"}, {"key": "C", "text": "Gluteus maximus"}, {"key": "D", "text": "Tensor fasciae latae"}], "correct": "C", "explanation": "Gluteus maximus is the prime mover for powerful hip extension activities like stair climbing."}, {"id": 1502, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The gastrocnemius muscle crosses which two joints?", "options": [{"key": "A", "text": "Hip and knee"}, {"key": "B", "text": "Knee and ankle"}, {"key": "C", "text": "Ankle only"}, {"key": "D", "text": "Hip and ankle"}], "correct": "B", "explanation": "Gastrocnemius is biarticular, crossing both the knee and ankle joints."}, {"id": 1503, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which calf muscle is most active during standing balance and is mono-articular (crosses ankle only)?", "options": [{"key": "A", "text": "Gastrocnemius"}, {"key": "B", "text": "Soleus"}, {"key": "C", "text": "Plantaris"}, {"key": "D", "text": "Popliteus"}], "correct": "B", "explanation": "Soleus crosses only the ankle joint and is key for postural stability during quiet standing."}, {"id": 1504, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Achilles tendon is formed by the union of which muscles' tendons?", "options": [{"key": "A", "text": "Gastrocnemius and soleus"}, {"key": "B", "text": "Tibialis posterior and flexor digitorum longus"}, {"key": "C", "text": "Peroneus longus and brevis"}, {"key": "D", "text": "Popliteus and plantaris"}], "correct": "A", "explanation": "Achilles (calcaneal) tendon is formed by the conjoined tendons of gastrocnemius and soleus."}, {"id": 1505, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Femoral nerve injury most significantly impairs which movement?", "options": [{"key": "A", "text": "Hip extension"}, {"key": "B", "text": "Knee extension"}, {"key": "C", "text": "Ankle dorsiflexion"}, {"key": "D", "text": "Hip adduction"}], "correct": "B", "explanation": "Femoral nerve supplies quadriceps; injury impairs knee extension significantly."}, {"id": 1506, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Sciatic nerve is formed from which nerve roots?", "options": [{"key": "A", "text": "L1-L3"}, {"key": "B", "text": "L2-L4"}, {"key": "C", "text": "L4-S3"}, {"key": "D", "text": "S2-S4"}], "correct": "C", "explanation": "Sciatic nerve arises from ventral rami of L4-S3."}, {"id": 1507, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Common peroneal nerve is most vulnerable to injury at which anatomical site?", "options": [{"key": "A", "text": "Popliteal fossa"}, {"key": "B", "text": "Neck of fibula"}, {"key": "C", "text": "Tarsal tunnel"}, {"key": "D", "text": "Adductor canal"}], "correct": "B", "explanation": "Common peroneal nerve winds around the neck of fibula, making it superficial and vulnerable there."}, {"id": 1508, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Injury to the common peroneal nerve classically results in which deformity?", "options": [{"key": "A", "text": "Claw foot"}, {"key": "B", "text": "Foot drop"}, {"key": "C", "text": "Pes cavus"}, {"key": "D", "text": "Hammer toe"}], "correct": "B", "explanation": "Common peroneal nerve injury causes foot drop due to paralysis of dorsiflexors and evertors."}, {"id": 1509, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Tibial nerve injury results in loss of which movement?", "options": [{"key": "A", "text": "Ankle dorsiflexion"}, {"key": "B", "text": "Ankle plantarflexion and toe flexion"}, {"key": "C", "text": "Knee extension"}, {"key": "D", "text": "Hip abduction"}], "correct": "B", "explanation": "Tibial nerve supplies posterior leg muscles responsible for plantarflexion and toe flexion."}, {"id": 1510, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Tarsal tunnel syndrome involves compression of which nerve?", "options": [{"key": "A", "text": "Superficial peroneal nerve"}, {"key": "B", "text": "Posterior tibial nerve"}, {"key": "C", "text": "Sural nerve"}, {"key": "D", "text": "Saphenous nerve"}], "correct": "B", "explanation": "Tarsal tunnel syndrome results from posterior tibial nerve compression behind the medial malleolus."}, {"id": 1511, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Meralgia paresthetica results from compression of which nerve?", "options": [{"key": "A", "text": "Femoral nerve"}, {"key": "B", "text": "Lateral femoral cutaneous nerve"}, {"key": "C", "text": "Obturator nerve"}, {"key": "D", "text": "Saphenous nerve"}], "correct": "B", "explanation": "Meralgia paresthetica is caused by compression of the lateral femoral cutaneous nerve near the inguinal ligament."}, {"id": 1512, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which cervical level accounts for approximately 50% of total cervical spine rotation?", "options": [{"key": "A", "text": "C1-C2 (atlanto-axial joint)"}, {"key": "B", "text": "C0-C1 (atlanto-occipital joint)"}, {"key": "C", "text": "C4-C5"}, {"key": "D", "text": "C6-C7"}], "correct": "A", "explanation": "Atlanto-axial (C1-C2) joint contributes about 50% of total cervical rotation."}, {"id": 1513, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The vertebral artery typically enters the transverse foramen first at which cervical level?", "options": [{"key": "A", "text": "C3"}, {"key": "B", "text": "C4"}, {"key": "C", "text": "C5"}, {"key": "D", "text": "C6"}], "correct": "D", "explanation": "Vertebral artery usually enters the transverse foramen at C6 in most individuals."}, {"id": 1514, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Cervical radiculopathy at C6 nerve root classically presents with weakness of which muscle?", "options": [{"key": "A", "text": "Triceps"}, {"key": "B", "text": "Biceps brachii and wrist extensors"}, {"key": "C", "text": "Finger flexors"}, {"key": "D", "text": "Intrinsic hand muscles"}], "correct": "B", "explanation": "C6 radiculopathy presents with biceps and wrist extensor weakness along with thumb/index sensory changes."}, {"id": 1515, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Spurling's test is used clinically to assess for?", "options": [{"key": "A", "text": "Thoracic outlet syndrome"}, {"key": "B", "text": "Cervical nerve root compression"}, {"key": "C", "text": "Carpal tunnel syndrome"}, {"key": "D", "text": "Rotator cuff tear"}], "correct": "B", "explanation": "Spurling's test (cervical compression with extension/lateral flexion) reproduces radicular symptoms in nerve root compression."}, {"id": 1516, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Vertebrobasilar insufficiency testing before cervical manipulation primarily screens for compromise of which vessels?", "options": [{"key": "A", "text": "Carotid arteries"}, {"key": "B", "text": "Vertebral arteries"}, {"key": "C", "text": "Subclavian arteries"}, {"key": "D", "text": "Jugular veins"}], "correct": "B", "explanation": "Pre-manipulative testing screens for vertebrobasilar (vertebral artery) insufficiency to avoid stroke risk."}, {"id": 1517, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Intervertebral discs are avascular structures that primarily receive nutrition by which mechanism?", "options": [{"key": "A", "text": "Direct capillary supply"}, {"key": "B", "text": "Diffusion through vertebral endplates"}, {"key": "C", "text": "Lymphatic drainage"}, {"key": "D", "text": "Synovial fluid exchange"}], "correct": "B", "explanation": "Adult intervertebral discs are avascular and rely on diffusion through cartilaginous endplates for nutrition."}, {"id": 1518, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Posterolateral disc herniation most commonly compresses which nerve root relative to vertebral level (e.g., L4-L5 disc)?", "options": [{"key": "A", "text": "The nerve root exiting above the disc level"}, {"key": "B", "text": "The traversing nerve root of the level below (e.g., L5)"}, {"key": "C", "text": "Both nerve roots equally"}, {"key": "D", "text": "No nerve root, only the cord"}], "correct": "B", "explanation": "Posterolateral herniation typically compresses the traversing (descending) nerve root, e.g., L4-L5 disc affects L5 root."}, {"id": 1519, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The annulus fibrosus of the intervertebral disc is composed of which tissue arrangement?", "options": [{"key": "A", "text": "Concentric lamellae of fibrocartilage with alternating fiber orientation"}, {"key": "B", "text": "Hyaline cartilage plates only"}, {"key": "C", "text": "Loose areolar connective tissue"}, {"key": "D", "text": "Hydrated gel without fibers"}], "correct": "A", "explanation": "Annulus fibrosus consists of concentric lamellae with collagen fibers oriented at alternating angles for strength."}, {"id": 1520, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Lumbar spinal stenosis classically produces symptoms that are relieved by which posture?", "options": [{"key": "A", "text": "Spinal extension"}, {"key": "B", "text": "Spinal flexion (e.g., leaning forward, sitting)"}, {"key": "C", "text": "Lateral flexion"}, {"key": "D", "text": "Prolonged standing"}], "correct": "B", "explanation": "Lumbar stenosis symptoms (neurogenic claudication) typically improve with flexion as it increases canal diameter."}, {"id": 1521, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which ligament, if it ossifies, is implicated in spinal canal stenosis especially in the cervical/thoracic spine?", "options": [{"key": "A", "text": "Anterior longitudinal ligament"}, {"key": "B", "text": "Posterior longitudinal ligament"}, {"key": "C", "text": "Supraspinous ligament"}, {"key": "D", "text": "Iliolumbar ligament"}], "correct": "B", "explanation": "Ossification of posterior longitudinal ligament (OPLL) can cause significant spinal canal stenosis."}, {"id": 1522, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Spondylolisthesis most commonly occurs at which lumbar level due to mechanical stress?", "options": [{"key": "A", "text": "L1-L2"}, {"key": "B", "text": "L2-L3"}, {"key": "C", "text": "L3-L4"}, {"key": "D", "text": "L5-S1"}], "correct": "D", "explanation": "L5-S1 is the most common site for spondylolisthesis due to high mechanical shear forces."}, {"id": 1523, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The pars interarticularis defect associated with spondylolysis is best visualized on which X-ray view?", "options": [{"key": "A", "text": "AP view"}, {"key": "B", "text": "Lateral view"}, {"key": "C", "text": "Oblique view ('Scottie dog' sign)"}, {"key": "D", "text": "Flexion-extension view"}], "correct": "C", "explanation": "Oblique lumbar spine X-ray shows the 'Scottie dog' appearance, with a collar representing pars interarticularis defect."}, {"id": 1524, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The sacroiliac joint is classified as which type of joint?", "options": [{"key": "A", "text": "Synovial plane joint with fibrous reinforcement (combination joint)"}, {"key": "B", "text": "Pure synovial ball and socket joint"}, {"key": "C", "text": "Pure fibrous joint"}, {"key": "D", "text": "Pure cartilaginous joint"}], "correct": "A", "explanation": "SI joint is a combination joint - synovial anteriorly and fibrous/ligamentous posteriorly, providing strong stability."}, {"id": 1525, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which test is commonly used clinically to provoke sacroiliac joint pain?", "options": [{"key": "A", "text": "Thomas test"}, {"key": "B", "text": "FABER (Patrick's) test"}, {"key": "C", "text": "Lachman test"}, {"key": "D", "text": "Spurling's test"}], "correct": "B", "explanation": "FABER/Patrick's test (Flexion, Abduction, External Rotation) is used to provoke SI joint pathology."}, {"id": 1526, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The coccyx typically consists of how many fused vertebral segments?", "options": [{"key": "A", "text": "2-3"}, {"key": "B", "text": "3-5"}, {"key": "C", "text": "6-7"}, {"key": "D", "text": "8-9"}], "correct": "B", "explanation": "Coccyx usually consists of 3 to 5 fused rudimentary vertebral segments."}, {"id": 1527, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Coccydynia is most commonly caused by which mechanism?", "options": [{"key": "A", "text": "Repetitive overhead activity"}, {"key": "B", "text": "Direct trauma from fall onto coccyx or childbirth"}, {"key": "C", "text": "Cervical disc herniation"}, {"key": "D", "text": "Shoulder impingement"}], "correct": "B", "explanation": "Coccydynia commonly results from direct trauma (fall) or childbirth-related injury to the coccyx."}, {"id": 1528, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Nutation of the sacrum (sacral base moving anteriorly/inferiorly) occurs during which phase of gait/activity?", "options": [{"key": "A", "text": "Trunk extension"}, {"key": "B", "text": "Trunk flexion and weight-bearing through pelvis"}, {"key": "C", "text": "Hip extension only"}, {"key": "D", "text": "Standing on one leg only"}], "correct": "B", "explanation": "Sacral nutation typically occurs with trunk flexion and increased load transmission through the pelvis, enhancing SI joint stability (self-locking mechanism)."}, {"id": 1529, "subject": "Mixed Revision", "difficulty": "Hard", "question": "How many pairs of ribs are classified as 'true ribs' attaching directly to the sternum?", "options": [{"key": "A", "text": "5 pairs"}, {"key": "B", "text": "7 pairs"}, {"key": "C", "text": "10 pairs"}, {"key": "D", "text": "12 pairs"}], "correct": "B", "explanation": "Ribs 1-7 are true ribs, attaching directly to the sternum via individual costal cartilages."}, {"id": 1530, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Ribs 11 and 12 are classified as which type of ribs?", "options": [{"key": "A", "text": "True ribs"}, {"key": "B", "text": "False ribs (vertebrochondral)"}, {"key": "C", "text": "Floating ribs"}, {"key": "D", "text": "Atypical true ribs"}], "correct": "C", "explanation": "Ribs 11 and 12 are floating ribs as they have no anterior attachment to the sternum or costal cartilage chain."}, {"id": 1531, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The diaphragm receives motor innervation from which nerve?", "options": [{"key": "A", "text": "Vagus nerve"}, {"key": "B", "text": "Phrenic nerve (C3-C5)"}, {"key": "C", "text": "Intercostal nerves"}, {"key": "D", "text": "Thoracodorsal nerve"}], "correct": "B", "explanation": "Phrenic nerve, arising from C3-C5, provides sole motor supply to the diaphragm."}, {"id": 1532, "subject": "Mixed Revision", "difficulty": "Hard", "question": "During quiet inspiration, contraction of the diaphragm causes which change in thoracic dimension?", "options": [{"key": "A", "text": "Decrease in vertical dimension"}, {"key": "B", "text": "Increase in vertical dimension of thoracic cavity"}, {"key": "C", "text": "No change in thoracic volume"}, {"key": "D", "text": "Decrease in transverse dimension"}], "correct": "B", "explanation": "Diaphragmatic contraction flattens the dome, increasing the vertical dimension of the thoracic cavity for inspiration."}, {"id": 1533, "subject": "Mixed Revision", "difficulty": "Hard", "question": "External intercostal muscles primarily assist in which respiratory phase?", "options": [{"key": "A", "text": "Forced expiration"}, {"key": "B", "text": "Inspiration (elevating ribs)"}, {"key": "C", "text": "Quiet expiration only"}, {"key": "D", "text": "Swallowing"}], "correct": "B", "explanation": "External intercostals elevate the ribs, assisting inspiration (bucket-handle and pump-handle movements)."}, {"id": 1534, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Internal intercostal muscles primarily assist in which respiratory phase?", "options": [{"key": "A", "text": "Quiet inspiration"}, {"key": "B", "text": "Forced expiration (depressing ribs)"}, {"key": "C", "text": "Diaphragmatic breathing only"}, {"key": "D", "text": "Swallowing"}], "correct": "B", "explanation": "Internal intercostals depress the ribs, contributing to forced expiration."}, {"id": 1535, "subject": "Mixed Revision", "difficulty": "Hard", "question": "The sternal angle (angle of Louis) corresponds to which important anatomical landmark?", "options": [{"key": "A", "text": "Articulation of 2nd costal cartilage with sternum; level of tracheal bifurcation"}, {"key": "B", "text": "Xiphisternal joint"}, {"key": "C", "text": "T4-T5 disc level only"}, {"key": "D", "text": "Level of diaphragm only"}], "correct": "A", "explanation": "Sternal angle marks the 2nd rib articulation and approximates the level of tracheal bifurcation (T4-T5)."}, {"id": 1536, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Pterion, a clinically important thin region of the skull, overlies which artery?", "options": [{"key": "A", "text": "Superficial temporal artery"}, {"key": "B", "text": "Middle meningeal artery"}, {"key": "C", "text": "Posterior auricular artery"}, {"key": "D", "text": "Occipital artery"}], "correct": "B", "explanation": "Middle meningeal artery runs deep to the pterion and is vulnerable to injury causing epidural hematoma."}, {"id": 1537, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Bilateral weakness of sternocleidomastoid most significantly impairs which function?", "options": [{"key": "A", "text": "Head rotation only"}, {"key": "B", "text": "Neck flexion against resistance and forced inspiration"}, {"key": "C", "text": "Neck extension"}, {"key": "D", "text": "Lateral flexion only"}], "correct": "B", "explanation": "Bilateral SCM weakness impairs neck flexion strength and accessory inspiratory function."}, {"id": 1538, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Thoracic outlet syndrome caused by scalene muscle hypertrophy most commonly compresses which neurovascular structures?", "options": [{"key": "A", "text": "Vertebral artery only"}, {"key": "B", "text": "Brachial plexus trunks and subclavian artery in the interscalene triangle"}, {"key": "C", "text": "Phrenic nerve only"}, {"key": "D", "text": "Internal jugular vein"}], "correct": "B", "explanation": "Tight/hypertrophied scalenus anterior and medius can compress brachial plexus trunks and subclavian artery in the interscalene triangle."}, {"id": 1539, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Greater occipital neuralgia, a cause of cervicogenic headache, involves irritation of a branch from which nerve root?", "options": [{"key": "A", "text": "C1 dorsal ramus"}, {"key": "B", "text": "C2 dorsal ramus"}, {"key": "C", "text": "C4 dorsal ramus"}, {"key": "D", "text": "C6 dorsal ramus"}], "correct": "B", "explanation": "Greater occipital nerve, the medial branch of C2 dorsal ramus, is implicated in occipital neuralgia/cervicogenic headache."}, {"id": 1540, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Brown-Sequard syndrome (spinal cord hemisection) produces contralateral loss of which sensory modality below the lesion?", "options": [{"key": "A", "text": "Proprioception"}, {"key": "B", "text": "Pain and temperature"}, {"key": "C", "text": "Fine touch"}, {"key": "D", "text": "Vibration"}], "correct": "B", "explanation": "Contralateral pain/temperature loss occurs due to crossed spinothalamic tract fibers below a hemisection lesion."}, {"id": 1541, "subject": "Mixed Revision", "difficulty": "Hard", "question": "A lesion of the corticospinal tract above the level of decussation in the medulla produces weakness on which side?", "options": [{"key": "A", "text": "Ipsilateral side"}, {"key": "B", "text": "Contralateral side"}, {"key": "C", "text": "Bilateral equally"}, {"key": "D", "text": "No motor deficit"}], "correct": "B", "explanation": "Lesions above the pyramidal decussation cause contralateral weakness since fibers cross in the medulla."}, {"id": 1542, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Cauda equina syndrome, presenting with saddle anesthesia and bowel/bladder dysfunction, involves compression of nerve roots below which level?", "options": [{"key": "A", "text": "T12"}, {"key": "B", "text": "L1-L2 (conus medullaris level)"}, {"key": "C", "text": "L5 only"}, {"key": "D", "text": "S1 only"}], "correct": "B", "explanation": "Cauda equina syndrome results from compression of nerve roots below the conus medullaris (around L1-L2)."}, {"id": 1543, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which dermatome correlates with sensory loss commonly seen in carpal tunnel syndrome (median nerve)?", "options": [{"key": "A", "text": "C6"}, {"key": "B", "text": "C7"}, {"key": "C", "text": "C8"}, {"key": "D", "text": "T1"}], "correct": "A", "explanation": "Median nerve sensory symptoms in carpal tunnel syndrome typically correspond to C6-C7 dermatomal/median distribution, primarily thumb/index (C6)."}, {"id": 1544, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Weakness of ankle dorsiflexion combined with diminished sensation over the dorsum of the foot suggests involvement of which nerve root?", "options": [{"key": "A", "text": "L3"}, {"key": "B", "text": "L4"}, {"key": "C", "text": "L5"}, {"key": "D", "text": "S1"}], "correct": "C", "explanation": "L5 nerve root involvement classically presents with weak dorsiflexion of the great toe/ankle and dorsal foot sensory changes."}, {"id": 1545, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Absent ankle jerk reflex combined with weakness of plantarflexion suggests pathology at which nerve root level?", "options": [{"key": "A", "text": "L3-L4"}, {"key": "B", "text": "L4-L5"}, {"key": "C", "text": "S1-S2"}, {"key": "D", "text": "S3-S4"}], "correct": "C", "explanation": "S1-S2 nerve root lesions classically present with diminished ankle reflex and plantarflexor weakness."}, {"id": 1546, "subject": "Mixed Revision", "difficulty": "Hard", "question": "A patient with Brown-Sequard syndrome shows ipsilateral spastic paralysis below the lesion due to involvement of which tract?", "options": [{"key": "A", "text": "Lateral spinothalamic tract"}, {"key": "B", "text": "Lateral corticospinal tract"}, {"key": "C", "text": "Dorsal column tract"}, {"key": "D", "text": "Spinocerebellar tract"}], "correct": "B", "explanation": "Ipsilateral motor weakness below a hemisection lesion results from interruption of the lateral corticospinal tract, which has already decussated above."}, {"id": 1547, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Quadrilateral space syndrome results from compression of which nerve and artery?", "options": [{"key": "A", "text": "Suprascapular nerve and artery"}, {"key": "B", "text": "Axillary nerve and posterior circumflex humeral artery"}, {"key": "C", "text": "Radial nerve and profunda brachii artery"}, {"key": "D", "text": "Musculocutaneous nerve and brachial artery"}], "correct": "B", "explanation": "Quadrilateral space syndrome involves compression of axillary nerve and posterior circumflex humeral artery."}, {"id": 1548, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Guyon's canal syndrome results from compression of which nerve at the wrist?", "options": [{"key": "A", "text": "Median nerve"}, {"key": "B", "text": "Ulnar nerve"}, {"key": "C", "text": "Radial nerve"}, {"key": "D", "text": "Anterior interosseous nerve"}], "correct": "B", "explanation": "Guyon's canal (ulnar tunnel) syndrome is caused by ulnar nerve compression at the wrist."}, {"id": 1549, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Piriformis syndrome classically mimics symptoms of which condition due to sciatic nerve irritation?", "options": [{"key": "A", "text": "Carpal tunnel syndrome"}, {"key": "B", "text": "Lumbar disc herniation/sciatica"}, {"key": "C", "text": "Meralgia paresthetica"}, {"key": "D", "text": "Tarsal tunnel syndrome"}], "correct": "B", "explanation": "Piriformis syndrome causes sciatica-like symptoms due to sciatic nerve compression/irritation by the piriformis muscle."}, {"id": 1550, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Genu valgum deformity places increased stress on which knee compartment and ligament?", "options": [{"key": "A", "text": "Medial compartment and MCL"}, {"key": "B", "text": "Lateral compartment and LCL"}, {"key": "C", "text": "Anterior compartment and ACL"}, {"key": "D", "text": "Posterior compartment and PCL"}], "correct": "B", "explanation": "Genu valgum (knock knee) increases lateral compartment loading and stresses the lateral collateral ligament."}, {"id": 1551, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Posterior cruciate ligament injury is classically tested using which special test?", "options": [{"key": "A", "text": "Anterior drawer test"}, {"key": "B", "text": "Posterior drawer test"}, {"key": "C", "text": "Valgus stress test"}, {"key": "D", "text": "McMurray test"}], "correct": "B", "explanation": "Posterior drawer test assesses posterior tibial translation, indicating PCL integrity."}, {"id": 1552, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which thoracic spine segment is most commonly associated with Scheuermann's kyphosis due to vertebral wedging?", "options": [{"key": "A", "text": "Upper cervical spine"}, {"key": "B", "text": "Mid-to-lower thoracic spine"}, {"key": "C", "text": "Lumbar spine"}, {"key": "D", "text": "Sacral spine"}], "correct": "B", "explanation": "Scheuermann's disease typically affects the mid-to-lower thoracic vertebrae causing wedge-shaped vertebrae and kyphosis."}, {"id": 1553, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Costotransverse joints are formed between ribs and which part of thoracic vertebrae?", "options": [{"key": "A", "text": "Vertebral body"}, {"key": "B", "text": "Transverse process"}, {"key": "C", "text": "Spinous process"}, {"key": "D", "text": "Lamina"}], "correct": "B", "explanation": "Costotransverse joints articulate the rib tubercle with the transverse process of the corresponding thoracic vertebra."}, {"id": 1554, "subject": "Mixed Revision", "difficulty": "Hard", "question": "Which suboccipital muscle, when tight, is implicated in cervicogenic headache via dural connections?", "options": [{"key": "A", "text": "Longus colli"}, {"key": "B", "text": "Rectus capitis posterior minor"}, {"key": "C", "text": "Scalenus medius"}, {"key": "D", "text": "Levator scapulae"}], "correct": "B", "explanation": "Rectus capitis posterior minor has fascial/myodural connections to the spinal dura and is implicated in cervicogenic headache."}, {"id": 1555, "subject": "Mixed Revision", "difficulty": "Hard", "question": "In central cord syndrome, the corticospinal tract fibers for which body region are most centrally located and thus most affected?", "options": [{"key": "A", "text": "Lower limb"}, {"key": "B", "text": "Upper limb"}, {"key": "C", "text": "Trunk only"}, {"key": "D", "text": "Face only"}], "correct": "B", "explanation": "Upper limb corticospinal fibers are positioned more centrally in the spinal cord, making them most affected in central cord syndrome."}];
